\section{Proof of canceling surface fluxes}\label{sec:surface}
Expanding the YBE, the coefficient of the $\xi\zeta^{2m}$ term gives
\begin{equation}
\sum_{k=0}^{2m}(-1)^k\binom{2m}{k}(a_kb_1a_{2m-k}-b_{2m-k}a_1b_k) =\sum_{k=0}^{2m}(-1)^k\binom{2m}{k}(b_{2m-k}b_{k+1}-a_{k+1}a_{2m-k}).
\label{eq:YBE12}
\end{equation}
The RHS is in fact the difference of two identical operators acting on two different pairs of neighboring sites:
\begin{equation*}
	\begin{split}
		&\sum_{k=0}^{2m}(-1)^k\binom{2m}{k}\left(a_{2m-k}a_{k+1}-a_{k+1}a_{2m-k}\right)\\
		=&\sum_{k=0}^{2m}(-1)^k\binom{2m}{k}\left(a_{k}a_{2m-k+1}-a_{k+1}a_{2m-k}\right)\\
		=&\sum_{k=1}^{2m}(-1)^k\binom{2m}{k}a_{k}a_{2m-k+1}-\sum_{k=0}^{2m-1}(-1)^k\binom{2m}{k}a_{k+1}a_{2m-k}\\
		=&\sum_{k=1}^{2m}(-1)^k\binom{2m}{k}a_{k}a_{2m-k+1}+\sum_{k=1}^{2m}(-1)^k\binom{2m}{k-1}a_{k}a_{2m-k+1}\\
		=&\sum_{k=1}^{2m}(-1)^k\binom{2m+1}{k}a_{k}a_{2m-k+1}\\
		=&0,
	\end{split}
\end{equation*}where in the last step Eq.~\eqref{eq:uniodd} has been used.
Using Eq.~\eqref{eq:unieven} to rewrite the LHS of Eq.~\eqref{eq:YBE12} in terms of commutators, one arrives at Eq.~\eqref{eq:highercurrent}.

\section{Concrete examples of integrable models}

\subsection{Spin-$\frac{1}{2}$ chains}
\label{sec:spin-1/2}
The Hamiltonian of a generic spin-$\frac{1}{2}$ chain with reciprocal interaction can be written as 
\begin{equation}
	H_{\frac{1}{2}}=\sum_{x} \left(J_1 \sigma_x^{1}\sigma_{x+1}^{1}+J_2 \sigma_x^{2}\sigma_{x+1}^{2}+J_3 \sigma_x^{3}\sigma_{x+1}^{3} +h_1\sigma_x^{1}+h_2\sigma_x^{2}+h_3\sigma_x^{3}\right).
\end{equation}
This is because any symmetric coupling matrix $\bm{J}$ can be diagonalized with the off-diagonal entries absorbed by a redefinition of the external field $\bm{h}$. Reshetikhin's condition gives the 5 solutions (up to permutations of the axes) summarized in \cref{tab:spin12} below, in agreement with the non-existence of conserved charges for the rest scenarios proven in \cite{yamaguchi2024complete,yamaguchi2024proof}.
\begin{table}[h!]
    \centering
    \begin{tabular}{ | m{4cm}| m{4cm} | } 
		\hline
		$J_1=J_2=J_3=0$ & non-interacting \\ 
		\hline
		$J_1=J_2=0$, $h_1=h_2=0$ & Longitudinal field Ising  \\ 
		\hline
		$J_1=J_2=0$, $h_3=0$ & Transverse field Ising \\ 
		\hline
		$J_3=0$, $h_1=h_2=0$ & XYh \\ 
		\hline
		$h_1=h_2=h_3=0$ & XYZ \\ 
		\hline
	\end{tabular}
    \caption{Integrable couplings for spin-$\frac{1}{2}$ chains.}
    \label{tab:spin12}
\end{table}


Now we are ready to examine more closely how the higher charges are conserved in the form of congruence relations of 3-local commutators, for specific integrable spin-$\frac{1}{2}$ Hamiltonians.

\subsubsection{The XYZ chain}
\label{sec:XYZ}

For the XYZ chain, local Hamiltonian terms satisfy the relations
\begin{align*}
	\ad_a^2 b-\ad_b^2 a=&2(a^3-b^3)-2J^2(a-b),\\
	\ad_a^4 b-\ad_b^4 a=&\frac{J^4}{J_1J_2J_3}(a^4-b^4)+8J^2(a^3-b^3)-(\frac{2J^6}{J_1J_2J_3}+40J_1J_2J_3)(a^2-b^2)\\ &-16(J_1^2J_2^2+J_2^2J_3^2+J_3^2J_1^2)(a-b),\\
	[bbaab]-[aabba]=&[abaab]-[babba]=32J_1J_2J_3(a^2-b^2),\\
	[abbba]-[baaab]=& 40J_1J_2J_3(a^2-b^2)-16(J_1^2J_2^2+J_2^2J_3^2+J_3^2J_1^2)(a-b),
\end{align*}where the right-normed Lie bracket $[o_1o_2\cdots o_n]$ has been used to denote $[o_1,[o_2,[[\cdots[\cdots,o_n]]\cdots]$. So we have $ij_x=2a^3-2J^2a$, which in turn satisfies
\begin{align*}
	i([j_xab]-[j_{x+1}ba])=&2J^2(a^3-b^3)-8J_1J_2J_3(a^2-b^2)\\
	&-(2J^4-16(J_1^2J_2^2+J_2^2J_3^2+J_3^2J_1^2))(a-b),\\
	i([aaj_{x+1}]-[bbj_x])=&10J^2(a^3-b^3)-8J_1J_2J_3(a^2-b^2)\\
	&-(10J^4+16(J_1^2J_2^2+J_2^2J_3^2+J_3^2J_1^2))(a-b),\\
	\ad_a^3b+\ad_b^3a=&-i[a+b,j_x+j_{x+1}].      
\end{align*}

\subsubsection{The XXZ chain}

As a special case of the XYZ Hamiltonian, the XXZ Hamiltonian of course satisfy all the above relations, with $J_1=J_2=1$ and $J_3=\Delta$. In addition, it satisfies
\begin{equation}
	\ad_a^{2n+1}b+\ad_b^{2n+1}a \propto \ad_a^3b+\ad_b^3a,
	\label{eq:GDG}
\end{equation}for all $n\in \mathbb{Z}^+$, which does not hold for the XYZ model in general. For instance, we have
\begin{align*}
	\ad_a^{5}b+\ad_b^{5}a=&  4(\Delta^2+11)(\ad_a^3b+\ad_b^3a),\\
	\ad_a^{7}b+\ad_b^{7}a=&  16(\Delta^4+22\Delta^2+57)(\ad_a^3b+\ad_b^3a),\\
	\ad_a^{9}b+\ad_b^{9}a=&  64(\Delta^6+37\Delta^4+163\Delta^2+247)(\ad_a^3b+\ad_b^3a).
\end{align*} They can be established using the SU(2) algebra of the Pauli matrices, but here we demonstrate instead with the simpler XXX chain.

\subsubsection{The XXX chain} 
\label{sec:Heisenberg}

Using the commutation relation
\begin{equation*}
	[\sigma^k,\sigma^l]=2i\epsilon^{klm}\sigma^m,
\end{equation*}with the Einstein summation convention implied, and the anti-commutation relation
\begin{equation*}
	\{\sigma^k,\sigma^l\}=2\delta^{kl} ,
\end{equation*}we have
\begin{align*}
	[\sigma_x^k\otimes \sigma_{x+1}^l,\sigma_x^m\otimes \sigma_{x+1}^n]=&\frac{1}{2}\left([\sigma_x^k,\sigma_x^m]\otimes\{\sigma_{x+1}^l,\sigma_{x+1}^n\}+\{\sigma_x^k,\sigma_x^m\}\otimes[\sigma_{x+1}^l,\sigma_{x+1}^n]\right)\\
	=&2i\left(\epsilon^{kmp}\delta^{ln}\sigma^p_{x}+\epsilon^{lnp}\delta^{km}\sigma^p_{x+1}\right).
\end{align*}
Hence for the Heisenberg Hamiltonian,
\begin{align*}
	[a,b]=&\sigma_{x-1}^k\otimes [\sigma_x^k,\sigma_x^l]\otimes\sigma_{x+1}^l=-2i\epsilon^{klm}\sigma_{x-1}^k \sigma_x^l\sigma_{x+1}^m,\\
	[a,[a,b]]=&-2i\epsilon^{klm}[\sigma_{x-1}^n\otimes\sigma_x^n,\sigma_{x-1}^k\otimes\sigma_x^l]\otimes\sigma_{x+1}^m\\
	=&4\epsilon^{klm}\left(\epsilon^{lkp}\sigma^p_{x-1}+\epsilon^{klp}\sigma^p_x\right)\sigma_{x+1}^m\\
	=&8\left(\sigma_{x}^m\sigma_{x+1}^m-\sigma_{x-1}^m\sigma_{x+1}^m\right),\\
	[b,[b,a]]=&8\left(\sigma_{x-1}^m\sigma_{x}^m-\sigma_{x-1}^m\sigma_{x+1}^m\right),\\
	a^2=&\sigma_{x-1}^k\sigma_{x-1}^l\otimes \sigma_x^k\sigma_x^l\\
	=&(\delta^{kl}+i\epsilon^{klm}\sigma^m_{x-1})\otimes (\delta^{kl}+i\epsilon^{klm}\sigma^m_x)\\
	=&3-6\sigma^m_{x-1}\sigma^m_x=3-6a,\\
	[abba]=&8[ab]=-[baab],\\
	[aaab]=&8[ab]-16i\epsilon^{klm}\sigma_{x-1}^k \sigma_x^l\sigma_{x+1}^m=16[ab]=-[bbba].
\end{align*}
The last equation is recognized as the Dolan-Grady (DG) relation\cite{PhysRevD.25.1587}, which is satisfied by the Onsager algebra~\cite{PhysRev.65.117}. While it does not hold for the XXZ Hamiltonian, \eqref{eq:GDG} can be viewed as a generalized version of the DG relation, different from the recently discovered generalized Onsager algebra by generalizing the Clifford algebra studied in \cite{Stokman:2020aa,10.21468/SciPostPhys.13.3.070}. The generalization here does not require a large dimensional local Hilbert space, but instead the DG relation is satisfied in a weaker sense. That being said, it is easy to see the key to the continuation of the pattern above in higher commutators is the Clifford nature of the Pauli algebra, so similar structures may well be observed in models with local degrees of freedom satisfying other Clifford algebras and their generalizations.

\subsection{Isotropic spin-1 chains}

The spin-1 representation of SU(2) is generated by 
\begin{equation*}
	S^1= \frac{1}{\sqrt{2}}\begin{pmatrix}
		0 & 1 & 0\\
		1 & 0 & 1\\
		0 & 1 & 0
	\end{pmatrix},\quad 	
	S^2= \frac{1}{\sqrt{2}}\begin{pmatrix}
		0 & -i & 0\\
		i & 0 & -i\\
		0 & i & 0
	\end{pmatrix},\quad 
	S^3= \begin{pmatrix}
		1 & 0 & 0\\
		0 & 0 & 0\\
		0 & 0 & -1
	\end{pmatrix}.
\end{equation*}Unlike the SU(3) model to be discussed in the next section, none of the generators here has non-vanishing 1,3 entry. But this can be compensated by including powers of the generators in the Hamiltonian, such as 
\begin{equation*}
	(S^+)^2=\frac{1}{2}(S^1+iS^2)^2=\begin{pmatrix}
		0 & 0 & 1\\
		0 & 0 & 0\\
		0 & 0 & 0
	\end{pmatrix}.
\end{equation*} Therefore, it is customary to study the integrability of the class of models 
\begin{equation}
	H_1(\theta)=\sum_x\left(\cos\theta \bm{S_x}\cdot\bm{S_{x+1}}+\sin\theta (\bm{S_x}\cdot\bm{S_{x+1}})^2\right),
\end{equation}as any SU(2) isotropic Hamiltonian of spin-$s$ can be expressed in terms of a polynomial of degree $2s$. 

Solution of the Reshetikhin condition recovers the 6 integrable parameters, $\theta=\pm\pi/4,\pm 3\pi/4,\pm\pi/2$, as recently confirmed by the exclusion of other possibilities~\cite{park2024proof}. Here it should be particularly noted that the next order integrability condition \eqref{eq:highercurrent} with $m=2$ can only be satisfied for $\theta= 3\pi/4, -\pi/4$ if the constant $c$ is included in $\check{R}_{x,x+1}^{(1)}$.

\subsection{SU($N$) chains}

As an alternative to higher spin representations of SU(2), multicomponent systems can also be described by an SU($N$) local degree of freedom. Instead of a polynomial of the SU(2) invariant $\bm{S_x}\cdot\bm{S_{x+1}}$, the Hamiltonian $H_1$ can be expressed in terms of the Gell-Mann matrices.

For general SU($N$) chains, it is more convenient to choose the basis
\begin{equation}
    (e^{(k,l)})_{m,n}=\delta_m^k\delta_n^l.
\end{equation}An SU(N) invariant chain would then be 
\begin{equation}
    H_{\mathrm{SU}(N)}=\sum_x\sum_{k,l=1}^N e_x^{(k,l)}\otimes e_{x+1}^{(l,k)}
\end{equation}Motivated by the partially integrable model studied in Ref.~\cite{PhysRevB.106.134420}, the SU($N$) symmetry can be broken to an $\mathfrak{S}_N$ permutation symmetry by introducing a diagonal potential
\begin{equation}
    H_{\mathfrak{S}_N}=\sum_x\sum_{k=1}^N\sum_{l\ne k} \left(e_x^{(k,l)}\otimes e_{x+1}^{(l,k)}+\Delta e_x^{(k,k)}\otimes e_{x+1}^{(k,k)}\right).
\end{equation}
Reshetikhin's condition is only satisfied if $\Delta=\pm 1$. This confirms the non-integrability of the Hamiltonian for generic $\Delta$ shown in Ref.~\cite{PhysRevB.106.134420} by the violation of the YBE.
