\begin{corollary}
For any $\theta\in(0, 1]$ the function $y_\be(x)$ admits the following  continued exponential representation:
 \beq
     y_\be(x) =  \dots\(1 -\exp\( -x\cdot \( 1 -\exp\(-x\cdot (1- e^{-x\theta})^\al\) \)^\al \) \)^\al \dots  \label{eq:gL_cem}
 \eeq
 where $\al=\be^{-1}\in (0, 1)$.
\end{corollary}

  \section{Asymptotic behaviour of  function $y_\be(x)$.}\label{sec:asympt_gLf}
  In this section, we consider the asymptotic behaviour of $y_\be(x)$ for both small  and  large values of argument $x$.
  First,  we construct the following asymptotic expansion for  function $y_\be(x)$ in the right-hand 
  neighbourhood of $0$.
  \begin{proposition}
  The function, $y_\be(x)$, has the following asymptotic on the lower tail: %%  $x\to 0$:
  \beq 
         y_\be(x) = \frac{ x^{\frac{1}{\be-1}}}{  1 + \frac{ x^{\frac{\be+1}{\be -1}}}{2(\be-1)}  } + o\(x^{\frac{\be+2}{\be-1}}\)
         \quad\text{as $x\downarrow 0$}.  \label{eq:asymp_y}
   \eeq   
  \end{proposition}
  \begin{proof}
  We have %% from (\ref{eq:gLf_def})
  $$  1 - e^{-xy_\be} = xy_\be - \frac12 x^2 y_\be^2 +o(x^2). $$
  %% Then we obtain from 
  Let us rewrite Equation~(\ref{eq:ybe_def}) as
  $$
    y^\be = 1 - e^{-xy},    \quad x>0,   
 $$
 Then we obtain from the latter equation that
  \beq 
      \(y_\be(x)\)^{\be -1} = x\cdot\(1-\frac12 x y_\be(x) + o(x)\).   \label{eq:y_bet} 
 \eeq
 Let $\ga\bydef \be-1$. Since $\be>1$, the parameter $\ga$ is positive and hence, we get for 
 small $t$ that   $ \( 1 - t\)^{\ga}= 1- \ga t + o(t). $

  From (\ref{eq:y_bet}) and the latter asymptotic formula we obtain that $y_\be(x)$ satisfies the following relation:
  $$ y_\be(x) = x^{\frac{1}{\be-1}}\( 1 -\frac{1}{2(\be-1)} x y_\be(x) + o\(x^{\frac{1}{\be-1}}\)\).  $$
  Then we derive that
  $$ y_\be(x)\cdot \( 1 + \frac{ x^{\frac{\be}{\be -1}}}{2(\be-1)} \) =  x^{\frac{1}{\be-1}} +  o\(x^{\frac{2}{\be-1}}\), $$
  and, finally,
  $$ y_\be(x) = \frac{ x^{\frac{1}{\be-1}}}{  1 + \frac{ x^{\frac{\be}{\be -1}}}{2(\be-1)}  } +  o\(x^{\frac{2}{\be-1}}\). $$
  The proposition is thus proved.
  \end{proof}
  The asymptotics (\ref{eq:asymp_y}) of $y_\be(x)$, as $x\!\to\! 0$, is just a starting point. It can be improved as follows:
   \begin{proposition}\label{prop:asympt_y1}
  The function, $y_\be(x)$ admits  the following  asymptotic expansion as   $x\dar 0$:
  {\small
