  \noindent Numerical comparison of the approximations (\ref{eq:asymp_y}) and (\ref{eq:asymp_y1}) and the lower bound, $y_L(x)$, introduced in Proposition~\ref{prop:bounds_y},  is discussed in Section~\ref{sec:numerics}.  

  %% The following proposition provides  simple non-uniform  upper and  lower bounds for    function $y_\be(x)$.                                                        
  \begin{proposition}\label{prop:bounds_y}
   For $x>0$ and $\be>1$,
  the function $y_\be(x)$ satisfies the following two-sided inequality:
  \beq
      \(1 - e^{-x}\)^{\frac{1}{\be-1}} < y_\be(x)<   \(1 - e^{-x}\)^{\frac{1}{\be}} \label{eq:ineq}
   \eeq
        \end{proposition}
        \begin{proof}
        It follows from the definition of the inverse function that
        $$ x = y_\be^{\be-1} + \frac12  y_\be^{2\be-1} + \frac13  y_\be^{3\be-1} + \dots $$
        Since $0<y_\ast<1$, we have
        $$ x < y_\be^{\be-1} + \frac12  y_\be^{2\be-2} + \frac13  y_\be^{3\be-3} + \dots $$
        The latter inequality can be written as
        $$ x < -\log\( 1 - y_\be^{\be-1}\). $$
        Therefore,
        $$ y_\be(x) >\( 1- e^{-x}\)^{\frac{1}{\be-1}}.  $$
        On the other hand, since
        $$ x = -\frac{\log(1-y_\be^\be)}{y_\ast} \quad\text{and} \quad 0<y_\be<1, $$
        we obtain that
        $$ x >  -\log(1-y_\be^\be) $$
      The latter inequality is equivalent to 
      $ y_\be(x) < \( 1- e^{-x}\)^{\frac{1}{\be}}.  $
      The upper bound, $y^U(x)= \( 1- e^{-x}\)^{\al}$, and the lower bound,
       $ y_L(x)= \( 1- e^{-x}\)^{\frac{\al}{1-\al}}$, hence established. %% derived.
        \end{proof}

