    We would like to verify the following sufficient condition for the moments   of the
    probability measure concentrated on $\R^1_+$ (see \cite{Krein}, \cite{Schmu}, \cite{Shir} ):
    \beq
     \limsup_{n\to\iy} \frac{M_n^{1/n}}{n}< \iy \label{eq:mom_cond}
    \eeq 
    From (\ref{eq:asympt_M_n}) we derive that as $n\to\iy$
    $$ M_n = c_\be \sqrt{2\pi n} \cdot \( \frac{n}{e}\)^n + o(n!). $$  
    Then we find that
    $$ \limsup_{n\to\iy}  \frac{M_n^{1/n}}{n} = {\mathcal{O}}(1). $$
    The latter asymptotic equation implies (\ref{eq:mom_cond}), as was to be proved.\end{proof}
    \begin{remark}
    One can also use  Carleman's test (see \cite{Krein}, \cite{Schmu}, \cite{Shir} ) to verify that the sequence
    of moments, $\{M_n\}_{n\ge 1}$ is determinate.
    \end{remark}

%%Moment Problem has a unique solution
\subsection{Moments, generating function and identities}
We conclude this section with a few remarks on the connection between the moments of the r.v. $\xi_\be$ and the 
generating functions of several remarkable sequences including the sequence $\{ \zeta(n)\}_{n\ge 2}$, where
$\zeta(\cdot)$ is the Riemann zeta function.

Let us start with the second moment, $\E[\xi_\be^2]$. From (\ref{eq:m2}) we have
\beq  \E[\xi^2_{1/\al}] = \al \cdot \mcI(\al),  \label{eq:E2_alf}  \eeq
where
$$  \mcI(\al)=  \int_0^1 t^{-1 -\al}\log^2(1-t)\d t.  $$
\begin{proposition}\label{prop:int_mom}
The integral, $\mcI(\al)$, satisfies the relation
\beq
    \mcI(\al) = \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{k+m-\al}, \qquad 0<\al <1.
       \label{eq:m3}
\eeq
\end{proposition}
Proposition~\ref{prop:int_mom} is proved in the Appendix.

Let us now represent the integral, $\mcI(\al)$, as the  generating function of a  harmonic                                                                                                                                                                                                                                                                                                                                                                                                              sequence. Denote by $H_n$,  the sum of the harmonic series
$$H_n=1 + \frac12 + \frac13 + \dots + \frac1n, \quad n=1, 2, \dots, $$
and for  $n=0$ we define $H_0=0$. Obviously, we have 
$$ H_n = H_{n-1} + \frac1n, \quad n=1, 2, \dots. $$
Let us now define the sequence
\beq
     A_\ell \bydef 2\cdot \sum_{n=1}^\iy \frac{H_{n-1}}{n^{\ell+2}}, \quad \ell=0, 1, 2, \dots.  \label{eq:A_ell}
  \eeq   
\begin{proposition}\label{prop:gen_fun_A}
The elements of the sequence $\{ A_\ell\}_{\ell\ge 1}$ satisfy the relation
 \beq
     A_\ell=  \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{(k+m)^{\ell + 1}},
  \quad \ell=0, 1, 2, \dots.  \label{eq:ident1}
  \eeq
The integral $\mcI(\al)$ is the generating function of the sequence $\{ A_\ell\}_{\ell\ge 1}$:
\beq
   \mcI(\al) =  \sum_{\ell=0}^\iy A_\ell \al^{\ell}. \label{eq:gf_Al}
  \eeq  
   \end{proposition}
The proof of Proposition~\ref{prop:gen_fun_A} is deferred to the Appendix.

The double sums similar to (\ref{eq:ident1}) are usually called {\it Tornheim series or Tornheim double sums}. 
They find applications in many
 areas of mathematics and physics, see  \cite{Kub},  \cite{Torn}.

\begin{remark}
The sequence $\{A_\ell\}_{\ell\ge 0}$ can also be expressed in terms of the Riemann zeta function as
follows %%  written as
$$ A_\ell = 2 \sum_{n=1}^\iy  \frac{H_n}{n^{\ell+2}} - 2\zeta(\ell+3). $$
\end{remark}
The coefficient, $A_0$, determines  the asymptotic behaviour of the second moment as $\al\dar 0$.
\begin{proposition}\label{prop:A0}
\beq
    A_0=2\zeta(3) =  2.404138\dots .  \label{eq:A0}
    \eeq
    \end{proposition}
    The proof of this proposition is deferred to the Appendix.
    \begin{corollary}
        The variance of the r.v. $\xi_\be$ admits  the following asymptotics as $\al\downarrow 0$: % relation 
        $$ \si^2(\xi_\be) = A_0\cdot\al + o(\al). $$
    \end{corollary}
    \begin{proof}
    The statement of the corollary immediately follows from Equations (\ref{eq:E2_alf}) and (\ref{eq:gf_Al}).
    \end{proof}
    Computation of the coefficients, $A_1$, $A_2$, ..., $A_N$ requires computation of the harmonic sums 
    $$ \mcS_k = \sum_{n=1}^\iy \frac{H_n}{n^k},\quad  k=2, 3, \dots. $$
    \begin{corollary}[compare with \cite{AliD},  \cite{Flaj}]
    $$ $$
    \begin{itemize}
    \item[i.] 
    The coefficient $A_1$ satisfies the relation
    $$ A_1 = 2 \sum_{k=1}^\iy \frac{H_k}{k^3} - 2 \zeta(4)=\frac{\pi^4}{180}.  $$
    \item[ii.] The harmonic sum
    $$ \sum_{k=1}^\iy \frac{H_k}{k^3}=\frac{\pi^4}{72}. $$
    \end{itemize}
    \end{corollary}
    Numerous representations of such character  for  harmonic sums can also be found in \cite{Flaj}.

    Analysis of the higher moments of $\xi_\be$ leads to relations generalizing properties  of 
    harmonic double sums. This line of research will be considered in our subsequent work.  %elsewhere.

