\section{Proof of Technical Results}
\begin{proof}[Proof of Proposition~{\rm \ref{prop:asympt_y1}}]
  Let us represent the function, $y_\be$, as 
  \beq   y_\be(x) \bydef x^{\frac{1}{\be-1} } \cdot \hat z(x).   \label{eq:y_z} \eeq
  Then, obviously,
  $$ \hat z(x) =  y_\be(x) \cdot x^{\frac{1}{1-\be} } .  $$
  From Equation~(\ref{eq:asymp_y}) it follows that the limit
  $$ \lim_{x\dar 0} \hat z(x) =1.  $$
It is convenient to introduce the variable $t\bydef x^{\frac{\be}{\be -1} }$. 
Denote by $z(t)\bydef \hat z(x)$. Then we obtain that the function $z(t)$
satisfies the implicit equation
\beq
    z^{\be-1}(t) = 1 - \frac12 z(t)\cdot t + \frac16 (z(t)\cdot t)^2 -\frac1{24} (z(t)\cdot t)^3 + \dots \label{eq:z_t}
\eeq
Let us represent the function $z(t)$ in the following form:
\beq 
    z(t)\bydef 1 + \sum_{n=1}^\iy z_n t^n.  \label{eq:z_expan}
 \eeq   
Then substituting (\ref{eq:z_expan}) into (\ref{eq:z_t}), we recursively derive the first coefficients in  Expansion (\ref{eq:z_expan}):
$$
     z_1 = -\frac{1}{2(\be -1)}, \quad z_2 = \frac{\be+8}{24(\be-1)^2}, \quad 
     z_3 = -\frac{\be + 3}{12(\be -1)^3}.
$$
The proposition is thus proved.
 \end{proof}
\begin{proof}[Proof of Lemma~{\rm \ref{lem:mom_Mn}}]
We have to prove that the moments $M_n$ have the following asymptotics: 
$$
    M_n =c_\be\cdot n! + o\({n!}\) \quad \text{as $n\to \iy$},  
  $$
  where the constant $c_\be$ satisfies the inequality $\frac{1}{\be} < c_\be < \frac{1}{\be - 1}.$
  Since the support of the measure $\mu$ is $\R^1_+$, the $n^{th}$ moment, $M_n$,  can be evaluated as follows:
$$
    M_n = n \int_0^\iy x^{n-1} \bar F(x) \d x,   
$$
where the survival function $\bar F(x)=\mu([x, +\iy))$. Therefore,
\beq M_n =n \int_0^\iy x^{n-1} \bar y_\be(x) \d x,   \label{eq:mom_tail} \eeq
where $\bar y_\be(x) = 1 - y_\be(x)$. Combining (\ref{eq:ineq}) and (\ref{eq:mom_tail}) we derive the inequalities
\beq  \int_0^\iy \!x^{n-1}\! \(1 - (1 - e^{-x})^{1/\be}\) \!\d x < \!\frac{M_n}{n}\! < 
         \int_0^\iy \!x^{n-1}\! \(1 - (1 - e^{-x})^{\frac{1}{\be-1}}\)\! \d x. \label{eq:ineq_Mn}
     \eeq    
 Next, consider the integral
 $$ \mcJ(\ga)\bydef  n \int_0^\iy x^{n-1} \(1 - (1 - e^{-x})^{1/\ga}\) \d x, \quad \ga>0.  $$
 Taking into account that
 $$  (1 - e^{-x})^{1/\ga} = 1 -\frac1\ga e^{-x} + \frac{1-\ga}{2\ga^2} e^{-2x} + o\(e^{-2x}\) $$
 as $x\to\iy $, we obtain the following asymptotic relation as $n\to\iy$
 \beq 
     \mcJ(\ga) = \frac1\ga n \Gamma(n) - \frac{n\cdot \Gamma(n)}{2^n} \frac{1-\ga}{ \ga^2} + o\(\frac{n!}{2^n}\), 
 \label{eq:asympt_J}
 \eeq
 where $\Gamma(n) $ is the Gamma function. Then from (\ref{eq:ineq_Mn}) and (\ref{eq:asympt_J}) we obtain
 that
 $$ \limsup_{n\to\iy} \frac{M_n}{n!} =c_\be, \quad \frac1{\be}\le c_\be \le\frac{1}{\be-1}. $$
 The lemma is thus proved.
\end{proof}

\begin{proof}[Proof of Proposition~{\rm \ref{prop:int_mom}}]
Recall the representation of the function $\log(1-t)$ by the following convergent series:
$$-\log(1-t) = \sum_{k=1}^\iy \frac{t^k}{k}, \quad 0\le t < 1. $$
Hence, the integral $\mcI(\al)$ can be written as follows:
$$  \mcI(\al)=  \int_0^1 t^{-1 -\al} \sum_{k=1}^\iy \frac{t^k}{k} \cdot \sum_{m=1}^\iy  \frac{t^m}{m} \d t.  $$
The latter relation implies that
\begin{eqnarray*}
      \mcI(\al) &=&  \int_0^1 t^{-1 -\al} \sum_{k=1}^\iy \frac{t^k}{k} \cdot \sum_{m=1}^\iy  \frac{t^m}{m} \d t \\  
      &=& \sum_{k=1}^\iy \frac{1}{k} \cdot \sum_{m=1}^\iy \frac{1}{m} \int_{0}^1 t^{k+m-\al-1} \d t \\
      &=&  \sum_{k=1}^\iy \sum_{m=1}^\iy \frac{1}{k\cdot m\cdot (k+m-\al)}.
   \end{eqnarray*}   
The proposition is thus proved.
\end{proof}
\begin{proof}[Proof of Proposition~{\rm \ref{prop:gen_fun_A}}]
Consider the double sum in  (\ref{eq:m3}). We have that for  $0<\al < 1$, 
$$
    \frac{1}{k+m-\al} = \frac1{k+m} \cdot \sum_{\ell=0}^\iy \frac{\al^\ell}{(k+m)^\ell}.
$$
Then we derive that
\begin{eqnarray*}
    \mcI(\al) &=& \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{k+m-\al}  \\
    &=& \sum_{\ell=0}^\iy \al^\ell \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{(k+m)^{\ell + 1}}.
     \end{eqnarray*}   
    The latter relation implies (\ref{eq:ident1}). Now, consider  the inner double sum,
    $$ A_\ell= \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{(k+m)^{\ell + 1}}. $$
Changing the summation index, $n=k+m$, we obtain that
  \begin{eqnarray*}
     A_\ell &=&  \sum_{k=1}^\iy \sum_{m=1}^\iy \frac1k\cdot \frac1m \cdot \frac{1}{(k+m)^{\ell + 1}} \\
    %% &=&  \sum_{n=2}^\iy \frac{1}{n^{\ell + 1}}\sum_{k=1}^{n-1} \(\frac1k + \frac{1}{n-k}\)  \\ 
    &=&  \sum_{n=2}^\iy \frac{1}{n^{\ell+2}} \sum_{k=1}^{n-1} \(\frac1k + \frac{1}{n-k}\).
 \end{eqnarray*}   
 It is obvious that the latter sum is equal to $2 H_{n-1}$. Therefore,
 $$  \mcI(\al) = 2\sum_{\ell=0}^\iy \al^\ell \sum_{n=2}^\iy \frac{H_{n-1}}{n^{\ell+2}}.  $$
 From the definition of the sequence $A_\ell$ (see Equation~(\ref{eq:A_ell})) we obtain that
 $$ \mcI(\al) = \sum_{\ell=0}^\iy A_\ell \al^{\ell }, $$ as was to be proved.
 \end{proof}
