\begin{theorem}[FLMD Impact on Convergence]\label{thm:convergence}
Considering the impact of FLMD on convergence, the global loss reduction after $t$ communication rounds is bounded by:
\begin{multline}
\mathbb{E}[F(\omega[t + 1], \mathcal{N}) - F(\omega^*)] \leq \\
\left(1 - \frac{\mu}{L}\right)^t \mathbb{E}[F(\omega[1], \mathcal{N}) - F(\omega^*)] \\
+ \frac{1}{2L} \sum_{i=1}^{t} \left(1 - \frac{\mu}{L}\right)^{t-i} \mathbb{E}[\|e[i]\|^2], \label{eq:convergence_bound}
\end{multline}
where the learning rate satisfies $\xi = \frac{1}{L}$.
\end{theorem}

