\subsection*{Proof of Lemma 3}
\begin{proof}
We define a random variable $X$ as:
\begin{equation}
X = \frac{1}{K}\sum_{n\in\mathcal{S}[t]}\zeta_n\nabla f_n(\omega[t]) - \frac{1}{N}\sum_{n\in\mathcal{N}}\zeta_n\nabla f_n(\omega[t]).
\end{equation}
Since $F_r(\omega[t]) = \frac{1}{N}\sum_{i=1}^N f_r(\omega[t])$, we have:
\begin{equation}
    \begin{split}
        &\mathbb{E}[\|e[t]\|^2] = \mathbb{E}[\|X\|^2] \\
        &= \mathbb{E}\left[\left\|\frac{1}{K}\sum_{n\in\mathcal{S}[t]}\zeta_n\nabla f_n(\omega[t]) - \nabla F(\omega[t], \mathcal{N})\right\|^2\right].
    \end{split}
\end{equation}
By analyzing the variance of the cluster sampling estimator with unequal cluster sizes and applying the Cauchy-Schwarz inequality, we obtain the result.
\end{proof}

\subsection*{Proof of Theorem 4}
\begin{proof}
According to the Lipschitz smoothness property in \textbf{Assumption 1}, we have:
\begin{multline}
\frac{1}{2L}\|\nabla F(\omega[t], \mathcal{N}) - \nabla F(\omega[t+1], \mathcal{N})\|^2 \leq \\
F(\omega[t+1], \mathcal{N}) - F(\omega[t], \mathcal{N}) + \\
[\nabla F(\omega[t], \mathcal{N})^{\mathrm{T}}(\omega[t] - \omega[t+1])] \\
\leq \frac{L}{2}\|\omega[t] - \omega[t+1]\|^2.
\end{multline}
From Eq. \eqref{eq:global model} and the definition of $e[t]$, we have:
\begin{equation}
\begin{split}
\omega[t] - \omega[t+1] &= \xi\nabla F(\omega[t], \mathcal{S}[t]) \\
&= \xi[\nabla F(\omega[t], \mathcal{N}) + e[t]].
\end{split}
\end{equation}
Substituting this into the previous inequality:
\begin{align*}
F&(\omega[t+1], \mathcal{N}) \leq F(\omega[t], \mathcal{N}) \\
&- \xi\nabla F(\omega[t], \mathcal{N})^{\mathrm{T}}[\nabla F(\omega[t], \mathcal{N}) + e[t]] \\
&+ \frac{\xi^2 L}{2}\|\nabla F(\omega[t], \mathcal{N}) + e[t]\|^2 \\
&= F(\omega[t], \mathcal{N}) - \xi\|\nabla F(\omega[t], \mathcal{N})\|^2 \\
&- \xi\nabla F(\omega[t], \mathcal{N})^{\mathrm{T}} e[t] + \frac{\xi^2 L}{2}[\|\nabla F(\omega[t], \mathcal{N})\|^2 \\
&+ \|e[t]\|^2 + 2\nabla F(\omega[t], \mathcal{N})^{\mathrm{T}} e[t]].
\end{align*}
With learning rate $\xi = \frac{1}{L}$, this simplifies to:
\begin{equation}
\begin{split}
F(\omega[t+1], \mathcal{N}) \leq & F(\omega[t], \mathcal{N}) - \frac{1}{2L}\|\nabla F(\omega[t], \mathcal{N})\|^2 \\
&+ \frac{1}{2L}\|e[t]\|^2.
\end{split}
\end{equation}
By subtracting $F(\omega^*)$, taking expectations, and applying \textbf{Assumption 2}:
\begin{align*}
\mathbb{E}&[F(\omega[t+1], \mathcal{N}) - F(\omega^*)] \leq \\
&\mathbb{E}[F(\omega[t], \mathcal{N}) - F(\omega^*)] - \frac{1}{2L}\mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \\
&+ \frac{1}{2L}\mathbb{E}[\|e[t]\|^2] \\
&\leq \left(1 - \frac{\mu}{L}\right)\mathbb{E}[F(\omega[t], \mathcal{N}) - F(\omega^*)] + \frac{1}{2L}\mathbb{E}[\|e[t]\|^2].
\end{align*}
Applying this recursively and summing over $t$, we obtain the bound.
\end{proof}

\subsection*{Proof of Theorem 5}

\begin{proof}
From Lemma 3, we can upper bound the deviation term by taking the maximum over all vehicles:
\begin{equation}
\mathbb{E}[\|e[t]\|^2] \leq \frac{(1-\frac{K}{N})\gamma^2}{K(N-1)\bar{\zeta}^2} \leq \frac{(1-\frac{K}{N})\gamma^2}{K\bar{\zeta}^2}.
\end{equation}

Starting from the general convergence bound, we have:
\begin{multline}
\mathbb{E}[F(\omega[t+1], \mathcal{N}) - F(\omega^*)] \leq \\
\left(1 - \frac{\mu}{L}\right)^t\mathbb{E}[F(\omega[1], \mathcal{N}) - F(\omega^*)] \\
+ \frac{1}{2L}\sum_{i=1}^{t}\left(1 - \frac{\mu}{L}\right)^{t-i}\mathbb{E}[\|e[i]\|^2].
\end{multline}

Substituting our bound on $\mathbb{E}[\|e[i]\|^2]$:
\begin{multline}
\mathbb{E}[F(\omega[t+1], \mathcal{N}) - F(\omega^*)] \leq \\
\left(1 - \frac{\mu}{L}\right)^t\mathbb{E}[F(\omega[1], \mathcal{N}) - F(\omega^*)] \\
+ \frac{1}{2L}\sum_{i=1}^{t}\left(1 - \frac{\mu}{L}\right)^{t-i}\frac{(1-\frac{K}{N})\gamma^2}{K\bar{\zeta}^2}.
\end{multline}

Factoring out constants from the summation:
\begin{multline}
= \left(1 - \frac{\mu}{L}\right)^t\mathbb{E}[F(\omega[1], \mathcal{N}) - F(\omega^*)] \\
+ \frac{(1-\frac{K}{N})\gamma^2}{2LK\bar{\zeta}^2}\sum_{i=1}^{t}\left(1 - \frac{\mu}{L}\right)^{t-i},
\end{multline}
which completes the proof.
\end{proof}


\subsection*{Proof of Theorem 7}

\begin{proof}
Let $\mathcal{M}_{a}[t] = \{n \in \mathcal{N} : \Theta_n[t] \leq \Lambda_{\Theta}[t]\}$ (eligible vehicles with adaptive threshold) and $\mathcal{M}_{f}[t] = \{n \in \mathcal{N} : \Theta_n[t] \leq \Lambda_{\Theta}^{\min}\}$ (eligible vehicles with fixed threshold). Since $\Lambda_{\Theta}[t] \geq \Lambda_{\Theta}^{\min}$, we have $\mathcal{M}_{f}[t] \subseteq \mathcal{M}_{a}[t]$.

From Lemma 3, the deviation bound for the adaptive case becomes:
\begin{multline}
\mathbb{E}[\|e_{a}[t]\|^2] \leq \\
\frac{(1-\frac{K}{N})\sum_{n\in\mathcal{M}_{a}[t]}\zeta_n^2\|\nabla f_n(\omega[t])-\nabla F(\omega[t], \mathcal{N})\|^2}{K(N-1)\left(\frac{1}{N}\sum_{n\in\mathcal{N}}\zeta_n\right)^2}
\end{multline}

\begin{multline}
\leq \frac{|\mathcal{M}_{a}[t]|}{|\mathcal{M}_{f}[t]|} \cdot \\
\frac{(1-\frac{K}{N})\sum_{n\in\mathcal{M}_{f}[t]}\zeta_n^2\|\nabla f_n(\omega[t])-\nabla F(\omega[t], \mathcal{N})\|^2}{K(N-1)\left(\frac{1}{N}\sum_{n\in\mathcal{N}}\zeta_n\right)^2} \\
= \rho[t] \cdot \mathbb{E}[\|e[t]\|^2],
\end{multline}
where the second inequality uses the fact that vehicles in $\mathcal{M}_{a}[t] \setminus \mathcal{M}_{f}[t]$ have bounded FLMD values.

From the general convergence bound, we have:
\begin{multline}
\mathbb{E}[F(\omega[t+1], \mathcal{N}) - F(\omega^*)] \leq \\
\left(1 - \frac{\mu}{L}\right)^t\mathbb{E}[F(\omega[1], \mathcal{N}) - F(\omega^*)] \\
+ \frac{1}{2L}\sum_{i=1}^{t}\left(1 - \frac{\mu}{L}\right)^{t-i}\mathbb{E}[\|e[i]\|^2].
\end{multline}

For the adaptive threshold case, we replace $\mathbb{E}[\|e[i]\|^2]$ with $\mathbb{E}[\|e_a[i]\|^2]$ in the deviation term. Using our established bound $\mathbb{E}[\|e_a[i]\|^2] \leq \rho[i] \cdot \mathbb{E}[\|e[i]\|^2]$, the convergence analysis applies directly with the adaptive threshold mechanism, yielding the desired result.
\end{proof}


\subsection*{Proof of Theorem 8}

\begin{proof}
Under local smoothness, the Lipschitz condition holds within $\mathcal{B}_R(\omega^*)$. Using concentration inequalities, we can show that with probability $1-\delta$, the iterates remain within the smoothness region, guaranteeing convergence.

Let $X_t = \|\omega[t] - \omega^*\|$ denote the distance from the optimal point at iteration $t$. From the algorithm update rule and local smoothness property:
\begin{equation}
X_{t+1} \leq X_t - \xi\|\nabla F(\omega[t], \mathcal{N})\|^2/L + \xi\|e[t]\|.
\end{equation}

By Azuma's inequality, since $\|e[t]\|$ has bounded differences, we have:
\begin{equation}
\mathbb{P}\left(\sum_{t=1}^T \xi\|e[t]\| \geq \epsilon/2\right) \leq \exp\left(-\frac{(\epsilon/2)^2}{2T\xi^2\sigma^2}\right),
\end{equation}
where $\sigma^2$ is the variance bound of $\|e[t]\|$.

Setting $\xi \leq \frac{\epsilon}{2LT\sqrt{\log(1/\delta)}}$ and using $\sigma^2 \leq L^2$, we get:
\begin{equation}
\mathbb{P}\left(\sum_{t=1}^T \xi\|e[t]\| \geq \epsilon/2\right) \leq \delta/2.
\end{equation}

Similarly, the gradient descent progress ensures:
\begin{equation}
\mathbb{P}\left(\sum_{t=1}^T \xi\|\nabla F(\omega[t], \mathcal{N})\|^2/L \geq \epsilon/2\right) \leq \delta/2.
\end{equation}

By union bound, with probability $1-\delta$:
\begin{equation}
X_T \leq X_0 - \epsilon/2 + \epsilon/2 = R - \epsilon \leq R,
\end{equation}
ensuring the iterates remain within the smoothness region.
\end{proof}


\subsection*{Proof of Theorem 9}

\begin{proof}
Following standard analysis for non-convex optimization, we telescope the smoothness inequality and apply Jensen's inequality to obtain the convergence rate to stationary points.

From the smoothness property (Assumption 1):
\begin{multline}
F(\omega[t+1], \mathcal{N}) \leq F(\omega[t], \mathcal{N}) \\
+ \nabla F(\omega[t], \mathcal{N})^T(\omega[t+1] - \omega[t]) \\
+ \frac{L}{2}\|\omega[t+1] - \omega[t]\|^2.
\end{multline}

Substituting $\omega[t+1] - \omega[t] = -\xi(\nabla F(\omega[t], \mathcal{N}) + e[t])$:
\begin{multline}
F(\omega[t+1], \mathcal{N}) \leq F(\omega[t], \mathcal{N}) - \xi\|\nabla F(\omega[t], \mathcal{N})\|^2 \\
- \xi\nabla F(\omega[t], \mathcal{N})^Te[t] \\
+ \frac{\xi^2L}{2}\|\nabla F(\omega[t], \mathcal{N}) + e[t]\|^2.
\end{multline}

Expanding the last term and using $\xi = 1/L$:
\begin{multline}
F(\omega[t+1], \mathcal{N}) \leq F(\omega[t], \mathcal{N}) \\
- \frac{1}{2L}\|\nabla F(\omega[t], \mathcal{N})\|^2 + \frac{1}{2L}\|e[t]\|^2.
\end{multline}

Rearranging and taking expectations:
\begin{multline}
\mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \leq \\
2L(\mathbb{E}[F(\omega[t], \mathcal{N})] - \mathbb{E}[F(\omega[t+1], \mathcal{N})]) \\
+ \mathbb{E}[\|e[t]\|^2].
\end{multline}

Summing over $t = 1, \ldots, T$:
\begin{multline}
\sum_{t=1}^T \mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \leq \\
2L(\mathbb{E}[F(\omega[1], \mathcal{N})] - \mathbb{E}[F(\omega[T+1], \mathcal{N})]) \\
+ \sum_{t=1}^T \mathbb{E}[\|e[t]\|^2].
\end{multline}

Since $F(\omega[T+1], \mathcal{N}) \geq F^*$:
\begin{equation}
\sum_{t=1}^T \mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \leq 2L(F(\omega[0]) - F^*) + \sum_{t=1}^T \mathbb{E}[\|e[t]\|^2].
\end{equation}

Dividing by $T$ and taking the minimum:
\begin{multline}
\min_{t=1,\ldots,T} \mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \\
\leq \frac{1}{T}\sum_{t=1}^T \mathbb{E}[\|\nabla F(\omega[t], \mathcal{N})\|^2] \\
\leq \frac{2L(F(\omega[0]) - F^*) + \sum_{t=1}^T \mathbb{E}[\|e[t]\|^2]}{T},
\end{multline}
which completes the proof.
\end{proof}

\subsection*{Proof of Theorem 10}
\begin{proof}
From the definition of FLMD and Eq. (4):
\begin{align*}
\Theta_n[t] &= \frac{\|\omega_n[t] - \omega[t]\|}{\|\omega[t]\|} \\
&= \frac{\left\|\omega[t] - \frac{\xi}{\zeta_n}\sum_{i=1}^{\zeta_n}\nabla\ell(\omega[t]; \mathbf{x}_{n,i}, y_{n,i}) - \omega[t]\right\|}{\|\omega[t]\|} \\
&= \frac{\left\|\frac{\xi}{\zeta_n}\sum_{i=1}^{\zeta_n}\nabla\ell(\omega[t]; \mathbf{x}_{n,i}, y_{n,i})\right\|}{\|\omega[t]\|} \\
&= \frac{\xi\|\nabla f_n(\omega[t])\|}{\|\omega[t]\|}.
\end{align*}
Using the Lipschitz continuity of gradients:
\begin{align*}
\|\nabla f_n(\omega[t])\| &\leq \|\nabla f_n(\omega[t]) - \nabla f_n(\omega^*)\| + \|\nabla f_n(\omega^*)\| \\
&\leq L\|\omega[t] - \omega^*\| + \|\nabla f_n(\omega^*)\|.
\end{align*}
Therefore:
\begin{equation}
\Theta_n[t] \leq \frac{\xi(L\|\omega[t] - \omega^*\| + \|\nabla f_n(\omega^*)\|)}{\|\omega[t]\|}.
\end{equation}
\end{proof}

\subsection*{Proof of Theorem 17}
\begin{proof}
Under high SNR, we can approximate $2^{\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B}} - 1 \approx 2^{\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B}}$. The energy constraint becomes:
\begin{equation}
\kappa \mu \zeta_n (\chi_n^* G_n)^2 + \delta_n^{\mathrm{tx}} \frac{2^{\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B}}}{|h_n|^2} = e_n^{\max}.
\end{equation}

Solving for $2^{\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B}}$:
\begin{equation}
2^{\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B}} = \frac{(e_n^{\max} - \kappa \mu \zeta_n (\chi_n^* G_n)^2)|h_n|^2}{\delta_n^{\mathrm{tx}}}.
\end{equation}

Taking logarithms:
\begin{equation}
\frac{D_n[t]}{\delta_n^{\mathrm{tx}} B} = \log_2\left(\frac{(e_n^{\max} - \kappa \mu \zeta_n (\chi_n^* G_n)^2)|h_n|^2}{\delta_n^{\mathrm{tx}}}\right).
\end{equation}

Rearranging to solve for $\delta_n^{\mathrm{tx}}$:
\begin{equation}
\delta_n^{\mathrm{tx}} = \frac{D_n[t]}{B \log_2\left(1 + \frac{e_n^{\max} |h_n|^2}{\kappa \mu \zeta_n (\chi_n^* G_n)^2}\right)},
\end{equation}

which completes the proof.
\end{proof}

\section*{Appendix B: Complete Implementation Specifications}

Our TSFEN architecture consists of three main components with the following specifications:
\begin{itemize}
\item Multi-Head Self-Attention: $d_{\text{model}} = 64$, $h = 8$ heads, input shape $(B, M=5, N=20, 64)$
\item LSTM Component: $d_{\text{hidden}} = 128$, bidirectional processing
\item Actor-Critic Networks: Linear layers $(128 \to 128 \to 20)$ with ReLU activation
\end{itemize}

The training configuration for our MAPPO implementation includes:
\begin{itemize}
\item MAPPO: $\beta = 10^{-4}$, $\gamma = 0.98$, $\lambda = 0.95$, $\epsilon = 0.2$
\item Batch size: 32 trajectories, Episodes per update: 10, Total episodes: 500
\item State representation: $s_{k,m}[t] = (\Theta_n[t], |h_n|^2, \Delta_n[t])$ for $n \in \mathcal{N}$
\end{itemize}

For the Lagrangian dual decomposition implementation, we specify:
\begin{itemize}
\item Numerical solver: scipy.optimize.brentq with tolerance $\epsilon = 10^{-6}$
\item Maximum iterations: 100, Search interval: $[\frac{D_n[t]}{B \log_2(1 + P_n |h_n|^2)}, \delta_{\max}]$
\end{itemize}

Our implementation environment comprises:
\begin{itemize}
\item Hardware: NVIDIA RTX 5070Ti with CUDA 12.8
\item Software: PyTorch 1.12.0, Python 3.10, scipy.optimize for numerical solving
\item Memory requirement: $\sim 2.3$ GB for $N=20, K=6$ configuration
\end{itemize}

Critical implementation details include:
\begin{itemize}
\item Numerical stability: Action probabilities clamped to $[10^{-7}, 1.0]$ and renormalized
\item FLMD computation: $\Theta_n[t] = \frac{\xi \|\nabla f_n(\omega[t])\|}{\|\omega[t]\|}$ after each local training step
\item Adaptive masking: Element-wise multiplication with mask vector before softmax
\item Vehicle dynamics: Updated using Eqs. (10)-(11) with $\tau = 1$s per communication round
\end{itemize}


\section*{Appendix C: Edge Device Feasibility Analysis}

Our framework is designed for realistic vehicular edge computing platforms:
\begin{itemize}
\item Mobile terminals: Raspberry Pi 5-based edge devices with ARM Cortex-A76 quad-core processor (2.4 GHz), 8 GB LPDDR4X-4267 SDRAM, and 64 GB microSD storage
\item Communication subsystem: NI USRP-2900 units (1 Tx/1 Rx, 56 MHz bandwidth) for vehicular communication, along with ROS2-compatible Lidar and 3D depth cameras
\item Platoon leader: NI USRP-2955 (4 Rx channels, 80 MHz bandwidth), Intel i7 processor with 16 GB RAM for model aggregation, and Ethernet/MXIe connectivity
\end{itemize}

The computational complexity analysis reveals manageable requirements for each framework component:
\begin{itemize}
\item MHSA module: Complexity $O(M \cdot N^2 \cdot d_{\text{model}})$ where $M = 5$, $N = 20$, and $d_{\text{model}} = 64$, requiring approximately 40 KB for attention matrices with projected computation time of 2.3 ms on ARM Cortex-A76
\item LSTM component: Complexity $O(M \cdot d_{\text{lstm}}^2)$ where $d_{\text{lstm}} = 256$, needs around 512 KB for hidden states and completes processing in 1.8 ms per sequence
\item Actor-critic networks: Linear transformations with less than 100K total parameters, requiring 400 KB memory and under 0.5 ms inference time
\end{itemize}

For practical deployment, our terrain classification model employs several optimizations:
\begin{itemize}
\item Backbone optimization: MobileNetV2-based feature extraction instead of full ResNet101, reducing parameters from 59M to 2.5M (95\% reduction) with approximately 10 MB memory footprint and 45 ms inference time
\item Quantization: 16-bit precision provides 50\% memory reduction compared to 32-bit floating point, cutting transmission overhead from 200+ MB to 2.5 MB per model update
\item Layer-wise updates: Only task-specific layers participate in federated training, with 2.1M trainable parameters requiring 12 ms for gradient computation per local training iteration
\end{itemize}

The Lagrangian dual decomposition solver implementation details are:
\begin{itemize}
\item Solver method: Modified Brent's method with tolerance $\epsilon = 10^{-6}$
\item Computational complexity: $O(\log(\Delta/\epsilon))$, typically requiring 15 iterations per vehicle
\item Execution time: Under 5 ms per vehicle with less than 1 KB memory requirement for solver state variables
\end{itemize}

System-level performance analysis shows encouraging results:
\begin{itemize}
\item Memory usage: 1.2 MB for TSFEN model storage, 10 MB for local terrain classification, 8 MB for MAPPO training buffers, and 200 MB for system overhead, totaling approximately 220 MB (2.7\% of available 8 GB memory)
\item Runtime latency: 45 ms for model inference, 4.1 ms for TSFEN feature extraction, 5 ms for resource allocation computation, and under 1 ms for FLMD calculation, resulting in total per-round latency under 60 ms (well below 100 ms real-time constraint)
\item Energy consumption: 2.1 J computational energy, 1.8 J communication energy, and 0.3 J idle processing per round, totaling 4.2 J per FL round (less than 2\% battery life impact per hour for typical 5000 mAh vehicular batteries)
\end{itemize}

Our scalability analysis demonstrates appropriate scaling characteristics:
\begin{itemize}
\item Vehicle scaling: From $N = 10$ to $N = 30$ increases memory linearly ($\sim 3.0 \times$) and computation time by $\sim 4.2 \times$
\item Subchannel scaling: From $K = 2$ to $K = 6$ has negligible impact on individual vehicle computation
\item Model complexity: Linear relationship between model size and resource requirements
\end{itemize}


