    \centering
    \includegraphics[width=0.6\textwidth]{figs/01_order_submission1.png}
    \caption{Order submission page}
    \label{cadyfigures/01_order_submission.png}
\end{figure}

\item Forecast Screen (30 seconds)(Figure \ref{fig:02_forecast}): Participants submit their expectations regarding current and future market prices.

\begin{figure}[!ht]
