\section{Introduction}


In a recent work \cite{our} we derived new results for the time evolution
of a finite pinned anharmonic chain of $2N+1$ oscillators,
indexed by $x \in\{-N,\ldots, N\}$, $N=0,1,\ldots$ subjected to an external
driving force  ${\cal F}(t/\theta)$ of
period $\theta>0$,   acting
on the oscillator at $x=0$. In this note we first describe briefly the rigorous results of \cite{our} and then present new numerical results
for values of the parameters not covered there. 

The Hamiltonian of the chain is given by:
\begin{equation}
\label{Hn}
\mathcal{H}_N (\mathbf q, \mathbf p;\nu):=
\sum_{x=-N}^N \left[ \frac{p_x^2}2 +
\frac12 (q_{x}-q_{x-1})^2 +\frac{\om_0^2 q_x^2}{2}+\nu\Big( V(q_x)+  U(q_x-q_{x-1})\Big)\right],
\end{equation}
where $(\mathbf q, \mathbf p)=\big(q_x,p_x\big)_{x\in \bbZ_N}$ is the configuration of the positions and momenta of the oscillators and $q_{-N-1}=q_{-N}$.

 The  microscopic dynamics of
the process  
 is  given   by the forced Hamiltonian
system with friction on both endpoints 
\begin{equation} 
\label{eq:HZ100}
\begin{aligned}
   \ddot    q_x(t;\nu) &=  \Delta q_x(t;\nu)-\om_0^2 q_x(t;\nu)  -\ga
   \dot q_x(t;\nu)\delta_{x,-N}-\ga
   \dot q_x(t;\nu)\delta_{x,N}\\
  &
 -\nu\Big( V'(q_x(t;\nu)) -\nabla U'\big(q_x(t;\nu)-q_{x-1}(t;\nu)\big) \Big)+ {\cal F}(t/\theta)\delta_{x,0} ,\quad
 x\in \bbZ_N.
\end{aligned} \end{equation}
where $\ga>0$ is the friction coefficient and $p_x(t;\nu)=\dot q_x(t;\nu)$. 
We let the force be of the form
\begin{equation}
  \label{forcing-g}
    {\cal F}(t/\theta)=\sum_{m\in\bbZ}\tilde{\rm F}_me^{im\om t},\quad
  \end{equation}
where {$ \om=2\pi/\theta$, $\tilde{\rm F}_{0}=0$, $\tilde{\rm F}_{-m}=\tilde{\rm F}_{m}^\star$ and $ \sum_m |\tilde{\rm F}_m|^2 < +\infty$}.


 The Neumann laplacian $\Delta $ and the discrete gradient are defined as
\begin{equation}
  \label{nmn}
  \Delta f_x=f_{x+1}+f_{x-1}-2f_x,\quad \nabla
  f_x=f_{x+1}-f_x,\quad  x\in[-N,N],
\end{equation}
    {with
      the boundary condition  $f_{N+1}=f_N,\quad f_{-N-1}=f_{-N}$.


We consider the case where the
non-quadratic parts of the pinning and interacting potentials $U$ and
$V$ have bounded second derivatives
\footnote{This is more restrictive than necessary, see \cite{our}, for the proofs of our claims.}.
Examples of such potentials are furnished
by a modified FPUT potential \cite{our}
\begin{equation}
 U(r)= \frac{r^{2n}}{1+\alpha r^{2n}}\quad\mbox{for some } \,\al>0\label{pot1}
\end{equation}
or by a pinning potential \cite{Geniet}
\begin{equation}
 V(q)=  (\sin q)^{2n}\quad,\quad V(q)=a(1+q^2)^{1/2}\label{pot2}
\end{equation}
where $n$ is a positive integer and $a>0$. 

\section{Summary of the results from \cite{our}}
\label{sec2}


\subsection{The existence and stability of a periodic solution to
  (\ref{eq:HZ100})}

We proved that when all integer multiplicities of
$\omega=\frac{2\pi}{\theta}$ are outside the interval containing the
spectrum of the infinite harmonic chain, $\mathcal{I}= [\omega_0, \sqrt{\omega_0^2 +4}]$,
the unique long time state of the system is given by a
{perturbative expansion in} $\nu$, see the detailed description in
Section \ref{sec2.2} below, which 
converges for $\vert\nu\vert<\nu_0$,
where 
\begin{equation}
  \label{eq:14}
  \begin{split}
    \nu_0=\frac{\delta_*}{{\frak V}}, \qquad  \delta_* &=
    \inf\{|(m\omega)^2 - w^2| : m\in \mathbb Z, w\in\mathcal{I}= [\omega_0, \sqrt{\omega_0^2 +4}] \}\\
  {\frak V} &= \sup_q [\vert V''(q)\vert+3\vert U''(q)\vert].
\end{split}
\end{equation}

If $\vert\nu\vert<\nu_0$, then for all $N$, $\cal{F}$, $\gamma>0$  and 
any initial configuration of the chain at time $s$ , allowing $s\rightarrow -\infty$, the configuration of the chain at any time $t$
converges to  $\{q_{x,p}(t;\nu),\dot q_{x,p}(t;\nu)\}$ where $q_{x,p}(t;\nu)$ is the unique $\theta$-periodic solution of  (\ref{eq:HZ100})  achieved at large times.
More precisely, if $\{{\bf q}(t,s;\nu),\dot{\bf q}(t,s;\nu)\}$ is the solution of
(\ref{eq:HZ100}) with initial conditions ${\bf q}(s,s;\nu)={\bf q}$, $\dot{\bf q}(s,s;\nu)=\dot{\bf q}$, then

\begin{equation}
  \label{eq:13}
  \lim_{s\to-\infty} \sum_{x=-N}^N \left[(q_x\big(t,s;\nu \big)-q_{x,p}(t;\nu))^2 +
    (\dot q_x\big(t,s;\nu \big)- \dot q_{x,p}(t;\nu))^2\right] = 0. 
\end{equation}

We also show that for some $0<\tilde \nu\le \nu_0$ and all $|\nu|<\tilde \nu$, there exists $A,\rho>0$ uniform in $N$ such that
       \begin{equation}
         \label{091410-24}
         \begin{split}
            &        |q_{x,p}(t;\nu)|\le A\exp\left\{-\rho|x|\right\},\quad
            t\in[0,\theta], \quad\mbox{and}\\
            &
           \int_0^{\theta}\dot q^2_{x,p}(t;\nu)d  t\le A\exp\left\{-\rho|x|\right\}
\end{split}
\end{equation}


The exponential decay of $\dot q^2_{x,p}(t;\nu)$ with $x$ implies
that the average work performed by the external force over the period
\begin{equation}
  \label{013105-23}
  {\cal W}(\nu)=\frac{1}{\theta}\int_0^\theta {\cal F}(t/\theta) \dot q_{0,{\rm p}}(t;\nu) d  t
  =\frac{\ga}{\theta}\Big( \int_0^{\theta}\dot q_{-N, {\rm p}}^2(s)d  s
          +\int_0^{\theta}\dot q_{N, {\rm p}}^2(s)d  s\Big)>0
  \end{equation}
 goes to zero for $\vert\nu\vert<\tilde\nu<\nu_0$ when
$N\rightarrow\infty$.

It can be seen from the above that the convergence of a
perturbative series expansion depends on supremum norm of the second derivatives of the
 anharmonic potential being bounded, and, as far as we
know, it has not been proven for any other non-equilibrium
system. Numerical simulations shown in the present paper indicate 
that the properties of the system for $\vert\nu\vert >\nu_0$ depend  on the sign
of $\nu$ but this domain of the parameter is beyond
our present mathematical abilities.

\subsection{Perturbative scheme}
\label{sec2.2}
For the harmonic case, $\nu = 0$, we can obtain explicitly  the unique  $\theta$-periodic solution which the system
approaches after long times of order $N^3/\gamma$, see \cite{menegaki}. 
To represent a $\theta$-periodic solution  for an anharmonic chain \eqref{eq:HZ100},
  consider a perturbative series
\begin{equation}
  \label{010401-24z}
 q_{x,{\rm p}}(t;\nu)=\sum_{\ell=0}^{+\infty}q^{(\ell)}_{x,{\rm p}}(t;\nu)\nu^\ell.
\end{equation}
Its 0-th order term is given by the $\theta$-periodic solution
of the harmonic chain.
To obtain \eqref{010401-24z} we construct a sequence $\Big(Q_{x}^{(L)}(t;\nu)\Big)_{
x\in \bbZ_N}$, $L=0,1,\ldots$
of $\theta$-periodic functions that satisfy
\begin{equation} 
\label{012805-24L}
\begin{split}
  \ddot    Q_{x}^{(L)} (t;\nu)= &
  \big(\Delta  -\om_0^2\big) Q_{x}^{(L)} (t;\nu) -\ga(\delta_{x,-N}+
   \delta_{x,N} )\dot Q_{x}^{(L)}(t;\nu)
   \\
   &
   -\nu
   W_x\big(Q_{x}^{(L-1)}(t;\nu)\big)  + {\cal F}(t/\theta)\delta_{x,0} ,\quad
  x\in \bbZ_N,
   \end{split}
 \end{equation}
 {where
 \begin{equation}
  \label{W}
  W_x(f):=V'(f_x)-\nabla U'(f_x-f_{x-1}), \qquad W_x\big(Q^{(-1)}(t;\nu)\big)\equiv 0.
\end{equation}
}
{By convention $Q^{(0)}(t;\nu) :=q^{(0)}_{x,{\rm p}}(t)$ is the $\theta$-periodic solution for the harmonic case.}
For $L\ge 1$ we define
 \begin{equation}
   \label{eq:3}
   q^{(L)}_{x,{\rm p}}(t;\nu) := \nu^{-L} \left(Q_{x}^{(L)}(t;\nu) - Q_{x}^{(L-1)}(t;\nu)\right)
 \end{equation}
i.e.

\begin{equation}
  \label{010905-24}
  Q_{x}^{(L)}(t;\nu)=\sum_{\ell=0}^{L}q^{(\ell)}_{x,{\rm p}}(t;\nu)\nu^\ell.
\end{equation}

Then, by \eqref{012805-24L}, we conclude that 
$q_{x }^{(L)}(t;\nu)$, $x\in\bbZ_N$ is a $\theta$-periodic solution of 
\begin{equation} 
\label{eq:flip-lZ}
\begin{aligned}
     \ddot    q _{x,{\rm p}}^{(L)}(t;\nu) &=  \Delta_x
    q _{x,{\rm p}}^{(L)}(t;\nu)-\om_0^2  q _{x,{\rm p}}^{(L)}(t;\nu)\\
   &
   -\ga\dot
   q _{x,{\rm p}}^{(L)}(t;\nu)\delta_{-N,x}-\ga\dot
     q _{x,{\rm p}}^{(L)}(t;\nu)\delta_{N,x}-   v_{x,L-1}(t)  ,\quad
  x\in \bbZ_N,
\end{aligned} \end{equation}
where
\begin{equation}
  \label{vxL}
  \begin{split}
    &v_{x,L-1}(t)=\frac{1}{\nu^{L-1}}\Big[W_x\big(Q^{(L-1)}(t)\big)
    -W_x\big(Q^{(L-2)}(t)\big)\Big].
\end{split}
\end{equation}
From
       \eqref{eq:flip-lZ} it follows that $ q _{x,{\rm
           p}}^{(L)}(t;\nu)$ are smooth functions of $\nu$ and $t$.

     Note that
$v_{x,0}(t)= W_x\big(q_{{\rm p}}^{(0)}(t) \big)$.
In addition,  $v_{L-1}(t,\nu)$ is bounded by
       $$
     \frak{V} |Q^{(L-1)}(t) - Q^{(L-2)}(t)|.
       $$
       with $\frak{V}$ is defined in eq.\eqref{eq:14}.  
        This is where the boundedness of the second derivative of the potential comes as a crucial property.
       Using the equations for the time harmonics of $q_{x,{\rm p}}^{(L)}$ and $v_{x,L}$ we
       obtain the bound, see \cite{our} for the derivation,
      \begin{equation}
        \label{eq:9}
        \|\!|v_{L-1}(\cdot,\nu)\|\!| \le \frak V \|\!| q^{(L-1)}_{\rm p} (\cdot,\nu)\|\!|.
      \end{equation}

   where $\frak V $ is defined in (\ref{eq:14}) and
    \begin{equation}
     \|\!| f \|\!|^2=\frac{1}{\theta}\int_0^\theta \Big(\sum_{x=-N}^N \vert f_x(t) \vert^2\Big)dt
    \end{equation}


   Thus, we have obtained
  \begin{align}
  \label{082302-24}
  \|\!|q^{(\ell)}_{\rm p}(\cdot;\nu)\|\!|\le
    \frac{1}{\nu_0}\|\!|q^{(\ell-1)}_{\rm p}(\cdot;\nu)\|\!|,\quad \nu\in\bbR,\, 
    \ell = 1,2 \dots .  
  \end{align}
 Consequently for $|\nu|<\nu_0$
    the sums  $Q_{x,{\rm p}}^{(L)}(t;\nu)$, given by \eqref{010905-24}  converge
    in the $\|\!|\cdot\|\!|$-norm, as $L\to+\infty$.
    The convergence is uniform in $N$ and $\gamma$. Moreover
   \begin{equation}
     \label{112302-24}
     \begin{split}
     &     \|\!|\sum_{\ell= L}^{+\infty}q^{(\ell)}_{\rm p} (\cdot;\nu)\nu^\ell\|\!|
  \le \frac{|\nu/\nu_0|^L \|\!| q^{(0)}_{\rm p}(\cdot;\nu)\|\!|}{1-|\nu/\nu_0|},\quad
  L =1,2,\ldots,\,|\nu|\le \nu_0 .
\end{split}
\end{equation}
As a  result the series 
\begin{equation}
  \label{010401-24z1}
 q_{x,{\rm p}}(t;\nu)=\sum_{\ell=0}^{+\infty}q^{(\ell)}_{x,{\rm p}}(t;\nu)\nu^\ell
\end{equation}
converges for $|\nu|< \nu_0$  and 
 defines a $\theta$-periodic solution of \eqref{eq:HZ100}. In fact it
 is a
 unique    $\theta$-periodic solution for this range of anharmonicity
parameter $\nu$. We note that $\nu_0$ is a lower bound on the radius of
 convergence for any fixed $\cal{F}$, $N$ and $\gamma>0$.
 % \end{theorem}


 \begin{remark}
   We note here that a $\theta$-periodic solution   exists for any value
  of $\nu$. This can be seen
by an abstract compactness argument, see \cite{our} for details.
However,  as it was pointed out there, the uniqueness  does not hold in general. In fact, there are
situations where the series \eqref{010401-24z} converges for 
$\vert\nu\vert>\nu_0$ but the respective periodic solution is not
unique, nor even locally stable, see \cite{our} and Section \ref{sec3} below.
 \end{remark}

 \begin{remark}
When the periodic components of the force
$\tilde{\rm F}_m$ vanish  for all even $m$,
e.g. $\mathcal{F}(t/\theta)=F\cos(\omega t)$ and the potentials $V$
and $U$ are even functions of their argument, then  the series
\eqref{010401-24z}  converges for $|\nu|< \bar\nu_0 = \frac{\bar\delta_*}{ {\frak V}}$, where
    \[
    \bar\delta_*:=\inf\Big[\big|\big((2m-1)\om\big)^2-w^2\big|
    :\,m\in\bbZ,\,w\in {\cal I}\Big] > \delta_*.
  \]
  However in this case $q_{\rm p}(t;\nu)$ defined by \eqref{010401-24z}  need not be stable.
\end{remark}

 \begin{remark}
   Note that, the condition $|\nu|<\nu_0$ implies in particular
    that the derivative of the pinning potential, 
    $\frac{d}{dq}[\om_0^2q^2/2+\nu V(q)]$, is non-decreasing. Therefore, the
    pinning part of the potential is convex.
\end{remark}
 \begin{remark}
  It also follows from the above analysis that for   $|\nu|<\nu_0$
there exists a constant $C>0$ independent of $N$ and $\ga>0$ such
 that 
 \begin{equation}
   \label{060810-24}
  \frac{1}{\theta}\int_0^\theta{\cal H}_N\big({\bf  q}_{{\rm
      p}}(t;\nu), {\bf  p}_{{\rm p}}(t;\nu)\big)d  t\le C.
   \end{equation}
\end{remark}




\section{The one oscillator case}
\label{sec3}

We consider here the case of a single damped anharmonic
oscillator with a periodic forcing. This is of its own interest
\cite{one} and explicitly shows the dependence of the radius of
convergence of a power series \eqref{010401-24z} on the
parameters. In the present case the spectral  interval $\mathcal{I}$
is just $\omega_0$. The equation of motion is:
\begin{equation}
\ddot q=-\omega_0^2 q+2\gamma\dot q -\nu V'(q)+F\cos(\omega t) \label{one}
\end{equation}
When $\gamma>0$ and $\nu=0$, the long time state of the system given in \eqref{eq:13} is:
\begin{equation}
q_p(t,\nu=0)=\frac{F}{(\omega_0^2-\omega^2)^2+4\gamma^2\omega^2}\left[(\omega_0^2-\omega^2)\cos(\omega t)+2\gamma\omega\sin(\omega t) \right]\label{qnu0}
\end{equation}
for any initial condition. For $\nu\neq 0$, the results above shows that there exists a unique globally stable periodic solution when 
\begin{equation}
\vert\nu\vert<\nu_0=\delta_*/ \|V''\|_\infty
\end{equation}
 with  $\|\cdot\|_\infty$  the supremum norm and 
\begin{equation}
\delta_*=\inf_{m\in \mathbb Z}\vert\omega_0^2-(m\omega)^2\vert .
\end{equation}

As noted before, when restricted to the case $V(q)=V(-q)$ the power series \eqref{010401-24z} converges for
\begin{equation}
\vert\nu\vert<\bar\nu_0=\bar\delta_*/\|V''\|_\infty
\end{equation}
 with 
\begin{equation}
\bar\delta_*=\inf_{m\in \mathbb Z}\sqrt{(\omega_0^2-((2m+1)\omega)^2)^2+ (2\gamma (2m+1)\omega)^2} \geq \delta_*.
\end{equation}


We can however be sure that it is stable only when $\vert\nu\vert<\nu_0<\bar\nu_0$.

\subsection{Numerical solution for $\nu\neq 0$}

We solve numerically eq.(\ref{one}) when $V(q)=-\cos q$,  $\omega_0=1$, $\gamma=1/2$ and $F=1.75$ and $\omega=0.8$. 
The initial conditions chosen are: $q(0,\nu)=q_p(0,\nu=0)$ and $\dot q(0,\nu)=\dot q_p(0,\nu=0)$. Observe that \tk{in} this case $ \|V''\|_\infty=1$, $\bar\nu_0=0.8772..$ and  $\nu_0=0.1055...$. 

We show in Figure \ref{conff} how the values $Q^{(L)}$ of the
perturbation scheme \eqref{012805-24L} converge to the numerical
solution  for $\nu=0.8$. Moreover, we compute the distance of
$Q^{(L)}$ to the numerical periodic solution $q$ starting at
$t_0=300$  (where $q(t)$ appears to attain  the
  stationary state) during one period
$\theta$:
%\tk{\em Comment: I do not understand this phrase}
\begin{equation}
s(L)=\left[\frac{1}{\theta}\int_{0}^{1}d\tau \left(Q^{(L)}(t_0+\tau\theta)-q(t_0+\tau\theta)\right)^2\right]^{1/2}.\label{dist}
\end{equation}
The distance $s(L)$ decay fast with $L$ as expected. 

