\title{Crossings and diffusion in Poisson driven marked random connection models}
\author[1]{Alessandra Faggionato}
\author[2]{Ivailo Hartarsky}
\affil[1]{\small Department of Mathematics, Sapienza University of Rome. P.le Aldo Moro 2, 00185 Roma, Italy, \texttt{faggiona@mat.uniroma1.it}}
