The next crucial definition is illustrated in Figure~\ref{fig:renorm}.
\begin{Definition}
\label{def:occupied}
Let $\Lambda:=\L_{6N}(-12N e_1)\cup\L_{6N}=[-18N,6N]\times[-6N,6N]^{d-1}$ and $\Lambda^1:=[-4N,4N]\times [-6N,-11N/2]\times[-4N,4N]^{d-2}$, $\Lambda^2:=[11N/2,6N]\times[-4N,4N]^{d-1}$, $ \Lambda^3:=-\Lambda^1$.
We say that the site $(0,0)$ is \emph{occupied} if, for each $i\in\{1,2,3\}$, there exists a seed \[\cS^i\subset \Big\{t\in \Lambda^i\times\bbM_g: t\leftrightarrow S_0 \text{ in  }G\big(S_0\cup  \xi \cup \xi_{(0, 100d]}\big) \text{ in } \Lambda\times\bbM\Big\}.\]
\end{Definition}

In order to satisfy Definition~\ref{def:domination}, we prove the following statement where $p_0\in (\pc(2), 1) $ has been fixed once and for all (recall that $\pc(2)$ is the critical probability of Bernoulli site percolation on $\bbZ^2$).
\begin{Lemma}\label{passo0} Choosing the scales in \eqref{eq:scales} suitably, it holds that $P(\text{$(0,0)$ is occupied})>p_0$.
\end{Lemma}
\begin{proof}
Recall \eqref{eq:def:F}.  For $\sigma\in\{-1,1\}^d$ and $i\in\{1,\dots,d\}$, let 
\[\tilde F^{i,\sigma}_N:=\{\sigma_iN\}^{\{i\}}\times\prod_{j\in\{1,\dots,d\}\setminus\{i\}}(\sigma_j[0,N]),\]
i.e.~$\tilde F^{i,\sigma}_N$ is given by the sites $x=(x_1,x_2,\dots, x_d)\in F_N^{i,\sigma}$ with $x_i=\s_i N$. We omit $i,\sigma$, if $i=1$ and $\sigma=(1,\dots,1)$. Let $z_0\in\bbR^d$ be such that $S_0\subset\L_{n-K}(z_0)\times\bbM_g\subset \L^0\times\bbM_g$ and, without loss of generality, assume that $z_0\in\bbR\times(-\infty,0]^{d-1}$ (in the general case one just has to replace in what follows $F_N$ by $F_N^{1,\s}$ where $\s\in\{-1,1\}^d$ satisfies $\s_1=1$ and $\s_j z_0(j)\le
0$ for $1<j\leq d$ with $z_0=(z_0(1),\dots,z_0(d))$). Let $\cD$ be the event that $G(\xi^*)|\Lambda_{6N}$ belongs to the set of graphs $\cH_*$ from Lemma~\ref{lem:seed:to:seed}. We first seek to connect $S_0$ to a seed close to $(z_0+{\tilde F}_N)\times\bbM$. By Lemma~\ref{lemma_crescita}, we get
    \begin{equation}\label{russell1}
    P \Big(S_0\leftrightarrow  (z_0+F_N)\times\bbM \text{ in  } (z_0+\Lambda_N)\times \bbM 
    \text{ in } G( S_0 \cup \xi'))\Big )\ge 1-e^{-c/\varepsilon},
\end{equation}
where $\xi':=\xi\cap (\Lambda\times\bbM)$. We call $E_1$ the event in the l.h.s.\ of \eqref{russell1} and we set 
\[ \cC:=S_0\cup\Big\{t\in \xi'\,:\, t\leftrightarrow S_0 \text{ in }  G( S_0 \cup \xi')\Big\}\,.
\]

By Lemma \ref{lem:seed:to:seed}\ref{cond:proba} we can estimate
$P( E_1\cap \cD)\geq P(E_1)- P(\cD^c) \geq 1-e^{-c/\varepsilon}-\e$.
The event $E_1\cap \cD$ and the decreasing property of $\cH_*$ in Lemma \ref{lem:seed:to:seed}\ref{cond:decreasing}  imply that the graph  $G(S_0 \cup \xi')|(\cC\cap(\Lambda_{6N}\times \bbM))$  belongs to $\cH_*$ (using that $S_0\cap(\Lambda_{6N}\times\bbM)=\varnothing$). Moreover, $E_1$  implies that there is a path of length at least $\sqrt{N}-1$ inside $G(S_0 \cup \xi')|(\cC\cap(\Lambda_{6N}\times\bbM))$ which intersects $z_0+F_N$. Hence, by Lemma~\ref{lem:seed:to:seed}\ref{cond:deterministic}, $E_1\cap \cD$  implies the following event $E_2$: $\cC$ contains a seed 

\[
\cS_1\subset  \L_{n-K}(z_1) \times\bbM_g  \subset (z_0+\tilde F_N+\L_{\sqrt{N}})\cap \bbM_g
\]
(using the bounds on the position of $S_0$, which imply that $z_0+F_N$ is well inside $\Lambda_{6N}$).
Due to the above considerations we conclude that 
\be\label{suono1}
P(E_1\cap E_2)\geq 1-e^{-c/\varepsilon}-\e=:\a_1\,.
\en

Note that the event $E_1\cap E_2$ is measurable with respect to the $\s$-algebra $\cT$ generated by $G(S_0\cup\xi')|\cC$. Let us consider the conditional probability
\[
P_1:=P\Big(\cdot \,\Big|\,  G( S_0 \cup \xi')|\cC=(\bar S, \bar E)\Big)\,,\]
where the above conditioning event $\{G( S_0 \cup \xi')|\cC=(\bar S, \bar E)\}$  is compatible with $E_1\cap E_2$ (considering a  regular version of the conditional probability $P(\cdot|\cT)$).
Under this conditioning event, the seed $\cS_1$ is determined (we choose  $\cS_1$ in a measurable way) and we denote by $S_1$ its value. A crucial observation is that the process $\xi'\setminus\cC$ under $P_{1}$ is a PPP on $\bbR^d\times \bbM$  with intensity  measure $\l \bar\varphi(t, \bar S) \mu(\md t)$ where $\mu$ denotes the restriction to $\L$ of $\cL\otimes \nu$.

 Fix $u>0$ to be chosen later. We apply Lemma~\ref{lemma_udine} with $R:=\Lambda_N(z_1)\times\bbM$, $A:=\bar S
 $, $B:=(z_1+F^{1,\s^1}_N)\times \bbM$ with $\s^1$ the sequence of the signs of the coordinates of $-z_1$ (exceptionally, in this section we define  the sign of $0$ as $+1$),  $\tilde\bbX:=\xi_1 \cap R$ under $P_1$ (and therefore under $P$), $\bbY:=(\xi\setminus\bar S) \cap R$ under $P_1$,  $\bbX:=\xi \cap R $  under $P$. 
 By Lemmas~\ref{lemma_udine}  and \ref{lemma_crescita} 
we then get 
\begin{multline}\label{suono2}
P_1\left(\bar S\leftrightarrow(z_1+F^{1,\s^1}_N)\times\bbM\text{ in }G\left(\bar S, \xi_1\cap R\right)\cup G(((\xi\setminus\bar S)\cup\xi_1)\cap R)\right)\\
\begin{aligned}[t]
&{}\ge  \bbP\left(A \leftrightarrow(z_1+F^{1,\s^1}_N)\times\bbM\text{ in }G\left(A, \tilde\bbX\right)\cup G\left(\tilde\bbX\cup\bbY\right)\right)\\
&{}\ge \left(1-e^{-(\lambda'-\lambda) u/(400d)}\right)\left(1-e^{\lambda u} P\left(A\not\leftrightarrow (z_1+F^{1,\s^1}_N)\times\bbM 
\text{ in } G\left(\left(R\cap\xi\right)\cup A\right)\right)\right)\\
&{}\ge \left(1-e^{-(\lambda'-\lambda) u/(400d)}\right)\left(1-e^{\lambda u-c/\varepsilon}\right)=:\a_2.\end{aligned}\end{multline}
We take $u:=400d/((\lambda'-\lambda)\sqrt \varepsilon)$ and using that $\varepsilon$ is small enough depending on $\lambda',\lambda,d,c$ we can make $\a_2$ and $\a_1$ from \eqref{suono1} arbitrarily close to $1$.

Let  $E_3$ be the event that $\cC\leftrightarrow(z_1+F^{1,\s^1}_N)\times\bbM\text{ in }G\big(\cC, \xi_1\cap R\big)\cup G\big(((\xi\setminus\cC)\cup\xi_1)\cap R\big)$. By combining \eqref{suono1} and \eqref{suono2}, we get $ P(E_1\cap E_2\cap E_3) \geq \a_1\a_2$. 
Since $P(\cD^c)\leq \e$,  we have 
\[P(E_1\cap E_2\cap E_3\cap \cD) \geq \a_1\a_2-\e\,.\]
We call $\cC'$ the set of points $t\in S_0\cup\big((\xi\cup\xi_1)\cap (\Lambda\times\bbM)\big)$ such that $\cC\leftrightarrow t $ in the graph $\G:=G\left(S_0\cup\big( (\xi\cup\xi_1)\cap(\Lambda\times\bbM)\big)\right)$. The event $E_1\cap E_2\cap E_3 \cap \cD$ and the decreasing property of $\cH_*$ in Lemma \ref{lem:seed:to:seed}\ref{cond:decreasing} imply that the graph  $\G|(\cC'\cap(\Lambda_{6N}\times\bbM))$  belongs to $\cH_*$. Furthermore,  $E_1\cap E_2\cap E_3 \cap \cD$   implies that there is a path of length at least $\sqrt{N}-1$ inside $\Gamma|\cC'$ intersecting 
$z_1+F^{1,\s^1}_N$. Hence, by Lemma \ref{lem:seed:to:seed}\ref{cond:deterministic}, $E_1\cap E_2\cap E_3 \cap \cD$  implies the following event $E_4$: $\cC'$ contains a seed 
  $\cS_2\subset  \L_{n-K}(z_2)\times\bbM_g\subset (z_1+\tilde F_N^{1,\s^1}+\L_{\sqrt{N}})\times\bbM_g$. Note that by the above observations 
\be\label{suono3}
P( E_1\cap E_2\cap E_3\cap E_4)\geq \a_1\a_2-\e=\a_3\,.
\en

We repeat the same reasoning 4 more times (using a new $\xi_i$ each time) until we obtain a seed $\cS_6\subset \Lambda_{n-K}(z_6)\times\bbM_g\subset [-N/2-6\sqrt N,6\sqrt N]\times [-4N-6\sqrt N,4N+6\sqrt N]^{d-1}\times\bbM_g$. Note that the projection on the first coordinate of $\Lambda_{n-K}(z_6)$ is included in $[-2N,2N]$ (by taking $N$ large). We then seek to adjust the other coordinates  by repeating the same procedure another $4(d-1)$ times.  We start with the second coordinate. For $i\in\{6,7,8,9\}$ we try to connect $S_{i}$ with $z_i+F_N^{2,\s^i}$ where  $\sigma^i$ is the sign sequence of $-z_i$, thus leading to the seed $\cS_{i+1}\subset \L_{n-K}(z_{i+1})\times\bbM_g$. Then we do the same for the third coordinate and so on. Notice that, at each step when adjusting the $j$--th coordinate, $|z_{i+1}(j)|\le \max(|z_i(j)|-3N/4,3N/2)$, while $|z_{i+1}(j')|\le \max(|z_i(j')|+\sqrt N,3N/2)$ for $j'\in\{1,\dots,d\}\setminus\{j\}$.

Recalling that $N$ is taken large enough, this yields a seed
\[\cS_{4d+2
}\subset\Lambda_{n-K}(z_{4d+2
})\times\bbM_g\subset\Lambda_{2N}\times\bbM_g.\]

From this point, for each $i\in\{1,2,3\}$ we proceed similarly going from $\cS_{4d+2
}$ towards $\Lambda^i\times\bbM$. For concreteness, consider $i=2$, the others being analogous. Further for concreteness, assume that $z_{4d+2
}\in[N-\sqrt N,2N]\times [-2N-3\sqrt N,2N+3\sqrt N]^{d-1}$ (if this is not the case, up to three additional steps are performed to reach this case, setting $\sigma_1=1$ rather than the sign of the first coordinate of $-z_j$). We perform another 3 steps to the right, obtaining $z_{4d+5
}\in[4N-4\sqrt N,5N+3\sqrt N]\times[-2N-6\sqrt N,2N+6\sqrt N]^{d-1}$. We now consider three cases for the first coordinate $\zeta$ of $z_{4d+5
}$.

If $\zeta\in[9N/2+2\sqrt N,5N-2\sqrt N]$, then an additional step as before yields the desired seed $\cS_{4d+6
}\subset\Lambda^2$ and we are done. Assume that $\zeta\in[4N-4\sqrt N,9N/2+2\sqrt N]$ and perform a step as before to get that the first coordinate of $z_{4d+6
}$ belongs to $[5N-5\sqrt N,11N/2+3\sqrt N]$. At this point, we need more care, since $\Lambda_N(z_{4d+6
})\not\subset\Lambda$. However, we may proceed in the same way as above, setting $R=\Lambda_N(z_{4d+6
})\cap((-\infty,23N/4]\times\bbR^{d-1})\subset \Lambda$ and replacing $z_{4d+6
}+F^{1,\sigma^{4d+6}}_N$ by $F'=R\cap([23N/4-1,23N/4]\times \bbR^{d-1})$. Indeed, for any seed $S\subset \Lambda_{n-K}$ and $x\in[n+1,N]$, we have
\begin{multline*}
P(S\leftrightarrow [x-1,x]\times [-N,N]^{d-1}\times\bbM\text{ in }G((S\cup\xi)\cap(\Lambda_N\times\bbM)))\\
\ge P(S\leftrightarrow F_N\times\bbM\text{ in }G((S\cup\xi)\cap (\Lambda_N\times\bbM)))\ge 1-e^{c/\varepsilon},\end{multline*}
using Lemma~\ref{lemma_crescita}. Noticing that $F'+\Lambda_{\sqrt N}\subset \Lambda^2$, we obtain a seed $\cS_{4d+7
}\subset \Lambda^2$ as desired. Finally, the remaining case $\zeta\in[5N-2\sqrt N,5N+3\sqrt N]$ is treated like $\zeta\in[4N-4\sqrt N,9N/2+2\sqrt N]$ omitting the first step, i.e.~the step used there to suitably localize  the first coordinate of $z_{4d+6
}$.

In total, in at most $4d+26
$ steps, we have obtained that
\[P((0,0)\text{ is occupied})\ge f^{\circ (4d+25
)}(\alpha_1)\,,\]
where $f(x)=\alpha_2x-\varepsilon$ for $x\in\bbR$ and $f^{\circ m}$ denotes the $m$-fold composition of the function $f$. Recalling \eqref{suono1} and \eqref{suono2}, by our choice of scales \eqref{eq:scales}, this completes the proof of Lemma~\ref{passo0}.
\end{proof}

Recall the notation of Definition~\ref{def:occupied}. From now on we choose the seeds $\cS^1,\cS^2,\cS^3$ appearing in Definition~\ref{def:occupied} in a measurable way in terms of  the connected components intersecting $S_0$ in 
    \[G\Big(S_0\cup \big((\xi\cup\xi_{(0,100d]}) \cap(\Lambda\times\bbM)\big)\Big).\]
Linking events are defined very similarly to occupation.
\begin{Definition}
\label{def:link}
    Assume that $(0,0)$ is occupied. 
    Let $\L'=\L\cup \L_{6N}(12N e_1)$ and set 
    \[\Gamma:=G\Big(S_0\cup\big((\xi\cup\xi_{(0,100d]})\cap(\Lambda'\times\bbM)\big)\cup\big(\xi_{(100d,200d]}\cap(\Lambda_{6N}\times\bbM)\big)\Big)\]
    We denote $\Lambda_2^i=12Ne_1+\Lambda^i$ for $i\in\{1,2,3\}$. We say that $(1,0)$ is \emph{linked} to $(0,0)$, if there exists a seed    \begin{align*}\cS^i_2&{}\subset\{t\in\Lambda^i_2\times\bbM_g:t\leftrightarrow\cS^2\text{ in }\Gamma\},
\end{align*}
    for each $i\in\{1,2,3\}$.
\end{Definition}

More generally, we can define the link variables simultaneously with the exploration process of Section~\ref{subsec:exploration}. Whenever a link variable is about to be explored in \eqref{reveal}, we define it as in Definition~\ref{def:link}. The only modifications are that $\Lambda^i$ may need to be rotated depending on the entry vertex of the link and that the ranges of the sprinkling PPP $\xi_{(0,100d]}$ and $\xi_{(100d,200d]}$ may need to be modified. More precisely, assume that we are currently exploring a link to construct the set $C^s_{j+1}$ (recall Section~\ref{subsec:exploration}) with $s\in\{0,\dots,M-1\}$ and $j\in\{2,\dots,\sharp\Lambda'_L-1\}$ (the cases $j=0$ and $j=1$ are exactly given by Definitions~\ref{def:occupied} and~\ref{def:link}, up to translation) and assume that a point $x_{j+1}^s\in\Delta E^s_{j}$ is to be added to $E_{j}^s\cup F_{j}^s$, as otherwise there is nothing to do. For each $x\in \cX:=(E^s_{j}\setminus\{(0,s)\})\cup F^s_j\cup\{x^s_{j+1}\}$, let $i_x\in\{1,2,3,4\}$ be the number of explored links with endpoint $x$, including the link with endpoint $x^s_{j+1}$ currently being explored. Then the vertex set of the graph $\Gamma$ in the analogue of Definition~\ref{def:link} is
\begin{multline*}
\big(S_0+12Nse_2\big)\cup\Big(\big(\xi\cup\xi_{(0,100d]}\big)\cap\big(\Lambda_{6N}(-12Ne_1+12Nse_2)\times\bbM\big)\Big)\\
\Big(\big(\xi\cup\xi_{(0,200d]}\big)\cap\big(\Lambda_{6N}(12Nse_2)\times\bbM\big)\Big)\cup\bigcup_{x\in\cX}\Big(\big(\xi\cup\xi_{(0,100di_x]}\big)\cap\big(\Lambda_{6N}(\bar x)\times\bbM\big)\Big).\end{multline*}

\begin{Lemma}
\label{lem:domination}
    The link and occupation events defined above satisfy that $P$ dominates $p_0$.
\end{Lemma}
The proof is omitted, as it is identical to the one of Lemma~\ref{passo0}, up to heavier notation.

We are now ready to complete the proof of Theorem~\ref{teo_crossings} by proving \eqref{2d_bound}.
\begin{proof}[Proof of \eqref{2d_bound}]
    By Corollary~\ref{cor:domination} and Lemma~\ref{lem:domination}, for some constants $\k,\k'>0$ and all positive $M,L$, we have $P(N_L\ge \k M)\ge 1-e^{-\k'M}$. By the reverse Fatou's lemma, this gives that 
    \[P(N_L\ge \k M\text{ for infinitely many $L$})\ge 1-e^{-\k'M}.\]
    But the above event implies that there are at least $\k M$ vertex-disjoint paths from occupied vertices in $\{0\}\times\{0,\dots,M-1\}$ to infinity in \[\Lambda_\infty':=\bigcup_{L\ge 1}\Lambda'_L=\{0,\dots,M-1\}^2\cup\{(x,y)\in\bbZ^2:x\ge M\}\] via present links. By Definition~\ref{def:occupied}, each such path starts at (a vertical translate) of the seed $S_0$ which is not necessarily present in $\xi^*$, but which is at distance at least $1$ from $\Lambda_{6N}$. Since all other vertices are in $\xi^*$ and bonds are present in $G(\xi^*)$, we obtain infinite vertex-disjoint paths starting to the left of $\Lambda_{\ell}$. Moreover, since, in $\Lambda_\infty'$, the only way of going to infinity requires intersecting $\{M\}\times\{0,\dots,M-1\}$, the above paths give crossings of $\Lambda_{\ell}$, completing the proof of \eqref{2d_bound}.
\end{proof}

