\title{Resolution Limits of Non-Adaptive 20 Questions Estimation for Tracking Multiple Moving Targets\\
}

\author{Chunsong Sun, Lin Zhou, Jingjing Wang, Weijie Yuan, Chunxiao Jiang and Alfred Hero\\

