Next, define the set of $k$ distinct trajectories sets as
\begin{align}
\calB_{n,M}^{(k)}:=\big\{\{\bw_1^n,\ldots,\bw_k^n\}:\bw_t^n\in\calB_{n,M}~\mathrm{for~any}~t\in[k]~\mathrm{and}~\bw_{t_1}^n \neq \bw_{t_2}^n~\mathrm{for~any}~(t_1,t_2)\in[k]^2 \big\}.
\end{align}
For any $k$ moving targets with initial location and velocity vectors $(\mathbf{s},\mathbf{v})^k\in([0,1]^d \times [-v_+,v_+]^d)^k$, define the set of targets' quantized trajectories as
\begin{align}
\calU_{n,M}\left((\mathbf{s},\mathbf{v})^k\right):=\big\{\mathbf{w}(\mathbf{s}_1,\mathbf{v}_1,[n]),\ldots,\mathbf{w}(\mathbf{s}_k,\mathbf{v}_k,[n])\big\}. \label{set-u}
\end{align}

The next definitions are analogous to the mutual information density in~\cite[Section III]{zhou2022resolution}. Given any sequence of random variables $X_{[k]} = (X_1,\ldots,X_k)$, we denote the binary OR of $X_{[k]}$ as the symbol $Z$. For any $(x_{[k]}, y)\in\{0, 1\}^k \times \calY$, define the joint distribution
\begin{align}
P_{X_{[k]} Y}^{h(p)}\big(x_{[k]}, y\big)
&:=\bigg(\prod_{t\in[k]} P_X(x_t)\bigg) P_{Y | Z}^{h(p)}(y | z) , \label{joint_d}
\end{align}
where $p\in(0,1)$, $P_X=\mathrm{Bern}(p)$ and $P_{Y | Z}^{h(p)}$ denotes the binary input query-dependent channel. Fix any $t\in[k]$. Let $P_{Y|X_{[t]}}$ be induced by $P_{X_{[k]} Y}^{h(p)}$. Given any $t\in[k]$ and any $p\in(0,1)$, define the mutual information density
\begin{align}
\imath^{h(p)}(x_{[t]} ; y):=\log \frac{P_{Y | X_{[t]}}^{h(p)}(y | x_{[t]})}{P_Y^{h(p)}(y)}. \label{mu_info_e}
\end{align} 
Given any query region $\calA \in [0,1]^d$, for any $(z,y)\in\{0,1\} \times \calY$, define the query-dependent mutual information density 
\begin{align}
\imath_{\calA}(z;y):=\log\frac{P_{Y|Z}^{h(|\calA|)}(y|z)}{P_{Y}^{h(|\calA|)}(y)} . \label{mu_info_a}
\end{align}

Given $(p,t)\in(0,1)\times[k]$, let $C(p,t)$ and $V(p,t)$ denote the mean and variance of the mutual information density $\imath^{h(p)}$, respectively, i.e.
\begin{align}
C(p,t)&:=\mathbb{E}\big[\imath^{h(p)}\big(X_{[t]};Y\big)\big] , \label{cempty}\\
V(p,t)&:=\mathrm{Var}\big[\imath^{h(p)}\big(X_{[t]};Y\big)\big] . \label{vempty}
\end{align}
Furthermore, the capacity of the binary-input multiple access channel (MAC) induced by \eqref{joint_d} is defined as
\begin{align}
C(k):=\max_{p\in(0,1)} C(p,k). \label{ck}
\end{align}
Let $\calP_k$ denote the set of capacity achieving optimizer $p^*$ in \eqref{ck}. Given any $\varepsilon \in (0,1)$, the dispersion for the channel is then defined as
\begin{align}
V(k,\varepsilon):=\Bigg\{
\begin{aligned}
&\min_{p^*\in\calP_k} V(p,k)&\mathrm{if}~\varepsilon \leq 0.5, \\
&\max_{p^*\in\calP_k} V(p,k)&\mathrm{if}~\varepsilon > 0.5.
\end{aligned}
\label{vk}
\end{align}

\subsection{Non-Asymptotic Bounds} \label{mr Non-Asymptotic Bounds}

\begin{algorithm}[tb]
\caption{Non-Adaptive Query Procedure for Multiple Moving Target Search}
\label{alg:1} 
\begin{algorithmic}[1]  
\REQUIRE
The number of queries $n\in\bbN$, dimension $d\in\bbN$ and three design parameters $(M,p,\gamma)\in\bbN \times (0,1) \times \bbR_+$
\ENSURE
A set of estimated trajectories $\{\hat{\bw}_1^n,\ldots,\hat{\bw}_k^n\}$ of $k$ targets with unknown initial locations and velocities
~\\
\hrule 
~\\
\STATE Divide the $d$-dimensional unit cube $\calS=[0,1]^d$ into $(nM)^d$ equally sized non-overlapping sub-cubes $(\calC_1,\ldots,\calC_{(nM)^d})$.
\STATE \textbf{\emph{Query generation and response collection:}}
\STATE Generate $n$ binary vectors $(x^n(1),\ldots,x^n((nM)^d))$ with length-$(nM)^d$, where each vector is generated i.i.d. from Bern$(p)$.
\FOR{$i\in[n]$}
\STATE Form a query region $\calA_i$ as
\begin{align}
\calA_i:=\bigcup_{j\in[(nM)^d]:~x_{i,j}=1} \calC_j \nn.
\end{align}
\STATE Pose the $i$-th query asking whether there are targets in the region $\calA_i$ and obtain a noisy response $y_i$ from the oracle.
\ENDFOR
\STATE Collect noisy responses $y^n=(y_1,\ldots,y_n)$.
\STATE \textbf{\emph{Decoding:}}
\IF{there exists a set of trajectories $\{\hat{\bw}_1^n,\ldots,\hat{\bw}_k^n\}\in\calB_{n,M}^{(k)}$ such that
\begin{align}
\imath^{h(p)}\big(x^n(\Gamma(\hat{\bw}_1^n)),\ldots,x^n(\Gamma(\hat{\bw}_k^n)); y^n\big) \geq \gamma, \label{single_thres}
\end{align}
}
\RETURN estimates $\{ (\hatbs_1,\hatbv_1),\ldots,(\hatbs_k,\hatbv_k) \}$ such that for any $t\in[k]$, $$w(\hatbs_t,\hatbv_t,[n])=\hat{\bw}_t^n.$$
\ELSE
\RETURN estimates $\{ (\hatbs_1,\hatbv_1),\ldots,(\hatbs_k,\hatbv_k) \}$ such that $(\hatbs_t,\hatbv_t)= (\mathbf{0.5}_{d \times 1},\mathbf{0}_{d \times 1})$ for each $t\in[k]$.
\ENDIF
\end{algorithmic}
\end{algorithm}

Recall that $h(\cdot)$ is a bounded Lipschitz continuous function with parameter $L$. Recall the definitions of the function $\Gamma(\cdot)$ in \eqref{gamma-func}, the trajectory set $\calB_{n,M}$ in \eqref{bnm} and the power set $\Lambda([k])$ in the Notation Section, respectively. Fix $p\in(0,1)$. Fix positive real numbers $(\gamma,\eta)$ and $\{\lambda_\calJ\}_{\calJ\in\Lambda([k])}$. Let $(x^n(1),\ldots,x^n((nM)^d))$ be a sequence of $n$ binary codewords with length-$(nM)^d$, where each codeword is generated i.i.d. from $P_X=\mathrm{Bern}(p)$. For ease of notation, given any trajectory $\bw^n\in\calB_{n,M}$, we use $x^n(\Gamma(\bw^n))$ to denote $(x_{1,\Gamma(w_1)},\ldots,x_{n,\Gamma(w_n)})$. For the convenience of showing our non-asymptotic achievability results, given any $(n,\gamma,\lambda_{\calJ})\in\bbN \times \bbR_+^2$ and $\calJ\in\Lambda([k])$ and random vectors $(X^n(1),\ldots,X^n(k),Y^n)$ that are generated i.i.d. from $P_{X_{[k]}Y}^{h(p)}$, define the following two events:
\begin{align}
\calG_1(n,\gamma)
&:=\big\{ \imath^{h(p)}\big(X^n(1),\ldots,X^n(k);Y^n\big) < \gamma \big\} , \label{calG1}\\
\calG_2(n,\calJ,\lambda_{\calJ})&:=\big\{ \imath^{h(p)}\big(X_{\calJ}^n;Y^n\big) > nC(p,|\calJ|)+n\lambda_\calJ \big\}\label{calG2},
\end{align}
where $X_\calJ^n=\{X_i^n\}_{i\in\calJ}$.

Furthermore, given any $(a,b,\gamma)\in\bbN^2 \times \bbR_+$ such that $a\geq b$, define the following two functions:
\begin{align}
\bbH_1(a,b,\gamma)&:=\binom{a}{b} \exp(-\gamma) , \label{calH1}\\
\bbH_2(a,b,\gamma)&:=a^b \exp(-\gamma),\label{calH2}
\end{align}
where $\binom{a}{b}:=\frac{a!}{b!(a-b)!}$ is the binomial coefficient.

Fix positive integers $(n,k,d,M)\in\bbN^4$. Recall the definitions of the function $c(\cdot)$ in \eqref{dmc} and the joint distribution $P_{X_{[k]} Y}^{h(p)}$ in \eqref{joint_d}. Recall that $L\in\bbR_+$ is the parameter for the Lipschitz continuous function. In our achievability analyses, we assume that the parameter $M$, which is used to quantize the target locations, is much greater than the number of targets $k$.

\begin{theorem} \label{th1}
For any discrete query-dependent channel satisfying the conditions in \eqref{dmc}, there exists an $(n,k,d,\frac{2}{M},\varepsilon)$-non-adaptive query procedure such that
\begin{align}
\varepsilon &\leq 4n\exp\big(-2n^dM^d\eta^2\big) + \exp\big(n \eta Lc(h(p))\big) \times \bigg( \underset{(P_{X_{[k]} Y}^{h(p)})^n}{\mathrm{Pr}}\big\{ \calG_1(n,\gamma) \big\} + \bbH_1\Big(\big((2nv_++3)n^4M^2\big)^d-k,k,\gamma\Big) \bigg. \nn\\*
&\qquad\bigg.+ \sum_{\calJ\in\Lambda([k])} \bigg( \underset{(P_{X_{[k]} Y}^{h(p)})^n}{\mathrm{Pr}}\big\{ \calG_2(n,\calJ,\lambda_{\calJ}) \big\} + \bbH_1\Big(\big((2nv_++3)n^4M^2\big)^d-k,k-|\calJ|,\gamma-nC(p,|\calJ|)-n\lambda_\calJ\Big) \bigg) \bigg). \label{th1-rlt} 
\end{align}
\end{theorem}

The proof of Theorem \ref{th1} is provided in Section \ref{Achievable Non-Asymptotic Bound DMC}. The non-asymptotic bound is achieved by the non-adaptive query procedure in Algorithm \ref{alg:1}. Analogously to~\cite{zhou2023resolution}, we first partition the $d$-dimensional unit cube $[0,1]^d$ into $(nM)^d$ equal-sized non-overlapping sub-cubes $(\mathcal{C}_1,\ldots,\mathcal{C}_{(nM)^d})$ to quantize the trajectory of $k$ targets. The reason for choosing $nM$ instead of $M$ is to ensure that the trajectory estimation resolution is within $\frac{1}{M}$ within $n$ time slots. The query procedure is divided into two phases: i) query generation and response collection, and ii) decoding. In the first phase, we choose random coding in~\cite{polyanskiy2011feedback} as the encoding method. All $n$ queries $\calA^n$ are generated based using $n$ randomly generated binary vectors $(x^n(1),\ldots,x^n((nM)^d))$ with length-$(nM)^d$. All $n$ noiseless responses from the oracle are corrupted by the query-dependent noisy channel, which yields noisy responses $y^n$. In the decoding phase, the decoder uses a single threshold rule inspired by~\cite[Section IV]{yavas2023variable}, where it is chosen as a decoding rule for variable-length sparse feedback code under MAC. Compared to the query generation phase of the algorithm in~\cite[Section III-B]{zhou2022resolution}, the unit cube is divided into $nM$ sub-cubes instead of $M$ sub-cubes in line $3$ of Algorithm $1$, meaning that searching region consists of all possible motion trajectories instead of all possible locations. Compared to the decoding phase of the algorithm in~\cite[Section III-B]{zhou2022resolution} that has $2^k-1$ thresholds for $k$ targets, our single threshold rule in \eqref{single_thres} of Algorithm \ref{alg:1} significantly reduces the computational complexity of the query procedure. Compared to the decoding phase of the algorithm in~\cite[Section III-B]{zhou2023resolution}, we use the information spectrum method~\cite[Lemma 7.10.1]{koga2002information} with a single threshold instead of the method finding the maximum mutual information density.

We next briefly explain what each term in Theorem \ref{th1} means. In \eqref{th1-rlt}, the first term $4n\exp(-2n^dM^d\eta^2)$ and the multiplicative term $\exp(n \eta Lc(h(p)))$ result from the atypicality of the query-dependent channel and the change-of-measure technique, respectively, analogously to~\cite{zhou2023resolution}. The other three terms inside the parenthesis result from the three error events leading to excess-resolution. Note that the true trajectory set consists of $k$ distinct trajectories. The first term upper bounds the probability that the mutual information density of the true trajectory set is smaller than the threshold $\lambda$. The second term upper bounds the probability that there exists another trajectory set that passes the threshold decoding rule and has no intersection with the true trajectory set. The last term upper bounds the probability that there exists another trajectory set that passes the threshold decoding rule and has intersection of less than $k$ trajectories compared to the true trajectory set. Theorem \ref{th1} is similar to~\cite[Theorem 1]{zhou2022resolution} when maximum speed $v_+=0$, with the differences coming from the improvement of single threshold decoding rule and no need to account for overlapping of two trajectories.

Since the query-dependent AWGN channel violates the continuous assumption in \eqref{dmc}, Theorem \ref{th1} does not apply. The problem can be solved by controlling the tail probability of Gaussian noise as in~\cite{zhou2023resolution}. The following definition is needed to present the result for Gaussian noise. Given any $(n,p,\sigma,\eta)\in\bbN \times (0,1) \times \bbR_+^2$, define
\begin{align}
\Xi(n,p,\sigma,\eta):=\frac{nL\eta}{h(p)-L\eta} + \frac{nL\eta\big(h(p)^2+L\eta(2h(p)+L\eta)\big)(2h(p)+L\eta)}{h(p)^2\big(h(p)^2-L\eta(2h(p)+L\eta)\big)}. \label{aleph}
\end{align}

\begin{theorem} \label{th2}
Given any positive real number $\sigma\in\bbR_+$, there exists an $\big(n,k,d,\frac{2}{M},\varepsilon\big)$-non-adaptive query procedure such that
\begin{align}
\varepsilon 
\nn&\leq 4n\exp\big(-2n^dM^d\eta^2\big) + \exp\Big(-\frac{n(1-\log 2)}{2}\Big)\\
&\qquad+ \exp\big(\Xi(n,p,\sigma,\eta)\big)\bigg( \underset{(P_{X_{[k]} Y}^{h(p)})^n}{\mathrm{Pr}}\Big\{ \calG_1(n,\gamma) \Big\} + \bbH_1\Big(\big((2nv_++3)n^4M^2\big)^d-k,k,\gamma\Big) \bigg. \nn\\
&\qquad\bigg. +\sum_{\calJ\in\Lambda([k])} \bigg( \underset{(P_{X_{[k]} Y}^{h(p)})^n}{\mathrm{Pr}}\Big\{\calG_2(n,\calJ,\lambda_{\calJ})\Big\} + \bbH_1\Big(\big((2nv_++3)n^4M^2\big)^d-k,k-|\calJ|,\gamma-nC(p,|\calJ|)-n\lambda_\calJ\Big) \bigg) \bigg). \label{th2-rlt} 
\end{align}
\end{theorem}

The proof of Theorem \ref{th2} is analogous to that of Theorem \ref{th1} and the important differences are emphasized in Section \ref{Achievable Non-Asymptotic Bound AWGN}. Relative to Theorem \ref{th1}, there is an additional term $\exp\big(-\frac{n(1-\log 2)}{2}\big)$ and coefficient term $\Xi(n,p,\delta,\eta)$, which quantify the effect of truncating the channel output.

The next result provides a non-asymptotic converse bound on the performance of any optimal non-adaptive query procedure. Fix any $(n,k,d,\varepsilon)\in\bbN^3\times(0,1)$ and recall the definition of $\imath_{\calA}(\cdot)$ in \eqref{mu_info_a}.

\begin{theorem} \label{th3}
Given any $\beta\in\big(0,\frac{1-\varepsilon}{2}\big)$ and any $\kappa\in(0,1-\varepsilon-2(1+4v_+)k^2d\beta)$, any $\delta(n,k,d,\varepsilon)$-non-adaptive query procedure satisfies
\begin{align}
-\log\delta
\nn&\leq \sup_{\calA^n\in([0,1]^d)^n}\frac{1}{2dk}\Bigg(\sup\Bigg\{r\in\bbR_+:~\mathrm{Pr}\Bigg\{\sum_{i\in[n]}\imath_{\calA_i}(Z_i;Y_i) \leq r\Bigg\} \leq \varepsilon+2(1+4v_+)k^2d\beta+\kappa\Bigg\}\\*
&\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad-dk\log(2nv_+\beta^2)-\log\kappa\Bigg), \label{th3-rlt} 
\end{align}
where $Z_i\sim\mathrm{Bern}(1-(1-|\calA_i|)^k)$.
\end{theorem}
The proof of Theorem \ref{th3} is similar to~\cite{zhou2021resolution,zhou2022resolution,zhou2023resolution} and is provided in Section \ref{Non-Asymptotic Converse Bound} for completeness. Theorem \ref{th3} resembles~\cite[Theorem 2]{zhou2022resolution} and~\cite[Theorem 3]{zhou2023resolution}, reflecting the similarity of analysis approach, specifically, converting the performance analysis of an non-adaptive query procedure to the performance analysis for a channel coding problem, followed by the application of the non-asymptotic converse bound~\cite[Proposition 4.4]{tan2014asymptotic} in channel coding.

\subsection{Second-Order Asymptotic Bounds} \label{mr Second-Order Asymptotic Bounds}

Recall the definitions of $C(k)$ in \eqref{ck} and $V(k,\varepsilon)$ in \eqref{vk}, respectively. Using the non-asymptotic bounds in Theorems \ref{th1} to \ref{th3}, we obtain the following second-order asymptotic approximation for any query-dependent DMC satisfying \eqref{dmc} and any query-dependent AWGN channel.

\begin{theorem} \label{th4}
For any excess-resolution probability $\varepsilon\in(0,1)$, the minimal achievable resolution $\delta^*(n,k,d,\varepsilon)$ of an optimal non-adaptive query procedure satisfies
\begin{align}
-\log \delta^*(n,k,d,\varepsilon)&\geq \frac{nC(k)+\sqrt{nV(k,\varepsilon)}\Phi^{-1}(\varepsilon)-4dk\log n-nv_+ + O(1)}{2dk},\label{th4-rlt}\\
-\log \delta^*(n,k,d,\varepsilon)&\leq \frac{nC(k)+\sqrt{nV(k,\varepsilon)}\Phi^{-1}(\varepsilon)+O(\log n)}{2dk}. \label{th4-rlt-2}
\end{align}
\end{theorem}

The proof of Theorem \ref{th4} requires an extension of the proofs in~\cite[Theorem 4]{zhou2023resolution} and~\cite[Theorem 3]{zhou2022resolution}. The lower bound \eqref{th4-rlt} and the upper bound \eqref{th4-rlt-2} on the negative log resolution become identical in the asymptotic limit as $n \rightarrow \infty$. The proposed single threshold procedure in Algorithm \ref{alg:1} asymptotically achieves the bound \eqref{th4-rlt}, and is therefore resolution optimal in the limit of large $n$. Theorem \ref{th4} implies that the minimal achievable resolution $\delta^*(n,k,d,\varepsilon)$ is closely related to the maximum speed $v_+$. Specifically,
\begin{align}
-2dk\log\delta^*(n,k,d,\varepsilon) =\left\{
\begin{aligned}
&nC(k)+O(nv_+)&\mathrm{if}~&nv_+=O(n^{\nu}),\nu\in[0.5,1], \\
&nC(k)+\sqrt{nV(k,\varepsilon)}\Phi^{-1}(\varepsilon)+O(nv_+)&\mathrm{if}~&nv_+=O(n^{\nu}),\nu\in(0,0.5), \\
&nC(k)+\sqrt{nV(k,\varepsilon)}\Phi^{-1}(\varepsilon)+O(\log n)&\mathrm{if}~&nv_+=O(1),
\end{aligned}
\right. \label{vclass}
\end{align}
where \eqref{vclass} identifies different regimes of $v_+$ as a function of the number of queries $n$. The above result generalizes~\cite[Corollary 2]{zhou2023resolution} that applies only to a single moving target.

Compared to~\cite[Theorem 3]{zhou2022resolution} for multiple stationary target search, Theorem \ref{th4} differs in two aspects: i) the denominator has an extra coefficient of $2$, ii) the numerator has an extra penalty term $nv_+$. The first term reflects that searching for moving targets twice as hard as searching for stationary targets. Put another way, searching for moving targets is equivalent to searching for double dimensional stationary targets, which specializes to~\cite[Theorem 4]{zhou2023resolution} when $k=1$. The second term appears since moving target search has maximal speed $v_+$. 

When specialized to stationary target search with $v_+=0$, the query procedure in Algorithm \ref{alg:1} with single threshold decoding achieves the same performance as the optimal query procedure~\cite{zhou2022resolution} that has $2^k-1$ thresholds for $k$ targets. Since only a single threshold is used, the computational complexity of Algorithm \ref{alg:1} is much lower.

Finally, in Fig. \ref{fig2}, we plot the second-order approximations to achievable resolutions as a function of the number of targets for various cases of maximal speed $v_+$. As observed, when the number of targets $k$ or the maximal speed $v_+$ increases, the achievable resolution decreases. The above numerical result is consistent with our intuition since it is more challenging to locate more number of targets or faster moving targets.

