\centering
\includegraphics[width=.7\columnwidth]{fig4_BTP.eps}
\caption{The beam tracking procedure with $k$ mobile TXs moving over the plane ($d=2$) and a stationary RX.}
\label{fig4}
\end{figure}

The first step is to quantize the angular space $[0,\pi]\times\big[0,\frac{\pi}{2}\big]$ of the RX into $M \times \frac{M}{2}$ sub-spaces denoted as $\big(\mathtt{C}_1,\ldots,\mathtt{C}_{\frac{M^2}{2}}\big)$. Given the total number of the sampling time points $n\in\mathbb{N}$, for any real-time AoA pair $\phi_{\mathrm{az,el}}:=(\phi_\mathrm{az},\phi_\mathrm{el})\in[0,\pi]\times\big[0,\frac{\pi}{2}\big]$, define the quantization function as follows:
\begin{align}
\mathrm{q}_{\mathrm{bt}}(\phi_{\mathrm{az,el}},n):= \Big(\Big\lceil\frac{\phi_\mathrm{az}}{\pi}\times nM\Big\rceil-1\Big) \times nM+\Big\lceil\frac{\phi_\mathrm{el}}{\pi/2}\times\frac{nM}{2}\Big\rceil.
\end{align}

Given any $\phi_{\mathrm{az,el}}\in[0,\pi]\times\big[0,\frac{\pi}{2}\big]$ and $\mathtt{v}_{\mathrm{az,el}}:=(\mathtt{v}_\mathrm{az},\mathtt{v}_\mathrm{el})\in[-\mathtt{v}_+,-\mathtt{v}_+]^2$, if a beam moves with a constant velocity pair $\mathtt{v}_{\mathrm{az,el}}$ from an initial AoA pair $\phi_{\mathrm{az,el}}$ at any sampling time point $i\in[n]$, the coordinate $\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},i)$ of the real-time AoA satisfies
\begin{align}
\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},i):=\Big(\mathrm{mod}\big(\phi_{\mathrm{az}}+i\mathtt{v}_{\mathrm{az}},\pi\big),\mathrm{mod}\Big(\phi_{\mathrm{el}}+i\mathtt{v}_{\mathrm{el}},\frac{\pi}{2}\Big)\Big).
\end{align}
After all $n$ sampling time points, let $\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},[n])$ denote $(\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},1),\ldots,\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},n))$ and $\mathrm{q}_{\mathrm{bt}}^n(\phi_{\mathrm{az,el}}^n,n)$ denote $(\mathrm{q}_{\mathrm{bt}}(\phi_{\{\mathrm{az,el}\},1},n),\ldots,\mathrm{q}_{\mathrm{bt}}(\phi_{\{\mathrm{az,el}\},n},n))$.

Assume that there are $k$ TXs in the communication system with initial AoA pairs $\phi_{\mathrm{az,el}}^k\in\big([0,\pi]\times\big[0,\frac{\pi}{2}\big]\big)^k$ and velocity pairs $\mathtt{v}_{\mathrm{az,el}}^k\in[-\mathtt{v}_+,-\mathtt{v}_+]^{2k}$. Recall the system model defined in Section \ref{app sm}. The beam tracking procedure is defined as follows and \blue{is} illustrated in Fig. \ref{fig4}. At first, the RX sets $n$ sampling time points and generates beamforming vectors $\mathtt{w}(i)$ for each time point $i$ in advance. Then $k$ TXs move at their respective constant velocities from their initial locations and send pilot sequences to the RX. After $n$ samples, the RX obtains $n$ decision results using power threshold $\iota$ and estimates the initial AoA pairs $\hat{\phi}_\mathrm{az,el}^k$ and velocity pairs $\hat{\mathtt{v}}_\mathrm{az,el}^k$ based on them.

\begin{definition} \label{def7}
Given any total number of sampling time points and TXs $(n,k)\in\bbN^{2}$, any tolerable resolution $\delta\in\bbR_+$ and constant $\varepsilon\in(0, 1)$, an $(n,k,\delta,\varepsilon)$ beam tracking procedure consists of
\begin{itemize}
\item[$\bullet$] $n$ query set $(\calA_1,\dots,\calA_n) \subseteq \big([0,\pi]\times\big[0,\frac{\pi}{2}\big]\big)^{n}$ and $n$ corresponding beamforming vector $(\mathtt{w}_{\calA_1}(1)\dots,\mathtt{w}_{\calA_n}(n)) \subseteq \mathbb{C}^{n}$, 
\item[$\bullet$] a power threshold $\iota\in\mathbb{R}_+$, making that for each sampling time point $i\in[n]$, the received signal power exceeds $\iota$ when at least one real-time AoA pair satisfies $\mathtt{b}(\phi_{\mathrm{az,el}},\mathtt{v}_{\mathrm{az,el}},i)\in\calA_i$ and does not exceed $\iota$ when none pair satisfies,
\item[$\bullet$] a estimator $g_\mathrm{bt}$ that obtains estimates of AoA pairs $\hat{\phi}_\mathrm{az,el}^k\in\big([0,\pi]\times\big[0,\frac{\pi}{2}\big]\big)^{k}$ and velocity pairs $\hat{\mathtt{v}}_\mathrm{az,el}^k\in[-\mathtt{v}_+,-\mathtt{v}_+]^{2k}$ after $n$ queries,
\end{itemize}
such that the excess-resolution probability satisfies
\begin{align}
&\mathrm{P_e}(n,k,\delta) \nn\\
&:= \sup \mathrm{Pr}\bigg\{ \exists~t\in[k]:\min_{(\hat{\phi}_\mathrm{az,el},\hat{\mathtt{v}}_\mathrm{az,el})\in(\hat{\phi}_\mathrm{az,el}^k,\hat{\mathtt{v}}_\mathrm{az,el}^k)} \max_{i\in[0:n]} \Big\| \mathtt{b}\big(\hat{\phi}_{\mathrm{az,el}},\hat{\mathtt{v}}_{\mathrm{az,el}},i\big)-\mathtt{b}\big(\phi_{\{\mathrm{az,el}\},t},\mathtt{v}_{\{\mathrm{az,el}\},t},i\big) \Big\|_{\infty} > \delta \bigg\} \leq \varepsilon.
\end{align}
\end{definition}

The following theorem establish the equivalence of twenty questions estimation and beam tracking.

\begin{theorem} \label{20Q-BeamTracking}
For any $(n,k,\delta,\varepsilon)\in\bbN^2 \times \bbR_+ \times [0,1]$, with any $(n,k,\delta,\varepsilon)$ beam tracking procedure, we can construct an $\big(n,k,2,\frac{\delta}{\pi},\varepsilon\big)$-non-adaptive query procedure for twenty questions estimation. Furthermore, with any $(n,k,2,\delta,\varepsilon)$-non-adaptive query procedure for twenty questions, we can construct an $(n,k,2,\pi\delta,\varepsilon)$ for beam tracking. 
\end{theorem}

\begin{proof}
Fix any $(n,k,\delta,\varepsilon)$ beam tracking procedure. By normalizing the entire angular space $[0,\pi]\times\big[0,\frac{\pi}{2}\big]$ to the two-dimensional unit cube $[0,1]^2$, we can associate the AoAs to moving targets with initial locations $\bS^k$ and velocities $\bV^k$ to be estimated. The angular space covered by $n$ beamforming vectors $(\mathtt{w}_{\calA_1}(1),\ldots,\mathtt{w}_{\calA_n}(n))$ can also be normalized to $n$ query regions $(\calA_1,\ldots,\calA_n)$. Then, we can estimate the initial locations $\hat{\bS}^k$ and velocities $\hat{\bV}^k$ of the $k$ targets after using the power threshold $\iota$ to obtain noisy query responses, and de-normalize them to the angular space.

Fix any $(n,k,2,\delta,\varepsilon)$-non-adaptive query procedure. By mapping the two-dimensional unit cube $[0,1]^2$ to the angular space $[0,\pi]\times\big[0,\frac{\pi}{2}\big]$, the $k$ moving targets represent $k$ TXs with AoA pairs $\phi_\mathrm{az,el}^k$ and velocity pairs $\mathtt{v}_\mathrm{az,el}^k$. Then, we can generate beamforming vectors $(\mathtt{w}_{\calA_1}(1),\ldots,\mathtt{w}_{\calA_n}(n))$ for searching the corresponding space based on the random query regions $(\calA_1,\ldots,\calA_n)$. Furthermore, we serve the noisy responses from the oracle as the decision results obtained by the RX using $1$-bit measurement model. Finally, we can estimate the AoA pairs $\hat{\phi}_\mathrm{az,el}^k$ and the velocity pairs $\hat{\mathtt{v}}_\mathrm{az,el}^k$ with the help of the decoder in the beam tracking procedure, and remap them to the unit cube.
\end{proof}


