\subsection{Proof Sketch of Prior Information on Target Velocities (Theorem \ref{caseA-2order})} 
\label{Specialization Bound 1}

\begin{algorithm}[ht]
\caption{Non-Adaptive Query Procedure for the Initial Location Search of Multiple Moving Targets with Known Velocities}
\label{alg:2} 
\begin{algorithmic}[0]  
\REQUIRE
The number of queries $n\in\bbN$, dimension $d\in\bbN$, the vector of targets' velocities $(\bv_1,\ldots,\bv_k)\in([-v_+,v_+]^d)^k$ and three design parameters $(M,p,\gamma)\in\bbN \times (0,1) \times \bbR_+$
\ENSURE
A set of estimated targets' initial locations $\hat{\calS}^k\in([0,1]^d)^k$
~\\
\hrule 
~\\
\STATE Divide the $d$-dimensional unit cube $[0,1]^d$ into $M^d$ equally sized non-overlapping sub-cubes $(\calC_1,\ldots,\calC_{M^d})$.
\STATE \textbf{\emph{Query generation and response collection:}}
\STATE Generate $n$ binary vectors $(x^n(1),\ldots,x^n(M^d))$ with length-$M^d$, where each vector is generated i.i.d. from Bern$(p)$.
\FOR{$i\in[n]$}
\STATE Form a query region $\calA_i$ as
\begin{align}
\calA_i:=\bigcup_{j\in[M^d]: x_{i,j}=1} \calC_j \nn.
\end{align}
\STATE Pose the $i$-th query about whether there are targets in the region $\calA_i$ and obtain a noisy response $y_i$ from the oracle.
\ENDFOR
\STATE Collect noisy responses $y^n=(y_1,\ldots,y_n)$.
\STATE \textbf{\emph{Decoding:}}
\IF{there exists a set of trajectories $\{\hat{\bw}_1^n,\ldots,\hat{\bw}_k^n\}\in\calB_{n,M}(\bv_1) \times \ldots \times \calB_{n,M}(\bv_k)$ such that $$\imath^{h(p)}\big(x^n(\Gamma(\hat{\bw}_1^n)),\ldots,x^n(\Gamma(\hat{\bw}_k^n)); y^n\big) \geq \gamma,$$}
\RETURN estimates $\{\hatbs_1,\ldots,\hatbs_k\}$ such that for any $t\in[k]$, $$w(\hatbs_t,\bv_t,[n])=\hat{\bw}_t^n.$$
\ELSE
\RETURN estimates $\{ \hatbs_1,\ldots,\hatbs_k \}$ such that $\hatbs_t = \mathbf{0.5}_{d \times 1}$ for each $t\in[k]$.
\ENDIF
\end{algorithmic}
\end{algorithm}

We still consider the same three excess-resolution events $\calE_1,\calE_2$ and $\calE_3$ mentioned in Section \ref{Achievable Non-Asymptotic Bound DMC}. Recall the definitions of events $\calG_1(\cdot),\calG_2(\cdot)$ in \eqref{calG1}, \eqref{calG2} and functions $\bbH_1(\cdot),\bbH_2(\cdot)$ in \eqref{calH1}, \eqref{calH2}. Given any $k$ targets' initial locations $\bs^k\in([0, 1]^d)^k$, for any query matrix $\mathbf{X}\in(\{0,1\}^n)^{M^d}$ and noisy responses $Y^n\in\calY^n$, when targets’ velocities $\bv^k\in([-v_+, v_+]^d)^k$ are known, the respective probabilities are as follows:
\begin{align}
\underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{\calE_1\big(\bs^k,\bv^k,\mathbf{X},Y^n\big)\big\} &= \underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{ \calG_1(n,\gamma) \big\} , \\
\underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{\calE_2\big(\bs^k,\bv^k,\mathbf{X},Y^n\big)\big\} &\leq \bbH_2\big(M^d-1,k,\gamma\big) , \\
\underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{\calE_3\big(\bs^k,\bv^k,\mathbf{X},Y^n\big)\big\} &\leq
\sum_{\calJ\in\Lambda([k])} \bigg(\underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{\calG_2(n,\calJ,\lambda_{\calJ})\big\} + \bbH_2\big(M^d-1,k-|\calJ|,\gamma-nC(p,|\calJ|)-n\lambda_\calJ\big)\bigg).
\end{align}

Therefore, given $(n, k, d)\in\bbN^3$, fixed constants $(\gamma,\lambda_{\calJ})\in\bbR_+^2$ for $\calJ\in\Lambda([k])$, for any $(M, p, \eta)\in\bbN \times (0,1) \times \bbR_+$, we have the achievable non-asymptotic bound for an $\big(n,k,d,\frac{1}{M},\varepsilon\big)$-non-adaptive query procedure with known velocities under any query-dependent DMC satisfying \eqref{dmc} such that
\begin{align}
\varepsilon &\leq 4n\exp\big(-2M^d\eta^2\big) + \exp\big(n \eta Lc(h(p))\big) \times \bigg( \underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{ \calG_1(n,\gamma) \big\} + \bbH_2\big(M^d-1,k,\gamma\big) \bigg. \nn\\ 
&\qquad\qquad\qquad\qquad \bigg.+ \sum_{\calJ\in\Lambda([k])} \bigg( \underset{P_{\mathbf{X}Y^n}^{\mathrm{alt}}}{\mathrm{Pr}}\big\{\calG_2\big(n,\calJ,\lambda_{\calJ}\big)\big\}+\bbH_2\big(M^d-1,k-|\calJ|,\gamma-nC(p,|\calJ|)-n\lambda_\calJ\big) \bigg) \bigg) ,
\end{align}
which shows that the excess-resolution probability is not affected by the maximum speed when targets' velocities are known. In other words, the multiple moving target case is equivalent to the multiple stationary targets case when targets' velocities are known because of the strong correspondence between velocity and trajectory.

Then, recall the definitions of $C(p,k)$ in \eqref{cempty} and $V(p,k)$ in \eqref{vempty}. We choose $M$ and $\gamma$ such that for some $\varepsilon^{\prime}\in(0,1)$,
\begin{align}
\log M &= \frac{1}{dk}\Big(nC(p,k)+\sqrt{nV(p,k)}\Phi^{-1}(\varepsilon^{\prime})-\frac{1}{2}\log n\Big) , \\
\gamma &= dk\log M + \frac{1}{2}\log n ,
\end{align}
and combine the same idea of data transmission over a point-to-point channel used in~\cite[Section III-C]{zhou2022resolution}. For any $(n, k, d, \varepsilon)\in\bbN^3 \times (0,1)$, we can obtain the second-order asymptotic bound as follows:
\begin{align}
-\log \delta^*(n,k,d,\varepsilon) = \frac{nC(k)+\sqrt{nV(k,\varepsilon)}\Phi^{-1}(\varepsilon)+\Theta(\log n)}{dk}.
\end{align}


