T_{\calA^{n_B}}&:=\frac{1}{n_B}\sum_{i\in[n_B]} \mathbb{E}\Big[\big|\imath_{\calA_i}(Z_i;Y_i)-\mathbb{E}[\imath_{\calA_i}(Z_i;Y_i)]\big|^3\Big] ,
\end{align}
and let $V_{\_} \in \bbR_+$ be chosen such that $V_{\_} \leq V_{\calA^{n_B}}$. Using the Berry-Esseen theorem, we have that
\begin{align}
\mathrm{Pr}\bigg\{\sum_{i\in[n_B]}\imath_{\calA_i}(Z_i;Y_i) \leq r\bigg\} \geq \Phi\Big(\frac{r-n_BC_{\calA^{n_B}}}{\sqrt{n_BV_{\calA^{n_B}}}}\Big)-\frac{6T_{\calA^{n_B}}}{\sqrt{n_B}\big(\sqrt{V_{\_}}\big)^3}.
\end{align}
Thus, for any $\varepsilon\in(0,1)$,
\begin{align}
\sup\bigg\{r\in\bbR_+:\mathrm{Pr}\bigg\{\sum_{i\in[n_B]}\imath_{\calA_i}(Z_i;Y_i) \leq r\bigg\} \leq \varepsilon\bigg\} \leq n_BC_{\calA^{n_B}}+\sqrt{n_BV_{\calA^{n_B}}}\Phi^{-1}\bigg(\varepsilon+\frac{6T_{\calA^{n_B}}}{\sqrt{n_B}\big(\sqrt{V_{\_}}\big)^3}\bigg).
\end{align}

Choosing $\beta=\frac{1}{\sqrt{n_B}}$ and $\kappa=\frac{1}{\sqrt{n_B}}$, we can obtain the second-order asymptotic converse bound under a piecewise constant velocity model as follows:
\begin{align}
-(B+1)dk\log \delta^*(\mathbf{n},k,d,\varepsilon) \leq n_BC(k)+\sqrt{n_BV(k,\varepsilon)}\Phi^{-1}(\varepsilon)+O(\log n_B).
\end{align}

