\dot{V}_2 &=& G(V_2,W_2,I)+cV_1 \qquad \dot{W}_2 = H(V_2,W_2)\\
\dot{V}_3 &=& G(V_3,W_3,I)+cV_2 \qquad \dot{W}_3 = H(V_3,W_3)\\
