\end{itemize}

\vspace{1mm}

\item[{\rm (c)}] Note that if $G = {\rm L}_n(2).2$ with $n \geqs 5$ odd, then \cite[Theorem 1]{Z_ln2} implies that $A \cap B^x \ne 1$ for all $x \in G$ if and only if $A$ and $B$ are both Sylow $2$-subgroups of $G$. This explains why $n$ is even for $G = {\rm L}_n(2).2$ in Table \ref{tab:primary}. And by \cite[Theorem 2]{Z_L2}, the same conclusion holds when 
$G = {\rm L}_2(q).2$ and $q \geqs 7$ is a Mersenne prime.
\end{itemize}
\end{remk}

In order to conclude the introduction, we present several remarks describing some related open problems.

\begin{remk}\label{r:ls}
Let $G$ be a finite group and let $P_i$ be a Sylow $p_i$-subgroup of $G$, where $p_1, \ldots, p_n$ are the distinct prime divisors of $|G|$. In a recent preprint \cite{LS}, Lisi and Sabatini conjecture that there exists an element $x \in G$ such that for each $i$, $P_i \cap P_i^x$ is inclusion-minimal in the set $\{P_i \cap P_i^g \,:\, g \in G\}$. So for a simple group $G$, in view of the main theorem of \cite{ZM}, this conjecture asserts that there is an element $x \in G$ such that $P_i \cap P_i^x = 1$ for all $i$. In particular, if $H$ is a nilpotent subgroup of $G$ (with $G$ simple), then $H \cap H^x = 1$ and so \cite[Conjecture A]{LS} immediately implies Conjecture \ref{c:nilp}. The Lisi-Sabatini conjecture is proved in \cite{LS} for all metanilpotent groups of odd order, as well as all sufficiently large symmetric and alternating groups. The latter asymptotic result relies on a probabilistic argument, which applies recent work of Diaconis et al. \cite{D25} and Eberhard \cite{Eb}. 
\end{remk}

\begin{remk}\label{r:ab}
Let $G$ be a finite non-abelian simple group and let $H$ be a nilpotent subgroup. Recall that Conjecture \ref{c:nilp} asserts that $H \cap H^x = 1$ for some $x \in G$. In fact, in several special cases, it has been shown that if $A$ and $B$ are any nilpotent subgroups of $G$, then $A \cap B^x = 1$ for some $x \in G$. This is proved in 
\cite{Z_spor,Z_sym} for alternating and sporadic groups, and we refer the reader to
\cite{Z_dim3,Z_L2} for the low-rank Lie type groups ${\rm L}_2(q), {\rm L}_3(q)$ and ${\rm U}_3(q)$. Given these results, it seems reasonable to speculate that this property holds for all simple groups, which can be viewed as a natural generalisation of Conjecture \ref{c:nilp}.
\end{remk}

\begin{remk}\label{r:depth}
Let $G$ be a finite group and let $H$ be a proper subgroup. In 2011, Boltje, Danz and K\"{u}lshammer \cite{BDK} introduced and studied the \emph{depth} of $H$, denoted $d_G(H)$, which is a positive integer defined in terms of the inclusion of complex group algebras $\mathbb{C}H \subseteq \mathbb{C}G$ (we refer the reader to \cite{BDK} for the formal definition). This notion has been the focus of numerous papers and there  has been a particular interest in studying the depth of subgroups of simple and almost simple groups (see \cite{B25} and the references therein). In this setting, if $G$ is almost simple and $H \ne 1$ is core-free, then we have 
\begin{equation}\label{e:dep}
3 \leqs d_G(H) \leqs 2b(G,H) -1
\end{equation}
(see \cite[Propositions 2.2 and 2.6]{B25}, for example). In particular, if $b(G,H) = 2$ then $d_G(H) = 3$, so the main theorem of \cite{ZM} implies that every Sylow subgroup of a simple group has depth $3$ (and Conjecture \ref{c:nilp} asserts that every non-trivial nilpotent subgroup has depth $3$). In view of Theorem \ref{t:main1}, in order to determine the depth of every Sylow subgroup of an almost simple group, it just remains to consider the pairs $(G,H)$ recorded in Table \ref{tab:zen}. Since $b(G,H) = 3$, the bounds in \eqref{e:dep} imply that $d_G(H) \in \{3,4,5\}$ and further work is needed in order to determine the precise depth of $H$:

\begin{itemize}\addtolength{\itemsep}{0.2\baselineskip}
\item[{\rm (a)}] As noted in \cite[Remark 8(b)]{B25}, if $G = {\rm PGL}_2(q)$ and $H$ is a Sylow $2$-subgroup of $G$, where $q$ is a Mersenne prime, then $d_G(H) = 5$. 
\item[{\rm (b)}] The relevant groups with socle ${\rm P\O}_8^{+}(3)$, $A_8$, $A_6$ and ${\rm L}_3(4)$ can be handled using {\sc Magma} and the character-theoretic approach for calculating $d_G(H)$, which is explained in \cite[Section 2.1.1]{B25}. In every case, we get $d_G(H) = 5$.
\item[{\rm (c)}] It remains an open problem to determine $d_G(H)$ for the remaining cases in Table \ref{tab:zen}, where $p=2$ and $G = F_4(2).2$, $E_6(2).2$, ${\rm L}_n(2).2$ or ${\rm O}_{n}^{+}(2)$. We have used {\sc Magma} to check that $d_G(H) = 5$ for $G = {\rm L}_n(2).2$ with $3 \leqs n \leqs 7$, and for $G = {\rm O}_n^{+}(2)$ with $n = 8$ or $10$. 
\end{itemize}

\noindent So there is some evidence to suggest that if $G$ is almost simple and $H$ is a Sylow $p$-subgroup of $G$, where $p$ is a prime divisor of $|G|$, then either $d_G(H) = 3$, or $(G,H)$ is one of the cases in Table \ref{tab:zen} and $d_G(H) = 5$.
\end{remk}

\begin{remk}\label{r:sylow}
Let $G$ be an almost simple group and set $N = N_G(H)$, where $H$ is a Sylow $p$-subgroup of $G$ and $p$ is a prime divisor of $|G|$. Then we can identify $G/N$ with the set of Sylow $p$-subgroups of $G$ and we can think of $b(G,N)$ as the base size with respect to the natural transitive action of $G$ by conjugation on the set of Sylow $p$-subgroups of $G$. Of course, if $N = H$, then $b(G,N)$ is given in Theorem \ref{t:main1}. However, it remains an open problem to determine $b(G,N)$ when $N \ne H$. Here we speculate that the upper bound $b(G,N) \leqs 4$ is best possible, noting that equality holds when $G = S_6$ and $p=3$ (in which case, $N = S_3 \wr S_2$ is a maximal subgroup of $G$). Let us also observe that there are examples where $b(G,N) > 2$ and $p$ is arbitrarily large (in contrast to the situation for $b(G,H)$, where Theorem \ref{t:zenkov} shows that $b(G,H) >2$ only if $p \leqs 3$). For example, if $G = {\rm L}_2(p)$ with $p \geqs 5$, then $N$ is a Borel subgroup of $G$ and we have $b(G,N) = 3$ (see \cite[Proposition 4.1]{Bur21}).
\end{remk}

