\subsection{Involutions}\label{ss:invol}

Our proof of Theorem \ref{t:main1} will rely on Lemma \ref{l:prob}, which means that we will need to compute an appropriate upper bound on $\widehat{Q}(G,H)$. And to do this, we will make use of Lemma \ref{l:est}. Let $I_2(G)$ be the set of involutions in $G$.

Typically, we will proceed by partitioning $I_2(G)$ into two or three disjoint subsets, say $\mathcal{I}_1, \ldots, \mathcal{I}_k$, and we will establish bounds of the form $|x^G \cap H| \leqs a_j$ and $|x^G| \geqs b_j$ for all $x \in \mathcal{I}_j$. Then Lemma \ref{l:est} yields
\[
\widehat{Q}(G,H) \leqs \sum_{j=1}^{k} a_j^2b_j^{-1}
\]
and our aim is to use this upper bound to force $\widehat{Q}(G,H)<1$.

In order to effectively apply this approach, we need some information on the `small' conjugacy classes of involutions in almost simple groups of Lie type in odd characteristic. For the exceptional groups, it turns out that we will only require a lower bound on $|x^G|$ that holds for all $x \in I_2(G)$ and we can refer to \cite[Proposition 2.11]{BTh} for this information (see \eqref{e:fq} in the proof of Proposition \ref{p:ex}). However, for classical groups, we will usually need to know the sizes of the two or three smallest conjugacy classes and with this aim in mind we present the following technical result. In the statement, we refer to the notation for involutions from \cite[Table 4.5.1]{GLS}.

\begin{prop}\label{p:inv}
Let $G$ be an almost simple classical group over $\mathbb{F}_q$ with socle $G_0$, where $q$ is odd. Let $x \in G$ be an involution.

\begin{itemize}\addtolength{\itemsep}{0.2\baselineskip}
\item[{\rm (i)}] If $G_0 = {\rm L}_n^{\e}(q)$ with $n \geqs 5$, then either $x$ is a $t_1$-type involution and
\[
|x^G| = \frac{|{\rm GL}^{\e}_n(q)|}{|{\rm GL}^{\e}_{n-1}(q)||{\rm GL}^{\e}_1(q)|} = \frac{q^{n-1}(q^n-\e^n)}{q-\e},
\]
or $|x^G| \geqs f(n,q)$ with
\[
f(n,q) = \left\{
\begin{array}{ll}
\frac{|G_0|}{|{\rm SU}_5(q_0)|} =  \frac{1}{d}q^5(q+1)(q^{3/2}-1)(q^2+1)(q^{5/2}-1) 
& \mbox{if $(\e,n,q) = (+,5,q_0^2)$} \\
\frac{|G_0|}{|{\rm PSp}_6(q)|} = \frac{2}{d}q^6(q^3-\e)(q^5-\e) & \mbox{if $n=6$} \\
\frac{|{\rm GL}_n^{\e}(q)|}{|{\rm GL}_{n-2}^{\e}(q)||{\rm GL}_2^{\e}(q)|} = \frac{q^{2n-4}(q^{n-1}-\e^{n-1})(q^n-\e^n)}{(q^2-1)(q-\e)} & \mbox{otherwise,}
\end{array}\right.
\]
where $d = (n,q-\e)$.

\item[{\rm (ii)}] If $G_0 = {\rm L}_4^{\e}(q)$, then either $x$ is a $\gamma_1$ graph automorphism and
\[
|x^G| \geqs \frac{|G_0|}{|{\rm PSp}_4(q)|} \geqs \frac{1}{2}q^2(q^3-\e),
\]
or 
\[
|x^G| \geqs \frac{|{\rm GL}^{\e}_4(q)|}{|{\rm GL}^{\e}_{3}(q)||{\rm GL}^{\e}_1(q)|} = \frac{q^{3}(q^4-1)}{q-\e}.
\]

\item[{\rm (iii)}] If $G_0 = {\rm PSp}_n(q)$ with $n \geqs 6$, then either $x$ is a $t_1$-type involution and
\[
|x^G| = \frac{|{\rm Sp}_n(q)|}{|{\rm Sp}_{n-2}(q)||{\rm Sp}_2(q)|} = \frac{q^{n-2}(q^n-1)}{q^2-1},
\]
or $|x^G| \geqs f(n,q)$ with
\[
f(n,q) = \left\{
\begin{array}{ll}
\frac{|G_0|}{|{\rm Sp}_{6}(q_0)|} = \frac{1}{2}q^{9/2}(q+1)(q^2+1)(q^3+1) & \mbox{if $(n,q)=(6,q_0^2)$} \\
\frac{|G_0|}{|{\rm GU}_{3}(q)|} = \frac{1}{2}q^6(q-1)(q^2+1)(q^3-1) & \mbox{if $n=6$, $q \ne q_0^2$} \\
\frac{|G_0|}{|{\rm Sp}_{4}(q^2)|} = \frac{1}{2}q^8(q^2-1)(q^6-1) & \mbox{if $n=8$} \\
\frac{|{\rm Sp}_n(q)|}{|{\rm Sp}_{n-4}(q)||{\rm Sp}_4(q)|} = \frac{q^{2n-4}(q^{n-2}-1)(q^n-1)}{(q^4-1)(q^2-1)} & \mbox{otherwise.} \\
\end{array}\right.
\]

\item[{\rm (iv)}] If $G_0 = {\rm PSp}_4(q)$, then either $x$ is a $t_2$-type or $t_2'$-type involution and
\[
|x^G| \geqs \frac{|G_0|}{|{\rm Sp}_{2}(q^2)|} = \frac{1}{2}q^2(q^2-1),
\]
or $|x^G| \geqs f(n,q)$ with
\[
f(n,q) = \left\{
\begin{array}{ll}
\frac{|G_0|}{|{\rm Sp}_{4}(q_0)|} = \frac{1}{2}q^2(q+1)(q^2+1) & \mbox{if $q=q_0^2$} \\
\frac{|G_0|}{|{\rm GU}_{2}(q)|} = \frac{1}{2}q^3(q-1)(q^2+1) & \mbox{otherwise.} \\
\end{array}\right.
\]

\item[{\rm (v)}] If $G_0 = \O_n(q)$ with $n = 2m+1 \geqs 7$, then either $x$ is a $t_m$-type or $t_m'$-type involution and
\[
|x^G| \geqs \frac{|{\rm SO}_n(q)|}{2|{\rm SO}_{n-1}^{-}(q)|} = \frac{1}{2}q^{m}(q^{m}-1),
\]
or 
\[
|x^G| \geqs \frac{|{\rm SO}_n(q)|}{2|{\rm SO}_{n-2}(q)||{\rm SO}_{2}^{-}(q)|} = \frac{q^{n-2}(q^{n-1}-1)}{2(q+1)}.
\]

\item[{\rm (vi)}] If $G_0 = {\rm P\O}_n^{\e}(q)$ with $n = 2m \geqs 8$, then either $x$ is a $\gamma_1$ graph automorphism and
\[
|x^G| \geqs \frac{|{\rm SO}_n^{\e}(q)|}{2|{\rm SO}_{n-1}(q)|} = \frac{1}{2}q^{m-1}(q^{m}-1),
\]
or
\[
|x^G| \geqs \frac{|{\rm SO}_n^{\e}(q)|}{2|{\rm SO}_{n-2}^{-\e}(q)||{\rm SO}_{2}^{-}(q)|} = \frac{q^{n-2}(q^m-\e)(q^{m-1}-1)}{2(q+1)}.
\]
\end{itemize}
\end{prop}

\begin{proof}
This is a straightforward exercise, working with the detailed information on conjugacy classes of semisimple involutions and involutory graph automorphisms presented in \cite[Table 4.5.1]{GLS} (also see \cite[Chapter 3]{BGiu}).

For example, suppose $G_0 = {\rm PSp}_n(q)$ with $n=2m \geqs 10$ and let $x \in G$ be an involution. If $x \in G$ is a field automorphism, then $q = q_0^2$ and \cite[Proposition 3.4.15]{BGiu} gives
\[
|x^G| \geqs \frac{|G_0|}{|{\rm Sp}_n(q_0)|} > \frac{1}{2}q^{n(n+1)/4}.
\]
Otherwise, $x \in {\rm PGSp}_n(q)$ is semisimple and we can read off $|x^G|$ from \cite[Table 4.5.1]{GLS} (or \cite[Table B.5]{BGiu}). Then either $x$ is an involution of type $t_m$, $t_m'$, $t_{m/2}$ or $t_{m/2}'$ (in the notation of \cite[Table 4.5.1]{GLS}), in which case
\[
|x^G| \geqs \frac{|G_0|}{|{\rm Sp}_m(q^2)|} > \frac{1}{4}q^{n^2/4},
\]
or $x$ is an involution of type $t_i$ with $1 \leqs i < m/2$ and we have
\[
|x^G| = \frac{|{\rm Sp}_n(q)|}{|{\rm Sp}_{n-2i}(q)||{\rm Sp}_{2i}(q)|}.
\]
By comparing the above expressions, we deduce that $|x^G|$ is minimal when $x$ is a $t_1$-type involution. And for all other involutions, $|x^G|$ is minimal when $x$ is of type $t_2$, which gives the result recorded in part (iii). Note that the latter statement is false when $n = 8$ since 
\[
\frac{|{\rm Sp}_8(q)|}{2|{\rm Sp}_{4}(q)|^2} > \frac{|{\rm Sp}_8(q)|}{2|{\rm Sp}_{4}(q^2)|},
\]
which explains why the expression for $f(n,q)$ in (iii) has a different form when $n=8$ (and similarly when $n=6$).

A very similar argument applies in each of the remaining cases and we omit the details.
\end{proof}

\subsection{Computational methods}\label{ss:comp}

In the proof of Theorem \ref{t:main1}, it will be convenient to use direct computation to handle certain low rank groups of Lie type defined over small fields. For all the computations, we will use {\sc Magma} \cite{magma} (version V2.28-21).

In order to state our main result, let us define $\mathcal{A}$ to be the following collection of simple groups of Lie type, recalling that we use the notation for simple groups from \cite{KL}:

\renewcommand{\arraystretch}{1.2}
\[
\begin{array}{l}
{\rm L}_4^{\e}(3), \, {\rm L}_4^{\e}(5), \, {\rm L}_4^{\e}(7), \, {\rm L}_4^{\e}(9), \, {\rm L}_4^{\e}(17), \,{\rm L}_4(31), \, {\rm L}_4(127), \, {\rm U}_5(3), \, {\rm L}_5(9), \, {\rm U}_6(3), \, {\rm L}_8^{\e}(3),\,   {\rm PSp}_{4}(3), \\
{\rm PSp}_{4}(5), \, {\rm PSp}_{4}(7),\, {\rm PSp}_{4}(9), \, {\rm PSp}_{4}(17), \, {\rm PSp}_{6}(3), \, {\rm PSp}_{8}(3), {\rm PSp}_{10}(3), \, \O_7(3), \, \O_9(3), \, \O_{11}(3), \\
\O_{13}(3), \, {\rm P\O}_{8}^{\pm}(3), \, {\rm P\O}_{10}^{\pm}(3),\, {\rm P\O}_{12}^{\pm}(3), \, G_2(3)
\end{array}
\]
\renewcommand{\arraystretch}{1}

\begin{prop}\label{p:comp}
Let $G$ be an almost simple group with socle $G_0 \in \mathcal{A}$ and let $H$ be a Sylow $2$-subgroup of $G$. Then $b(G,H) = 2$.
\end{prop}

\begin{proof}
To begin with, assume $G_0 \ne {\rm P\O}_{8}^{+}(3)$. We first construct the full automorphism group $L = {\rm Aut}(G_0)$ as a permutation group, using the function \texttt{AutomorphismGroupSimpleGroup}, and we take a Sylow $2$-subgroup $J$ of $L$. In every case, we note that $L/G_0$ is a $2$-group and we can use random search to find an element $x \in L$ such that $J \cap J^x = 1$. This means that $J$ has a regular orbit on $L/J$, which in turn implies that $H$ has a regular orbit on $G/H$ and thus $b(G,H) = 2$.

Finally, suppose $G_0 = {\rm P\O}_{8}^{+}(3)$. Here $|{\rm Out}(G_0)| = 24$ and we can use {\sc Magma} to construct the index-three subgroup $L = {\rm PGO}_8^{+}(q) = G_0.D_8$ of ${\rm Aut}(G_0)$ as a permutation group of degree $3360$. We can then proceed as before, taking a Sylow $2$-subgroup $J$ of $L$ and using random search to find an element $x \in L$ such that $J \cap J^x = 1$. The result follows.
\end{proof}

\section{Proof of Theorem \ref{t:main1}}\label{s:main1}

We are now ready to prove Theorem \ref{t:main1}. Our starting point is Zenkov's main reduction theorem for almost simple groups from \cite{Z_92p}, which we stated as Theorem \ref{t:zenkov} in Section \ref{s:intro}. For the reader's convenience, in the following remark we provide a brief overview of Zenkov's proof.

\begin{rem}\label{r:zenkov}
Let $G$ be an almost simple group with socle $G_0$ and let $H$ be a Sylow $p$-subgroup of $G$, where $p$ is a prime divisor of $|G|$. 

\begin{itemize}\addtolength{\itemsep}{0.2\baselineskip}
\item[{\rm (a)}] A starting point is the main theorem from \cite{ZM} on simple groups, which allows us to assume that $p$ divides $|G:G_0|$. In particular, $p=2$ when $G_0$ is an alternating or sporadic group; the argument for symmetric groups is given in \cite{ZM} and the $12$ sporadic groups of the form $G = G_0.2$ are handled case-by-case in \cite[Section 3]{Z_92p} (the result for sporadic groups can also be verified very easily using {\sc Magma} \cite{magma}, proceeding as in the proof of Proposition \ref{p:comp}).

\item[{\rm (b)}] Now assume $G_0$ is a simple group of Lie type over $\mathbb{F}_q$. For $p$ odd, a long and technical argument, based on the elimination of a counterexample of minimal order, is presented in \cite[Section 6]{Z_92p}. Here the main result is \cite[Theorem 6.1]{Z_92p}, which shows that $b(G,H) = 3$ if and only if $p=3$ and $G_0 = {\rm P\O}_8^{+}(3)$, with $G$ recorded in Table \ref{tab:zen}. Here it is worth noting that it is easy to use {\sc Magma} to verify that $b(G,H) = 3$ for the two relevant groups with $G_0 = {\rm P\O}_8^{+}(3)$.

\item[{\rm (c)}] The analysis for $p=2$ divides naturally into two cases, according to whether or not $q$ is odd or even, and the main details are given in Sections 4 and 5 of \cite{Z_92p}, respectively. For $q$ odd, the main result is \cite[Theorem 4.1]{Z_92p}, which implies that $b(G,H) = 2$ unless $q=9$ or $q$ is a Mersenne or Fermat prime. The proof relies on a detailed analysis of a minimal counterexample, with \cite[Lemma 4.3]{Z_92p} as a key tool. The latter states that if $G$ is a minimal counterexample, then $O_2(C) \cap H^x \ne 1$ for all $x \in G$, where $C = C_G(z)$ is the centraliser of an involution $z \in Z(H) \cap G_0$. Then by studying the structure of involution centralisers in $G$, in many cases Zenkov is able to reach a contradiction by establishing the existence of an element $x \in G$ with $O_2(C) \cap H^x = 1$.

\item[{\rm (d)}] In \cite[Lemma 3.18]{Z_92p}, Zenkov proves that $b(G,H) = 3$ when $p=2$ and either $G = {\rm Aut}({\rm L}_2(9)) = {\rm L}_2(9).2^2 \cong A_6.2^2$ or $G = {\rm PGL}_2(q)$ with $q \geqs 7$ a Mersenne prime.

\item[{\rm (e)}] Finally, suppose $p=2$ and $q$ is even. Here the first main result is \cite[Theorem 5.1]{Z_92p}, which tells us that $b(G,H) = 3$ only if $G_0$ is one of the following (here we exclude ${\rm L}_4(2).2 \cong S_8$ and ${\rm PSp}_4(2)'.2^2 \cong {\rm L}_2(9).2^2$):
\[
\hspace{12mm} {\rm L}_3(4), \, {\rm L}_n(2) \mbox{ $(n \geqs 3)$}, \, \O_n^{\pm}(2) \mbox{ $(n \geqs 8)$},\, E_6(2), \, F_4(2), \, {}^2F_4(2)', \, G_2(2)' 
\]
As before, the proof proceeds by studying the structure of a minimal counterexample, using the fact that $N_G(H)$ is a Borel subgroup of $G$. 

\vspace{2mm}

\noindent And then it remains to determine which of these possibilities lead to the genuine examples with $b(G,H) = 3$ recorded in Table \ref{tab:zen}. For instance,  suppose $G = {\rm L}_n(2).2$, $\Omega_n^+(2).2$, $E_6(2).2$ or $F_4(2).2$ and set $H_0 = H \cap G_0$. By \cite[Lemma 3.13]{Z_92p}, $H_0$ has a  unique regular orbit on ${\rm Syl}_2(G_0)$ with respect to the usual conjugation action. And since $N_{G_0}(H_0) = H_0$, it follows that $H_0$ has a unique regular orbit on $G_0/H_0$ and this implies that $b(G,H)>2$ (indeed, if $b(G,H) = 2$ then $H_0$ would have at least $|H:H_0| = 2$ regular orbits on $G_0/H_0$).
\end{itemize}
\end{rem}

By combining Zenkov's main theorem for almost simple groups in \cite{Z_92p} (see Theorem \ref{t:zenkov} in Section \ref{s:intro}), together with \cite[Lemma 3.18]{Z_92p} (socle ${\rm L}_2(q)$) and the main results in \cite{Z_dim3} (socle ${\rm L}_3(q)$ or ${\rm U}_3(q)$) and \cite{ZM} (simple groups), we see that it suffices to prove the following result.

\begin{thm}\label{t:main2}
Let $G$ be an almost simple group of Lie type over $\mathbb{F}_q$ with socle $G_0$ and let $H$ be a Sylow $2$-subgroup of $G$. Assume that 
\begin{itemize}\addtolength{\itemsep}{0.2\baselineskip}
\item[{\rm (i)}] $G_0$ is not isomorphic to ${\rm L}_2(q)$, ${\rm L}_3(q)$ or ${\rm U}_3(q)$;
\item[{\rm (ii)}] $|G:G_0|$ is even; and 
\item[{\rm (iii)}] Either $q=9$, or $q$ is a Mersenne or Fermat prime.
\end{itemize}
Then $b(G,H) = 2$.  
\end{thm}

\subsection{Exceptional groups}\label{ss:excep}

\begin{prop}\label{p:ex}
The conclusion to Theorem \ref{t:main2} holds when $G$ is an exceptional group of Lie type.
\end{prop}

\begin{proof}
First observe that the hypotheses in parts (ii) and (iii) of Theorem \ref{t:main2} imply that \[
G_0 \ne {}^2B_2(q), \, {}^2G_2(q)', \, {}^2F_4(q)'.
\]
Set $\a = (q^2-1)_2$ and $\b = \delta_{9,q}$ (so $\b = 1$ if $q=9$, otherwise $\b=0$). Note that $\a \leqs 2(q+1)$.

\renewcommand{\arraystretch}{1.2}
Let $x \in G$ be an involution. Then by appealing to \cite[Proposition 2.11]{BTh}, we see that $|x^G|> f_G(q)$, where $f_G(q)$ is defined as follows (with $\gamma = (q-1)/q$ and $\delta = (3,q-\e)^{-1}$):
\begin{equation}\label{e:fq}
\begin{array}{l|llllll}
G_0 & E_8(q) & E_7(q) & E_6^{\e}(q) & F_4(q) & {}^3D_4(q) & G_2(q) \\ \hline
f_G(q) & q^{112} & \frac{1}{2}\gamma q^{54} & \gamma\delta q^{26} & q^{16} & q^{14} & q^7
\end{array}
\end{equation}
Let $H$ be a Sylow $2$-subgroup of $G$ and set $H_0 = H \cap G_0$. As in \eqref{e:Q}, let $Q(G,H)$ be the probability that two random elements in $\O = G/H$ form a base for $G$ and recall that $Q(G,H) \leqs \widehat{Q}(G,H)$ as in \eqref{e:Qhat}, so it suffices to show that $\widehat{Q}(G,H)<1$.  
\renewcommand{\arraystretch}{1}

First assume $G_0 = E_8(q)$. Here Proposition \ref{p:syl} gives $|H_0| = 2^6\a^8$ and we deduce that $|H| \leqs 2^{14+\b}(q+1)^8 = a$. Since $|x^G| > f_G(q)$ for every involution $x \in G$, Lemma \ref{l:est} implies that
\begin{equation}\label{e:easy}
\widehat{Q}(G,H) \leqs a^2f_G(q)^{-1}
\end{equation}
and it is easy to check that this upper bound is less than $1$ for all $q \geqs 3$. Similarly, \eqref{e:easy} holds in each of the remaining cases, where $f_G(q)$ is given in \eqref{e:fq} and $a = 2^{c+\b}(q+1)^d$ with  
\[
(c,d) = (10,7),\, (8,6), \, (7,4), \, (2,2), \, (3,2) 
\]
for $G_0 = E_7(q), E_6^{\e}(q), F_4(q), {}^3D_4(q), G_2(q)$, respectively. It is now a routine exercise to check that the upper bound in \eqref{e:easy} is sufficient unless $G_0 = F_4(3)$, $G_2(5)$ or $G_2(3)$. Here the first two possibilities can be discarded since $G$ is simple (recall that we may assume $|G:G_0|$ is even), while the latter case was handled in Proposition \ref{p:comp}.
\end{proof}

\subsection{Classical groups}\label{ss:class}

In this section we complete the proof of Theorem \ref{t:main1} by establishing Theorem \ref{t:main2} for classical groups. Throughout, we will adopt the standard notation for classical groups given in \cite{KL}. In particular, we write ${\rm L}_n(q) = {\rm L}_n^{+}(q) $ and ${\rm U}_n(q) = {\rm L}_n^{-}(q)$ for the projective linear and unitary groups ${\rm PSL}_n(q)$ and ${\rm PSU}_n(q)$. We also denote the simple orthogonal groups by ${\rm P\O}_n^{\e}(q)$, which differs from the notation for orthogonal groups used in the Atlas \cite{Atlas}, for example. 

Let $G$ be an almost simple classical group over $\mathbb{F}_q$ as in the statement Theorem \ref{t:main2}. By combining the hypotheses of the theorem with the existence of well-known isomorphisms among some of the low-dimensional classical groups (see \cite[Proposition 2.9.1]{KL}, for example), we may assume $G_0$ is one of the following:
\[
\begin{array}{ll}
{\rm L}_n(q), \, {\rm U}_n(q) & n \geqs 4 \\
{\rm PSp}_n(q) & \mbox{$n \geqs 4$ even} \\
\O_n(q) & \mbox{$n \geqs 7$ odd} \\
{\rm P\O}_n^{+}(q), \, {\rm P\O}_n^{-}(q) & \mbox{$n \geqs 8$ even}
\end{array}
\]

We will sometimes refer to the `type' of a subgroup $L$ of $G$, which is intended to provide an approximate description of the structure of $L$. For example, if $G_0 = {\rm P\O}_{10}^{+}(q)$ then we may refer to a subgroup $L$ of type $({\rm O}_{2}^{-}(q) \wr S_4) \times {\rm O}_{2}^{+}(q)$, which indicates that $L$ is the stabiliser in $G$ of an orthogonal decomposition 
\[
V = U \perp W = (U_1 \perp U_2 \perp U_3 \perp U_4) \perp W
\]
of the natural module $V$ for $G_0$, where each $U_i$ is a $2$-dimensional non-degenerate subspace of minus-type, and $W$ is a non-degenerate $2$-space of plus-type (recall that if $m = 2\ell$ is even, then an orthogonal $m$-space is of \emph{plus-type} if it contains a totally singular $\ell$-space, otherwise it is a \emph{minus-type} space).

Finally, we refer the reader to \cite[Table 4.5.1]{GLS} and \cite[Chapter 3]{BGiu} for detailed information on the conjugacy classes of involutions in ${\rm Aut}(G_0)$. As in the statement of Proposition \ref{p:inv}, we will freely adopt the notation for involutions given in \cite[Table 4.5.1]{GLS}.

\begin{prop}\label{p:psl}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = {\rm L}_n(q)$.
\end{prop}

\begin{proof}
Let $H$ be a Sylow $2$-subgroup of $G$ and set $H_0 = H \cap G_0$ and $\a = (q^2-1)_2$ as before. In addition, set $d = (n,q-1)$ and $\b = \delta_{9,q}$.

Given an integer $1 \leqs k \leqs n/2$, we say that an involution $x \in G$ is of type $t_k$ if it is conjugate in ${\rm PGL}_n(q)$ to $y = \hat{y}Z$, where $\hat{y} = (-I_k,I_{n-k}) \in {\rm GL}_n(q)$ is a diagonal matrix and $Z$ is the centre of ${\rm GL}_n(q)$. This notation is consistent with \cite[Table 4.5.1]{GLS}.

\vs

\noindent \emph{Case 1. $n$ odd, $q \equiv 1 \imod{4}$}

\vs

Here $n = 2m+1 \geqs 5$ and either $q = 9$ or $q \in \{5, 17, 257, 65537, \ldots\}$ is a Fermat prime. In particular, $q-1$ is a $2$-power and $\a = 2(q-1)$. As recorded in Table \ref{tab:syl}, we have
\[
|H_0| = \a^m((q-1)_2)^m(m!)_2 = (q-1)^{n-1}((n-1)!)_2 = (q-1)^{n-1}(n!)_2
\]
and it follows that $H$ is contained in a subgroup $L$ of $G$ of type ${\rm GL}_1(q) \wr S_n$. The case $(n,q) = (5,9)$ was handled in Proposition \ref{p:comp}, so we may assume $n \geqs 7$ if $q=9$.

Suppose $x \in G$ is a $t_1$-involution. Then
\begin{equation}\label{e:psl1}
|x^G| = \frac{|{\rm GL}_n(q)|}{|{\rm GL}_{n-1}(q)||{\rm GL}_1(q)|} = \frac{q^{n-1}(q^n-1)}{q-1} = b_1
\end{equation}
and we claim that $H$ contains at most $a_1 = n+\binom{n}{2}(q-1)$ such elements. To justify the claim, we will count the number of involutions of type $(-I_1,I_{n-1})$ in the subgroup $J = {\rm GL}_1(q) \wr S_n$ of ${\rm GL}_n(q)$. Visibly, there are $\binom{n}{1} = n$ such elements in the base group $B = {\rm GL}_1(q)^n$ of $J$. And if $x \in B\pi$ with $1 \ne \pi \in S_n$, then $\pi$ is a transposition, $x$ is $B$-conjugate to $\pi$ and we have $|C_B(x)| = |{\rm GL}_1(q)|^{n-1}$. Since $S_n$ contains $\binom{n}{2}$ transpositions, it follows that there are exactly $\binom{n}{2}(q-1)$ such involutions in $J \setminus B$, whence $a_1$ in $J$ in total.

By Proposition \ref{p:inv}, if $x \in G$ is a non-$t_1$ involution then
\begin{equation}\label{e:psl2}
|x^G| \geqs \frac{|{\rm GL}_n(q)|}{|{\rm GL}_{n-2}(q)||{\rm GL}_2(q)|} = \frac{q^{2n-4}(q^{n-1}-1)(q^n-1)}{(q^2-1)(q-1)} = b_2
\end{equation}
(minimal if $x$ is a $t_2$-involution, using the fact that $(n,q) \ne (5,9)$) and we note that 
\[
|H| = |H_0||G:G_0|_2 \leqs (q-1)^{n-1}((n-1)!)_22^{1+\b} < 2^{n+\b}(q-1)^{n-1} = a_2,
\]
since $((n-1)!)_2 < 2^{n-1}$ by Lemma \ref{l:factorial}.

Then by applying Lemmas \ref{l:prob} and \ref{l:est}, we deduce that
\begin{equation}\label{e:two}
Q(G,H) < a_1^2b_1^{-1} + a_2^2b_2^{-1}
\end{equation}
and it is routine to check that this upper bound yields $Q(G,H) < 1$ and thus $b(G,H) = 2$.

\vs

\noindent \emph{Case 2. $n$ odd, $q \equiv 3 \imod{4}$}

\vs

Here $n = 2m+1 \geqs 5$ and $q \in \{3, 7, 31, 127, 8191, \ldots\}$ is a Mersenne prime. Note that $q+1$ is a $2$-power and $\a = 2(q+1)$. By inspecting Table \ref{tab:syl},
\[
|H_0| = \a^m((q-1)_2)^m(m!)_2 = (2\a)^m(m!)_2
\]
and we deduce that $H$ is contained in a subgroup $L$ of $G$ of type $({\rm GL}_2(q) \wr S_m) \times {\rm GL}_1(q)$. Here $L$ is the stabiliser in $G$ of a direct sum decomposition of the natural module of the form
\[
V = U \oplus W = (U_1 \oplus \cdots \oplus U_m) \oplus W,
\]
where $\dim W = 1$ and each $U_i$ is $2$-dimensional. The case $(n,q) = (5,3)$ was handled in Proposition \ref{p:comp}, so we may assume $q \geqs 7$ when $n = 5$. 

As in Case 1, if $x \in G$ is a $t_1$-involution then $|x^G| = b_1$ as in \eqref{e:psl1} and by counting the number of such elements in $L$ we deduce that there are at most 
\[
a_1 = 1 + \binom{m}{1}\frac{|{\rm GL}_2(q)|}{|{\rm GL}_1(q)|^2} = 1+mq(q+1)
\]
such involutions in $H$. And for any other involution $x \in G$ we see that \eqref{e:psl2} holds and we note that $|H| \leqs 2^{3m}(q+1)^m = a_2$. As before, the result now follows via the upper bound in \eqref{e:two}.

\vs

\noindent \emph{Case 3. $n$ even, $q \equiv 1 \imod{4}$}

\vs

Here $n = 2m \geqs 4$ and either $q=9$ or $q$ is a Fermat prime. From Table \ref{tab:syl} we read off
\[
|H_0| = \frac{1}{d}\a^m(q-1)^{m-1}(m!)_2 = \frac{1}{d}(q-1)^{n-1}(n!)_2
\]
and we see that $H$ is contained in a subgroup $L$ of type ${\rm GL}_1(q) \wr S_n$.

For $n \geqs 8$, we can now proceed as in Case 1 and we deduce that \eqref{e:two} holds, where $a_1,b_1$ and $b_2$ are defined as in Case 1, and we set $a_2 = 2^{n+1+\b}(q-1)^{n-1}$. It is easy to check that the bound in \eqref{e:two} implies that $Q(G,H) <1$ for all $n \geqs 8$ and $q \geqs 5$, so for the remainder of Case 3 we may assume $n = 4$ or $6$.

Suppose $n = 6$ and note that $d = (n,q-1) = 2$. In view of Proposition \ref{p:comp}, we may assume $q \geqs 17$. As above, the contribution to $\widehat{Q}(G,H)$ from $t_1$-involutions is at most $a_1^2b_1^{-1}$, where $a_1$ and $b_1$ are defined as before. As recorded in Proposition \ref{p:inv}, if $x \in G$ is any other involution then $|x^G|$ is minimal when $x$ is a $\gamma_1$-type  graph automorphism (rather than a $t_2$-involution) and thus
\[
|x^G| \geqs \frac{|G_0|}{|{\rm PSp}_6(q)|} = q^6(q^3-1)(q^5-1)=b_2.
\]
In addition, we have $|H| \leqs 2^{1+\b}(q-1)^5(6!)_2 = 2^{5+\b}(q-1)^5=a_2$. It is now routine to check that the upper bound in \eqref{e:two} is sufficient.

Finally, let us assume $n=4$. The groups with $q \in \{5,9,17\}$ were handled in Proposition \ref{p:comp}, so we may assume $q \geqs 257$. As usual, the contribution to $\widehat{Q}(G,H)$ from $t_1$-involutions is at most $a_1^2b_1^{-1}$. If $x \in G$ is a $\gamma_1$ graph automorphism, then 
\[
|x^G| \geqs \frac{|G_0|}{|{\rm PSp}_4(q)|} = \frac{1}{2}q^2(q^3-1)=b_2.
\]
and the proof of \cite[Proposition 2.7]{FPR3} indicates that there are at most 
\[
\frac{4!}{2!2^2}|{\rm GL}_1(q)| = 3(q-1)=a_2
\]
such elements in $L$. And since $q$ is a prime, we see that  
\[
|x^G| \geqs \frac{|{\rm GL}_4(q)|}{2|{\rm GL}_2(q^2)|} = \frac{1}{2}q^4(q-1)(q^3-1)=b_3
\]
for all other involutions $x \in G$. Now $|H| \leqs 2^{1+\b}(q-1)^3(4!)_2 = 2^{4+\b}(q-1)^3=a_3$, so 
\begin{equation}\label{e:three}
Q(G,H)< a_1^2b_1^{-1} + a_2^2b_2^{-1} + a_3^2b_3^{-1}
\end{equation}
and it is straightforward to check that this upper bound is less than $1$ for all $q \geqs 257$.

\vs

\noindent \emph{Case 4. $n$ even, $q \equiv 3 \imod{4}$}

\vs

Write $n = 2m \geqs 4$ and note that $q$ is a Mersenne prime. From Table \ref{tab:syl} we read off
\[
|H_0| = \frac{1}{2}\a^m(q-1)^{m-1}(m!)_2,
\]
which allows us to conclude that $H$ is contained in a subgroup $L$ of type ${\rm GL}_2(q) \wr S_m$. 

Let $x \in G$ be a $t_1$-involution and note that $|x^G| = b_1$, where $b_1$ is defined as in \eqref{e:psl1}. We calculate that there are at most 
