\begin{prop}\label{p:psu}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = {\rm U}_n(q)$.
\end{prop}

\begin{proof}
As in the proof of the previous proposition, let $H$ be a Sylow $2$-subgroup of $G$ and set $H_0 = H \cap G_0$ and $\a = (q^2-1)_2$. Write $d = (n,q+1)$ and $\b = \delta_{9,q}$.

For an integer $1 \leqs k \leqs n/2$, we say that $x \in G$ is of type $t_k$ if it is conjugate in ${\rm PGU}_n(q)$ to $y = \hat{y}Z$, where $\hat{y} = (-I_k,I_{n-k}) \in {\rm GU}_n(q)$ is a diagonal matrix (with non-degenerate eigenspaces) and $Z$ is the centre of ${\rm GU}_n(q)$. As before, this notation is consistent with \cite[Table 4.5.1]{GLS}.

\vs

\noindent \emph{Case 1. $n$ odd, $q \equiv 1 \imod{4}$}

\vs

Write $n = 2m+1 \geqs 5$ and note that $\a = 2(q-1)$. By inspecting Table \ref{tab:syl}, we see that
\[
|H_0| = \a^m((q+1)_2)^m(m!)_2 = 2^{n-1}(q-1)^{n-1}(m!)_2
\]
and hence $H$ is contained in a subgroup $L$ of $G$ of type $({\rm GU}_2(q) \wr S_m)\perp {\rm GU}_1(q)$. Here the notation indicates that $L$ is the stabiliser in $G$ of an orthogonal decomposition  
\[
V = U \perp W = (U_1 \perp \cdots \perp U_m) \perp W
\]
of the natural module $V$ for $G_0$, where $W$ is a non-degenerate $1$-space and each $U_i$ is a non-degenerate $2$-space.

Suppose $x \in G$ is a $t_1$-involution. Then
\begin{equation}\label{e:psu1}
|x^G| = \frac{|{\rm GU}_n(q)|}{|{\rm GU}_{n-1}(q)||{\rm GU}_1(q)|} = \frac{q^{n-1}(q^n-(-1)^n)}{q+1} = b_1
\end{equation}
and by arguing as in the proof of Proposition \ref{p:psl} (see Case 2), we can show that there are at most 
\[
1+ \binom{m}{1}\frac{|{\rm GU}_2(q)|}{(q+1)^2} = 1+mq(q-1) = a_1
\]
