\begin{prop}\label{p:psp}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = {\rm PSp}_n(q)$.
\end{prop}

\begin{proof}
Here $n = 2m \geqs 4$ and we set $H_0 = H \cap G_0$ and $\a = (q^2-1)_2$ as before, where $H$ is a Sylow $2$-subgroup of $G$. As in \cite[Table 4.5.1]{GLS}, we say that an involution $x \in G$ is of type $t_1$ if it is $G_0$-conjugate to $y = \hat{y}Z$, where $\hat{y} = (-I_2,I_{n-2}) \in {\rm Sp}_n(q)$ is a diagonal matrix (with non-degenerate eigenspaces) and $Z$ is the centre of ${\rm Sp}_n(q)$. As usual, set $\b = \delta_{9,q}$.

\vs

\noindent \emph{Case 1. $n \geqs 6$}

\vs

By inspecting Table \ref{tab:syl}, we see that $|H_0| = \frac{1}{2}\a^m(m!)_2$ and thus $H$ is contained in a subgroup $L$ of $G$ of type ${\rm Sp}_2(q) \wr S_m$. In particular, if $x$ is a $t_1$-involution, then 
\begin{equation*}
|x^G| = \frac{|{\rm Sp}_{n}(q)|}{|{\rm Sp}_{n-2}(q)||{\rm Sp}_2(q)|} = \frac{q^{n-2}(q^n-1)}{q^2-1} = b_1
\end{equation*}
and by counting in $L$ we deduce that there are at most 
\begin{equation*}
\binom{m}{1} + \binom{m}{2}|{\rm Sp}_2(q)| = m\left(1+\frac{1}{2}(m-1)q(q^2-1)\right) = a_1
\end{equation*}
such elements in $H$.

First assume $n \geqs 10$. If $x \in G$ is a non-$t_1$ involution, then Proposition \ref{p:inv} implies that 
\begin{equation*}
|x^G| \geqs \frac{|{\rm Sp}_{n}(q)|}{|{\rm Sp}_{n-4}(q)||{\rm Sp}_4(q)|} > \frac{1}{2}q^{4n-16} = b_2.
\end{equation*}
In addition, $|H| \leqs 2^{n+\b}(q+1)^{m} = a_2$ and one can check that the upper bound in \eqref{e:two} is good enough unless $(n,q) = (10,3)$. But the latter case was handled in Proposition \ref{p:comp}, so the result follows.

Similarly, if $n=8$ and $x$ is a non-$t_1$ involution, then 
\[
|x^G| \geqs \frac{|{\rm Sp}_{8}(q)|}{2|{\rm Sp}_{4}(q^2)|}  = \frac{1}{2}q^8(q^2-1)(q^6-1) = b_2
\]
and we have $|H| \leqs 2^{7+\b}(q+1)^4 = a_2$. Then \eqref{e:two} holds and we immediately deduce that $Q(G,H) < 1$ if $q \geqs 5$. This completes the argument since we treated the case $G_0 = {\rm PSp}_8(3)$ in Proposition \ref{p:comp}.

Next assume $n=6$. If $x$ is a non-$t_1$ involution, then 
\[
|x^G| \geqs \frac{|{\rm Sp}_{6}(q)|}{2|{\rm GU}_{3}(q)|} = \frac{1}{2}q^{6}(q-1)(q^2+1)(q^3-1) = b_2
\]
(see Proposition \ref{p:inv}) and we note that $|H| \leqs 2^{4+\b}(q+1)^3 = a_2$. Then \eqref{e:two} holds and we deduce that $Q(G,H)<1$ for all $q \geqs 5$. This just leaves the case $G_0 = {\rm PSp}_6(3)$, which was handled in Proposition \ref{p:comp}.

\vs

\noindent \emph{Case 2. $n=4$}

\vs

For the remainder of the proof, we may assume $n = 4$. The groups with $q \leqs 17$ can be handled using {\sc Magma} (see Proposition \ref{p:comp}), so we may assume $q \geqs 31$ is a Fermat or Mersenne prime. In particular, $G = {\rm PGSp}_4(q) = G_0.2$. Write $G_0 = L/Z$ and $H_0 = J/Z$, where $Z$ is the centre of $L = {\rm Sp}_4(q)$, and note that
\begin{align*}
J & = Q_{2(q-\e)} \wr S_2 < {\rm Sp}_2(q) \wr S_2 \\
H & = D_{2(q-\e)} \wr S_2,
\end{align*}
where $\e = 1$ if $q \equiv 1\imod{4}$, otherwise $\e= -1$ (here $Q_{2(q-\e)}$ denotes the quaternion group of order $2(q-\e)$). In particular, $|H| = 8(q-\e)^2$. Given a finite group $X$, we recall that $i_2(X)$ denotes the number of involutions in $X$.

To begin with, we will assume $q \equiv 1 \imod{4}$, so $q \geqs 257$ is a Fermat prime and
\[
i_2(H) = (q+1)^2 -1 + 2(q-1) = q^2+4q-2.
\]
There are four $G$-classes of involutions, with representatives labelled $t_1,t_2,t_1'$ and $t_2'$ in \cite[Table 4.5.1]{GLS}. Here $t_1,t_2 \in G_0$ and $t_1',t_2' \in G \setminus G_0$. It will be useful to note that the involutions of type $t_1$ lift to involutions in $L$, whereas those of type $t_2$ lift to elements of order $4$.

Suppose $x \in G$ is a $t_1$-involution. Then 
\[
|x^G| = \frac{|{\rm Sp}_{4}(q)|}{2|{\rm Sp}_2(q)|^2} = \frac{1}{2}q^2(q^2+1) = b_1
\]
and we note that $x = \hat{x}Z \in L/Z$ with $\hat{x} \in L$ an involution of type $(-I_2,I_2)$. Now 
\[
i_2(J) = 2q+|Z|-1 = 2q+1
\]
since $Q_{2(q-1)}$ has a unique involution, and we deduce that exactly $q$ involutions in $H_0$ lift to an involution in $J$. This means that $H$ contains $a_1 = q$ involutions of type $t_1$. Similarly, we calculate that there are precisely $q^2+4q-1$ elements $y \in J$ of order $4$ with $y^2 \in Z$ and this allows us to conclude that $H$ contains $(q^2+4q-1)/2$ involutions of type $t_2$.

Now let $x \in G$ be an involution of type $t_1'$ in the notation of \cite[Table 4.5.1]{GLS}. Here $x \in G \setminus G_0$ and
\[
|x^G| = \frac{|{\rm Sp}_{4}(q)|}{2|{\rm Sp}_2(q^2)|} = \frac{1}{2}q^2(q^2-1) = b_2.
\]
Moreover, our previous calculations show that there are at most 
\[
i_2(H) - q - \frac{1}{2}(q^2+4q-1) = \frac{1}{2}(q^2+2q-3) = a_2
\]
such involutions in $H$.

Now, if $x \in G$ is an involution of type $t_2$ or $t_2'$, then 
\[
|x^G| \geqs \frac{|{\rm Sp}_{4}(q)|}{2|{\rm GU}_{2}(q)|} = \frac{1}{2}q^{3}(q-1)(q^2+1) = b_3
\]
and we note that $|H| = 8(q-1)^2 = a_3$. It follows that \eqref{e:three} holds and we conclude that $Q(G,H)<1$ for all $q \geqs 257$.

A very similar argument applies when $q \equiv 3 \imod{4}$. Here the involutions in $G$ of type $t_1$ and $t_2'$ are contained in $G_0$, whereas those of type $t_1'$ and $t_2$ are in $G \setminus G_0$. Since $H = D_{2(q+1)} \wr S_2$ we compute
\[
i_2(H) = (q+3)^2 - 1 +2(q+1) = q^2+8q+10
\]
and as before we calculate that $H$ contains $a_1 = q+2$ involutions of type $t_1$. By counting the elements $y \in J$ of order $4$ with $y^2 \in Z$, we deduce that there are $(q^2+8q+11)/2$ involutions of type $t_2'$ in $H$. As a consequence, it follows that $H$ contains at most 
\[
i_2(H) - (q+2) - \frac{1}{2}(q^2+8q+11) = \frac{1}{2}(q^2+6q+5) = a_2
\]
involutions of type $t_1'$. Putting this together, we deduce that \eqref{e:three} holds with $a_3 = 8(q+1)^2$ and $a_1,a_2,b_1,b_2,b_3$ defined as above. It is now easy to check that this upper bound on $Q(G,H)$ is less than $1$ for all $q \geqs 31$.
\end{proof}

\begin{prop}\label{p:o_odd}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = \O_n(q)$.
\end{prop}

\begin{proof}
Here $n = 2m+1 \geqs 7$ and we set $H_0 = H \cap G_0$, where $H$ is a Sylow $2$-subgroup of $G$. For $k \in \{1,2\}$, we will say that an involution $x \in {\rm SO}_n(q) = G_0.2$ is of type $s_k$ if it is conjugate to an element of the form $(-I_{n-1},I_1)$ for $k=1$, or $(-I_2,I_{n-2})$ for $k = 2$ (in the notation of \cite[Table 4.5.1]{GLS}, these are the involutions of type $t_m$ or $t_m'$ (for $k=1$), and type $t_1$ or $t_1'$ (for $k=2$)). Note that if $x \in G$ is an involution of type $s_1$ then
\begin{equation}\label{e:o_odd1}
|x^G| \geqs \frac{|{\rm SO}_n(q)|}{2|{\rm SO}_{n-1}(q)|} = \frac{1}{2}q^{m}(q^{m}-1) = b_1.
\end{equation}
And similarly, if $x$ is an $s_2$-type involution then
\begin{equation}\label{e:o_odd2}
|x^G| \geqs \frac{|{\rm SO}_n(q)|}{2|{\rm SO}_{n-2}(q)||{\rm SO}_{2}^{-}(q)|} = \frac{q^{n-2}(q^{n-1}-1)}{2(q+1)} = b_2.
\end{equation}
As recorded in Table \ref{tab:syl}, we have $|H_0| = \frac{1}{2}\a^m(m!)_2$, where $\a = (q^2-1)_2$. Let $V$ be the natural module for $G_0$. As before, set $\b = \delta_{9,q}$.

\vs

\noindent \emph{Case 1. $q \equiv 1 \imod{4}$}

\vs

First we assume $q \equiv 1 \imod{4}$, so $|H_0| = \frac{1}{2}(2(q-1))^m(m!)_2$ and we note that $H$ is contained in a subgroup $L$ of $G$ of type 
\[
({\rm O}_2^{+}(q) \wr S_m) \perp {\rm O}_{1}(q) < {\rm O}_{2m}^{+}(q) \perp {\rm O}_1(q).
\]
Note that $L$ is the stabiliser in $G$ of an orthogonal decomposition of the form
\[
V = U \perp W = (U_1 \perp U_2 \perp \cdots \perp U_m) \perp W,
\]
where each $U_i$ is a $2$-dimensional non-degenerate orthogonal space of plus-type and $W$ is a non-degenerate $1$-space (recall that a $2$-dimensional orthogonal space is of \emph{plus-type} if it contains a non-zero singular vector with respect to the defining quadratic form). In particular, if $G = {\rm SO}_n(q) = G_0.2$, then
\[
L = D_{2(q-1)} \wr S_m = {\rm O}_2^{+}(q) \wr S_m < {\rm O}_{2m}^{+}(q) < G.
\]

Let $x \in G$ be an $s_1$-type involution, so $|x^G| \geqs b_1$ as in \eqref{e:o_odd1}. Working in $L$, and noting that $D_{2(q-1)}$ has exactly $q-1$ non-central involutions, we calculate that $H$ contains at most 
\[
\binom{m}{1}(q-1) +1 = m(q-1)+1 = a_1
\]
such elements. And if $x \in G$ is any other type of involution, then Proposition \ref{p:inv} implies that $|x^G| \geqs b_2$ with $b_2$ defined as in \eqref{e:o_odd2} and we note that $|H| \leqs 2^{n-1+\b}(q-1)^m = a_2$. It follows that $Q(G,H)$ satisfies the upper bound in \eqref{e:two} and this allows us to deduce that $Q(G,H)<1$ unless $(n,q) \in \{ (7,5), (7,9), (9,5)\}$. In the latter cases, by setting $a_2 = 2^{\b}(q-1)^m(n!)_2$, one can check that \eqref{e:two} is sufficient. 

\vs

\noindent \emph{Case 2. $q \equiv 3 \imod{4}$}

\vs

Here $|H_0| = \frac{1}{2}(2(q+1))^m(m!)_2$ and $H$ is contained in a subgroup $L$ of $G$ of type 
\[
({\rm O}_2^{-}(q) \wr S_m) \perp {\rm O}_{1}(q) < {\rm O}_{2m}^{\e}(q) \perp {\rm O}_1(q),
\]
where $\e = +$ if $m$ is even, otherwise $\e=-$. By arguing as in Case 1, we deduce that the contribution to $\widehat{Q}(G,H)$ from $s_1$-involutions is at most $a_1^2b_1^{-1}$, where $a_1 = m(q+1)+1$ and $b_1$ is defined in \eqref{e:o_odd1}. And if $x \in G$ is an $s_2$-type involution, then $|x^G| \geqs b_2$ as above and we note that $|H| \leqs 2^{n-1}(q+1)^m = a_2$. Then as in Case 1, we deduce that \eqref{e:two} holds and for $q \geqs 7$ we check that this bound is sufficient unless $q = 7$ and $n \in \{7,9,11\}$. But in each of these cases, by setting $a_2 = 2^m(q+1)^m(m!)_2$, we obtain $Q(G,H)<1$ via \eqref{e:two}.

Now suppose $q=3$. In view of Proposition \ref{p:comp}, we may assume $n \geqs 15$. Here we need a more accurate estimate of the number of $s_2$-involutions in $H$. By working in $L$, we calculate that there are at most $a_2$ such elements, where
\begin{align*}
a_2 & = \binom{m}{1}+\binom{m}{1}(q+1) + \binom{m}{2}(q+1)^2 + \binom{m}{2}|{\rm O}_2^{-}(q)| \\
& = m(q+2)+\frac{1}{2}m(m-1)\left((q+1)^2+2(q+1)\right).
\end{align*}
And if $x \in G$ is an involution, which is not of type $s_1$ or $s_2$, then it is easy to see that 
\[
|x^G| \geqs \frac{|{\rm SO}_n(q)|}{2|{\rm SO}_{n-3}^{-}(q)||{\rm SO}_3(q)|} > \frac{1}{4}q^{3n-9} = b_3.
\]
Setting $a_3 = 2^{n-1}(q+1)^m$, it follows that \eqref{e:three} holds and one can check that this upper bound is sufficient if $n \geqs 17$. Finally, if $n=15$ then $(m!)_2 = 2^4$ and so we can set $a_3 = 2^{11}(q+1)^7$ in \eqref{e:three} and we deduce that $Q(G,H)<1$ as required.
\end{proof}

\begin{prop}\label{p:o_even1}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = {\rm P\O}_n^{+}(q)$.
\end{prop}

\begin{proof}
Here $n = 2m \geqs 8$ and as usual we set $H_0 = H \cap G_0$, where $H$ is a Sylow $2$-subgroup of $G$. Set $d = (4,q^m-1)$ and $\b = \delta_{9,q}$.

For $k \in \{1,2\}$, we say that an involution $x \in {\rm PO}_n^{+}(q)$ is of type $s_k$ if it lifts to an involution in ${\rm O}_n^{+}(q)$ of the form $(-I_{n-k},I_k)$. If $x$ is an  $s_1$-type involution, then $x \in {\rm PO}_n^{+}(q) \setminus {\rm PSO}_n^{+}(q)$ is an involutory graph automorphism of $G_0$ (of type $\gamma_1$ in \cite[Table 4.5.1]{GLS}) and we have
\begin{equation}\label{e:oeven1}
|x^G| \geqs \frac{|{\rm SO}_n^{+}(q)|}{2|{\rm SO}_{n-1}(q)|} = \frac{1}{2}q^{m-1}(q^m-1) = b_1.
\end{equation}
Similarly, if $x$ is an $s_2$-involution then
\begin{equation}\label{e:oeven2}
|x^G| \geqs \frac{|{\rm SO}_n^{+}(q)|}{2|{\rm SO}_{n-2}^{-}(q)||{\rm SO}_{2}^{-}(q)|} = \frac{q^{n-2}(q^m-1)(q^{m-1}-1)}{2(q+1)} = b_2.
\end{equation}
Recall that ${\rm Inndiag}(G_0)$ is the index-two subgroup of ${\rm PGO}_{n}^{+}(q)$ generated by the inner and diagonal automorphisms of $G_0$.  

\vs

\noindent \emph{Case 1. $q \equiv 1 \imod{4}$}

\vs

Here $d = 4$ and we first observe that
\[
|H_0| = \frac{1}{8}(2(q-1))^m(m!)_2,
\]
which means that $H$ is contained in a subgroup $L$ of $G$ of type ${\rm O}_{2}^{+}(q) \wr S_m$.

To begin with, let us assume $n \geqs 10$. If $x \in G$ is an $s_1$-type involution, then $|x^G| \geqs b_1$ as in \eqref{e:oeven1} and by counting in $L$ we deduce that there are at most $a_1 = m(q-1)$ such elements in $H$. Similarly, if $x$ is an $s_2$-type involution, then $|x^G| \geqs b_2$ (see \eqref{e:oeven2}) and we calculate that $H$ contains no more than $a_2$ such involutions, where
\[
a_2 = \binom{m}{1} + \binom{m}{2}(q-1)^2 + \binom{m}{2}|{\rm O}_{2}^{+}(q)| = m+\frac{1}{2}m(m-1)((q-1)^2+2(q-1)).
\]
And if $x \in G$ is any other type of involution, then by inspecting \cite[Table 4.5.1]{GLS} we deduce that $|x^G|$ is minimal when $x$ is an involutory graph automorphism of type $(-I_3,I_{n-3})$. So in this situation we get 
\begin{equation}\label{e:oeven3}
|x^G| \geqs \frac{|{\rm SO}_n^{+}(q)|}{2|{\rm SO}_{n-3}(q)||{\rm SO}_{3}(q)|} > \frac{1}{4}q^{3n-9} = b_3
\end{equation}
and we note that $|H| \leqs 2^{n+\b}(q-1)^m = a_3$. Putting all of this together, we deduce that \eqref{e:three} holds and this implies that $Q(G,H)<1$. The result follows.

Now assume $n = 8$ and $q \equiv 1 \imod{4}$. To begin with, we will assume $q \geqs 5$ is a Fermat prime, noting that a separate argument for $q = 9$ will be given below.

As above, the contribution to $\widehat{Q}(G,H)$ from $s_1$-involutions is at most $a_1^2b_1^{-1}$. Next suppose $x \in G$ is an $s_2$-involution and recall that $|x^G| \geqs b_2$. If $C_G(x)$ is of type ${\rm O}_6^{\e}(q) \times {\rm O}_2^{\e}(q)$, then $x$ is conjugate under a triality graph automorphism $\tau$ of $G_0$ to an involution $y$ with $C_G(y)$ of type ${\rm GL}_4^{\e}(q)$. And in turn, $z = y^{\tau}$ is contained in a second ${\rm Inndiag}(G_0)$-class of involutions with $C_G(z)$ of type ${\rm GL}_4^{\e}(q)$. Since the number of $s_2$-involutions in $H$ is at most $4+6(q-1)^2+12(q-1)$, as noted above, it follows that there are no more than
\[
a_2 = 3(4+6(q-1)^2+12(q-1))
\]
involutions $x \in H$ with $C_G(x)$ of type ${\rm O}_6^{\e}(q) \times {\rm O}_2^{\e}(q)$ or ${\rm GL}_4^{\e}(q)$ for $\e = \pm$. And if $x$ is any other involution, then the fact that $q$ is a prime (so $G$ does not contain any involutory field or graph-field automorphisms) implies that
\begin{equation}\label{e:o8}
|x^G| \geqs \frac{|{\rm SO}_8^{+}(q)|}{2|{\rm SO}_{5}(q)||{\rm SO}_{3}(q)|} = \frac{1}{2}q^7(q^2+1)(q^6-1) = b_3
\end{equation}
as in \eqref{e:oeven3}. Finally, since $|H| \leqs 2^7(q-1)^4 = a_3$ we deduce that \eqref{e:three} holds and this upper bound yields $Q(G,H)<1$, as required.

To complete the proof for $n = 8$ with $q \equiv 1 \imod{4}$, we may assume $q = 9$. The analysis of this case is complicated by the fact that $G$ may contain involutory field or graph-field automorphisms. Using {\sc Magma} \cite{magma}, we begin by constructing $L = {\rm Aut}(G_0) = G_0.[48]$ as a permutation group of degree $1795800$ and we construct a Sylow $2$-subgroup $J$ of $L$. We then take a set of representatives of the conjugacy classes of involutions in $J$ and we deduce that $i_2(J) = 14495$. In addition, by computing $|x^L|$ for each involution $x \in J$, we find that $J$ contains exactly $a_1 = 32$ involutions of type $s_1$. As before, if $x$ is any other involution in $G$, then $|x^G| \geqs b_2$ as in \eqref{e:oeven2}. So by applying Lemma \ref{l:est}, we see that \eqref{e:two} holds with $b_1$ defined in \eqref{e:oeven1} and $a_2 = 14463$. It is easy to check that this estimate gives  $Q(G,H)<1$ and the result follows.

\vs

\noindent \emph{Case 2. $q \equiv 3 \imod{4}$}

\vs

First assume $m$ is even and note that
\[
|H_0| = \frac{1}{2d}(2(q+1))^m(m!)_2.
\]
It follows that $H$ is contained in a subgroup $L$ of $G$ of type ${\rm O}_{2}^{-}(q) \wr S_m$, which means that the analysis of this case is almost identical to our previous work in Case 1. 

First assume $n \geqs 12$. Here we see that \eqref{e:three} holds, where
\[
a_1 = m(q+1), \; a_2 = \frac{1}{2}m(m-1)((q+1)^2+2(q+1))+m,\; a_3 = 2^n(q+1)^m
\]
and $b_1$, $b_2$ and $b_3$ are defined in \eqref{e:oeven1}, \eqref{e:oeven2} and \eqref{e:oeven3}, respectively. Then one can check that this upper bound is sufficient unless $q=3$ and $n \in \{12,16,20\}$. The case $(n,q) = (12,3)$ was handled in Proposition \ref{p:comp}. For $(n,q) = (20,3)$ we have $|H| \leqs 2^{18}4^{10}$ since $(10!)_2 = 2^8$ and by setting $a_3 = 2^{18}4^{10}$ we check that the revised bound in \eqref{e:three} is good enough. 

Finally, suppose $(n,q) = (16,3)$. We may assume $G = {\rm PGO}_{16}^{+}(3) = G_0.D_8$. Set $H_1 = H \cap {\rm Inndiag}(G_0)$ and note that $|H:H_1| = 2$. If $x \in H$ is an involutory graph automorphism of type $(-I_3,I_{13})$, then 
\[
|x^G| \geqs \frac{|{\rm SO}_{16}^{+}(3)|}{2|{\rm SO}_{13}(3)||{\rm SO}_3(3)|} = 2279214355760562960 = b_3
\]
and we note that all such involutions are contained in the coset $H_1x$, so there are at most $|H_1| = 2^{30} = a_3$ such elements in $H$. And if $x \in G$ is an involution that is not of type $s_1$ or $s_2$, nor a graph automorphism of type $(-I_3,I_{13})$, then 
\[
|x^G| \geqs \frac{|{\rm SO}_{16}^{+}(3)|}{2|{\rm SO}_{12}^{-}(3)||{\rm SO}_{4}^{-}(3)|} = 40320213639146662987584 = b_4.
\]
We deduce that 
\[
Q(G,H) < a_1^2b_1^{-1} + a_2^2b_2^{-1} + a_3^2b_3^{-1} + a_4^2b_4^{-1} < 1,
\]
where $a_4 = |H| = 2^{31}$, and the result follows.

Now assume $n=8$. In view of Proposition \ref{p:comp}, we are free to assume that $q \geqs 7$. Then by arguing as in Case 1, we deduce that  \eqref{e:three} holds, where $b_1$ and $b_2$ are defined as above, $b_3$ is given in \eqref{e:o8}, and we set
\[
a_1 = 4(q+1), \; a_2 = 18((q+1)^2+2(q+1))+12, \; a_3 = 2^7(q+1)^4,
\]
noting that $|H| \leqs a_3$. It is easy to check that this yields $Q(G,H)<1$ for all $q \geqs 7$ and the result follows.

To complete the proof, we may assume $m \geqs 5$ is odd. Here
\[
|H_0| = (2(q+1))^{m-1}((m-1)!)_2
\]
and we deduce that $H$ is contained in a subgroup $L$ of $G$ of type 
\[
({\rm O}_{2}^{-}(q) \wr S_{m-1}) \times {\rm O}_{2}^{+}(q) < {\rm O}_{n-2}^{+}(q) \times {\rm O}_{2}^{+}(q).
\]
If $x \in G$ is an $s_1$-involution, then $|x^G| \geqs b_1$ as in \eqref{e:oeven1} and by working in $L$ we deduce that there are at most 
\[
a_1 = \binom{m-1}{1}(q+1) + q-1 = m(q+1)-2
\]
such elements in $H$. Similarly, if $x$ is an $s_2$-involution then $|x^G| \geqs b_2$ with $b_2$ defined as in \eqref{e:oeven2} and we calculate that $H$ contains no more than $a_2$ such elements, where
\begin{align*}
a_2 & = \binom{m}{1} + \binom{m}{1}(q+1)(q-1) + \binom{m}{2}(q+1)^2  + \binom{m}{2}|{\rm O}_{2}^{-}(q)| + 1 \\
 & = \frac{1}{2}m(m-1)((q+1)^2+2(q+1)) + mq^2 + 1.
 \end{align*}
And if $x \in G$ is any other type of involution, then as in \eqref{e:oeven3} we have $|x^G|>\frac{1}{4}q^{3n-9} = b_3$ and we note that $|H| \leqs 2^n(q+1)^{m-1} = a_3$. Then one checks that the upper bound in \eqref{e:three} is sufficient unless $q=3$ and $n \in \{10,14\}$. The case $(n,q) = (10,3)$ was handled in Proposition \ref{p:comp}. And for $(n,q) = (14,3)$ we have $|H| \leqs 2^{24}$; by setting $a_3 = 2^{24}$ we find that the bound in \eqref{e:three} is good enough and the proof is complete.
\end{proof}

\begin{prop}\label{p:o_even2}
The conclusion to Theorem \ref{t:main2} holds if $G_0 = {\rm P\O}_n^{-}(q)$.
\end{prop}

\begin{proof}
Here $n = 2m \geqs 8$ is even. Let $H$ be a Sylow $2$-subgroup of $G$ and set $H_0 = H \cap G_0$, $d = (4,q^m+1)$ and $\b = \delta_{9,q}$.

For $k \in \{1,2\}$, we define an involution $x \in {\rm PO}_n^{-}(q)$ to be of type $s_k$ if it lifts to an involution in ${\rm O}_n^{-}(q)$ of the form $(-I_{n-k},I_k)$. If $x$ is of type $s_1$, then 
\begin{equation*}
|x^G| \geqs \frac{|{\rm SO}_n^{-}(q)|}{2|{\rm SO}_{n-1}(q)|} = \frac{1}{2}q^{m-1}(q^m+1) = b_1
\end{equation*}
and we get
\begin{equation*}
|x^G| \geqs \frac{|{\rm SO}_n^{-}(q)|}{2|{\rm SO}_{n-2}^{+}(q)||{\rm SO}_{2}^{-}(q)|} = \frac{q^{n-2}(q^m+1)(q^{m-1}+1)}{2(q+1)} = b_2
\end{equation*}
if $x$ is of type $s_2$. As in the proof of the previous proposition, we divide the analysis into two cases, according to whether or not $q \equiv 1 \imod{4}$ or $q \equiv 3 \imod{4}$.

\vs

\noindent \emph{Case 1. $q \equiv 1 \imod{4}$}

\vs

Here $d=2$ and 
\[
|H_0| = (2(q-1))^{m-1}((m-1)!)_2,
\]
which means that $H<L<G$, where $L$ is of type 
\[
({\rm O}_{2}^{+}(q) \wr S_{m-1}) \times {\rm O}_{2}^{-}(q) < {\rm O}_{n-2}^{+}(q) \times {\rm O}_{2}^{-}(q).
\]
Then by arguing as in Case 2 (with $m$ odd) in the proof of Proposition  \ref{p:o_even1}, we calculate that $H$ contains at most $a_1 = m(q-1)+2$ involutions of type $s_1$ and at most 
\[
a_2 = \frac{1}{2}m(m-1)((q-1)^2+2(q-1)) + mq^2 + 1
\]
involutions of type $s_2$. And if $x \in G$ is any other type of involution, then $|x^G|>\frac{1}{4}q^{3n-9} = b_3$ as in \eqref{e:oeven3} and we note that $|H| \leqs 2^{n+\b}(q-1)^{m-1} = a_3$. It is now routine to check that the upper bound in \eqref{e:three} is sufficient.

\vs

\noindent \emph{Case 2. $q \equiv 3 \imod{4}$}

\vs

First assume $m$ is even. Here $|H_0| = (2(q+1))^{m-1}((m-1)!)_2$ and thus $H$ is contained in a subgroup of type 
\[
({\rm O}_{2}^{-}(q) \wr S_{m-1}) \times {\rm O}_{2}^{+}(q) < {\rm O}_{n-2}^{-}(q) \times {\rm O}_{2}^{+}(q).
\]
The by arguing as in Case 1, setting $b_1,b_2$ and $b_3$ as above, we deduce that \eqref{e:three} holds with  
\[
a_1 = m(q+1)-2, \; a_2 = \frac{1}{2}m(m-1)((q+1)^2+2(q+1)) + mq^2 + 1,\; a_3 = 2^{n-1}(q+1)^{m-1}.
\]
It is easy to check that this bound is sufficient unless $q = 3$ and $n \in \{8,12\}$. The latter two cases were handled in Proposition \ref{p:comp} and the result follows.

Finally, suppose $m$ is odd.  In this case we have
\[
|H_0| = \frac{1}{8}(2(q+1))^m(m!)_2
\]
and thus $H<L<G$ with $L$ of type ${\rm O}_{2}^{-}(q) \wr S_m$. And so by arguing as in Case 2 (with $m$ even) in the proof of Proposition \ref{p:o_even1}, we deduce that \eqref{e:three} holds, where $b_1,b_2,b_3$ are defined as above and 
\[
a_1 = m(q+1), \; a_2 = \frac{1}{2}m(m-1)((q+1)^2+2(q+1))+m,\; a_3 = 2^{n-1}(q+1)^m.
\]
We then check that this bound is sufficient unless $q = 3$ and $n \in \{10,14,18\}$. For $(n,q)=(10,3)$ we can appeal to Proposition \ref{p:comp}. And in the two remaining cases, by setting $a_3 = 2^{3m}(m!)_2$, we can check that the bound in \eqref{e:three} is good enough. The result follows.
\end{proof}

\vs

This completes the proof of Theorem \ref{t:main2}. By combining this result with Theorem \ref{t:zenkov}, we conclude that the proof of Theorem \ref{t:main1} is complete.

