\section{Stability under the convolution product}\label{AppendixStability}

\begin{proof}[Proof of Proposition~\ref{stableprod}]
    Let $\lambda_1, \lambda_2 \in \Lambda^+$ be dominant coweights, and let $d > 0$ be a sufficiently large positive integer such that $\BR^d_{\mu}$ is defined for all $\mu$ satisfying $\mu \leq \lambda_1$, $\mu \leq \lambda_2$, or $\mu \leq \lambda_1 + \lambda_2$. It suffices to show that under the product map (\ref{convolution2}), the image of 
    \[
    \left(z^*H^{G_\oh}_\bullet(\BR^d_{\leq \lambda_1})\right) \otimes \left(z^*H^{G_\oh}_\bullet(\BR^d_{\leq \lambda_2})\right)
    \]
    is contained in $z^*H^{G_\oh}_\bullet(\BR^d_{\leq \lambda_1 + \lambda_2})$, where $z^*: H^{G_\oh}_\bullet(\BT^d) \to H^{G_\oh}_\bullet(\Gr_G)$ is the Gysin map.

    Consider the following diagram
    \[
    \begin{tikzcd}
    \BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2} \ar[d, symbol=\subset] 
    & p^{-1}(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2}) \ar[l, "p''", swap] \ar[d, symbol=\subset]
    & Z \ar[l, "j"] \ar[d, symbol=\subset] \\
    \BT^d_{\leq \lambda_1} \times \BT^d_{\leq \lambda_2} 
    & p^{-1}(\BT^d_{\leq \lambda_1} \times \BT^d_{\leq \lambda_2}) \ar[l, "p'", swap] 
    & (G_\ok)_{\leq \lambda_1} \times \BT^d_{\leq \lambda_2} \\
    C_{\leq \lambda_1} \times C_{\leq \lambda_2} \ar[u, "z_1"] 
    & (G_\ok)_{\leq \lambda_1} \times C_{\leq \lambda_2} \ar[l, "p", swap] \ar[u, "z_2"] \ar[r, equal]
    & (G_\ok)_{\leq \lambda_1} \times C_{\leq \lambda_2} \ar[u, "z_3"].
    \end{tikzcd}
    \]
    Here, 
    \[
    Z \vcentcolon= \{(g_1, [g_2, s]) \in (G_\ok)_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2} : g_1 g_2 s \in \bN_\oh\},
    \]
    and $j$ is defined by 
    \[
    j(g_1, [g_2, s]) = (g_1, g_2 s, [g_2, s]).
    \]
    The $G_\oh \times G_\oh$-action on $p^{-1}(\BT^d_{\leq \lambda_1} \times \BT^d_{\leq \lambda_2})$ is given by:
    \[
    (g, g') \cdot (g_1, s_1, [g_2, s_2]) = (g g_1 (g')^{-1}, g' s_1, [g' g_2, s_2]),
    \]
    so $j$ is $G_\oh \times G_\oh$-equivariant. There is a section $\phi$ of (the pullback of) $\BT^d_{\leq \lambda_1}$ over $p^{-1}(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2})$ defined by
    \[
    \phi(g_1, s_1, [g_2, s_2]) = [g_1, s_1 - g_2 s_2],
    \]
    whose vanishing locus is $Z$. Therefore,
    \begin{equation}\label{pullpart}
    \begin{split}
        p^*z_1^*H^{G_\oh \times G_\oh}_\bullet(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2}) 
        =&z_2^*(p')^*H^{G_\oh \times G_\oh}_\bullet(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2})\\
        \subset&z_2^*H^{G_\oh \times G_\oh}_\bullet(p^{-1}(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2}))\\
        \subset& z_3^* H^{G_\oh \times G_\oh}_\bullet(Z).
    \end{split}
    \end{equation}
    Next, consider the diagram
    \[
    \begin{tikzcd}
    Z' \ar[d, symbol=\subset] \ar[r, "m''"] 
    & \BR^d_{\leq \lambda_1 + \lambda_2} \ar[d, symbol=\subset] \\
    (\Gr_\ok)_{\leq \lambda_1} \times_{G_\oh} \BT^d_{\leq \lambda_2} \ar[r, "m'"] 
    & \BT^d_{\leq \lambda_1 + \lambda_2} \\
    (G_\ok)_{\leq \lambda_1} \times_{G_\oh} C_{\leq \lambda_2} \ar[r, "m"] \ar[u, "z_4"] 
    & \overline{C}_{\lambda_1 + \lambda_2} \ar[u, "z_5"].
    \end{tikzcd}
    \]
    Here, $Z' = Z / G_\oh$ is the image of $Z$ under the canonical map 
    \[
    (\Gr_\ok)_{\leq \lambda_1} \times \BT^d_{\leq \lambda_2} \to (\Gr_\ok)_{\leq \lambda_1} \times_{G_\oh} \BT^d_{\leq \lambda_2}.
    \]
    Hence,
    \begin{equation}\label{pushpart}
    \begin{split}
        m_*(q^*)^{-1}z_3^* H^{G_\oh \times G_\oh}_\bullet(Z) 
        &= m_*z_4^* H^{G_\oh}_\bullet(Z') \\
        &= z_5^*(m')_* H^{G_\oh}_\bullet(Z') \\
        &\subset z_5^* H^{G_\oh}_\bullet(\BR^d_{\leq \lambda_1 + \lambda_2}).
    \end{split}
    \end{equation}

    Combining \eqref{pullpart} and \eqref{pushpart}, we obtain
    \[
    m_*(q^*)^{-1}p^*z_1^*H^{G_\oh \times G_\oh}_\bullet(\BR^d_{\leq \lambda_1} \times \BR^d_{\leq \lambda_2}) \subset z_5^* H^{G_\oh}_\bullet(\BR^d_{\leq \lambda_1 + \lambda_2}),
    \]
    as desired.
\end{proof}


\section{\texorpdfstring{Universal $G$-torsor}{Universal G-torsor}}
\label{Gtorsorappendix}
In this subsection, we will define in terms of functor of points an ind-scheme $\sE$ equipped with an action of $G_{\C[t^{-1}]}\rtimes\Cxh$ which is a $G$-torsor over $\Gr_G\times\PP^1$. It is best to work in the language of functors of points, since the algebraic loop group $G_\ok$ is highly non-reduced (see \cite[Remark 1.3.10]{Zhu}).

\subsubsection*{Universal $G$-torsors on the loop group}
 Here $G_{\C[t^{-1}]}$ is the fppf sheaf which sends any $\C$-algebra $R$ to $G(R[t^{-1}])$. The space $\sE$ is understood as the universal $G$-torsor.

Let $R$ be a $\C$-algebra, and $\gamma \in G(R\cct)$. By the theorem of \citeauthor{BL} (\cite{BL}), there exists a unique $G$-torsor $\hat{\sE}_{R,\gamma}$ on $\mathbb{P}^1_R$, equipped with trivializations
\begin{align*}
\varphi^\gamma_0 \colon \hat{\sE}_{R,\gamma}|_{\spec R[[t]]} &\xrightarrow{\sim} \spec R[[t]] \times G, \\
\varphi^\gamma_\infty \colon \hat{\sE}_{R,\gamma}|_{\spec R[t^{-1}]} &\xrightarrow{\sim} \spec R[t^{-1}] \times G.
\end{align*}
$\varphi^\gamma_\infty=\gamma\cdot\varphi^\gamma_0$ on $\hat{\sE}_{R,\gamma}|_{\spec R\cct}$. In simple terms, $\hat{\sE}_{R,\gamma}$ is obtained by gluing trivial $G$-torsors over $\spec R[[t]]$ and $\spec R[t^{-1}]$ using $\gamma$ as the transition function.


Moreover, if $f\colon R \to S$ is a $\C$-algebra homomorphism, and $\gamma' \in G(S\cct)$ is the image of $\gamma$ under the map $G_\ok(f)\colon G(R\cct) \to G(S\cct)$, then there is an isomorphism
\begin{equation}\label{cart}
\hat\sE_{S,\gamma'} \cong \hat\sE_{R,\gamma} \times_R S
\end{equation}
such that $\varphi_0^{\gamma'}=\varphi_0^\gamma\times_RS$ and $\varphi_\infty^{\gamma'}=\varphi_\infty^\gamma\times_RS$.

Conversely, if $\mathcal{P}$ is a $G$-torsor over $\PP^1_R$, with trivializations $\varphi_0$ and $\varphi_\infty$ over $\spec R[[t]]$ and $\spec R[t^{-1}]$ respectively, then there exists a unique $\gamma\in G_\ok(R)=G(R\cct)$ such that $\varphi_\infty=\varphi_0$ when restricted to $\spec R\cct$. The following lemma summarizes the above discussion.
\begin{lem}\label{Gtorsor}
The loop group $G_\ok$ represents the functor
\[
R \longmapsto \left\{
\begin{array}{l}
\text{Isomorphism classes of the pair } (\mathcal{P}, \varphi_0,\varphi_\infty): \\
\mathcal{P} \text{ is a } G\text{-torsor over } \PP^1_R,\ \\
\varphi_0 \text{ is a trivialization of }\mathcal{P} \text{ over } \spec R[[t]],\\ \varphi_\infty \text{ is a trivialization of }\mathcal{P} \text{ over } \spec R[t^{-1}]
\end{array}
\right\}.
\]
\end{lem}
By abstract nonsense, there exists a universal bundle $\hat \sE\to G_\ok\times \PP^1$ with trivializations $\varphi_0$ and $\varphi_\infty$ of $\hat \sE$ over $G_\ok\times \spec \C[[t]]$ and $G_\ok \times \spec \C[t^{-1}]$ respectively. We will now describe them explcitly.

We understand schemes as functors from the category $\C\Alg$ of $\C$-algebras to the category $\Set$ of sets, via the functor of points construction. If $f\colon R \to S$ is a $\C$-algebra homomorphism, we let $\hat\sE_{R,\gamma}(S)_f$ denote the preimage of $f \in \spec(R)(S)$ under the natural projection $\hat\sE_{R,\gamma}\to \spec R$. In particular, the isomorphism \eqref{cart} implies that
\begin{equation}\label{cart2}
    \hat\sE_{S, G_\ok(f)(\gamma)}(S)_{\operatorname{id}_S} = \hat\sE_{R,\gamma}(S)_f
\end{equation}
for any $\gamma \in G_\ok(R)$.

Now $\hat\sE\colon \C\Alg \to \mathrm{Sets}$ can be defined as follows. We set
\begin{equation*}
    \hat\sE(R) = \{(\gamma, x) \mid \gamma \in G(R\cct),\ x \in \hat\sE_{R,\gamma}(R)_{\operatorname{id}_R} \}
\end{equation*}
for each $\C$-algebra $R$; and
\begin{equation*}
    \hat\sE(f)(\gamma, x) = \big(G_\ok(f)(\gamma),\ \hat\sE_{R,\gamma}(f)(x)\big)
\end{equation*}
for each $\C$-algebra homomorphism $f\colon R \to S$. Note that $\hat\sE_{R,\gamma}(f)(x) \in \hat\sE_{S, G_\ok(f)(\gamma)}(S)_{\operatorname{id}_S}$ in view of (\ref{cart2}).


\subsubsection*{The \texorpdfstring{$(G_{\C[t^{-1}]} \times G_\oh) \rtimes \Cxh$}{(G_{C[t^{-1}]} x G_O) ⋉ C*}-actions on \texorpdfstring{$\hat\sE$}{Ê}.}
We let $\Cxh$ act on $G_\oh$, $G_\ok$, and $G_{\C[t^{-1}]}$ by loop rotations defined as follows. Let $R$ be a $\C$-algebra. Each element $z \in \Cxh(R) = R^\times$ induces an $R$-algebra automorphism $m_z^*$ of $R[[t]]$ by sending $t$ to $z^{-1}t$. By abuse of notation, we denote the composition
\[
G_\oh(R) = G(R[[t]]) \xrightarrow{G(m_{z}^*)} G(R[[t]]) = G_\oh(R),
\]
also by $m_z^*$.

The action of $\Cxh$ on $G_\oh$ is then given by
\begin{align*}
    \Cxh(R) \times G_\oh(R) &\to G_\oh(R) \\
    (z, g) &\mapsto m_z^{*-1}(g).
\end{align*}
It is notationally more instructive to write $g = g(t)$ and $m_z^{*-1}(g) = g(zt)$. The loop rotation actions on $G_\ok$ and $G_{\C[t^{-1}]}$ are defined similarly.

We write $(G_{\C[t^{-1}]} \times G_\oh) \rtimes \Cxh$ for the semidirect product in which $\Cxh$ acts on $G_{\C[t^{-1}]} \times G_\oh$ via loop rotation. It is clear that $(G_{\C[t^{-1}]} \times G_\oh) \rtimes \Cxh$ acts on $G_\ok$ by
\[
(g(t), h(t), z) \cdot \gamma(t) = g(t)\, \gamma(zt)\, h(t)^{-1}
\]
for any $\C$-algebra $R$, any $(g(t), h(t), z) \in \left(G(R[t^{-1}]) \times G(R[[t]])\right) \rtimes R^\times$, and any $\gamma(t)\in G(R\cct)$. In view of \Cref{Gtorsor}, one can understand the action of $G(R[t^{-1}])$ (resp.\ $G(R[[t]])$) as changing the trivialization $\varphi_\infty$ (resp.\ $\varphi_0$), and $z \in R^\times$ acts via the pullback along $m_z^{-1}\colon \PP^1_R \to \PP^1_R$.

We are going to show that this action lifts to an action of $(G_{\C[t^{-1}]} \times G_\oh) \rtimes \Cxh$ on $\hat\sE$. Let $R$ be a $\C$-algebra, $(g(t), h(t), z) \in (G(R[t^{-1}]) \times G(R[[t]])) \rtimes R^\times$, and let $\gamma(t) \in G_\ok(R)$,  $\gamma'=(g,h,z)\cdot\gamma$. Namely
\begin{equation*}
    \gamma'(t)=g(t)\gamma(zt)h(t)^{-1}.
\end{equation*}
Note that $\varphi_0' = m_z^*h\cdot \varphi_0^{\gamma}$ and $\varphi_\infty' = m_z^*g\cdot \varphi_\infty^{\gamma}$ are local trivializations of $\hat\sE_{R,\gamma}$ over $\spec R[[t]]$ and $\spec R[t^{-1}]$, respectively. One checks immediately that $\varphi_\infty' = m_z^*\gamma'\cdot\varphi_0'$ over $\spec R\cct$. By the theorem of \citeauthor{BL}, there exists a unique isomorphism
\[
\vartheta_{g,h,z}\colon \hat\sE_{R,\gamma} \xrightarrow{\sim} m_z^*\hat\sE_{R,\gamma'},
\]
such that $m_z^*\varphi_0^{\gamma'}\circ \vartheta_{g,h,z} =\varphi_0' $ and $m_z^*\varphi_\infty^{\gamma'}\circ\vartheta_{g,h,z} =\varphi_\infty' $.

Now let $(g'(t), h'(t), z') \in (G(R[t^{-1}]) \times G(R[[t]])) \rtimes R^\times$, then we have
\begin{equation}\label{productvarphi}
(g'(t), h'(t), z') \cdot (g(t), h(t), z) = (g'(t) g(z't),\ h'(t) h(z't),\ z'z).
\end{equation}
We denote the right-hand side of \eqref{productvarphi} by $(g'', h'', z'')$, and write $\gamma'' = (g'', h'', z'') \cdot \gamma \in G(R\cct)$. We claim that
\begin{equation}\label{cocylevarphi}
    m_z^*\vartheta_{g', h', z'} \circ \vartheta_{g, h, z} = \vartheta_{g'', h'', z''}.
\end{equation}

To see this, it suffices to check that both sides of \eqref{cocylevarphi} agree with the unique isomorphism $\vartheta\colon \hat\sE_{R,\gamma} \xrightarrow{\sim}  m_{z'z}^*\hat\sE_{R,\gamma''}$ satisfying
\begin{align*}
    m_{z'z}^*\varphi^{\gamma''}_0\circ\vartheta &= m_{z'z}^*h''\cdot  \varphi_0^\gamma, \\
    m_{z'z}^*\varphi^{\gamma''}_\infty\circ\vartheta &= m_{z'z}^*g''\cdot  \varphi_\infty^\gamma. \\
\end{align*}
This is immediate for the right-hand side of \eqref{cocylevarphi}. For the left-hand side, we compute
\begin{align*}
    m_{z'z}^*\varphi_0^{\gamma''}\circ m_{z}^*\vartheta_{g', h', z'} \circ \vartheta_{g, h, z}&=m_z^*(m_{z'}^*\varphi_0^{\gamma''}\circ\vartheta_{g', h', z'})\circ \vartheta_{g, h, z}\\
    &=m_z^*(m_{z'}^*h'\cdot \varphi_0^{\gamma'})\circ \vartheta_{g, h, z}\\
    &=m_{z'z}^*h'\cdot m_{z}^*\varphi_0^{\gamma'}\circ \vartheta_{g, h, z}\\
    &=m_{z'z}^*h'\cdot m_z^*h\cdot \varphi_0^\gamma\\
    &=m_{z'z}^*h''\cdot \varphi_0^\gamma.
\end{align*}
The other equality $m_{z'z}^*\varphi_\infty^{\gamma''}\circ m_z^*\vartheta_{g', h', z'} \circ\vartheta_{g, h, z} = m_{z'z}^*h''\cdot \varphi_\infty^\gamma$ can be checked in the same way.

Moreover, let $f\colon R \to S$ be a $\C$-algebra homomorphism. We write $\gamma_S = G_\ok(f)(\gamma)$, $g_S = G_{\C[t^{-1}]}(f)(g)$, etc. Then we have
\begin{equation}\label{naturalvarphi}
    \vartheta_{g_S, h_S, z_S} = \vartheta_{g, h, z} \times_R S,
\end{equation}
because both sides agree with the unique isomorphism $\vartheta:\hat\sE_{S,\gamma_S} \xrightarrow{\sim} m_{z_S}^*\hat  \sE_{S,\gamma'_S}$ with $m_{z_S}^*(\varphi^{\gamma'}_0)_S\circ \vartheta=m_{z_S}^*h_S\cdot(\varphi_0^\gamma)_S$ and $m_{z_S}^*(\varphi^{\gamma'}_\infty)_S\circ \vartheta=m_{z_S}^*h_S\cdot(\varphi_\infty^\gamma)_S$


Now we can define the action
\[\Phi_R:(G_\C[t^{-1}](R))\times G_\oh(R))\rtimes \Cxh(R)\times \hat\sE(R)\longrightarrow \hat\sE(R)\]
by
\begin{equation}\label{sEaction}\Phi_R(g(t),h(t),z,\gamma(t),x)=(g(t)\gamma(zt)h^{-1}(t),\vartheta_{(g,h,z)}(x)).
\end{equation}
By \eqref{cocylevarphi}, this defines an action of $(G_\C[t^{-1}](R))\times G_\oh(R))\rtimes \Cxh(R)$ on $\hat\sE(R)$. In view of \eqref{naturalvarphi}, we obtain an action of $(G_\C[t^{-1}]\times G_\oh)\rtimes \Cxh$ on $\hat\sE$.

Since the projection $\hat \sE\to G_\ok$ is clearly $(G_{\C[t^{-1}]}\times G_\oh) \rtimes \Cxh$-equivariant, and $\Gr_G=G_\ok/G_\oh$, 
\begin{equation}\label{univbundle}
   \sE=\hat \sE/G_\oh 
\end{equation}
is a $G$-torsor over $\Gr_G$. Moreover, there is a canonical trivialization $\varphi_\infty$ of $\sE$ over $\Gr_G\times \spec \C[t^{-1}]$. Moreover, there is a remaining action of $G_{\C[t^{-1}]}\rtimes\Cxh$ on $\sE$.

The trivializations $\varphi_0$ and $\varphi_\infty$ induce the isomorphisms
\begin{align*}
    \hat{\sE}|_{{G_\ok} \times \{0\}} \cong G_\ok \times G, \quad
    \hat{\sE}|_{{G_\ok} \times \{\infty\}} \cong G_\ok \times G.
\end{align*}
Since $G_\mathcal{O}$ acts by changing the trivialization $\varphi_0$, these identifications descend to isomorphisms
\begin{equation}\label{fibresofsE}
    \sE|_{\Gr_G \times \{0\}} \cong G_\mathcal{K} \times_{G_\mathcal{O}} G, \quad
    \sE|_{\Gr_G \times \{\infty\}} \cong \Gr_G \times G. 
\end{equation}

\section{Regularity of \texorpdfstring{$\cM_{\leq\lambda}(G/P)$}{M(G/P)}}\label{Convexity}

In this appendix, we show that the restriction of $T\sE_{\leq\lambda}(G/P)$ to any stable map $\sigma:\Sigma\to \sE_{\leq\lambda}(G/P)$ has vanishing higher cohomology. By a standard argument (e.g.~\cite{Chow}), this implies that the moduli space $\cM_{\leq\lambda}(G/P)$ is smooth of the expected dimension.

Using semicontinuity of the dimension of cohomology, one may assume that $\sigma$ is $T$-invariant. Moreover, since $G/P$ is convex, it suffices to verify the case where $\Sigma \cong \PP^1$, and $\sigma(\Sigma)$ is a genuine section over some $T$-fixed point $p \in \widetilde{C}_{\leq\lambda}$ lying over a point $t^\mu \in C_{\leq\lambda}$.

Under this assumption, there exists $v \in W/W_P$ such that $\sigma$ maps $\Sigma$ isomorphically onto the constant section curve $\mathrm{Sec}_{p,v}$ over the point $p \in \widetilde{C}_{\leq\lambda}$, with value $[v] \in G/P$.

Let \( v(R_P^+) = \{\alpha_1, \dots, \alpha_k\} \). Suppose that $\alpha_i(\mu) > 0$ if and only if $i \leq r$.

Consider the map
\begin{align*}
    V = \C^{\sum_{i=1}^r (\alpha_i(\mu) - 1)} &\to \widetilde{C}_{\leq\lambda} \\
    s = (s_{i,j})_{\substack{1 \leq i \leq r \\ 1 \leq j < \alpha_i(\mu)}} &\mapsto \exp\left( \sum_{i=1}^r \sum_{j=1}^{\alpha_i(\mu)-1} s_{i,j} t^j X_{\alpha_i} \right) \cdot p.
\end{align*}

Let $\sE_V(G/P)$ be the pullback of $\sE_{\leq\lambda}(G/P)$ along $V \to \widetilde{C}_{\leq\lambda}$. 

Since $H^1(\mathrm{Sec}_{p,v}, T\mathrm{Sec}_{p,v}) = 0$, it suffices to show that the normal bundle to the curve $\mathrm{Sec}_{p,v}$ in $\sE_V(G/P)$ has vanishing higher cohomology.

In fact, $\sE_V(G/P)$ is obtained by gluing $V \times \spec \C[t] \times G/P$ with $V \times \spec \C[t^{-1}] \times G/P$ via the transition function
\[
(s, t, x) \mapsto \left(s, t, \exp\left(\sum_{i=1}^{r} \sum_{j=1}^{\alpha_i(\mu)-1} s_{i,j} t^j X_{\alpha_i} \right) t^\mu\cdot x \right).
\]

The transition function for the normal bundle is therefore equivalent to a block-diagonal matrix with blocks $B_1, \dots, B_k$, where:
\begin{itemize}
    \item For $i \leq r$, the block $B_i$ is the matrix $D_{\alpha_i(\mu)}$ defined below;
    \item For $i > r$, the block $B_i$ is the $1 \times 1$ matrix with entry $t^{\alpha_i(\mu)}$.
\end{itemize}

We define
\[
D_n :=
\left[
\begin{array}{c|ccc}
t^n & t^{n-1} & \cdots & t \\
\hline
0 &  &  &  \\
\vdots &  & I_{n-1} &  \\
0 &  &  &
\end{array}
\right]
\]

\smallskip

We claim that the double coset $G_{\C[t^{-1}]} D_n G_\oh$ contains the scalar matrix $t \cdot I_n$. To see this, observe that

\[
\begin{pmatrix}
t^{1-n} & -1 & 0 & \cdots & 0 \\
1 & 0 & 0 & \cdots & 0 \\
0 & 0 & 1 & & 0 \\
\vdots & \vdots & & \ddots & \vdots \\
0 & 0 & 0 & \cdots & 1
\end{pmatrix}
D_n
\begin{pmatrix}
1 & 0 & 0 & \cdots & 0 \\
-t & 1 & 0 & \cdots & 0 \\
0 & 0 & 1 & & 0 \\
\vdots & \vdots & & \ddots & \vdots \\
0 & 0 & 0 & \cdots & 1
\end{pmatrix}
=
\begin{pmatrix}
t & 0 & 0 & \cdots & 0 \\
0 & t^{n-1} & t^{n-2} & \cdots & t \\
0 & 0 & 1 & & 0 \\
\vdots & \vdots & & \ddots & \vdots \\
0 & 0 & 0 & \cdots & 1
\end{pmatrix}
\]

The claim now follows by induction on $n$.

To conclude, the normal bundle is a direct sum of line bundles $\mathcal{O}_{\PP^1}(\ell)$ with $\ell \geq -1$, and hence has vanishing higher cohomology.


