\appendix
\section{Implementation details}
We collect here the equations that we numerically solved, with some detail about techniques used.

For inversion at first order, we are simultaneously solving the analogs to the BCS number and gap equations:
        \begin{align}
            \rho &= \int\frac{\dd{k}}{2\pi}\qty(1 - \frac{\xi}{E}) ,\\
            j_0 &= \frac{\LEC}{2}\int\frac{\dd{k}}{2\pi}\frac{j_0}{E}
        .\end{align}
        This is accomplished by minimizing 
        \begin{align}
            \qty(j_0 - \frac{\LEC}{2}\int\frac{\dd{k}}{2\pi}\frac{j_0}{E})^2 + \qty(1 - \frac{1}{\rho}\int\frac{\dd{k}}{2\pi}\qty(1 - \frac{\xi}{E}))^2
        \end{align}
        Minimizing the sum of squares was stable here. 
%
For inversion at second order, we simultaneously solve 
        \begin{align}
            \rho & = \int\frac{\dd{k}}{2\pi}\qty(1 - \frac{\xi}{E}) ,\\
            j_0 &= \int\frac{\dd{k}}{2\pi}\frac{j_0}{E} + \pdv{\beachball}{\mu_0} \frac{B}{CA - B^2} + \pdv{\beachball}{j_0} \frac{A}{B^2 - CA}
        ,\end{align}
        where $A, B, C$ are defined by Eq.~\eqref{eq:inv_ABC}.
        Both of these minimizations were stable with Nelder-Mead.
        All minimizations here are performed with the Optim package in julia~\cite{mogensen2018optim}.
The second-order contribution to the chemical potential is 
 \begin{align}
     \mu_2 = \pdv{\beachball}{\mu_0}\qty(\frac{C}{AC - B^2}) + \pdv{\beachball}{j_0}\qty(\frac{B}{B^2 - AC})
 ,\end{align}
 and this is added to $\mu_0 + \mu_1 = \mu_0 - \frac{\LEC}{2}\rho$ to get the 2nd order contribution to the chemical potential.


For VPT, at first order we have 
%      
\begin{align}
    \pdv{W_1}{\sigmaVPT} &= -\rho 
    - \frac{\LEC}{2}\rho\pdv{\rho}{\sigmaVPT} 
    - \frac{\LEC}{2}\phi\pdv{\phi}{\sigmaVPT} \notag\\
    &\quad+ \rho 
    + \sigmaVPT\pdv{\rho}{\sigmaVPT} 
    + \DeltaVPT\pdv{\phi}{\sigmaVPT}  \notag\\
    &= 
    %\qty(\sigmaVPT - \frac{\LEC}{2}\rho)
    \mathcal{N}\pdv{\rho}{\sigmaVPT}  
    %\qty(\DeltaVPT - \frac{\LEC}{2}\phi)
    + \mathcal{G}\pdv{\phi}{\sigmaVPT} , \\
    \pdv{W_1}{\DeltaVPT} &= -\phi - \frac{\LEC}{2}\rho\pdv{\rho}{\DeltaVPT} - \frac{\LEC}{2}\phi\pdv{\phi}{\DeltaVPT} + \sigmaVPT\pdv{\rho}{\DeltaVPT} 
        \notag \\ & \qquad \null
    + \phi + \DeltaVPT\pdv{\phi}{\DeltaVPT}  \notag\\
    &= 
    %\qty(\sigmaVPT - \frac{\LEC}{2}\rho)
    \mathcal{N}\pdv{\rho}{\DeltaVPT} 
    %+ \qty(\DeltaVPT - \frac{\LEC}{2}\phi)
    + \mathcal{G}\pdv{\phi}{\DeltaVPT} ,
\end{align}
where $\mathcal{N} \equiv \sigmaVPT - \frac{\LEC\rhot}{2}$ and $\mathcal{G} \equiv \DeltaVPT - \frac{\LEC\phi}{2}$.
These were solved in the same manner as inversion as they are mathematically very similar equations. 
The coefficients to the ``number'' and ``gap'' terms are positive-definite and do not cause any numerical complication.

For VPT, at second order we have
%
\begin{align}
    \pdv{W_2}{\sigmaVPT} = &\frac{\LEC}{2}\Biggl\{\qty[\qty(\pdv{\rhot}{\sigmaVPT})^2 
    + \qty(\pdv{\phi}{\sigmaVPT})^2]\mathcal{N} \notag\\
    &+ \pdv{\phi}{\sigmaVPT}\qty[\pdv{\rhot}{\sigmaVPT} 
    + \pdv{\phi}{\DeltaVPT}]\mathcal{G}\Biggr\} \notag \\
    &- \frac{1}{2}\pdv[2]{\rhot}{\sigmaVPT}\mathcal{N}^2 
    - \frac{1}{2}\pdv{\phi}{\sigmaVPT}{\DeltaVPT}\mathcal{G}^2 \notag\\
    &- \pdv{\rhot}{\sigmaVPT}{\DeltaVPT}\mathcal{NG} + 
    \pdv{\beachball}{\sigmaVPT} ,\label{eq:dW2_sigma}
\end{align}
%
and
%
\begin{align}
    \pdv{W_2}{\DeltaVPT} = &\frac{\LEC}{2}\Biggl\{\pdv{\rhot}{\DeltaVPT}\qty[\qty(\pdv{\phi}{\DeltaVPT}) + \pdv{\rhot}{\sigmaVPT}]\mathcal{N} \notag\\
    + &\qty[\qty(\pdv{\phi}{\DeltaVPT})^2 + \qty(\pdv{\rhot}{\DeltaVPT})^2]\mathcal{G}\Biggr\} \notag \\
    - &\frac{1}{2}\pdv{\rhot}{\DeltaVPT}{\sigmaVPT}\mathcal{N}^2 
    - \frac{1}{2}\pdv[2]{\phi}{\DeltaVPT}\mathcal{G}^2 \notag\\
    - &\pdv{\phi}{\DeltaVPT}{\sigmaVPT}\mathcal{NG} + \pdv{\beachball}{\DeltaVPT} ,\label{eq:dW2_Delta}
\end{align}
%
where $\pdv*{\rhot}{\DeltaVPT} = \pdv*{\phi}{\sigmaVPT}$, so they can be used interchangeably. 
The beachball diagram is basically the same form as we had for inversion in Eq.~\eqref{eq:bb}, the only difference is $\xi$ is now defined as $\frac{k^2}{2m} - \mu - \sigmaVPT$.


A stable way to solve for when Eqs.~\eqref{eq:dW2_sigma} and \eqref{eq:dW2_Delta} equal zero is to treat them as components of the gradient of $W$ as a function of $\sigmaVPT, \DeltaVPT$ at given input $\mu$ values, and then minimizing the approximation to the full $W$ with respect to the VPT parameters.
So to find the second order VPT parameters, we minimized 
\begin{align}
    W & \approx \int_k(\xi - E) 
    - \frac{\LEC}{4}(\rhot^2 + \phi^2) 
    + \sigmaVPT\rhot + \DeltaVPT\phi \notag \\
    &\qquad\null - \frac{1}{2}\pdv{\rhot}{\sigmaVPT}\mathcal{N}^2\notag \\
    &\qquad\null - \frac{1}{2}\pdv{\phi}{\DeltaVPT}\mathcal{G}^2 \notag \\
    &\qquad\null - M\mathcal{N}\mathcal{G} + \beachball,
\end{align}
where, in terms of the input parameters, 
\begin{align}
    \rhot &= \int\frac{\dd{k}}{2\pi}\qty(1 - \frac{\frac{k^2}{2m} - \mu - \sigmaVPT}{\sqrt{\qty(\frac{k^2}{2m} - \mu - \sigmaVPT)^2 + \DeltaVPT^2}})\\
    \phi &= \int\frac{\dd{k}}{2\pi}\frac{\DeltaVPT}{\sqrt{\qty(\frac{k^2}{2m} - \mu - \sigmaVPT)^2 + \DeltaVPT^2}}
.\end{align}
The optimiziation was performed in two steps: 
\begin{enumerate}
    \item An initial, softer optimization using Adam with the first-order values of $\sigmaVPT,\DeltaVPT$ at a given chemical potential as an initial guess. The learning rate for Adam was 0.001.
    \item A second, more strict optimization using BFGS with the output from Adam as the initial guess.
\end{enumerate}
Criteria for termination of the algorithms were smallness of the gradient and the size of steps taken. 
Adaptive quadrature was used to accommodate the changing of the curves for the diagrams.
For the beachball, a Genz-Malik rule was implemented through the \texttt{Cubature.jl} package~\cite{cubature}.



