%\begin{equation}
%\hat{\bar{H}}_N \ket{R} = E_{CC}\ket{R} \label{cc-st-wave-eq-gs}
%\end{equation}
%with $E_{CC}$ denoting the correlation energy. For brevity we will drop the subscript $N$ in $\bar{H}_N$. We recall that the CC Jacobian matrix $\mathbf{A}$ that appears in the following (see also table~\ref{tab:ListOfTensor}) is equivalent to $\hat{\bar{H}}$.
we have the unperturbed amplitudes and multipliers obtained from the equations
\begin{align}
\left\langle \mu \right| \bar{\mathbf{H}} \left| \mathrm{R} \right\rangle &= 0 \\
\bar{t}\;\bar{\mathbf{H}} + \eta &= 0
\end{align}
where $\mathbf{\bar{H}}$ %
%$ = \left[ \exp(-T)\hat{H}_0\exp(-T) - \bra{R}\hat{H}_0\ket{R} \right]$ 
is matrix representation of the normal-ordered similarity transformed Hamiltonian. The definitions of $\mathbf{\mathbf{\bar{H}}}$ and $\eta$ are given in table~\ref{tab:ListOfTensor}. Further details on the evaluation of these equations in our implementation can be found in~\cite{pototschnig_implementation_2021}.

After solving for the unperturbed wave function parameters, the first-order parameters are next obtained by solving the response equations~\cite{Christiansen1998,Yuan_Xiang_LR,Yuan_Xiang_QR}
\begin{subequations}
\label{eq:PerturbatedLinearEquations}
\begin{align}
\left( \mathbf{\bar{H}} - \omega_{Y}\mathbf{I} \right) \tYs{}{}(\omega_Y) + \xi^Y= & 0 \label{eq:tPerturbated}\\
	\tbYs {}{} \left(\omega_Y\right)\left(\mathbf{\bar{H}}+\omega_Y \mathbf{I}\right)+\eta^Y+\mathbf{F} \tYs {}{} \left(\omega_Y\right)=&0,
 \label{eq:tBarPerturbated}
\end{align}
\end{subequations}
where $\mathbf{I}$ is the identity matrix. We employ the shorthand notation $\tYs{}{}, \tbYs{}{}$ to describe the first-order perturbed amplitudes and multipliers, obtained for perturbation $\hat{Y}$ at frequency $\omega_Y$, respectively. We note that, in contrast to the first-order response equations in QR-EOMCC, the equations for the first-order perturbed multipliers depend on the first-order perturbed amplitudes. The definitions of terms $\mathbf{F}$, $\xi^Y, \eta^Y$ are also given in table~\ref{tab:ListOfTensor}. 

The frequency-(in)dependent quadratic response function is given by the expression
\begin{align}
	\langle\langle Z; X, Y\rangle\rangle & {}_{\omega_X, \omega_Y} 
	= \frac{1}{2} C^{\pm \omega} P\left( X\left(\omega_{X}\right), Y\left(\omega_{Y}\right), Z\left(\omega_{Z}\right)\right) \nonumber \\
	& \times\left\{ \left[\frac{1}{2} \mathbf{F}^{X}+\frac{1}{6} \mathbf{G} \tXs {}{} \left(\omega_{X}\right)\right] \tYs{}{} \left(\omega_{Y}\right) +\tbXs{}{}\left(\omega_X\right)\left[\mathbf{A}^{Y}+\frac{1}{2} \mathbf{B} \tYs{}{}\left(\omega_{Y}\right)\right]\right\} \tZs{}{} \left(\omega_{Z}\right)\ ,
    \label{eq:QuadraticResponse}
\end{align}
where the perturbing frequencies satisfy the relationship $\omega_Z = -(\omega_X + \omega_Y)$. The operator $P\left( X\left(\omega_{X}\right), Y\left(\omega_{Y}\right), Z\left(\omega_{Z}\right)\right)$  takes care of the permutation of the perturbing operators, and 
\begin{equation}
C^{\pm\omega}f^{XYZ}(\omega_X,\omega_Y,\omega_Z) = f^{XYZ}(\omega_X,\omega_Y,\omega_Z) + [f^{XYZ}(-\omega_X,-\omega_Y,-\omega_Z)]^*
\label{eq:symmetrization}
\end{equation}
is used for the symmetrization of the response functions~\cite{Christiansen1998}, which requires the solution of response $f^{XYZ}(\omega_X,\omega_Y,\omega_Z)$ also for the negative of the frequencies (inverting the frequencies followed by complex conjugation). Eq.~\ref{eq:QuadraticResponse} can also be rewritten as 
\begin{align}
	   \langle\langle X, Y, Z\rangle\rangle_{\omega_Y, \omega_Z} 
	   &= \frac{1}{2} C^{\pm \omega} P\left( X\left(\omega_{X}\right), Y\left(\omega_{Y}\right), Z\left(\omega_{Z}\right)\right) \times\left\{ 
        \left[O^{X,Y}\right] +\left[O^{\bar{X},Y}\right]\right\} \tZs{}{} \left(\omega_{Z}\right),
        \label{eq:PropertyWith_O_Expression}
\end{align}
where  $O^{X,Y}$ and $O^{\bar{X},Y}$ group the terms involving contractions only with perturbed amplitudes or with both perturbed amplitudes and multipliers, respectively:
\begin{subequations}
    \label{eq:ExpressionOfSubEquationWithO}
    \begin{align}
        O^{X;Y} = & \left[ \frac{1}{2} \mathbf{F}^{X}+\frac{1}{6} \mathbf{G} \tXs{}{} \left(\omega_{X}\right) \right] \tYs{}{} \left(\omega_{Y}\right)  = \frac{1}{2} \mathbf{F}^{X} \tYs{}{} \left(\omega_{Y}\right) +\frac{1}{6} \mathbf{G} \tXs {}{} \left(\omega_{X}\right) \tYs {}{} \left(\omega_{Y}\right) \label{eq:Ott}   \\
        O{}^{\bar{X};Y} =&\ \tbXs {}{} \left(\omega_X\right)\left[ \mathbf{A}^{Y}+\frac{1}{2} \mathbf{B} \tYs {}{} \left(\omega_{Y}\right) \right]  = \tbXs{}{} \left(\omega_X\right) \mathbf{A}^{Y}+ \frac{1}{2} \tbXs{}{} \left(\omega_X\right)  \mathbf{B} \tYs {}{} \left(\omega_{Y}\right) \label{eq:Otbart}
    \end{align} 
\end{subequations}
and that for all combinations allowed by the $C^{\pm \omega} P  $ product.



