	\centering
		\includegraphics[width= \columnwidth]{figures/Mixer_board_schem.pdf}
	\caption{Schematic of the high frequency board electronics, showing amplifiers (ADL), attenuators (LAT), a splitter (ADP) and the mixer itself (SRA).}
