% To validate our theoretical framework, we conduct comprehensive numerical experiments using parallel Monte Carlo simulation with 100,000 paths. We implement the INAR($\infty$) approach to price various types of options, including European, Asian, Lookback, and Barrier options, and compare the European call option results with established methods. Our numerical results demonstrate that the INAR($\infty$) approach achieves comparable accuracy to these methods, with pricing differences typically within a few basis points for European options. The implementation successfully handles path-dependent features required for Asian options (averaging), Lookback options (extreme values), and Barrier options (boundary crossing), showing the versatility of our approach. This empirical validation not only confirms the practical relevance of our theoretical findings but also suggests that the INAR($\infty$) framework could serve as a viable alternative for pricing both vanilla and exotic options under rough volatility.

The remainder of this paper is organized as follows. Section \ref{sec2} presents the theoretical framework and proves the convergence of INAR($\infty$) processes to the rough Heston model. %Section 3 provides the Proof of Theorem \ref{theorem1}. 
Section \ref{sec3} provides the proposed simulation algorithm and detailed numerical analysis.  Section \ref{sec4} concludes with a discussion of our findings and potential future research directions. Technical proofs are collected in the Appendix. 

\section{From INAR$(\infty)$ process to rough Heston model}\label{sec2}
\subsection{Discrete-time microstructural foundation for the rough Heston model}
Let $\alpha^{(1)}, \alpha^{(2)}, \alpha^{(3)}, \alpha^{(4)}$ denote four positive $\ell^1$ sequences, each satisfying $\norm{\alpha^{(i)}}_1 < 1$ for $1 \leq i \leq 4$, where $\norm{\cdot}_1$ represents the standard $\ell^1$ norm. We examine a sequence of bivariate cumulative INAR$(\infty)$ processes $(N^{\tau,+}, N^{\tau,-})$, indexed by $\tau > 0$ as $\tau \to \infty$. For $n \in \mathbb{N}$, their intensity is defined as
\begin{align*}
    \begin{pmatrix}
        \lambda_n^{\tau,+} \\
        \lambda_n^{\tau,-}
    \end{pmatrix}
    := \hat{\mu}_{\tau}(n) 
    \begin{pmatrix}
        1 \\
        1
    \end{pmatrix}
    + a_{\tau} \sum_{s=1}^{n-1} 
    \begin{pmatrix}
        \alpha_{n-s}^{(1)} & \alpha_{n-s}^{(3)} \\
        \alpha_{n-s}^{(2)} & \alpha_{n-s}^{(4)}
    \end{pmatrix}
    \begin{pmatrix}
        X_s^{\tau,+} \\
        X_s^{\tau,-}
    \end{pmatrix},
\end{align*}
where $\hat{\mu}_{\tau}(n)$ is the time-dependent baseline intensity, to be specified in Definition \ref{definition1}, and $a_{\tau}$ denotes the decay parameter. Based on this framework, we model the tick-by-tick transaction price $P_n^{\tau}$ as
\[
    P_n^{\tau} = N_n^{\tau,+} - N_n^{\tau,-}.
\]
We now present a set of assumptions for continuous-time cases, analogous to those in \cite{el2019characteristic}.
\begin{assumption}  
    The stability condition guarantees that the spectral radius of the matrix
    \[
       a_\tau\left(
        \begin{matrix}
          \norm {\alpha^{(1)}}_1 & \norm {\alpha^{(3)}}_1\\
          \norm {\alpha^{(2)}}_1 & \norm {\alpha^{(4)}}_1
        \end{matrix}
        \right)
    \]
    is  less than $1$, but it should almost be saturated (close to 1) and the intensity of exogenous orders $\mu_{\tau}$ should be small. Thus the suitable constraint for model parameters should be
    \[
        a_{\tau}\rightarrow 1,\ \quad \mathcal S\left( \begin{matrix}
            \norm {\alpha^{(1)}}_1 & \norm {\alpha^{(3)}}_1\\
            \norm {\alpha^{(2)}}_1 & \norm {\alpha^{(4)}}_1
          \end{matrix} \right) =1,\ \quad \mu_{\tau}\rightarrow 0.
    \]
\end{assumption}

Following \cite{wang2024scaling}, the heavy-tailed condition requires that
  \[
    (1-a_{\tau})\tau^\alpha\rightarrow \gamma,\ \quad  \mu_{\tau}\tau^{1-\alpha}\rightarrow \mu,
  \]
for some positive constants $\gamma$ and $\mu$. In this paper, we explicitly define
\[
    a_{\tau}=1-\gamma \tau^{-\alpha}\ \text{ and }\ \mu_{\tau}=\mu \tau^{\alpha-1},
\]
as specified in Definition \ref{definition2} below.
\begin{assumption}
  The ``no statistical arbitrage" condition requires
  \[
    \alpha^{(1)}+\alpha^{(3)}=\alpha^{(2)}+\alpha^{(4)}.
  \]
\end{assumption}

\begin{assumption}\label{assumption3}
  The liquidity asymmetry on the bid and ask sides of the order book:
  \[
    \alpha^{(3)}=\beta \alpha^{(2)},
  \]
  for some $\beta>1$, hence $\alpha^{(4)}=\alpha^{(1)}+(\beta-1)\alpha^{(2)}$.
\end{assumption}

\begin{assumption} 
  The heavy-tailed assumption: for some positive constant $C$,
  \[
    \alpha n^\alpha \sum_{s=n}^\infty \left( \alpha_s^{(1)}+\beta\alpha_s^{(2)} \right)\rightarrow C,\ \text{as}\ n\rightarrow \infty.
  \]
\end{assumption}



\begin{definition}\label{definition1}
  The baseline intensity $\hat\mu_{\tau}$ is given by
  \[
    \hat \mu_{\tau}(n):=\mu_{\tau}+\xi \mu_{\tau}\left( \frac1{1-a_{\tau}}\left( 1-\sum_{s=1}^{n-1}\varphi_s^{\tau} \right)-\sum_{s=1}^{n-1}\varphi_s^{\tau} \right),
  \]
  with $\xi>0$ and $\mu_{\tau}=\mu\tau^{\alpha-1}$ for some $\mu>0$.
\end{definition}

We work on a sequence of probability spaces $(\Omega^{\tau},\mathcal F^{\tau},\mathbb P^{\tau})$, indexed by $\tau>0$ (going to infinity), under which 
\[
\mathbf N^{\tau}=(N^{\tau,+},N^{\tau,-})^\top
\]
is a bivariate INAR$(\infty)$ process with intensity
\[
  \bm{\lambda}_n^{\tau}=\left(
  \begin{matrix}
     \lambda_n^{\tau,+}\\
     \lambda_n^{\tau,-}
  \end{matrix}\right)
  =\hat\mu_{\tau}(n)\left(
    \begin{matrix}
      1\\
      1
    \end{matrix}
    \right)+
    \sum_{s=1}^{n-1}\alpha_{n-s}^{\tau}\left(
      \begin{matrix}
        X_s^{\tau,+}\\
        X_s^{\tau,-}
      \end{matrix}
      \right).
\]


\begin{definition}\label{definition2}
  There exist $\beta>1$, $1/2<\alpha<1$ and $\gamma>0$ such that
  \[
    a_\tau=1-\gamma \tau^{-\alpha},\ \quad  \alpha_{n}^{\tau}=\varphi_n^{\tau} \chi,
  \]
  where
  \[
    \chi=\frac1{\beta+1}\left(
      \begin{matrix}
        1 & \beta\\
        1 & \beta
      \end{matrix}
      \right),\ \quad \varphi_n^{\tau}=a_{\tau}\varphi_n, 
   \]
   \[
    \varphi_n=
    \begin{cases}
      1-\frac1{\Gamma(1-\alpha)\cdot 2^\alpha}, &n=1,\\
      \frac1{\Gamma(1-\alpha)}\left( \frac1{(n-1)^\alpha}-\frac1{n^\alpha}\right), &n\ge2.
    \end{cases}
   \]
   Here, $\beta>1$ reflects the liquidity asymmetry between bid and ask sides, as specified in Assumption \ref{assumption3}.
\end{definition}

\begin{remark}  
  Definition \ref{definition2} closely resembles Definition 2.1 in \cite{el2019characteristic}, with the notable exception of the sequence $\{\varphi_n\}_{n \geq 1}$. Here, $\{\varphi_n\}_{n \geq 1}$ is specifically constructed to satisfy the unstable condition  
  \[  
  \sum_{n=1}^\infty \varphi_n = 1,  
  \]  
  and the heavy-tailed behavior  
  \[  
  n^\alpha \sum_{k=n+1}^\infty \varphi_k \to \frac{1}{\Gamma(1-\alpha)} \quad \text{as} \quad n \to \infty.  
  \]  
\end{remark}
Following Definition \ref{definition2}, we can express $\lambda_n^{\tau,+}$ as a sum of its deterministic and stochastic components. We start by observing that
\[
  \lambda_n^{\tau,+}=\lambda_n^{\tau,-}.
\]
Let us write
\[
  \mathbf M_n^{\tau}=(M_n^{\tau,+},M_n^{\tau,-})^\top=\mathbf N_n^{\tau}-\sum_{s=1}^{n}\bm\lambda_s^{\tau}
\]
for the martingale associated to $\mathbf N_t^{\tau}$. We can easily obtain
\[
  \lambda_n^{\tau,+}=\hat \mu_{\tau}(n)+\sum_{s=1}^{n-1}\varphi_{n-s}^{\tau}\lambda_s^{\tau,+}+\frac1{1+\beta}\sum_{s=1}^{n-1}\varphi_{n-s}^{\tau}(M_s^{\tau,+}-M_{s-1}^{\tau,+}+\beta(M_s^{\tau,-}-M_{s-1}^{\tau,-})).
\]
Now let
\[
  \psi^{\tau}=\sum_{k=1}^\infty (\varphi^{\tau})^{*k},
\]
where $*$ denotes the discrete convolution operation, i.e.,   for two non-negative sequences $\{q_n\}_{n\ge1},\{m_n\}_{n\ge1}\in \ell^1$, there is 
\[
  (q*m)(n)=\sum_{s=1}^{n-1}q_sm_{n-s},
\]
and $\alpha^{*k+1}$ denotes the discrete convolution of $\alpha^{*k}$ with $\alpha$, i.e., $\alpha^{*k+1}=\alpha*\alpha^{*k}$. $\psi^{\tau}$ is well defined since $\norm {\varphi^{\tau}}_1<1$. Drawing from the solution of discrete renewal equations, as established in Lemma 4.1 of \cite{wang2024scaling}, we derive
\begin{equation}\label{lambdaT+expression}
  \lambda_n^{\tau,+} = \hat{\mu}_\tau(n) + \sum_{s=1}^{n-1} \psi_{n-s}^\tau \hat{\mu}_\tau(s) + \frac{1}{1 + \beta} \sum_{s=1}^{n-1} \psi_{n-s}^\tau \big( M_s^{\tau,+} - M_{s-1}^{\tau,+} + \beta M_s^{\tau,-} - \beta M_{s-1}^{\tau,-} \big).
\end{equation}








\subsection{The rough limits of cumulative INAR$(\infty)$ processes}
First, we consider how to choose the right scaling constant. We have chosen
\[
  \mu_{\tau}=\mu \tau^{\alpha-1},
\]
where $\mu$ is some positive constant. To get a nondegenerate limit, similar to \cite{wang2024scaling}, for $t\in[0,1]$, we  consider $(1-a_{\tau})\lambda_{\lfloor t\tau\rfloor}^{\tau,+}/\mu_{\tau}$, and define the renormalized intensity
\[
  C_t^{\tau}=\frac{1-a_{\tau}}{\mu_{\tau}}\lambda_{\lfloor t\tau\rfloor}^{\tau,+}.
\]
After some calculations, this can be rewritten as
\[
\begin{aligned}
  C_t^{\tau}
  =&\frac{1-a_{\tau}}{\mu_{\tau}}\hat\mu_{\tau}(\lfloor t\tau \rfloor)+(1-a_{\tau})\sum_{s=1}^{\lfloor t\tau \rfloor-1}\psi_{\lfloor t\tau \rfloor-s}^{\tau}\frac{\hat\mu_{\tau}(s)}{\mu_{\tau}}\\
  &+\nu \tau(1-a_{\tau}) \sum_{s=1}^{\lfloor t\tau \rfloor-1}\psi_{\lfloor t\tau \rfloor-s}^{\tau}\sqrt{C_{s/\tau}^{\tau}}\left( B_{(s+1)/\tau}^{\tau}-B_{s/\tau}^{\tau} \right),
\end{aligned}
\]
where 
\[
  B_t^{\tau}:=\frac1{\sqrt{\tau}}\sum_{s=1}^{\lfloor t\tau \rfloor-1}\frac{M_s^{\tau,+}-M_{s-1}^{\tau,+}+\beta(M_s^{\tau,-}-M_{s-1}^{\tau,-})}{\sqrt{\lambda_s^{\tau,+}+\beta^2\lambda_s^{\tau,-}}},\ \quad \nu=\sqrt{\frac{1+\beta^2}{\gamma\mu(1+\beta)^2}}
\]
will converge weakly to a standard Brownian motion $B$ as $\tau\rightarrow\infty$ by the martingale central limit theorem, see \cite{wang2024scaling}. Hence, for $t\in[0,1]$, we define
\[
    \mathbf Y_t^{\tau}=\frac{1-a_{\tau}}{\tau^\alpha \mu}\mathbf N_{\lfloor t\tau \rfloor}^{\tau},\ \quad
    \bm\Lambda_t^{\tau}=\frac{1-a_{\tau}}{\tau^\alpha \mu}\sum_{s=1}^{\lfloor t\tau \rfloor}\bm\lambda_s^{\tau},\ \quad 
    \mathbf Z_t^{\tau}=\sqrt{\frac{\tau^\alpha\mu}{1-a_{\tau}}}(\mathbf Y_t^{\tau}-\bm\Lambda_t^{\tau}).
\]
We then state the main result of the paper. 

\begin{theorem}\label{theorem1}
  As $\tau\rightarrow \infty$, under Definitions \ref{definition1} and \ref{definition2}, the process $(\bm\Lambda_t^{\tau},\mathbf Y_t^{\tau},\mathbf Z_t^{\tau})_{t\in[0,1]}$ converges in law under the Skorohod topology to $(\bm\Lambda,\mathbf Y,\mathbf Z)$, where 
  \[
    \bm\Lambda_t=\mathbf Y_t=\int_0^t\dot{Y}_sds\left(  \begin{matrix}
     1\\1
    \end{matrix}\right),\ \mathbf Z_t=\int_0^t\sqrt{\dot{Y}_s}\left(\begin{matrix}
    dB_s^1\\dB_s^2
    \end{matrix}\right),
  \]
  and $\dot{Y}$ is the unique solution of the following rough stochastic differential equation
  \[
    \dot{Y}_t=\xi+\frac1{\Gamma(\alpha)}\int_0^t\gamma(1-\dot{Y}_s)ds+\gamma \sqrt{\frac{1+\beta^2}{\gamma \mu(1+\beta^2)}}\frac1{\Gamma(\alpha)}\int_0^t(t-s)^{\alpha-1}\sqrt{\dot{Y}_s}dB_s,
  \]
  where
  \[
     B=\frac{B^1+\beta B^2}{\sqrt{1+\beta^2}},
  \]
  and $(B^1,B^2)$ is a bivariate Brownian motion. Furthermore, for any $\epsilon>0$, $Y$ has \holder\ regularity $\alpha-1/2-\epsilon$. 
\end{theorem}

\begin{proof}
  We provide the proof in Appendix \ref{sectionproof}.
\end{proof}

Then we can also build microscopic processes converging to the log-price like in \cite{el2019characteristic}. For $\theta>0$, we define
\[
  P^{\tau}=\sqrt{\frac{\theta}2}\sqrt{\frac{1-a_{\tau}}{\tau^\alpha\mu}}\left( N_{\lfloor \cdot \tau \rfloor}^{\tau,+}-N_{\lfloor \cdot \tau \rfloor}^{\tau,-} \right)-\frac\theta2\frac{1-a_{\tau}}{\tau^\alpha\mu}N_{\lfloor \cdot \tau \rfloor}^{\tau,+}=\frac{\theta}{2}(Z^{\tau,+}-Z^{\tau,-})-\frac\theta2X^{\tau,+}.
\]
The properly rescaled microscopic price process
\[
  \sqrt{\frac{1-a_{\tau}}{\mu \tau^\alpha}}P_{\lfloor t\tau \rfloor}^{\tau},\ t\in[0,1],
\]
converges in law as $\tau$ tends to infinity to a macroscopic price dynamic $P$. From Theorem \ref{theorem1}, we know that $P^{\tau}$ converges in law under the Skorohod topology to the process $\{P_t\}_{t\ge0}$ given by
\[
 P_t = \sqrt{\frac\theta2}\int_0^t\sqrt{\dot{Y}_s}(dB_s^1-dB_s^2)-\frac\theta2\int_0^t\dot{Y}_sds.
\]
Let $V_t=\theta \dot{Y}_t$ and $W_t=\frac1{\sqrt2}(B_t^1-B_t^2)$. Then we have the following Theorem.

\begin{theorem}\label{maintheorem}
  As $\tau\rightarrow\infty$, under Definitions \ref{definition1} and \ref{definition2}, the sequence of processes $\{P_t^{\tau}\}_{t\in[0,1]}$ converges in law under the Skorohod topology to
  \[
    P_t=\int_0^t\sqrt{V_s}dW_s-\frac12\int_0^tV_sds,
  \]
  where $V$ is the unique solution of the rough stochastic differential equation
  \begin{equation}\label{finalequation2}
    V_t=\theta\xi+\frac1{\Gamma(\alpha)}\int_0^t(t-s)^{\alpha-1}\gamma(\theta-V_s)ds+\gamma\sqrt{\frac{\theta(1+\beta^2)}{\gamma\mu(1+\beta)^2}}\frac1{\Gamma(\alpha)}\int_0^t(t-s)^{\alpha-1}\sqrt{V_s}dB_s,
  \end{equation}
  with $(W,B)$ a correlated bivariate Brownian motion whose bracket satisfies
  \begin{equation}\label{correlation}
    d\langle W,B \rangle_t=\frac{1-\beta}{\sqrt{2(1+\beta^2)}}dt.
  \end{equation}
\end{theorem}

\begin{proof}
The proof of Theorem \ref{maintheorem} follows similarly from the proof in Section 6.1.4 of \cite{el2019characteristic} after we have established Theorem \ref{theorem1} above.
\end{proof}

\begin{remark}
   From \eqref{correlation} and the condition that $\beta > 1$, the correlation coefficient $\rho$ between the two Brownian motions must lie in the interval $\left(-\frac{1}{\sqrt{2}}, 0\right)$, which is consistent with \cite{el2019characteristic}.
\end{remark}

\section{Numerical Results}\label{sec3}
Based on the theoretical convergence established above, we can simulate a rough Heston model by simulating from its approximating cumulative INAR($\infty$) model. More specifically,  we present an efficient Monte Carlo simulation framework for pricing various types of path-independent and path-dependent options by simulating a bidimensional cumulative INAR($\infty$) processes and demonstrate numerically that they provide accurate approximations to corresponding option prices under the rough Heston model. Our implementation includes European, Asian, lookback, and barrier options, with an emphasis on computational efficiency through parallel processing. 
\subsection{Rough case ($\alpha=0.62$)}

%\subsubsection{Review of different options contracts}
Let $S_t$ denote the price of the underlying asset at time $t$, $K$  the strike price, $T$  the maturity time, and $r$ be the risk-free interest rate. We recall the following option types and the corresponding payoff functions. 
\begin{enumerate}
    \item \textbf{European Option:} The payoff at maturity is:
    \[
        V_T = \begin{cases}
        \max(S_T - K, 0) & \text{for a call option}\\
        \max(K - S_T, 0) & \text{for a put option}
        \end{cases}
    \]
    The option price is given by the discounted expected payoff:
    \[
        V_0 = e^{-rT}\mathbb{E}[V_T]
    \]

    \item \textbf{Arithmetic Asian Option:} For arithmetic Asian options, the payoff depends on the arithmetic average price:
    \[
        \bar{S}_T = \frac{1}{T}\int_0^T S_u du
    \]
    The payoff at maturity is:
    \[
        V_T = \begin{cases}
        \max(\bar{S}_T - K, 0) & \text{for an Asian call option}\\
        \max(K - \bar{S}_T, 0) & \text{for an Asian put option}
        \end{cases}
    \]

    \item \textbf{Lookback Option:} Let $M_T = \max_{0\leq t\leq T} S_t$ and $m_T = \min_{0\leq t\leq T} S_t$. The payoff at maturity is:
    \[
        V_T = \begin{cases}
        M_T - K & \text{for a lookback call option}\\
        K - m_T & \text{for a lookback put option}
        \end{cases}
    \]

    \item \textbf{Barrier Options:} Let $B$ be the barrier level. For up-and-in barrier call options:
    \[
        V_T = \begin{cases}
        \max(S_T - K, 0) & \text{if } \max_{0\leq t\leq T} S_t \geq B\\
        0 & \text{otherwise}
        \end{cases}
    \]
    For down-and-out barrier put options:
    \[
        V_T = \begin{cases}
        \max(K - S_T, 0) & \text{if } \min_{0\leq t\leq T} S_t > B\\
        0 & \text{otherwise}
        \end{cases}
    \]
\end{enumerate}

%\subsubsection{Simulation framework and core functions}
The core of our implementation consists of several key functions that work together to simulate price paths and compute option values. The primary components include the following. 
\begin{enumerate}
    \item A helper function $f_{\alpha}(t)$ that computes the fractional kernel:
    \[
    f_{\alpha}(t) = 
    \begin{cases}
    0 & \text{if } t \leq 0 \\
    1 - \frac{1}{\Gamma(1-\alpha) \cdot 2^{\alpha}} & \text{if } t = 1 \\
    \frac{1}{\Gamma(1-\alpha)} \left(\frac{1}{t^{\alpha}} - \frac{1}{(t+1)^{\alpha}}\right) & \text{if } t > 1
    \end{cases}
    \]

    \item Path generation functions for different option types:
    \begin{itemize}
        \item Standard path simulation for European options
        \item Path with running average calculation for Asian options
        \item Path with maximum/minimum tracking for lookback options
        \item Barrier crossing detection for barrier options
    \end{itemize}
\end{enumerate}

%\subsubsection{Enhanced parallel Monte Carlo implementation}
We employ a parallel Monte Carlo simulation that effectively distributes the computational workload across multiple CPU cores. The structure of the algorithm is outlined in Algorithm \ref{algo1} below. For the sake of simplicity, we define $T=1$ and $\tau=250$.

\begin{algorithm}[H]
\caption{Enhanced Parallel Monte Carlo Option Pricing}\label{algo1}
\label{algo:parallel_mc}
\SetAlgoLined
\KwIn{Parameters $(\alpha, \gamma, \tau, \beta, \mu, \theta, \xi, S_0)$, number of simulations $n_{\text{sims}}$}
\KwOut{Option price estimates with 95\% confidence intervals}

Determine number of available CPU threads \;
Divide $n_{\text{sims}}$ among available threads \;
Initialize arrays for simulation results \;

\For{each thread in parallel}{
    Initialize thread-specific random number generator \;
    \For{each simulation assigned to thread}{
        Generate stock price path using INAR($\infty$) simulation \;
        Compute various option payoffs:
        \begin{itemize}
            \item European: $\max(S_T - K, 0)$
            \item Asian: $\max(\frac{1}{\tau}\sum_{i=1}^\tau S_{iT/\tau} - K, 0)$
            \item Lookback: $\max(M_T - K, 0)$ where $M_T = \max_{0\leq i\leq \tau} S_{iT/\tau}$
            \item Barrier: conditional payoffs based on barrier crossing
        \end{itemize}
        Store results in respective arrays \;
    }
}

Compute mean and 95\% confidence intervals for each option type \;

\Return{Option price estimates and confidence intervals}
\end{algorithm}

