\section{Technical Proofs}\label{sectionproof}
\subsection{$\mathbb C$-tightness of $(\bm\Lambda^{\tau},\mathbf Y^{\tau},\mathbf Z^{\tau})$}
\begin{proposition}\label{proposition1}
  Under Definition \ref{definition1} and \ref{definition2}, the sequence $(\bm\Lambda^{\tau},\mathbf Y^{\tau},\mathbf Z^{\tau})$ is $\mathbb C$-tight and 
  \[
    \sup_{t\in[0,1]}\norm {\bm\Lambda_t^{\tau}-\mathbf Y_t^{\tau}}_1\rightarrow 0
  \]
  in probability as $\tau\rightarrow\infty$, where $\norm \cdot_1$ represents $\ell^1$ norm in Euclidean space. Moreover, if $(\mathbf Y,\mathbf Z)$ is a possible limit point of $(\mathbf Y^{\tau},\mathbf Z^{\tau})$, then $\mathbf Z$ is a continuous martingale with $[\mathbf Z,\mathbf Z]=\text{diag}(\mathbf Y)$.
\end{proposition}

Since the components of $(\mathbf Y^{\tau})$ and $(\bm\Lambda^{\tau})$ are pure jump processes, the classical Kolmogorov-Chentsov tightness criterion cannot be applied. Lemma 3.5 in \cite{horst2023convergence} gives a new criterion to verify the $\mathbb C$-tightness for a sequence of \cadlag\  processes which is useful in proving Proposition \ref{proposition1}. To make the proof clear, we introduce the lemma here.

\begin{lemma}[Lemma 3.5 in \cite{horst2023convergence}]\label{xu2023}
  If 
  \[
    \sup_{n\ge1}\mathbb E\left[ \left|X^{(n)}_0\right|^\beta \right]<\infty
  \]
  for some $\beta>0$, then the sequence $(X^{(n)})_{n\ge1}$ is $\mathbb C$-tight if for $\tau\ge0$ and some constant $\theta>2$, the following two conditions hold.
  \begin{enumerate}
    \item \begin{align*}
      \sup_{k=0,1,\cdot,\lfloor\tau n^\theta\rfloor}\sup_{h\in[0,1/n^\theta]}|\Delta_hX_{k/n^\theta}^{(n)}|\rightarrow 0\ \text{in probability as}\ n\rightarrow\infty.
    \end{align*}
    \item There exists some constants $C>0$, $p\ge1$, $m\in\{1,2,\cdots\}$ and pairs $\{(a_i,b_i)\}_{i=1,\cdots,m}$ satisfying
        \[
          a_i\ge0,\ b_i>0,\ \rho:=\min_{1\le i\le m}\{b_i+a_i/\theta\}>1,
        \]
        such that for all $n\ge1$ and $h\in(0,1)$,
        \[
          \sup_{t\in[0,T]}\mathbb E\left[ \left|\Delta_h X_t^{(n)}\right|^p \right]\le C\cdot\sum_{i=1}^m\frac{h^{b_i}}{n^{a_i}}.
        \]
  \end{enumerate}
\end{lemma}

\begin{proof}[Proof]
  The following computations are performed on the probability space $(\Omega^{\tau}, \mathcal F^{\tau}, \mathbb P^{\tau})$, with $\tau\rightarrow\infty$.

  \textbf{$\mathbb C$-tightness of $\mathbf Y^{\tau}$ and $\bm\Lambda^{\tau}$:}\

  We just need to check whether each component of $\mathbf Y^{\tau}$ and $\bm\Lambda^{\tau}$ is $\mathbb C$-tight. Without loss of generality, for $\mathbf Y^{\tau}$, we can check $Y^{\tau,+}$. First, we use Lemma \ref{xu2023} which is a criterion to verify the $\mathbb C$-tightness for a sequence of \cadlag\ processes. For $(Y_t^{\tau,+})_{t\in[0,1]}$, we need to check these three conditions. The verification for $(\bm\Lambda_t^{\tau})_{t\in[0,1]}$ is exactly the same as $(\mathbf Y_t^{\tau})_{t\in[0,1]}$. 
  \begin{enumerate}
    \item Since $Y_0^{\tau,+}=0$, $\sup_{n\ge1}\mathbb E\left[ |Y_0^{\tau,+}|^\beta \right]=0<\infty$ is satisfied.
    \item Given a constant $\theta>2$, 
          \begin{align*}
            \sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}\sup_{h\in[0,1/\tau^\theta]}\left| \Delta_hY_{k/\tau^\theta}^{\tau,+} \right|
           =&\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}\left| Y_{(k+1)/\tau^\theta}^{\tau,+}-Y_{k/\tau^\theta}^{\tau,+} \right|\\
           =&\frac{1-a_{\tau}}{\tau^\alpha\mu}\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}\sum_{s=\lfloor k/\tau^{\theta-1} \rfloor+1}^{\lfloor (k+1)/\tau^{\theta-1} \rfloor}X_s^{\tau,+}\\
           =&\frac{1-a_{\tau}}{\tau^\alpha\mu}\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}X_{\lfloor \frac{k+1}{\tau^{\theta-1}} \rfloor}^{\tau,+}.
          \end{align*}
          We need to prove for any $\epsilon>0$, 
          \begin{equation}\label{convergeinprobability}
            \mathbb P\left(\frac{1-a_\tau}{\tau^\alpha \mu}\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}X_{\lfloor \frac{k+1}{\tau^{\theta-1}} \rfloor}^{\tau,+}>\epsilon\right)\rightarrow 0
          \end{equation}
          as $\tau\rightarrow\infty$. In fact, since there are at most $\lfloor \tau \rfloor$ integers in $\{\lfloor \frac{k+1}{\tau^{\theta-1}}\rfloor:k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1\}$, from the Markov inequality,
          \begin{align*}
            &\mathbb P\left(\frac{1-a_\tau}{\tau^\alpha \mu}\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}X_{\lfloor \frac{k+1}{\tau^{\theta-1}} \rfloor}^{\tau,+}>\epsilon\right)\\
            =&\mathbb P\left( \sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}X_{\lfloor \frac{k+1}{\tau^{\theta-1}} \rfloor}^{\tau,+}>\frac{\tau^\alpha \mu}{1-a_\tau}\epsilon \right)\\
            \le &\sum_{s=0}^{\lfloor \tau \rfloor}\frac{\mathbb E\left[ (X_s^{\tau,+})^2 \right]}{\left( \frac{\tau^\alpha\mu}{1-a_\tau}\epsilon \right)^2}\\
            =&\sum_{s=0}^{\lfloor \tau \rfloor}\frac{\mathbb E\left[ \lambda_s^{\tau,+} \right]+\mathbb E\left[ (\lambda_s^{\tau,+})^2 \right]}{\left( \frac{\tau^\alpha\mu}{1-a_\tau}\epsilon \right)^2}.
          \end{align*}
          Now we need to estimate the magnitude of $\mathbb E[\lambda_s^{\tau,+}]$ and $\mathbb E[(\lambda_s^{\tau,+})^2]$ for $s\sim \tau$. We calculate them step by step.
          \begin{enumerate}
             \item We begin by deriving an upper bound for \(\hat{\mu}_{\tau}(s)\) over the range \(1 \leq s \leq \lfloor \tau \rfloor\). Recalling that \(a_{\tau} = 1 - \gamma \tau^{-\alpha}\) and \(\mu_{\tau} = \mu \tau^{\alpha-1}\), we compute that for sufficiently large $\tau$, and $t\in(0,1)$,
            \[    
             \begin{aligned}
               \hat\mu_{\tau}(\lfloor \tau t \rfloor)
               =&\mu_{\tau}+\xi\mu_{\tau}\left( \frac1{1-a_{\tau}}\left( 1-\sum_{s=1}^{\lfloor \tau t \rfloor-1}\varphi_s^{\tau} \right)-\sum_{s=1}^{\lfloor \tau t \rfloor-1}\varphi_s^{\tau}   \right)\\
               =&\mu_{\tau}+\xi\mu_{\tau}\left( \frac1\gamma \tau^{\alpha-1}\left( 1-\sum_{s=1}^{\lfloor \tau t \rfloor-1}\varphi_s^{\tau} \right)-\sum_{s=1}^{\lfloor \tau t \rfloor-1}\varphi_s^{\tau}  \right)\\
               \sim &\mu_{\tau}+\xi\mu_{\tau}\left( \frac1\gamma \tau^{\alpha-1}\cdot\frac1{\Gamma(1-\alpha)}\cdot\frac1{\lfloor \tau t \rfloor^\alpha}-\left( 1-\frac1{\Gamma(1-\alpha)}\cdot\frac1{\lfloor \tau t \rfloor^\alpha} \right) \right)\\
               \sim &\mu_{\tau}\left( 1+\xi\left( \frac1{\gamma \Gamma(1-\alpha)}\cdot t^{-\alpha}-1+\frac1{\Gamma(1-\alpha)}\cdot\frac1{\lfloor \tau t \rfloor^\alpha} \right) \right)\\
               \le &\mu_{\tau}\left( 1-\xi+\frac{\xi}{\gamma \Gamma(1-\alpha)t^\alpha} \right)\\
               =&\mu\tau^{\alpha-1}\left( 1-\xi+\frac{\xi}{\gamma \Gamma(1-\alpha)t^\alpha} \right).
             \end{aligned}
             \]
             As a result, $\hat\mu_{\tau}(\lfloor \tau t \rfloor)\sim \tau^{\alpha-1}$.
             \item From (a), we obtain that for $t\in(0,1)$,
             \[
               \begin{aligned}
               \sum_{s=1}^{\lfloor \tau t \rfloor-1}\psi_{\lfloor \tau t \rfloor-s}^{\tau}\hat\mu_{\tau}(s)
               \sim &\sum_{s=1}^{\lfloor \tau t \rfloor-1} \psi_{\lfloor \tau t \rfloor-s}^{\tau}\mu \tau^{\alpha-1}\left( 1-\xi+\frac{\xi}{\gamma\Gamma(1-\alpha)(\frac{s}{\tau})^\alpha} \right)\\
               \le &C\mu \tau^{\alpha-1}\cdot\frac{a_{\tau}}{1-a_{\tau}}\sim \tau^{2\alpha-1},
               \end{aligned}
             \]
             where $1-\xi+\frac{\xi}{\gamma\Gamma(1-\alpha)(\frac{s}{\tau})^\alpha}$ can be bounded by a positive constant $C$.
             \item From \eqref{lambdaT+expression}, it follows that for $t\in(0,1)$,
             \begin{equation}\label{lambdaTexpression}
             \mathbb{E}[\lambda_{\lfloor \tau t \rfloor}^{\tau,+}] = \hat{\mu}_\tau(\lfloor \tau t \rfloor) + \sum_{s=1}^{\lfloor \tau t \rfloor-1} \psi_{\lfloor \tau t \rfloor-s}^\tau \hat{\mu}_\tau(s) \lesssim \tau^{2\alpha-1}.
             \end{equation}
             \item Use \eqref{lambdaT+expression}, define
             \begin{equation}\label{kappadefinition}
               \kappa_n^{\tau,+} = \frac1{1+\beta}\sum_{s=1}^{n-1}\psi_{n-s}^{\tau}(M_s^{\tau,+}-M_{s-1}^{\tau,+}+\beta M_s^{\tau,-}-\beta M_{s-1}^{\tau,-}).
             \end{equation}

             Denote 
              \[
                f^{\alpha,\gamma}(t)=\gamma t^{\alpha-1}E_{\alpha,\alpha}(-\gamma t^\alpha),
              \]
              where 
              \[
                E_{\alpha,\beta}(z)=\sum_{k=0}^\infty \frac{z^k}{\Gamma(\alpha k+\beta)}
              \]
              is the Mittag-Leffler function. Using the fact that the Laplace transform $\hat f^{\alpha,\gamma}$ of the Mittag-Leffler density function $f^{\alpha,\gamma}$ is given by
            \[
            \hat f^{\alpha,\gamma}(z)=\frac{\gamma}{\gamma+z^\alpha},
            \]
            and the proof of Lemma 5.6 in \cite{wang2024scaling}, we easily obtain that
            \[
            \frac{(1-a_\tau)}{a_\tau}\tau\psi_{\lfloor \tau\cdot \rfloor}^\tau\stackrel{\text{w}}{\longrightarrow} f^{\alpha,\gamma}\ \text{as}\ \tau\rightarrow\infty,
            \]
            where \(\stackrel{\text{w}}{\longrightarrow}\) denotes weak convergence in the sense of the distribution space \( \mathcal{D}'(\mathbb{R}) \). Hence, from \eqref{lambdaTexpression}, for $t\in[0,1]$, we compute
               \begin{align*}
                 \mathbb E[(\kappa_{\lfloor t\tau \rfloor}^{\tau,+})^2]
                 =&\frac1{(1+\beta)^2}\sum_{s=1}^{\lfloor t\tau \rfloor-1}(\psi_{\lfloor t\tau \rfloor-s}^\tau)^2\mathbb E\left[ \left((X_s^{\tau,+}-\lambda_s^{\tau,+})+\beta(X_s^{\tau,-}-\lambda_s^{\tau,-})\right)^2 \right]\\
                 \le & \frac2{(1+\beta)^2}\sum_{s=1}^{\lfloor t\tau \rfloor-1}(\psi_{\lfloor t\tau \rfloor-s}^\tau)^2\left( \mathbb E(X_s^{\tau,+}-\lambda_s^{\tau,+})^2+\beta^2\mathbb E(X_s^{\tau,-}-\lambda_s^{\tau,-})^2\right)\\
                 =&\frac2{(1+\beta)^2}\sum_{s=1}^{\lfloor t\tau \rfloor-1}(\psi_{\lfloor t\tau \rfloor-s}^\tau)^2\left( \mathbb E[\lambda_s^{\tau,+}]+\beta^2\mathbb E[\lambda_s^{\tau,-}] \right)\\
                 =&\frac{2(1+\beta^2)}{1+\beta}\sum_{s=1}^{\lfloor t\tau \rfloor-1}(\psi_{\lfloor t\tau \rfloor-s}^\tau)^2\mathbb E[\lambda_s^{\tau,+}]\\
                 \lesssim &\tau^{2\alpha-1}\sum_{s=1}^{\lfloor \tau \rfloor-1}(\psi_s^\tau)^2\\
                 \sim &\tau^{2\alpha-1}\sum_{u=1}^{\lfloor t\tau \rfloor - 1}\left( \frac{a_\tau}{(1-a_\tau)\tau}f^{\alpha,\gamma}\left( t-\frac{u}{\tau} \right) \right)^2\\
                \sim &\tau^{4\alpha-2}\sum_{u=1}^{\lfloor t\tau \rfloor - 1}\frac1\tau\left( t-\frac{u}{\tau} \right)^{2\alpha-2}\left( E_{\alpha,\alpha}\left( -\gamma\left( t-\frac{u}{\tau} \right)^\alpha \right) \right)^2\\
                \sim &\tau^{4\alpha-2}\int_0^{t-\frac{1}{\tau}} (t-u)^{2\alpha-2}\left( E_{\alpha,\alpha}\left( -\gamma\left( t-u \right)^\alpha \right) \right)^2du.
                  \end{align*}
              Noticing that the Mittag-Leffler function $E_{\alpha,\alpha}\left( -\gamma\left( t-u \right)^\alpha \right)$ has no singularities, and $\alpha\in(\frac12,1)$, the integral 
              \[
                \int_0^{t-\frac1\tau}(t-u)^{2\alpha-2}(E_{\alpha,\alpha}\left( -\gamma(t-u)^\alpha \right))^2dx=\mathcal O(1),
              \]
              hence,
              \[
                \mathbb{E}\left[ \left( \kappa_{\lfloor t\tau \rfloor}^{\tau,+} \right)^2 \right]\sim \tau^{4\alpha-2}.
              \]
             From \eqref{lambdaTexpression}, since $(\lambda_s^{\tau,+}-\kappa_s^{\tau,+})^2\sim \tau^{4\alpha-2}$ is deterministic and $\mathbb E[(\kappa_s^{\tau,+})^2]\sim \tau^{4\alpha-2}$, we obtain
             \[
               \mathbb E[(\lambda_s^{\tau,+})^2]=(\lambda_s^{\tau,+}-\kappa_s^{\tau,+})^2+2\mathbb E[(\lambda_s^{\tau,+}-\kappa_s^{\tau,+})\kappa_s^{\tau,+}]+\mathbb E[(\kappa_s^{\tau,+})^2]\sim \tau^{4\alpha-2}.
             \]
          \end{enumerate}
          As a result, since $\frac{\tau^\alpha\mu}{1-a_\tau}\sim \tau^{2\alpha}$,
          \[
            \sum_{s=0}^{\lfloor \tau \rfloor}\frac{\mathbb E\left[ \lambda_s^\tau \right]+\mathbb E\left[ (\lambda_s^\tau)^2 \right]}{\left( \frac{\tau^\alpha\mu}{1-a_\tau}\epsilon \right)^2}\sim \tau^{-1}\rightarrow 0
          \]
          as $\tau\rightarrow \infty$. This implies $\sup_{k=0,1,\cdots,\lfloor \tau^\theta \rfloor-1}\sup_{h\in[0,1/\tau^\theta]}\left| \Delta_hY_{k/\tau^\theta}^\tau \right|\rightarrow 0$ in probability as $\tau\rightarrow\infty$. This implies the first condition in Lemma \ref{xu2023} is satisfied.
        \item Set $p=2$, $a_1=0$, $b_1=2$, $\rho=2$, for $t\in(0,1]$, from \eqref{lambdaTexpression} and a fundamental inequality
        \[
          \left( \sum_{i=1}^n x_i \right)^2\le n\sum_{i=1}^n x_i^2,
        \]
        we obtain
          \begin{align*}
             \mathbb E\left[ \left| \Delta_h Y_t^{\tau,+}\right|^2 \right]
            =&\mathbb E\left[ \left( \frac{1-a_\tau}{\tau^\alpha \mu} \right)^2\left(\sum_{i=\lfloor \tau t \rfloor}^{\lfloor \tau(t+h) \rfloor}X_i^{\tau,+}\right)^2 \right]\\
            \le & \left( \frac{1-a_\tau}{\tau^\alpha \mu} \right)^2(\lfloor\tau(t+h) \rfloor-\lfloor \tau t \rfloor+1)\sum_{i=\lfloor \tau t \rfloor}^{\lfloor\tau(t+h) \rfloor}\mathbb E\left[ (X_i^{\tau,+})^2 \right].
          \end{align*}
          We can estimate the order of $\mathbb E[(X_s^{\tau,+})^2]$ for sufficiently large $\tau$ and $s\sim \tau$. Note that
          \[
            \mathbb E[(X_s^{\tau,+})^2]=\mathbb E[\lambda_s^{\tau,+}]+2\mathbb E[X_s^{\tau,+}\lambda_s^{\tau,+}]-\mathbb E[(\lambda_s^{\tau,+})^2]\sim \tau^{4\alpha-2},
          \]
          finally, 
          \begin{align*}
            &\left( \frac{1-a_\tau}{\tau^\alpha \mu} \right)^2(\lfloor\tau(t+h) \rfloor-\lfloor \tau t \rfloor+1)\sum_{i=\lfloor \tau t \rfloor}^{\lfloor\tau(t+h) \rfloor}\mathbb E\left[ (X_i^{\tau,+})^2 \right]\\
            =&\left( \frac{1-a_\tau}{\tau^\alpha \mu} \right)^2(\lfloor\tau(t+h) \rfloor-\lfloor \tau t \rfloor+1)^2\tau^{4\alpha-2}\sim h^2,
          \end{align*}
          as $\tau \rightarrow\infty$. This implies the second condition in Lemma \ref{xu2023} is satisfied.
  \end{enumerate}

  \textbf{$\mathbb C$-tightness of $\mathbf Z^\tau$ and Limit of $\mathbf Z^\tau$:} We need to show
  \[
    \langle \mathbf Z^\tau,\mathbf Z^\tau \rangle_t-\text{diag}(\bm\Lambda^\tau)_t\rightarrow 0\ \text{in probability}
  \]
  and
  \[
    [\mathbf Z^\tau,\mathbf Z^\tau]_t-\text{diag}(\mathbf Y^\tau)_t\rightarrow 0\ \text{in probability}
  \]
  as $\tau\rightarrow\infty$ for $t\in[0,1]$, which means each component of $\mathbf Z^\tau$ is $\mathbb C$-tight. The proof follows analogously to the one-dimensional case presented in Proposition 1 of \cite{wang2024scaling}, with the key difference being the extension to bivariate setting through component-wise application of the same techniques. Without loss of generality, it suffices to show the convergence in probability of two brackets of $Z^{\tau,+}$, i.e. for $t\in[0,1]$,
  \begin{equation}\label{anglebracketofz+}
    \langle Z^{\tau,+},Z^{\tau,+} \rangle_t-\Lambda_t^{\tau,+}\rightarrow 0 \quad \text{in probability},
  \end{equation}
  \begin{equation}\label{sharpbracketofz+}
    \left[ Z^{\tau,+},Z^{\tau,+} \right]_t-Y_t^{\tau,+}\rightarrow 0 \quad \text{in probability},
  \end{equation}
  as $\tau\rightarrow\infty$.
  To establish \eqref{anglebracketofz+}, we define
  \[
    U_n^{\tau,+} := \left( \sum_{s=1}^n (X_s^{\tau,+} - \lambda_s^{\tau,+}) \right)^2 - \sum_{s=1}^n \lambda_s^{\tau,+}.
  \]
  It suffices to show that $(U_n^{\tau,+})_{n\ge1}$ is a martingale. Indeed, we compute the conditional expectation:
  \begin{align*}
    \mathbb{E}\left[ U_n^{\tau,+} \mid \mathcal{F}_{n-1} \right]
    &= \mathbb{E}\left[ \left( \sum_{s=1}^n (X_s^{\tau,+} - \lambda_s^{\tau,+}) \right)^2 - \sum_{s=1}^n \lambda_s^{\tau,+} \ \bigg| \ \mathcal{F}_{n-1} \right]\\
    &= \sum_{s=1}^{n-1} \{(X_s^{\tau,+} - \lambda_s^{\tau,+})^2 - \lambda_s^{\tau,+} \}  + \mathbb E\left[ (X_n^{\tau,+}-\lambda_n^{\tau,+})^2-\lambda_n^{\tau,+}|\mathcal F_{n-1} \right]\\
    &\quad + 2 \sum_{1 \leq i < j \leq n-1} \mathbb{E}\left[ (X_i^{\tau,+} - \lambda_i^{\tau,+})(X_j^{\tau,+} - \lambda_j^{\tau,+}) \mid \mathcal{F}_{n-1} \right] \\
    &\quad + 2 \sum_{s=1}^{n-1} \mathbb{E}\left[ (X_s^{\tau,+} - \lambda_s^{\tau,+})(X_n^{\tau,+} - \lambda_n^{\tau,+}) \mid \mathcal{F}_{n-1} \right] \\
    &= U_{n-1}^{\tau,+},
  \end{align*}
  because \( \mathbb{E}[X_n^{\tau,+} - \lambda_n^{\tau,+} \mid \mathcal{F}_{n-1}] = 0 \) and the cross terms \( (X_i^{\tau,+} - \lambda_i^{\tau,+}) \) and \( (X_j^{\tau,+} - \lambda_j^{\tau,+}) \) are uncorrelated. Therefore, \( (U_n^{\tau,+})_{n\ge1} \) is indeed a martingale.

  Next, to prove \eqref{sharpbracketofz+}, it suffices to demonstrate that
  \[
    \mathbb{E}\left[ \left( \left[ Z^{\tau,+} \right]_t - Y_t^{\tau,+} \right)^2 \right] \rightarrow 0 \quad \text{for every} \ t \in [0,1] \quad \text{as} \quad \tau \rightarrow \infty.
  \]

  The left-hand side is given by
  \begin{align*}
    \left( \frac{1 - a_\tau}{\tau^\alpha \mu} \right)^2 \mathbb{E}\left[ \left( \sum_{s=1}^{\lfloor t\tau \rfloor} (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 - X_s^{\tau,+} \right)^2 \right].
  \end{align*}

  Therefore, we first analyze the asymptotic behavior of
  \[
    \mathbb{E}\left[ \left( \sum_{s=1}^n (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 - X_s^{\tau,+} \right)^2 \right].
  \]
  By direct computation,
  \begin{align*}
    \mathbb{E}\left[ \left( \sum_{s=1}^n (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 - X_s^{\tau,+} \right)^2 \right]
    &= \mathbb{E}\left[ \sum_{s=1}^n \left( (X_s^{\tau,+} - \lambda_s^{\tau,+})^4 - 2 X_s^{\tau,+} (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 + (X_s^{\tau,+})^2 \right) \right] \\
    &\quad + 2 \mathbb{E}\left[ \sum_{1 \leq i < j \leq n} \left( (X_i^{\tau,+} - \lambda_i^{\tau,+})^2 - X_i^{\tau,+} \right) \left( (X_j^{\tau,+} - \lambda_j^{\tau,+})^2 - X_j^{\tau,+} \right) \right] \\
    &= \sum_{s=1}^n \mathbb{E}\left[ (\lambda_s^{\tau,+})^3 \right],
  \end{align*}
  where we utilized the centering property of \( (X_s^{\tau,+} - \lambda_s^{\tau,+}) \) and the properties of higher-order moments.

  To analyze the asymptotic behavior of \( \mathbb{E}\left[ (\lambda_s^{\tau,+})^3 \right] \), we first decompose \( \lambda_s^{\tau,+} \) into two components:
  \[
    \lambda_s^{\tau,+} = q_s^{\tau,+} + \kappa_s^{\tau,+},
  \]
  where
  \[
    q_s^{\tau,+} = \hat\mu_\tau(s)+\sum_{u=1}^{s-1}\psi_{s-u}^\tau \hat\mu_\tau(u)
  \]
  and 
  \[
    \kappa_n^{\tau,+} = \frac1{1+\beta}\sum_{s=1}^{n-1}\psi_{n-s}^{\tau}(M_s^{\tau,+}-M_{s-1}^{\tau,+}+\beta M_s^{\tau,-}-\beta M_{s-1}^{\tau,-}).
  \]
  By direct expansions,
  \[
    \mathbb{E}\left[ (\lambda_s^{\tau,+})^3 \right]
    =\mathbb E\left[ (q_s^{\tau,+})^3+3(q_s^{\tau,+})^2\kappa_s^{\tau,+} +3q_s^{\tau,+}(\kappa_s^{\tau,+})^2 + (\kappa_s^{\tau,+})^3\right].
  \]

  Let us calculate them one by one. For all \( t \in (0,1] \), we have shown
  \[
    \mathbb E[\lambda_{\lfloor t\tau \rfloor}^{\tau,+}]
    =q_{\lfloor t\tau \rfloor}^{\tau,+} \lesssim \tau^{2\alpha-1}, 
    \mathbb{E}\left[ \left( \kappa_{\lfloor t\tau \rfloor}^{\tau,+} \right)^2 \right] \sim \tau^{4\alpha - 2}.
  \]


  For the third moment, we also use the same method to compute,
\[
    \begin{aligned}
    \mathbb{E}\left[ \left( \kappa_{\lfloor t\tau \rfloor}^{\tau,+} \right)^3 \right]
    &= \sum_{u=1}^{\lfloor t\tau \rfloor-1} \left( \psi_{\lfloor t\tau \rfloor - u}^{\tau,+} \right)^3 \mathbb{E}\left[ (X_u^{\tau,+} - \lambda_u^{\tau,+})^3 \right] \\
    &= \sum_{u=1}^{\lfloor t\tau \rfloor - 1} \left( \psi_{\lfloor t\tau \rfloor - u}^{\tau,+} \right)^3 \mathbb{E}\left[ \lambda_u^{\tau,+} \right] \\
    &\lesssim \tau^{2\alpha-1}\sum_{u=1}^{\lfloor t\tau \rfloor - 1} \left( \psi_{\lfloor t\tau \rfloor - u}^{\tau,+} \right)^3\\
    &\sim \tau^{2\alpha-1}\sum_{u=1}^{\lfloor t\tau \rfloor - 1}\left( \frac{a_\tau}{(1-a_\tau)\tau}f^{\alpha,\gamma}\left( t-\frac{u}{\tau} \right) \right)^3\\
    &\sim \tau^{5\alpha-3}\sum_{u=1}^{\lfloor t\tau \rfloor - 1}\frac1\tau\left( t-\frac{u}{\tau} \right)^{3\alpha-3}\left( E_{\alpha,\alpha}\left( -\gamma\left( t-\frac{u}{\tau} \right)^\alpha \right) \right)^3\\
    &\sim \tau^{5\alpha-3}\int_0^{t-\frac{1}{\tau}} (t-u)^{3\alpha-3}\left( E_{\alpha,\alpha}\left( -\gamma\left( t-u \right)^\alpha \right) \right)^3du.
    \end{aligned}
\]
Noticing that the Mittag-Leffler function $E_{\alpha,\alpha}\left( -\gamma\left( t-u \right)^\alpha \right)$ has no singularities, the integral
\[
  \int_0^{t-\frac{1}{T}} (t-u)^{3\alpha-3}\left( E_{\alpha,\alpha}\left( -\gamma\left( t-u \right)^\alpha \right) \right)^3du =
    \begin{cases}
        \mathcal{O}\left( \tau^{2-3\alpha} \right) & \text{if } \frac{1}{2} < \alpha < \frac{2}{3}, \\
        \mathcal{O}\left( \log \tau\right) & \text{if } \alpha = \frac{2}{3}, \\
        \mathcal{O}\left( 1 \right) & \text{if } \frac{2}{3} < \alpha < 1.
    \end{cases}
\]

Hence, 
  \[
    \mathbb{E}\left[ \left( \kappa_{\lfloor t\tau \rfloor}^{\tau,+} \right)^3 \right] =
    \begin{cases}
        \mathcal{O}\left( \tau^{2\alpha-1} \right) & \text{if } \frac{1}{2} < \alpha < \frac{2}{3}, \\
        \mathcal{O}\left( \tau^{5\alpha-3}\log \tau\right) & \text{if } \alpha = \frac{2}{3}, \\
        \mathcal{O}\left( \tau^{5\alpha-3} \right) & \text{if } \frac{2}{3} < \alpha < 1,
    \end{cases}
\]
  this implies that for sufficiently large \( \tau \),
  \begin{align*}
    \mathbb{E}\left[ (\lambda_s^{\tau,+})^3 \right]
    =\mathbb E\left[ (q_s^{\tau,+})^3+3(q_s^{\tau,+})^2\kappa_s^{\tau,+} +3q_s^{\tau,+}(\kappa_s^{\tau,+})^2 + (\kappa_s^{\tau,+})^3\right] 
    \sim \tau^{6\alpha - 3},
  \end{align*}
  where higher-order terms are dominated by \( \tau^{6\alpha - 3} \).
  Therefore,
  \[
    \left( \frac{1 - a_\tau}{\tau^\alpha \mu} \right)^2 \mathbb{E}\left[ \left( \sum_{s=1}^{\lfloor t\tau \rfloor} (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 - X_s^{\tau,+} \right)^2 \right] \sim \tau^{2\alpha - 2} \rightarrow 0,
  \]
  which proves \eqref{sharpbracketofz+}. 

  The preceding analysis for $Z^{\tau,+}$ extends symmetrically to $Z^{\tau,-}$, as $\lambda_n^{\tau,+} = \lambda_n^{\tau,-}$ implies identical asymptotic behavior for their quadratic variations. Furthermore, since $X_s^{\tau,+}$ and $X_s^{\tau,-}$ are conditionally independent Poisson random variables given $\mathcal{F}_{s-1}$ under the bivariate INAR$(\infty)$ construction, their martingale increments $X_s^{\tau,+} - \lambda_s^{\tau,+}$ and $X_s^{\tau,-} - \lambda_s^{\tau,-}$ are uncorrelated. Thus, $\langle Z^{\tau,+}, Z^{\tau,-} \rangle_t = 0$ and $[Z^{\tau,+}, Z^{\tau,-}]_t = 0$, ensuring that both the predictable and quadratic covariations of $(Z^{\tau,+}, Z^{\tau,-})$ are diagonal matrices.

  Using Theorem VI-6.26 in \cite{jacod2013limit}, we get that $[\mathbf Z, \mathbf Z]$ is the limit of $[\mathbf Z^\tau,\mathbf Z^\tau]$ and $[\mathbf Z,\mathbf Z]=\text{diag}(\mathbf Y)$. By Fatou's lemma, the expectation of $[\mathbf Z,\mathbf Z]$ is finite and therefore every component of $\mathbf Z$ is a martingale.  This completes the proof of Proposition \ref{proposition1}. 
\end{proof}

\subsection{Convergence of $Y^\tau$ and $Z^\tau$}
Let us first prove that
\[
  \sup_{t \in [0,1]} \|\bm{\Lambda}_t^\tau - \mathbf{Y}_t^\tau\|_1 \rightarrow 0 \text{ in probability}
\]
as \(\tau \rightarrow \infty\). Without loss of generality, it suffices to verify that
\[
  \sup_{t \in [0,1]} |\Lambda_t^{\tau,+} - Y_t^{\tau,+}| \rightarrow 0 \text{ in probability}
\]
as \(\tau \rightarrow \infty\).

Indeed, using \eqref{lambdaTexpression} and applying Doob's inequality to \(M^{\tau,+}\), we obtain
\begin{align*}
  \sup_{t \in [0,1]} (Y_t^{\tau,+} - \Lambda_t^{\tau,+})
  &\le C \left( \frac{1 - a_\tau}{\tau^\alpha} \right)^2 \mathbb{E} \left[ (M_{\lfloor \tau \rfloor}^{\tau,+})^2 \right] \\
  &= C \left( \frac{1 - a_\tau}{\tau^\alpha} \right)^2 \mathbb{E} \left[ \sum_{s=1}^{\lfloor \tau \rfloor} (X_s^{\tau,+} - \lambda_s^{\tau,+})^2 + 2 \sum_{1 \le i < j \le \lfloor \tau \rfloor} (X_i^{\tau,+} - \lambda_i^{\tau,+})(X_j^{\tau,+} - \lambda_j^{\tau,+}) \right] \\
  &= C \left( \frac{1 - a_\tau}{\tau^\alpha} \right)^2 \sum_{s=1}^{\lfloor \tau \rfloor} \mathbb{E} [\lambda_s^{\tau,+}] \\
  &\sim C \tau^{-2\alpha}.
\end{align*}
This implies the uniform convergence to zero in probability of \(Y^{\tau,+} - \Lambda^{\tau,+}\).

Next, noting that
\[
  \Lambda_t^{\tau,+} = \Lambda_t^{\tau,-},
\]
we obtain
\[
  \sup_{t \in [0,1]} |Y_t^{\tau,+} - Y_t^{\tau,-}| \rightarrow 0
\]
as \(\tau \rightarrow \infty\). Therefore, if a subsequence of \(Y^{\tau,+}\) converges to some \(Y\), then the corresponding subsequence of \(Y^{\tau,-}\) converges to the same \(Y\). We thus have the following proposition regarding the limit points of \(Y^{\tau,+}\) and \(Y^{\tau,-}\).

\begin{proposition}\label{prop2}
  If $(Y,Y,Z^+,Z^-)$ is a possible limit point for $(Y^{\tau,+},Y^{\tau,-},Z^{\tau,+},Z^{\tau,-})$, then $(Y_t,Z_t^+,Z_t^-)$ can be written as
  \[
    Y_t=\int_0^t\dot{Y}_sds,\ Z_t^+=\int_0^t\sqrt{\dot{Y}_s}dB_s^1,\ Z_t^-=\int_0^t\sqrt{\dot{Y}_s}dB_s^2,
  \]
  where $(B^1,B^2)$ is a bivariate Brownian motion and $\dot{Y}$ is solution of
  \begin{equation}\label{finalequation1}
    \dot{Y}_t=\xi(1-F^{\alpha,\gamma}(t))+F^{\alpha,\gamma}(t)+\sqrt{\frac{1+\beta^2}{\gamma\mu(1+\beta)^2}}\int_0^tf^{\alpha,\gamma}(t-s)\sqrt{\dot{Y}_s}dB_s,
  \end{equation}
  with
  \[
    B=\frac{B^1+\beta B^2}{\sqrt{1+\beta^2}}.
  \]
  Furthermore, for any $\epsilon>0$, $\dot{Y}$ has \holder\ regularity $\alpha-1/2-\epsilon$.
\end{proposition}

\begin{proof}
  We first show the following equality
  \begin{equation}\label{62}
    \hat\mu_\tau(n)+\sum_{s=1}^{n-1}\psi_{n-s}^\tau\hat\mu_\tau(s)=\mu_\tau+\xi\mu_\tau\frac1{1-a_\tau}+\mu_\tau(1-\xi)\sum_{s=1}^{n-1}\psi_{n-s}^\tau.
  \end{equation}
  In fact, using discrete convolution by $\varphi^\tau$ and fact that $\psi^\tau * \varphi^\tau=\psi^\tau-\varphi^\tau$, we obtain from the LHS of \eqref{62}:
  \begin{align*}
    &\sum_{s=1}^{n-1}\hat\mu_\tau(s)\varphi_{n-s}^\tau+\sum_{s=1}^{n-1}\varphi_{n-s}^\tau\sum_{u=1}^{s-1}\psi_{s-u}^\tau\hat\mu_\tau(u)\\
    =&\sum_{s=1}^{n-1}\hat\mu_\tau(s)\varphi_{n-s}^\tau+\sum_{u=1}^{n-1}\hat\mu_\tau(u)\sum_{s=1}^{n-u-1}\psi_s^\tau\varphi_{n-u-s}^\tau\\
    =&\sum_{s=1}^{n-1}\hat\mu_\tau(s)\varphi_{n-s}^\tau+\sum_{u=1}^{n-1}\left( \psi_{n-u}^\tau-\varphi_{n-u}^\tau \right)\hat\mu_\tau(u)\\
    =&\sum_{s=1}^{n-1}\psi_{n-s}^\tau\hat\mu_\tau(s).
  \end{align*}
   From RHS of \eqref{62}, we get
   \begin{align*}
     &\sum_{s=1}^{n-1}\varphi_{n-s}^\tau\left( \mu_\tau+\xi\mu_\tau\frac1{1-a_\tau} \right)+\mu_\tau(1-\xi)\sum_{s=1}^{n-1}\varphi_{n-s}^\tau\sum_{u=1}^{s-1}\psi_{s-u}^\tau\\
     =&\mu_\tau\left( 1+\xi\frac1{1-a_\tau} \right)\sum_{s=1}^{n-1}\varphi_{n-s}^\tau+\mu_\tau(1-\xi)\sum_{u=1}^{n-1}\sum_{s=1}^{n-u-1}\psi_s^\tau\varphi_{n-u-s}^\tau\\
     =&\mu_\tau\left( 1+\xi\frac1{1-a_\tau} \right)\sum_{s=1}^{n-1}\varphi_{n-s}^\tau+\mu_\tau(1-\xi)\sum_{u=1}^{n-1}\left( \psi_{n-u}^\tau-\varphi_{n-u}^\tau \right).
   \end{align*}
   Consequently, we necessarily have
   \[
     \sum_{s=1}^{n-1}\psi_{n-s}^\tau\hat\mu_\tau(s)=\mu_\tau\xi\left( \frac1{1-a_\tau}+1 \right)\sum_{s=1}^{n-1}\varphi_{n-s}^\tau+\mu_\tau(1-\xi)\sum_{s=1}^{n-1}\psi_{t-s}^\tau.
   \]
   The last equation together with \eqref{62} gives that 
   \[
     \hat\mu_\tau(n)=\mu_\tau+\xi\mu_\tau\frac1{1-a_\tau}\left( 1-\sum_{s=1}^{n-1}\varphi_{n-s}^\tau \right)-\mu_\tau\xi\sum_{s=1}^{n-1}\varphi_{n-s}^\tau.
   \]
   Recall that $\lambda_n^{\tau,+}=\lambda_n^{\tau,-}$. By directly computing, we can write
   \begin{align*}
     \lambda_n^{\tau,+}
     =&\mu_\tau+\mu_\tau\sum_{s=1}^{n-1}\psi_{n-s}^\tau+\xi \mu_\tau\left( \frac1{1-a_\tau}-\sum_{s=1}^{n-1}\psi_{n-s}^\tau \right)\\
     &+\frac1{\beta+1}\sum_{s=1}^{n-1}\psi_{n-s}^\tau\left( M_s^{\tau,+}-M_{s-1}^{\tau,+}+\beta M_s^{\tau,-}-\beta M_{s-1}^{\tau,-} \right).
   \end{align*}
   Then using Tonelli's theorem and the fact that $\sum (\alpha * \beta)=(\sum \alpha)*\beta$, we get
   \begin{align*}
     \sum_{s=1}^{n}\lambda_s^{\tau,+}
     =&\mu_\tau n+\mu_\tau\sum_{s=1}^{n-1}s\psi_{n-s}^\tau+\xi \mu_\tau\left( \frac{n}{1-a_\tau}-\sum_{s=1}^{n-1}s\psi_{n-s}^\tau \right)\\
     &+\frac1{\beta+1}\sum_{s=1}^{n-1}\psi_{n-s}^\tau\left( M_s^{\tau,+}+\beta M_s^{\tau,-} \right).
   \end{align*}
   Therefore, for $t\in[0,1]$, we have the decomposition
   \begin{equation}\label{63}
     \Lambda_t^{\tau,+}=\Lambda_t^{\tau,-}=T_1+T_2+T_3,
   \end{equation}
   with
   \begin{align*}
    &T_1=(1-a_\tau)t,\\
    &T_2=\frac{1-a_\tau}{\tau}\sum_{s=1}^{\lfloor \tau t \rfloor-1}s\psi_{\lfloor \tau t \rfloor-s}^\tau+\xi\left( t-\frac{1-a_\tau}{\tau}\sum_{s=1}^{\lfloor \tau t \rfloor-1}s\psi_{\lfloor \tau t \rfloor-s}^\tau \right),\\
    &T_3=\frac{\tau(1-a_\tau)}{\sqrt{\gamma\mu(1+\beta)^2}}\sum_{s=1}^{\lfloor \tau t \rfloor-1}\frac1{\tau}\psi_{\lfloor \tau t \rfloor-s}^\tau\left( Z_{s/\tau}^{\tau,+}+\beta Z_{s/\tau}^{\tau,-} \right).
   \end{align*}

   Recall that
\[
  \frac{(1-a_\tau)}{a_\tau}\tau\psi_{\lfloor \tau\cdot \rfloor}^\tau\rightarrow f^{\alpha,\gamma}\ \text{as}\ \tau\rightarrow\infty.
\]
Thus,
  \[
    T_2\rightarrow \int_0^tf^{\alpha,\gamma}(t-s)sds+\xi\left( t-\int_0^tf^{\alpha,\gamma}(t-s)sds \right)
  \]
  and
  \[
    T_3\rightarrow \frac1{\sqrt{\gamma\mu(1+\beta)^2}}\int_0^tf^{\alpha,\gamma}(t-s)(Z_s^++\beta Z_s^-)ds.
  \]
  Therefore, letting $\tau\rightarrow\infty$, we obtain from Proposition \ref{proposition1} that $Y$ satisfies
  \[
    Y_t=\int_0^tf^{\alpha,\gamma}(t-s)sds+\xi\left( t-\int_0^tf^{\alpha,\gamma}(t-s)sds \right)+\frac1{\sqrt{\gamma\mu(1+\beta)^2}}\int_0^tf^{\alpha,\gamma}(t-s)(Z_s^++\beta Z_s^-)ds.
  \]
  The rest of the proof follows similarly from the proof of Proposition 6.2 in \cite{el2019characteristic}. This completes the proof of Proposition \ref{prop2}.
\end{proof}

Finally, by applying Proposition 4.10 of \cite{el2018microstructural}, which establishes the equivalence between the solutions of \eqref{finalequation1} and \eqref{finalequation2}, and together with Proposition \ref{proposition1} and Proposition \ref{prop2}, we complete the proof of Theorem \ref{theorem1}. \qed 




