\section{Main results}\label{sec:3}

This section solves the  optimization problem \eqref{m1} with the concave distortion function. The situation of non-concave distortion function will be discussed in Section \ref{sec:4}. Subsection \ref{subsec:3.1} gives the solution for $\mathcal{N}=\mathcal{M}(\mu,\sigma)$, and subsection \ref{subsec:3.2} presents the solution for $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$ and depicts some figures for discussions.  

\subsection{ $\mathcal{N}=\mathcal{M}(\mu,\sigma)$}\label{subsec:3.1}

%First, we consider problems \eqref{m1} with $\mathcal{N}=\mathcal{M}(\mu,\sigma)$ where there is no limit to the distance between the desired distribution function and the reference distribution function. And for convenience, $h(u)$ will be used below to represent the quantile of the distribution function $G(u)$ and $G(u)$ is replaced by $h(u)$.

The following theorem provides the optimal distribution result of problem \eqref{m1} for $\mathcal{N}=\mathcal{M}(\mu,\sigma)$. The result extends Theorem 2 in \cite{l18} to admit the linear penalty function. 


%To rule out the trivial results, we introduce the following assumption. 

%\begin{assumption}\label{a3}Let distortion $g$, $\delta$ be given in assumption \ref{a2}. Suppose $(\gamma(u)-2\delta F^{-1})(\cdot)\not\equiv0$.\end{assumption}



\begin{theorem}\label{t1}
Let $g$ be a concave distortion function and $\mathcal{N}=\mathcal{M}(\mu,\sigma)$. Suppose \ref{a1} and \ref{a2} hold.   Then problem \eqref{m1} has a unique solution, and its optimal quantile function is
\begin{equation}\label{eq:optimal-quantile}
	G^{-1}(u)=\mu-\frac{\sigma}{\sigma_\delta}\mu_\delta+\frac{\sigma}{\sigma_\delta}(\gamma(u)+2{\delta }F^{-1} (u)),~~0<u<1,
\end{equation}
where $\mu_\delta=\mathbb{E}[\gamma(U)+2\delta F^{-1} (U)]$, $\sigma _\delta=\text{std}(\gamma(U)+2\delta F^{-1} (U))$. Furthermore, the corresponding optimal value function is
\begin{align*}
H_g (G)-\varphi({d_W^2(F,G)} )=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_{\delta}.
\end{align*}
\end{theorem}



\noindent\textbf{Proof}.  For any $G\in\mathcal{M}(\mu,\sigma)$, recalling $U\sim U(0,1)$,  one can obtain that
\begin{align}\label{eq:erg}
H_g(G)=\mathbb{E}[\gamma(U)\cdot G^{-1}(U)]&=\mathbb{E}[\gamma(U)]\mathbb{E}[G^{-1}(U)]+\text{cov}(\gamma(U),G^{-1}(U))\nonumber\\
&=\mu+\sigma\sigma_0\text{corr}(\gamma(U),G^{-1}(U)),  
\end{align}where the third equality is derived from the facts that 
$\mathbb{E}[\gamma(U)]=1$, $\mathbb{E}[G^{-1}(U)]=\mu$ and $\text{std}(G^{-1}(U))=\sigma$, respectively.  

Using equations \eqref{eq:dfg}, \eqref{f1} and  \eqref{eq:erg}, by  directly calculations, then the objective function of problem \eqref{m1} can be reduced to\begin{align*}
&H_g (G)-{\varphi({d_W^2(F,G)} )}\\
=&\mathbb{E}[\gamma(U)\cdot G^{-1}(U)]-\delta(\varepsilon_{min}+2\sigma\sigma_F(1-\text{corr}(F^{-1}(U),G^{-1}(U)))\\
=&\mu+\text{cov}(\gamma(U), G^{-1}(U))-\delta(\varepsilon_{min}+2\sigma\sigma_F)+2\delta\text{cov}( F^{-1}(U),G^{-1}(U))\\
=&\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma \text{std}(\gamma(U)+2\delta F^{-1}(U))\text{corr}(\gamma(U)+2\delta F^{-1}(U),G^{-1}(U)).
\end{align*}
From the above, one recognizes that if $\text{corr}(\gamma(U)+2\delta F^{-1}(U),G^{-1}(U))=1$, then the objective function can obtain the maximum value.  In other words, when $\gamma(U)+2\delta F^{-1}(U)$ is completely positive correlated with $G^{-1}(U)$, taking account of the first two moment constraints, then the optimal value can be obtained by choosing the distribution $G$ with quantile function 
\begin{equation*}
	G^{-1}(u)=\mu-\dfrac{\sigma}{\sigma_\delta}\mu_\delta+\dfrac{\sigma}{\sigma_\delta}(\gamma(u)+2{\delta }F^{-1} (u)),~~0<u<1,
\end{equation*}where $\mu_\delta=\mathbb{E}[\gamma(U)+2\delta F^{-1} (U)]$, $\sigma _\delta=\text{std}(\gamma(U)+2\delta F^{-1} (U))$.

Therefore, with the expression above for $G^{-1}$, the corresponding optimal value is$$H_g (G)-\varphi({d_W^2(F,G)} )=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma \sigma_{\delta}.$$The proof is complete.  \hfill$\Box$

\begin{remark}
Under Assumption \ref{a1}, it is obviously $\sigma_{\delta}=\text{std}(\gamma(U)+2\delta F^{-1}(U))>0$.  
Despite the existence of penalty functions, the proof procedure of Theorem \ref{t1} is standard.
The form of the optimal quantile function \eqref{eq:optimal-quantile} is very important for the subsequent proof.   
\end{remark}


Theorem \ref{t1} indicates that the penalty parameter $\delta$ significantly affects the value function, while structure of the optimal solution does not change much. In particular, when there is no penalty function ($\delta=0$), the result of Theorem \ref{t1} reduces to the Theorem 2 in \cite{l18}.





\begin{corollary}\label{c1}
(\cite{l18})
Suppose the Assumptions in Theorem \ref{t1} hold. When $\delta=0$, then  
the optimal quantile is $$G^{-1}(u)=\mu+\frac{\sigma}{\sigma_0}(\gamma(u)-1),~~u\in(0,1),$$ where $\sigma_0=\text{std}(\gamma(U))$, and the optimal value function is
\begin{align*}
   \mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)} H_g (G)=\mu+\sigma \sigma_0.
   %\sigma\text{std}(\gamma(U))%=\mu-\sigma\sqrt{\int_0^1(\gamma(u)-1)^2du}. 
\end{align*}
\end{corollary} 










Theorem \ref{t1} gives the quantile formulation of the optimal distribution among in $\mathcal{M}(\mu,\sigma)$.  The next proposition investigates the boundedness  of the distance between this optimal distribution and the reference distribution, which is more sharper than \eqref{eq:emin-emax} under the situation of concave distortion function. Besides, this distance is very useful when we consider the problem \eqref{m1} with $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$.

\begin{proposition}\label{pro:emax}
Let $g$ be a concave distortion function and suppose \ref{a1} and \ref{a2} hold. 
For any $\delta>0$, suppose the quantile function for distribution function $G_\delta$ defined as follows:
\begin{equation}\label{eq:optimal-quantile-g-delta}
	G^{-1}_{\delta}(u):=\mu-\dfrac{\sigma}{\sigma_\delta}\mu_\delta+\dfrac{\sigma}{\sigma_\delta}(\gamma(u)+2{\delta }F^{-1} (u)),~~0<u<1,
\end{equation}
where $\mu_\delta=\mathbb{E}[\gamma(U)+2\delta F^{-1} (U)]$, $\sigma _\delta=\text{std}(\gamma(U)+2\delta F^{-1} (U))$.  
Then $G_\delta \in\mathcal{M}(\mu,\sigma)$, and the Wasserstein distance between $G_\delta$ and the reference distribution $F$ satisfies
\begin{align}\label{eq:optimal-distance}
\varepsilon_{min}\leq d_W^2(F,G_{\delta})\leq \varepsilon_{max}, ~~\forall \delta>0,
\end{align}where $\varepsilon_{max}$ is defined in \eqref{eq: notations}.
\end{proposition}

\noindent\textbf{Proof}. For any $\delta>0$,  from the definition of quantile function for distribution $G_\delta$,  obviously,
 $G_\delta \in\mathcal{M}(\mu,\sigma)$. Next, we show that $d_W(F,G_{\delta})$ is uniformly bounded with respect to $\delta$.

 Indeed, for any given $\delta>0$, 
\begin{align*}
 {d^2_W(F,G_{\delta})}&=\int_0^1 {(F^{-1}(u)-G_{\delta}^{-1}(u))}^2\text{d}u\\
		&=(\mu_F-\mu)^2+(\sigma_F-\sigma)^2+2\sigma\sigma_F(1-\text{corr}(F^{-1}(U),G_{\delta}^{-1}(U)))\\
&=\varepsilon_{min}+2\sigma\sigma_F\Big(1-\text{corr}\big(F^{-1}(U),\gamma(U)+2{\delta }F^{-1} (U)\big)\Big).
\end{align*} 
For the term of correlation function, for all $\delta>0$, define 
\begin{align}\label{eq:fdelta}
f(\delta):=\text{corr}(F^{-1}(U),\gamma(U)+2{\delta }F^{-1} (U))
=\frac{2\delta\sigma_F^2+\sigma_0\sigma_F\rho}{\sigma_F\sqrt{\sigma_0^2+4\delta^2\sigma_F^2+4\delta\sigma_0\sigma_F\rho}}.
    \end{align}
One can verify that $f(\delta)$ is (strictly, when $\rho<1$) increasing with respect to $\delta$ on $(0,+\infty)$. Then, we can find that 
$$\lim_{\delta\rightarrow+\infty}f(\delta)=1 \text{~~and~~}\lim_{\delta\rightarrow 0}f(\delta)=\rho.$$
Therefore, we get the upper bound and lower bound, respectively. \hfill$\Box$



