\subsection{$\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$}\label{subsec:3.2}

The distance between the required distribution and the known reference distribution should not be too large. Therefore, this subsection will consider $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$ with a given penalty function.  

Firstly, applying the results of Proposition \ref{pro:emax} and Theorem \ref{t1}, we can easily get the following theorem.  

%Firstly, we introduce the following penalty function.

%\begin{assumption}\label{a3}The penalty function is $\varphi(x)=\delta x \mathbf{1}_{\left\{x\le\varepsilon\right\}}+\infty \mathbf{1}_{\left\{ x>\varepsilon\right\}}$, $x\geq0$  where $\varepsilon>0$ and $\delta>0$ are the given constants.\end{assumption}

%\begin{remark}\label{rem:zhuanhuan}It is noting that our original problem \begin{equation}\label{eq:zhuanhuan}\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\delta d^2_W(F,G) = \mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)}\ H_g (G)-\varphi(d^2_W(F,G)),\end{equation}where $\varphi$, $\delta$ and $\varepsilon$ are both defined in assumption \ref{a3}. \end{remark}

%From Remark \ref{rem:zhuanhuan},  one can find that the problem \eqref{m1} restriction on $\mathcal{N}=\mathcal{M}_\varepsilon(\mu,\sigma)$ with the linear penalty function can be reformulated by considering on $\mathcal{N}=\mathcal{M}(\mu,\sigma)$ with the penalty function in \ref{a4}.









\begin{theorem}\label{tu}
    Let $g$ be a concave distortion function and $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$. Suppose  \ref{a1} and \ref{a2}  hold.  For the problem \eqref{m1}, then we have the following situations.
\begin{itemize}	
\item[(i)] Case of $\varepsilon<\varepsilon_{min}$.  In this case, $\mathcal{M}_{\varepsilon}(\mu,\sigma)=\emptyset$ and the problem is meaningless.
\item[(ii)] Case of $\varepsilon= \varepsilon_{min}$. Then  $\mathcal{M}_{\varepsilon}(\mu,\sigma)$ contains only one element, and the optimal quantile expression of $G$ is
\begin{equation*}
	G^{-1}(u)=\mu-\dfrac{\sigma}{\sigma_F}\mu_F +\dfrac{\sigma}{\sigma_F}F^{-1} (u), ~~0<u<1.
\end{equation*}
The corresponding optimal value function is
\begin{equation*}
	H_g (G)-{\varphi({d^2_W(F,G)} )}=\mu+\sigma\sigma_0\rho-{\delta }\varepsilon_{min}.
\end{equation*}
%where $C_{\gamma,F}=\text{cov}(F^{-1}(U),\gamma(U))$.
%\item[(iii)] %Case of$\varepsilon=\varepsilon_{max}$.Then  $\mathcal{M}_{\varepsilon}(\mu,\sigma)$ contains only one element, and the optimal quantile expression of $G$ is\begin{equation*}G^{-1}(u)=\mu+\dfrac{\sigma}{\sigma_F}\mu_F-\dfrac{\sigma}{\sigma_F}F^{-1} (u), ~~0<u<1.\end{equation*}The corresponding optimal value function is\begin{equation*}H_g (G)+{\varphi({d_W(F,G)}^2 )}=\mu-\frac{\sigma}{\sigma_F}C_{\gamma,F}+{\delta }\varepsilon_{max}.\end{equation*}
\item[(iii)] Case of $\varepsilon\geq\varepsilon_{max}$.  The problem reduces to Theorem \ref{t1}. 
\end{itemize}
\end{theorem}



\noindent\textbf{Proof}.  By \eqref{eq:emin-emax}, we know that the results of case (i) is obvious. 

For the case (ii), 
when $\varepsilon = \varepsilon_{min}$, then $\mathcal{M}_{\varepsilon}(\mu ,\sigma)$ contains only one element $G$ with $\text{corr}(F^{-1}(U),G^{-1}(U))=1$.  Taking account of the moment constraints, $G$ should have the quantile expression as follows:
\begin{equation*}
	G^{-1}(u)=\mu-\dfrac{\sigma}{\sigma_F}\mu_F+\dfrac{\sigma}{\sigma_F}F^{-1} (u),~~0<u<1.
\end{equation*}
The optimal value is
\begin{align*}
		H_g (G)-{\varphi({d_W^2(F,G)} )}&=\mathbb{E}[\gamma(U)\cdot G^{-1}(U)]-\delta\varepsilon_{min}\\
		&=\mu+\frac{\sigma}{\sigma_F}(  \int_0^1 \gamma(u)F^{-1} (u){\rm d}u-\mu_F )-{\delta }\varepsilon_{min}\\
 % &=\mu+\frac{\sigma}{\sigma_F}C_{\gamma,F}-{\delta }\varepsilon_{min}\\
   &=\mu+\sigma\sigma_0\rho-{\delta }\varepsilon_{min}.
\end{align*}

For the case (iii), by Proposition 
\ref{pro:emax}, we find that the optimal solution $G$, defined by \eqref{eq:optimal-quantile} in Theorem \ref{t1}, lies in  $\mathcal{M}_\varepsilon(\mu,\sigma)$ since $\varepsilon\geq\varepsilon_{max}$.
Hence, when $\varepsilon\geq\varepsilon_{max}$, the following two problems are equivalent: $$\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\delta {d_W^2(F,G)} = \mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)}\ H_g (G)-\delta d_W^2(F,G).$$Therefore, 
the problem reduces to Theorem \ref{t1}.  The proof is complete.
\hfill$\Box$



The following technical lemma provides the existence of a distribution with a specific structure in $\mathcal{M}_\varepsilon(\mu,\sigma)$ for the given Wasserstein distance. It is derived from the further discussion and analysis of Proposition \ref{pro:emax}, which will play a key role for Theorem \ref{tu-2}. 



\begin{lemma}\label{l1}  Let $g$ be a concave distortion function. 
Suppose \ref{a1} and \ref{a2} hold and $\rho<1$.  For any $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, then there exists a unique $\delta^*=\delta^*(\varepsilon)>0$ 
and $G_{\delta^*}\in \mathcal{M}_{\varepsilon}(\mu,\sigma)$ with $d^2_W(F, G_{\delta^*})=\varepsilon$, and its quantile function in the following expression
$$G^{-1}_{\delta^*}(u):=\mu-\dfrac{\sigma}{\sigma_{\delta^*}}\mu_{\delta^*}+\dfrac{\sigma}{\sigma_{\delta^*}}(\gamma(u)+2{{\delta^*} }F^{-1} (u)),~~u\in(0,1),$$
where $\mu_{\delta^*}=\mathbb{E}[\gamma(U)+2\delta^* F^{-1} (U)]$, $\sigma _{\delta^*}=\text{std}(\gamma(U)+2\delta^* F^{-1} (U))$.
To be more specifically,  
\begin{equation}\label{eq:delta*}
\delta^*=-\frac{\sigma_0\rho}{2\sigma_F}+\frac{\sigma_0(\varepsilon_{min}+2\sigma\sigma_F-\varepsilon)\sqrt{1-\rho^2}}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.
\end{equation}
%where$\varepsilon_{mid}:=\varepsilon_{min}+2\sigma\sigma_F$.
\end{lemma}

\noindent\textbf{Proof}.
 For any $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, for $\delta>0$ and $G_\delta$ defined by \eqref{eq:optimal-quantile-g-delta}, we will choose $\delta^*$ by
setting 
$$d^2_W(F, G_{\delta^*})=\varepsilon.$$

By
virtue of the definition of function $f(\cdot)$ by \eqref{eq:fdelta} in Proposition \ref{pro:emax} and the fact that $f(\delta)$ is strictly increasing with respect to $\delta$ on $(0,+\infty)$. Therefore, there exists a unique $\delta>0$ such that 
\begin{align}\label{eq:fdelta-solution}
f(\delta)=1-\frac{\varepsilon-\varepsilon_{min}}{2\sigma\sigma_F}=\frac{2\delta\sigma_F^2+\sigma_0\sigma_F\rho}{\sigma_F\sqrt{\sigma_0^2+4\delta^2\sigma_F^2+4\delta\sigma_0\sigma_F\rho}}.
\end{align}
%Noting that $f(\cdot)$ is strictly increasing on $(0,+\infty)$, and 
%$$\max_{\delta>0}f(\delta)=\max_{\delta>\frac{\sigma_0\rho}{2\sigma_F}}f(\delta)=1\text{~~and~~}\min_{\delta>0}f(\delta)=\min_{0<\delta<\frac{\sigma_0\rho}{2\sigma_F}}f(\delta)=\rho.$$
%When $\varepsilon\in(\varepsilon_{min},\varepsilon_{mid}]$,  then the fact $f(\delta^*)\geq0$ requires  $\delta^*\geq \frac{\sigma_0\rho}{2\sigma_F}$; while when $\varepsilon\in(\varepsilon_{mid},\varepsilon_{max})$, then $f(\delta^*)<0$ leads $\delta^*<\frac{\sigma_0\rho}{2\sigma_F}$.
%These facts rule out another solution for this quadratic equation. 
By direct calculations, one can solve  $\varepsilon+2\sigma\sigma_F f(\delta)=\varepsilon_{min}+2\sigma\sigma_F$
 and get 
$$\delta^*=\delta^*(\varepsilon)=-\frac{\sigma_0\rho}{2\sigma_F}+\frac{\sigma_0\sqrt{1-\rho^2}(\varepsilon_{min}+2\sigma\sigma_F-\varepsilon)}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.$$It completes the proof. 
\hfill$\Box$




%We can solve it by solving the quadratic equation with one variable, i.e., \begin{align*}  (2\delta\sigma_F^2-\sigma_0\sigma_F\rho)^2=\frac{\sigma_0^2(1-\rho^2)(\varepsilon_{mid}-\varepsilon)^2}{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}.\end{align*}It two solutions are as follows: \begin{align*}\delta^*=\frac{\sigma_0\rho}{2\sigma_F}\pm\frac{\sigma_0\sqrt{1-\rho^2}(\varepsilon_{mid}-\varepsilon)}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.\end{align*}



%Therefore, we have if $\varepsilon\in(\varepsilon_{min},\varepsilon_{mid}]$, then $\delta^*=\delta=\frac{\sigma_0\rho}{2\sigma_F}+\frac{\sigma_0\sqrt{1-\rho^2}(\varepsilon_{mid}-\varepsilon)}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.$ If $\varepsilon\in(\varepsilon_{mid},\varepsilon_{max})$, then $\delta^*=\delta=\frac{\sigma_0\rho}{2\sigma_F}-\frac{\sigma_0\sqrt{1-\rho^2}(\varepsilon-\varepsilon_{mid})}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.$

 %In summary, we have when $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$,$G^{-1}$ can reach the optimal value, $\delta$ has the optimal solution



\begin{remark}\label{rem:3.2}
When $\rho=1$, Lemma \ref{l1} does not hold any more. In this situation, noting that $f(\cdot)$
is defined in \eqref{eq:fdelta}, one can derive that   
$d^2_W(F, G_{\delta})=\varepsilon_{min}$ for all $\delta\geq0$. For $\rho=1$, then the solution of  problem \eqref{m1} is trivial (the same to case (ii) of Theorem \ref{tu}) even for $\varepsilon>\varepsilon_{min}$. Thus, we only consider the situation of $\rho<1$ in the following Theorem \ref{tu-2}. 
\end{remark}



Now we will give the main theorem of this subsection. 



\begin{theorem}\label{tu-2}
    Let $g$ be a concave distortion function, and $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$, and let \ref{a1} and \ref{a2} hold and $\rho<1$.  Suppose $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, and 
$\delta^*>0$ determined by \eqref{eq:delta*}. Then for the problem \eqref{m1}, we have that
    \begin{itemize}
    \item [(i)] When $\delta\ge\delta^*$, problem  \eqref{m1} has a  unique optimal solution and its quantile function is
\begin{equation}\label{eq:hb-th3.3}
G^{-1}_\delta(u)=\mu-\dfrac{\sigma}{\sigma_\delta}\mu_\delta+\dfrac{\sigma}{\sigma_\delta}(\gamma(u)+2{\delta }F^{-1} (u)),~~~0<u<1,
\end{equation}where $\mu_\delta=\mathbb{E}[\gamma(U)+2\delta F^{-1} (U)]$, $\sigma_\delta=\text{std}(\gamma(U)+2\delta F^{-1} (U))$. 
Its corresponding optimal value is
\begin{align*}
H_g (G_\delta)-{\varphi({d_W^2(F,G_\delta)} )}=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_{\delta}.
\end{align*}
  %\mu+\sigma(2\delta\sigma_F-\sigma_0) \text{corr}(\gamma(U),\gamma(U)-2\delta F^{-1} (U))+{\delta }\varepsilon_{mid}.}


\item[(ii)] When $\delta<\delta^*$, problem  \eqref{m1} has a  unique optimal solution and its quantile function is
\begin{equation}
G^{-1}_{\delta^*}(u)=\mu-\dfrac{\sigma}{\sigma_{\delta^*}}\mu_{\delta^*}+\dfrac{\sigma}{\sigma_{\delta^*}}(\gamma(u)+2{\delta^*}F^{-1} (u)),~~~0<u<1.
\end{equation}
  Its corresponding optimal value is
\begin{align*}
		H_g (G_{\delta^*})-\varphi(d_W^2(F,G_{\delta^*}))=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_\delta\text{corr}(\gamma+2\delta F^{-1},G^{-1}_{\delta^*}),
\end{align*}
where $\text{corr}(\gamma+2\delta F^{-1},G^{-1}_{{\delta^*}})=\frac{\sigma_0^2+2\delta\sigma_0\sigma_F\rho+2{\delta^*}\sigma_F\sigma_0\rho+4\delta{\delta^*}\sigma_F\sigma_F}{\sigma_\delta\sigma_{\delta^*}}$.

    \end{itemize}

\end{theorem}


\noindent\textbf{Proof}.
 For each $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, by Lemma \ref{l1}, we can find
$\delta^*=\delta^*(\varepsilon)$ determined by \eqref{eq:delta*} with $d_W(F,G_{\delta^*})=\varepsilon$. 
Moreover, one can derive that  
\begin{align}\label{eq:delta daoshu}\frac{\mathrm{d}\delta^*(\varepsilon)}{\mathrm{d}\varepsilon}=\frac{\sigma_0\sqrt{1-\rho^2}\Big(-(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})-(\varepsilon_{min}+2\sigma\sigma_F-\varepsilon)^2\Big)}{2\sigma_F[(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})]^{\frac{3}{2}}}<0
\end{align}on $(\varepsilon_{min},\varepsilon_{max})$.  It implies that $\delta^*(\cdot)$ is strictly decreasing, then 
 when the penalty function coefficient $\delta$ is fixed, there exists a similarly optimal distance $\varepsilon^*=\varepsilon^*(\delta)$.  

%then we can find that   for any 
%$\delta^*$ indicates that the distance is $ \varepsilon$ corresponds to the optimal penalty function coefficient (conversely, when the penalty function coefficient $\delta$ is fixed, there exists a similar optimal distance $\varepsilon^*=\varepsilon^*(\delta)$).  This means that 



Case (i):   For any 
$\delta\geq \delta^*$, choosing $G^{-1}_\delta$ by \eqref{eq:hb-th3.3}, it implies that 
\begin{align}\label{eq:dw<d}
d_W^2(F, G_\delta)=\varepsilon^*\leq\varepsilon=d_W^2(F, G_{\delta^*}).
\end{align}From Theorem \ref{t1}, we know that 
$$G_\delta=\text{arg}\mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)}\ H_g (G)-\varphi({d_W^2(F,G)}).$$
By virtue of the fact that $d_W^2(F, G_\delta)=\varepsilon^*\leq\varepsilon$, then we have that 
$$G_\delta=\text{arg}\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\varphi({d_W^2(F,G)}).$$ Therefore, this case is exactly the same as Theorem \ref{t1}.  

Case (ii): When $\delta<\delta^*$,  from the proof procedure and analysis in case (i),  we know that in this case the optimal distribution  can not be $G_\delta$ in \eqref{eq:hb-th3.3} any more, since 
$$d_W^2(F,G_\delta)=\varepsilon^*(\delta)>\varepsilon=d_W^2(F,G_{\delta^*}),$$resulting in  $G_\delta\notin\mathcal{M}_{\varepsilon}(\mu,\sigma)$.

When $\delta<\delta^*$, we claim that 
\begin{align}\label{eq:g* for delta<delta*}
G_{\delta^*}=\text{arg}\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\delta {d_W^2(F,G)}.
\end{align}

Step 1: We will show that for any given distance less than $\varepsilon$, the form of \eqref{eq:hb-th3.3} is optimal. 

Indeed, for any given $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, then by Lemma \ref{l1}, there exists a unique $\bar{\delta}^*=\delta^*(\bar{\varepsilon})\geq\delta^*=\delta^*(\varepsilon)$ and $d_W^2(F, G_{\bar{\delta}^*})=\bar\varepsilon$. On the other hand, for any $G\in\mathcal{M}_\varepsilon (\mu,\sigma)$ such that  $d_W(F,G)=\sqrt{\overline{\varepsilon}}$, we obviously have that 
\begin{equation*}	d_W(F,G)=d_W(F,G_{\bar{\delta}^*})\quad\Leftrightarrow\quad \mathbb{E}[F^{-1}\cdot G^{-1}] = \mathbb{E}[F^{-1}\cdot G^{-1}_{\bar{\delta}^*}].
\end{equation*}
From the Cauchy-Schwarz inequality, it implies that $$\mathbb{E}[\gamma\cdot G^{-1}]\le \mathbb{E}[\gamma\cdot G^{-1}_{\bar{\delta}^*}].$$
Therefore,  $G_{\bar{\delta}^*}$ makes the objective function greater than $G$ for the same distance, that is, for any $G\in\mathcal{M}_\varepsilon (\mu,\sigma)$ with  $d_W(F,G)=\sqrt{\overline{\varepsilon}}$, then one has
\begin{align*}%\label{eq:fix distance}
   H_g (G)-\delta d_W^2(F,G)\le H_g (G_{\bar{\delta}^*})-{\delta {d_W^2(F,G_{\bar{\delta}^*})} }. 
\end{align*}
In other words, for any $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, we have that
$$G_{\bar{\delta}^*}=\text{arg}\sup_{G\in\mathcal{M}_\varepsilon (\mu,\sigma)\atop d_W(F,G)=\sqrt{\overline\varepsilon}}H_g (G)-\delta{d_W^2(F,G)}. $$



Step 2: We show that for any $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, $G_{\delta^*}$ is more optimized than $G_{\bar{\delta}^*}$, i.e., \eqref{eq:g* for delta<delta*} holds. Here, $\bar{\delta}^*=\delta^*(\overline\varepsilon)$ and $\delta^*=\delta^*(\varepsilon)$
are determined by \eqref{eq:delta*}, respectively. 

By the one-to-one  corresponding relationship between $\overline\varepsilon$ and $\bar\delta^*$, then showing \eqref{eq:g* for delta<delta*} is equivalent to verify the following fact
 \begin{align}\label{eq:Gstar314-1}
G_{\delta^*}=\text{arg}\mathop{\sup}_{G_{\bar{\delta}^*}\in \mathcal{M}_\varepsilon(\mu,\sigma)\atop \bar{\delta}^*\ge\delta^*>\delta}\quad H_g (G_{\bar{\delta}^*})-\delta{d_W^2(F,G_{\bar{\delta}^*})}.
  \end{align}

Specifically,  for any $\bar{\delta}^*\ge \delta^*> \delta$, we can transform the form of the objective function
\begin{align}\label{Hdelta}
   H_g (G_{\bar{\delta}^*})-\delta d_W^2(F,G_{\bar{\delta}^*})=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+h(\bar{\delta}^*), 
\end{align}where 
\begin{align}\label{hdelta}
h(\bar{\delta}^*)&:=\text{cov}(\gamma+2\delta F^{-1},G^{-1}_{\bar{\delta}^*})\nonumber\\
&=cov(\gamma+2\bar{\delta}^* F^{-1},G^{-1}_{\bar{\delta}^*})+2(\delta-\bar{\delta}^*)\text{cov}(F^{-1},G^{-1}_{\bar{\delta}^*})\nonumber\\
&=\sigma\sigma_{\bar{\delta}^*}+2\frac{(\delta-\bar{\delta}^*)\sigma}{\sigma_{\bar{\delta}^*}}(2\bar{\delta}^*\sigma_F^2+\sigma_0\sigma_F\rho).
\end{align}Here $\sigma_{\bar{\delta}^*}=\sqrt{\sigma_0^2+4(\bar{\delta}^*)^2\sigma_F^2+4\bar{\delta}^*\sigma_0\sigma_F\rho}$. 
The last equality is from the fact that  $\text{corr}(\gamma+2\bar{\delta}^* F^{-1},G^{-1}_{\bar{\delta}^*})=1$ and the formulation of $G^{-1}_{\bar{\delta}^*}$.




%\begin{align}\label{hdelta}h(\bar{\delta}^*):&=H_g (G_{\bar{\delta}^*})-\delta d_W^2(F,G_{\bar{\delta}^*}) \nonumber\\&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\text{cov}(\gamma+2\delta F^{-1},G^{-1}_{\bar{\delta}^*})\nonumber\\&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+cov(\gamma+2\bar{\delta}^* F^{-1},G^{-1}_{\bar{\delta}^*})+2(\delta-\bar{\delta}^*)\text{cov}(F^{-1},G^{-1}_{\bar{\delta}^*})\\&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\text{std}(\gamma+2\bar{\delta}^* F^{-1})+2(\delta-\bar{\delta}^*)\text{cov}(F^{-1},G^{-1}_{\bar{\delta}^*})\nonumber\\&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_{\bar{\delta}^*}+2\frac{\sigma(\delta-\bar{\delta}^*)}{\sigma_{\bar{\delta}^*}}(2\bar{\delta}^*\sigma_F^2+\sigma_0\sigma_F\rho),\nonumber\end{align}where $\sigma_{\bar{\delta}^*}=\sqrt{\sigma_0^2+4(\bar{\delta}^*)^2\sigma_F^2+4\bar{\delta}^*\sigma_0\sigma_F\rho}$ and the last equality is from the fact that $\text{corr}(\gamma+2\bar{\delta}^* F^{-1},G^{-1}_{\bar{\delta}^*})=1$. 

%\red{to be revised.}

By directly calculations, one can derive that
\begin{align*}   \frac{\mathrm{d}h(\bar{\delta}^*)}{\mathrm{d}\bar{\delta}^*}=4\sigma(\delta-\bar{\delta}^*)\frac{\sigma_0^2\sigma_F^2(1-\rho^2)}{\sigma_{\bar{\delta}^*}^3}<0.
\end{align*}
It implies that the objective function is monotonically decreasing with respect to $\bar{\delta}^*$. 

Hence, for any $ \bar{\delta}^*\ge\delta^*>\delta$ and
$G_{\bar{\delta}^*}\in \mathcal{M}_\varepsilon(\mu,\sigma)$, we have that 
$$ H_g (G_{\bar{\delta}^*})-{\delta d_W^2(F,G_{\bar{\delta}^*})} \le H_g (G_{\delta^*})-\delta{d_W^2(F,G_{\delta^*})}.$$In other words,  \eqref{eq:Gstar314-1} holds. 

Furthermore, we can obtain the optimal value of the objective function at $G_{\delta^*}$. 
\begin{align*}
		&~~~H_g (G_{\delta^*})-{\delta({d_W^2(F,G_{\delta^*})} )}\\
&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\text{cov}(\gamma+2\delta F^{-1},G^{-1}_{{\delta^*}})\\
&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\frac{\sigma}{\sigma_{\delta^*}}\text{cov}(\gamma+2\delta F^{-1},\gamma+2{\delta^*} F^{-1})\\
%&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_\delta\text{corr}(\gamma+2\delta F^{-1},\gamma+2{\delta^*} F^{-1})\\
&=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\frac{\sigma}{\sigma_{\delta^*}}(\sigma_0^2+2(\delta+\delta^*)\sigma_0\sigma_F\rho+4\delta{\delta^*}\sigma_F^2).
\end{align*}By carefully verifications, we can also get 
$$\text{corr}(\gamma+2\delta F^{-1},G^{-1}_{{\delta^*}})=\frac{\sigma_0^2+2(\delta+\delta^*)\sigma_0\sigma_F\rho+4\delta{\delta^*}\sigma_F^2}{\sigma_\delta\sigma_{\delta^*}}<1.$$ 
%\begin{align*}[\text{corr}(\gamma+2\delta F^{-1},G^{-1}_{{\delta^*}})]^2=\frac{\Delta+8\delta\delta^*\sigma_0^2\sigma_F^2+4(\delta+\delta^*)^2\sigma_0^2\sigma_F^2\rho^2}{\Delta+4(\delta^2+{\delta^*}^2)\sigma_0^2\sigma_F^2+16\delta\delta^*\sigma_0^2\sigma_F^2\rho^2}<1\end{align*}where $\Delta=\sigma_0^4+4(\delta+\delta^*)\sigma_0^3\sigma_F\rho+16\delta\delta^*(\delta+\delta^*)\sigma_0\sigma_F^3\rho+16\delta^2{\delta^*}^2\sigma_F^4$,the equality is from the fact that $\delta^2+{\delta^*}^2>2\delta\delta^*,\delta<\delta^*$.
The proof is complete. \hfill$\Box$





The results of Theorem \ref{tu-2} are attractive and fascinating. It indicates that the agent makes a \textit{trade-off} between the distortion risk measure and the penalty term, depending on the Wasserstein distance $\varepsilon$ and the penalty parameter $\delta$. This feature is the key ingredient between our model and the model of \cite{bpv24}.  

More precisely, when the penalty parameter $\delta$ is large enough with $\delta>\delta^*$ or the penalty term is dominant, 
then the agent chooses the optimal distribution $G_{\delta}$ such that $$d_W^2(F,G_\delta)<\varepsilon~~~~\text{and}~~~\text{corr}(\gamma+2\delta F^{-1}, G^{-1}_{\delta})=1.$$ In contrast, when the penalty parameter $\delta$  is strictly less than $\delta^*$, then the agent selects the optimal distribution $G_{\delta^*}$ such that $$d_W^2(F,G_{\delta^*})=\varepsilon ~~~~\text{and}~~~ \text{corr}(\gamma+2\delta F^{-1}, G^{-1}_{\delta^*})<1.$$ 

\begin{remark}
When $\delta=0$, then the result of Theorem \ref{tu-2} reduces to Theorem 3.1 in \cite{bpv24}. Theorem \ref{tu-2} shows that the relationship between the penalty parameter and the Wasserstein distance plays a key role in determining the optimal (quantile) distribution. 

Our analysis reveals that the optimal control strategy proposed in \cite{bpv24} ceases to be admissible when the penalty parameter $\delta$ falls below a critical threshold $\delta^*$, particularly when the penalty term is incorporated into the objective functional. This result is exciting, and it also illustrates the non-trivial nature of the study of results with penalty term.
\end{remark} 



