\section{The general case}\label{sec:4}


In the previous section,  we only consider the cases where the distortion function is concave.
Motivated by \cite{bpv24},  this section will consider the general distortion function $g$, which is no longer a concave function. The isotonic projection technique also works well when the penalty function appears in the objective function. The readers can also refer to \cite{pw24}, where an envelope method is used to solve the non-concave case.

\subsection{General distortion function case: $\mathcal{N}=\mathcal{M}(\mu,\sigma)$}

Define the space of square-integrable, non-decreasing, and left-continuous functions on $(0,1)$ as follows: 
%Denote the following two function spaces on $(0,1)$ as follows: $$\mathcal{Z}=\left\lbrace z:(0,1)\rightarrow \mathbb{R}~\big|~~\int_0^1z^2(u)\text{d}u<+\infty\right\rbrace,$$
\begin{equation*}
	\mathcal{R}=\left\lbrace {r:(0,1)\to \mathbb{R}~\big|~\int_0^1 r^2(u) \text{d}u<+\infty, ~r\text{~non-decreasing and left-continuous}}\right\rbrace.
\end{equation*}

When $g$ is not concave, then the term $\gamma+2\delta F^{-1}$ is not necessarily increasing, and thereby $G^{-1}$ defined in \eqref{eq:optimal-quantile} maybe not a quantile function any more.   The following definition of isotonic projection can solve this problem.  The readers can refer to Appendix A in \cite{bpv24} for more details and properties of isotonic projections. 

\begin{definition}(Isotonic projection) For $\delta\geq0$, define $\hat{r}_\delta$ as $\gamma+2\delta F^{-1}$ to an isotonic projection on a square-integrable, non-increasing, left-continuous function space on $(0,1)$, i.e
\begin{equation*}
\hat{r}_\delta=\text{arg} \mathop{\min}_{r\in\mathcal{R}}||\gamma+2\delta F^{-1}-r||^2,
\end{equation*}
where $||\cdot||$ denotes the norm on the $L^2$ space.
\end{definition}









\begin{theorem}\label{t41}
Let $g$ be a distortion function and $\mathcal{N}=\mathcal{M}(\mu,\sigma)$. Suppose \ref{a1} and \ref{a2} hold and $\hat{\sigma}_0=\text{std}(\hat{r}_0(U))>0$.  Then problem \eqref{m1} has a unique solution, and its optimal quantile function is
\begin{equation}\label{ep}
	\hat{G}_\delta^{-1}(u)=\mu-\frac{\sigma}{\hat{\sigma}_\delta}\hat{\mu}_\delta+\frac{\sigma}{\hat{\sigma}_\delta}\hat{r}_\delta(u),~~ 0<u<1,
\end{equation}
where $ \hat{\mu}_\delta=\mathbb{E}[\hat{r}_\delta(U)]$. Furthermore, the corresponding optimal value function is
\begin{align*}
H_g (\hat{G}_\delta)-\varphi({d_W^2(F,\hat{G}_\delta)} )=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\hat{\sigma}_\delta.
\end{align*}
\end{theorem}



\noindent\textbf{Proof}.  For any $G\in\mathcal{M}(\mu,\sigma)$, by  directly calculations, then the objective function of problem \eqref{m1} can be reduced to 
\begin{align}\label{eg}
H_g (G)-\varphi({d_W^2(F,G)} )
=\mathbb{E}[(\gamma+2\delta F^{-1}(U))\cdot {G}^{-1}(U)]-\delta(\mu_F^2+\mu^2+\sigma_F^2+\sigma^2).
\end{align}


Firstly, it is obvious that $\hat{G}_\delta\in \mathcal{M}(\mu,\sigma)$,  where $\hat{G}_\delta$ is defined by \eqref{ep}. Then by  Lemma B.4 of \cite{bpv24}, we know that 
\begin{align}\label{eq:hatg}
		\mathbb{E}[(\gamma(U)+2\delta F^{-1}(U))\cdot \hat{G}_\delta^{-1}(U)] \ge \mathbb{E}[(\gamma(U)+2\delta F^{-1}(U))\cdot {G}^{-1}(U)], ~~\forall G\in \mathcal{M}(\mu,\sigma).
\end{align}Coming back to \eqref{eg}, one recognizes that $\hat{G}_\delta^{-1}$ is the optimal quantile function. 


Noting that $\hat{\sigma}_0>0$, we can easily get  $\hat{\sigma}_\delta>0$ for all $\delta\geq0$.
Furthermore, the corresponding optimal value is
\begin{align*}
		&H_g (\hat{G}_{\delta})-{\varphi({d_W^2(F,\hat{G}_{\delta})} )}\\
		=&\mathbb{E}[\gamma(U)\cdot\hat{G}^{-1}_{\delta}(U)]-\delta\big(\varepsilon_{min}+2\sigma\sigma_F-2\sigma\sigma_F\text{corr}(F^{-1}(U),\hat{G}^{-1}_{\delta}(U))\big)\\
		%&=\mu+\frac{\sigma}{\hat{\sigma}_{{\delta}}}( \int_0^1 \gamma(u)\hat{r}_\delta(u){\rm d}u -\hat{\mu}_{{\delta}} )-{\delta }(\varepsilon_{min}+2\sigma\sigma_F-2cov(F^{-1},\hat{G}^{-1}_{\delta}) )\\		
        =&\mu+\sigma \sigma_0\text{corr}(\gamma(U),\hat{r}_\delta(U))-{\delta }(\varepsilon_{min}+2\sigma\sigma_F-2\frac{\sigma}{\hat{\sigma}_{{\delta}}}\text{cov}(F^{-1}(U),\hat{r}_\delta(U))).\\=&\mu+\sigma\sigma_\delta \text{corr}(\gamma(U)+2\delta F^{-1}(U),\hat{r}_\delta(U))-{\delta }(\varepsilon_{min}+2\sigma\sigma_F).
\end{align*}
By the basic properties of the isotonic projection (see Proposition A.3, \cite{bpv24}), we have  $\mathbb{E}[\hat{r}_\delta(U)]=\mathbb{E}[\gamma(U)+2\delta F^{-1}(U)]=1+2\delta\mu_F$ and $\mathbb{E}[(\hat{r}_\delta(U))^2]=\mathbb{E}[(\gamma(U)+2\delta F^{-1}(U))\hat{r}_\delta(U)]$. Hence, it implies that
\begin{align*}
		\text{corr}(\gamma(U)+2\delta F^{-1}(U),\hat{r}_\delta(U))=\frac{\text{cov}(\gamma(U)+2\delta F^{-1}(U),\hat{r}_\delta(U))}{\sigma_\delta\hat{\sigma}_{{\delta}}}%=\frac{E[(\hat{r}_\delta(U))^2]-\hat{\mu}_{\delta}^2}{\sigma_\delta\hat{\sigma}_{{\delta}}}
=\frac{\hat{\sigma}_{{\delta}}}{\sigma_\delta}.
\end{align*}
Therefore, the optimal value for $\hat{G}^{-1}_{\delta}$ is
\begin{align*}
		H_g (\hat{G}_{\delta})-{\varphi({d^2_W(F,\hat{G}_{\delta})} )}=\mu+\sigma{\hat{\sigma}_{\delta}}-{\delta }(\varepsilon_{min}+2\sigma\sigma_F).
\end{align*}The proof is complete.  \hfill$\Box$

Theorem \ref{t41} is a general characterization of the optimal quantile under the penalty term situation. It is a natural generalization of Theorem 2 in \cite{l18} and our Theorem \ref{t1}. 



%\begin{remark}Assumption \ref{a4} holds automatically when $g$ is concave. For the general distortion function, one can directly verify that $$\lim_{\delta\rightarrow 0}\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)=\hat{\rho} \text{~~and~~} \lim_{\delta\rightarrow+\infty}\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)=1,$$where $\hat{\rho}:=\text{coor}(F^{-1}(U), \hat{\gamma}(U))$.   \end{remark}





Similarly, we introduce the following notations: 
\begin{align}\label{eq: notations-nonconcave}
    \hat{\rho}:=\text{corr}(F^{-1}(U),\hat{\gamma}(U)), 
    \qquad \hat{\sigma}_0=\text{std}(\hat{\gamma}(U)),
 \qquad\hat{\varepsilon}_{max}=\varepsilon_{min}+2\sigma\sigma_F(1-\hat{\rho}).   
\end{align}

In the sequel, we investigate the distance between $\hat{G}_{\delta}$ and $F$.  We add a technical condition for this purpose.

\begin{assumption}\label{a4}
Given the reference distribution $F$ and a distortion function $g$, and suppose $\hat{\sigma}_0>0$ and the following two conditions hold:
\begin{itemize}
    \item[(a)] For any $G\in\mathcal{M}(\mu,\sigma)$,
  $\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)$ is strictly increasing with $\delta$ on $(0,\infty)$, and
 $$\lim_{\delta\rightarrow 0}\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)=\hat{\rho} \text{~~and~~} \lim_{\delta\rightarrow+\infty}\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)=1;$$
    \item[(b)] For any $\delta>0$, $\text{corr}\big(\gamma(U)+\delta F^{-1}(U),\hat{r}_{\delta'} (U)\big)$ is decreasing with respect to $\delta'$ on $(\delta, +\infty)$.
\end{itemize}   
\end{assumption}

\begin{remark}
Suppose $g$ is a concave distortion function and $\rho<1$, then \ref{a4} holds automatically from the proof procedure of Lemma \ref{l1}.  Besides, \ref{a4}(a) also holds in the proof of Theorem 3.7 in \cite{bpv24}.

If $\text{corr}\big(F^{-1}(U),\hat{r}_\delta (U)\big)\equiv 1$ for all $\delta\geq0$, then one can obtain that $d^2_W(F, G_{\delta})=\varepsilon_{min}$ for all $\delta\geq0$. Thus, the solution to problem \eqref{m1} is trivial (the same to Remark \ref{rem:3.2}) even for $\varepsilon>\varepsilon_{min}$. Thus, we only consider the situation of $\hat\rho<1$ in the following Theorem \ref{th-hat}. 
\end{remark}

Following the proof procedure of Proposition \ref{pro:emax} closely, for any distortion function $g$,  suppose \ref{a1}-\ref{a4} hold,  
then one can easily get that 
\begin{align}\label{eq:optimal-distance-general}
\varepsilon_{min}\leq d_W^2(F,\hat{G}_{\delta})\leq \hat{\varepsilon}_{max}, ~~\forall \delta\geq0,
\end{align}where $\hat{\varepsilon}_{max}$ and $\hat{G}_{\delta}$ are defined by \eqref{eq: notations-nonconcave} and \eqref{ep} respectively. Noting that this estimation does not need Assumption  \ref{a4}(b).  



%\begin{lemma}\label{p1-}Suppose \ref{a1} and \ref{a4} hold and $\hat\rho<1$. For any $\varepsilon\in(\varepsilon_{min},\hat{\varepsilon}_{max})$, then there exists a unique $\hat{\delta}^*>0$ and $\hat{G}_{\hat{\delta}^*}\in \mathcal{M}_{\varepsilon}(\mu,\sigma)$ with $d_W^2(F, \hat{G}_{\hat{\delta}^*})=\varepsilon$, and its quantile function in the following expression$$\hat{G}_{\hat{\delta}^*}^{-1}(u):=\mu-\dfrac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}\hat{\mu}_{\hat{\delta}^*}+\dfrac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}\hat{r}_{\hat{\delta}^*}(u),~~u\in(0,1),$$where $\mu_{\hat{\delta}^*}=\mathbb{E}[\hat{r}_{\hat{\delta}^*}(U)]$, $\sigma _{\hat{\delta}^*}=\text{std}(\hat{r}_{\hat{\delta}^*} (U))$.\end{lemma}\noindent\textbf{Proof}.It completes the proof. \hfill$\Box$



\subsection{General distortion function case: $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$}


Applying the estimation \eqref{eq:optimal-distance-general}, for the general distortion function $g$ and $\mathcal{N}=\mathcal{M}_{\varepsilon}(\mu,\sigma)$, under Assumptions \ref{a1}-\ref{a4}, then the results of Theorem \ref{tu} also hold similarly. Specifically, when $\varepsilon <\varepsilon_{min}$, then the problem \eqref{m1} has no solution; when $\varepsilon = \varepsilon_{min}$, then the optimal quantile for problem \eqref{m1} is still
\begin{equation*}
	G^{-1}(u)=\mu-\dfrac{\sigma}{\sigma_F}\mu_F+\dfrac{\sigma}{\sigma_F}F^{-1} (u), ~0<u<1,
\end{equation*}
when $\varepsilon\geq\hat{\varepsilon}_{max}$, then the solution to problem \eqref{m1} is the same as in Theorem \ref{t41}. 


The following Theorem \ref{th-hat} extends the results of Theorem \ref{tu-2} to the general distortion function and also includes the results of Theorem 3.7 in \cite{bpv24} by incorporating the penalty function.  



\begin{theorem}\label{th-hat}
Let $g$ be a distortion function,  $\mathcal{N}=\mathcal{M}_\varepsilon(\mu,\sigma)$ and Assumptions \ref{a1}-\ref{a4} hold.    Suppose $\varepsilon\in(\varepsilon_{min},\hat{\varepsilon}_{max})$.  Then there exists a unique critical threshold $\hat{\delta}^*:=\hat{\delta}^*(\varepsilon)>0$, such that for the problem \eqref{m1}, we claim that 

\begin{itemize}
        \item [(i)]When $\delta\ge\hat{\delta}^*$, problem  \eqref{m1} has a  unique optimal solution and its quantile function is
\begin{equation*}
	\hat{G}_\delta^{-1}(u)=\mu-\frac{\sigma}{\hat{\sigma}_\delta}\hat{\mu}_\delta+\frac{\sigma}{\hat{\sigma}_\delta}\hat{r}_\delta(u), ~~0<u<1.
\end{equation*}
Its corresponding optimal value is
\begin{align*}
		H_g (\hat{G}_{\delta})-{\varphi({d_W^2(F,\hat{G}_{\delta})} )}=\mu+\sigma{\hat{\sigma}_{\delta}}-{\delta }(\varepsilon_{min}+2\sigma\sigma_F).
\end{align*}
\item[(ii)] When $\delta<\hat{\delta}^*$, problem  \eqref{m1} has a  unique optimal solution and its quantile function is
\begin{equation}\label{hat*}
\hat{G}_{\hat{\delta}^*}^{-1}(u)=\mu-\dfrac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}\hat{\mu}_{\hat{\delta}^*}+\dfrac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}\hat{r}_{\hat{\delta}^*} (u),~~~0<u<1,
\end{equation}where $\hat{\mu}_{\hat{\delta}^*}=\mathbb{E}[\hat{r}_{\hat{\delta}^*}]$ and $\hat{\sigma}_{\hat{\delta}^*}=\text{std}(\hat{r}_{\hat{\delta}^*})$. Its corresponding optimal value is
\begin{align*}
		H_g (\hat{G}_{\hat{\delta}^*})-{\varphi({d^2_W(F,\hat{G}_{\delta^*})} )}=\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+\sigma\sigma_\delta\text{corr}(\gamma+2\delta F^{-1},\hat{r}_{\hat{\delta}^*}).
\end{align*}

    \end{itemize}
\end{theorem}

\noindent\textbf{Proof}. 
Similar to Lemma \ref{l1}, for each $\varepsilon\in(\varepsilon_{min}, \hat{\varepsilon}_{max})$, we can find
$\hat{\delta}^*>0$ by setting  $d_W^2(F,\hat{G}_{\delta})=\varepsilon$. From the directly calculation,  then we have  
\begin{align}\label{cdelta}
\text{corr}(F^{-1}(U),\hat{r}_\delta(U))=\frac{\varepsilon_{min}+2\sigma\sigma_F-\varepsilon}{2\sigma\sigma_F}.
\end{align}
By the continuity of the isotonic projection and and Assumption \ref{a4}(a), then there exists a unique $\hat{\delta}^*>0$ such that equation \eqref{cdelta} holds.  From equation \eqref{cdelta} we can see that there is a one-to-one corresponding between $\varepsilon\in(\varepsilon_{min}, \hat{\varepsilon}_{max})$ and $\hat{\delta}^*=\hat{\delta}^*(\varepsilon)$,  and $\hat{\delta}^*$ is inversely proportional to $\varepsilon$.

Conversely, for any $\delta>0$, then there exists a unique $\hat{\varepsilon}^*=\hat{\varepsilon}^*(\delta)$ such that $$\text{corr}(F^{-1}(U),\hat{r}_\delta(U))=\frac{\varepsilon_{min}+2\sigma\sigma_F-\hat{\varepsilon}^*}{2\sigma\sigma_F}.$$





Case (i):  for any 
$\delta\geq \hat{\delta}^*$, choosing $\hat{G}^{-1}_\delta$ by \eqref{ep}, it implies that 
\begin{align}
d_W^2(F, \hat{G}_\delta)=\hat{\varepsilon}^*\leq\varepsilon=d_W^2(F, \hat{G}_{\hat{\delta}^*}).
\end{align}


According to Theorem \ref{t1}, the objective function can also be written as
\begin{align*}
	H_g ({G})+{\varphi({d_W^2(F,G)})}=\mathbb{E}[(\gamma+2\delta F^{-1})\cdot {G}^{-1}]-\delta(\mu_F^2+\mu^2+\sigma_F^2+\sigma^2),
\end{align*}
and  (by Lemma B.4 of \cite{bpv24}) we also have 
\begin{equation*}
	 \mathbb{E}[(\gamma+2\delta F^{-1})\cdot {G}^{-1}] \le \mathbb{E}[(\gamma+2\delta F^{-1})\cdot \hat{G}^{-1}_{\delta}], ~~\forall G \in \mathcal{M}(\mu,\sigma).
\end{equation*}

Therefore,  we know that 
$$\hat{G}_\delta=\text{arg}\mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)}\ H_g (G)-\varphi({d_W(F,G)}^2).$$
By virtue of the fact that $d_W^2(F, \hat{G}_\delta)=\hat{\varepsilon}^*\leq\varepsilon$, then we have that 
$$\hat{G}_\delta=\text{arg}\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\delta {d_W^2(F,G)}.$$ 
Moreover, the optimal value of $\hat{G}^{-1}_{\delta}$ is $H_g (\hat{G}_{\delta})-{\varphi({d^2_W(F,\hat{G}_{\delta})})}=\mu+\sigma{\hat{\sigma}_{\delta}}-{\delta }(\varepsilon_{min}+2\sigma\sigma_F)$.




Case (ii): this proof procedure is similar to Theorem \ref{tu-2}.   
When $\delta<{\hat{\delta}^*}$,  from the proof procedure and analysis of case (i),  we know that in this case the optimal distribution  can not be $G_\delta$ in \eqref{eq:hb-th3.3} any more, since 
$
d_W^2(F, \hat{G}_\delta)=\hat{\varepsilon}^*>\varepsilon=d_W^2(F, \hat{G}_{\hat{\delta}^*})$, which means  $\hat{G}_\delta\notin\mathcal{M}_{\varepsilon}(\mu,\sigma)$. 



Firstly, we claim that for any $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$, we have that
\begin{equation}\label{eq:step1-nonc}
\hat{G}_{\bar\delta}=\text{arg}\sup_{G\in\mathcal{M}_\varepsilon (\mu,\sigma)\atop d_W(F,G)=\sqrt{\overline\varepsilon}}H_g (G)-\delta{d^2_W(F,G)},   
\end{equation}where 
 $\bar{\delta}=\hat{\delta}^*(\bar{\varepsilon})\geq\hat{\delta}^*=\hat{\delta}^*(\varepsilon)$ since $\bar{\varepsilon}\leq \varepsilon$. 


In fact, for any given $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\hat{\varepsilon}_{max})$, since $d_W^2(F, \hat{G}_{\bar\delta})=\bar\varepsilon$, and the fact that for any $G \in \mathcal{M}_{\varepsilon}(\mu,\sigma)$ with $d_W(F,G)=\sqrt{\overline{\varepsilon}}$, we have that 
\begin{equation*}
	 \mathbb{E}[(\gamma+2\delta F^{-1})\cdot {G}^{-1}] \le \mathbb{E}[(\gamma+2\delta F^{-1})\cdot \hat{G}^{-1}_{\bar{\delta}}].
\end{equation*}
Therefore,  $\hat{G}_{\bar{\delta}}$ makes the objective function greater than ${G}^{-1}$ for the same distance, that is, for any $G\in\mathcal{M}_\varepsilon (\mu,\sigma)$ with  $d_W(F,G)=\sqrt{\overline{\varepsilon}}$, then one has
\begin{align*}%\label{eq:fix distance}
   H_g (G)-{\delta({d^2_W(F,G)} )}\le H_g (\hat{G}_{\bar{\delta}})-{\delta {d^2_W(F,\hat{G}_{\bar{\delta}})} }, 
\end{align*}which is exactly \eqref{eq:step1-nonc}. 

Secondly, for any $\bar\varepsilon\leq\varepsilon$ and $\bar\varepsilon\in(\varepsilon_{min},\hat{\varepsilon}_{max})$, we show that 
 \begin{align}\label{eq:Gstar314}
\hat{G}_{\hat{\delta}^*}=\text{arg}\mathop{\sup}_{\hat{G}_{\bar{\delta}}\in \mathcal{M}_\varepsilon(\mu,\sigma)\atop \bar{\delta}\ge\hat{\delta}^*>\delta}\quad H_g (\hat{G}_{\bar{\delta}})-\delta{d_W^2(F,\hat{G}_{\bar{\delta}})},
  \end{align}where 
 $\bar{\delta}=\hat{\delta}^*(\bar{\varepsilon})\geq\hat{\delta}^*=\hat{\delta}^*(\varepsilon)>\delta$ since $\bar{\varepsilon}\leq \varepsilon$.

Specifically,  for any $\delta<\hat{\delta}^*\le\bar{\delta}$, we can transform the form of the objective function as 
\begin{align*}
	H_g (\hat{G}_{\bar{\delta}})-\delta({d_W^2(F,\hat{G}_{\bar{\delta}})})
    =\mu-\delta(\varepsilon_{min}+2\sigma\sigma_F)+h(\bar{\delta}),
\end{align*}
where $h(\bar{\delta})=\text{cov}(\gamma+2\delta F^{-1},\hat{G}^{-1}_{\bar{\delta}})$. 
Moreover, one has 
\begin{align*}
h(\bar{\delta})=\text{cov}(\gamma+2\delta F^{-1},\hat{G}^{-1}_{\bar{\delta}})=\sigma_\delta \sigma \text{corr}(\gamma+2\delta F^{-1},\hat{\gamma}^{-1}_{\bar{\delta}}),
\end{align*} then by the Assumption A3(b), it implies that $h(\bar{\delta})$ is decreasing in $\bar{\delta}$. 


%\red{to be revised}
%\begin{align*}h(\bar{\delta})&=\text{cov}(\gamma+2{\bar{\delta}} F^{-1},\hat{G}^{-1}_{\bar{\delta}})+2(\delta-{\bar{\delta}})\text{cov}(F^{-1},\hat{G}^{-1}_{\bar{\delta}})\\&=\mathbb{E}[(\gamma+2{\bar{\delta}} F^{-1})\cdot \hat{G}^{-1}_{\bar{\delta}}]-\mu\mu_{\bar\delta}+2(\delta-{\bar{\delta}})\sigma\sigma_F\text{corr}(F^{-1},\hat{G}^{-1}_{\bar{\delta}}),\end{align*}where  $\mu_{\bar\delta}=\mathbb{E}[\gamma+2{\bar{\delta}} F^{-1}]=1+2\bar{\delta}\mu_F$.the last equality is from the fact that $\mathbb{E}[(\gamma+2\bar\delta F^{-1})\cdot {G}^{-1}] \le \mathbb{E}[(\gamma+2\bar\delta F^{-1})\cdot \hat{G}^{-1}_{\bar\delta}]$ and the strict monotonicity of the projection. 


%It implies that the objective function is monotonically decreasing with respect to $\bar{\delta}$. 

Hence, for any $ \bar{\delta}\ge\delta^*>\delta$ and
$\hat{G}_{\bar{\delta}}\in \mathcal{M}_\varepsilon(\mu,\sigma)$, we have that 
$$ H_g (\hat{G}_{\bar{\delta}})-{\delta d_W^2(F,\hat{G}_{\bar{\delta}})} \le H_g (\hat{G}_{\delta^*})-\delta{d_W^2(F,\hat{G}_{\delta^*})}.$$Therefore,  \eqref{eq:Gstar314} holds.  

Finally, combining \eqref{eq:step1-nonc} and \eqref{eq:Gstar314} together, we finally prove that 
\begin{align}\label{hatd*}
\hat{G}_{\hat{\delta}^*}=\text{arg}\mathop{\sup}_{G\in \mathcal{M}_{\varepsilon}(\mu,\sigma)}\ H_g (G)-\delta {d^2_W(F,G)}.
\end{align}

Furthermore, we can obtain the optimal value of the objective function at $\hat{G}_{\delta^*}$. 
\begin{align*}
   & H_g(\hat{G}_{\hat{\delta}^*})-\varphi(d_W^2(F,\hat{G}_{\hat{\delta}^*}))\\
&=\mathbb{E}\big(\gamma\cdot\hat{G}^{-1}_{\hat{\delta}^*}\big)-\varphi[\varepsilon_{min}+2\sigma\sigma_F-2\sigma\sigma_F\text{corr}(F^{-1},\hat{G}^{-1}_{\hat{\delta}^*})]\\
&=\mu+\frac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}(\int_0^1 \gamma(u)\hat{r}_{\hat{\delta}^*}(u){\rm d}u- \hat{\mu}_{\hat{\delta}^*})-{\delta }(\varepsilon_{min}+2\sigma\sigma_F-2\text{cov}(F^{-1},\hat{G}^{-1}_{\hat{\delta}^*}) )\\
&=\mu+\sigma\sigma_0\text{corr}(\gamma,\hat{r}_{\hat{\delta}^*})-{\delta }(\varepsilon_{min}+2\sigma\sigma_F-2\frac{\sigma}{\hat{\sigma}_{\hat{\delta}^*}}\text{cov}(F^{-1},\hat{r}_{\hat{\delta}^*}))\\
&=\mu+\sigma\sigma_\delta \text{corr}(\gamma+2\delta F^{-1},\hat{r}_{\hat{\delta}^*})-{\delta }(\varepsilon_{min}+2\sigma\sigma_F),
\end{align*}where $\hat{r}_{\delta^*}$is the projection of $\gamma+2{\delta^*}F^{-1}$,  $\hat{\mu}_{\hat{\delta}^*}=\mathbb{E}[\hat{r}_{\delta^*}]$ and $\hat{\sigma}_{\hat{\delta}^*}=\text{std}(\hat{r}_{\delta^*})$. 
\hfill$\Box$

Theorem \ref{th-hat}  shows that when the penalty term is involved, there exist similar characterizations of Theorem \ref{tu-2} under the general distortion function.

The following corollary is almost obvious. The proof is omitted.

\begin{corollary}\label{c41}
($\varepsilon=+\infty$)\quad Suppose \ref{a1}-\ref{a4} hold and $g$ is a distortion function. Then
\begin{align*}
		\mathop{\sup}_{G\in \mathcal{M}(\mu,\sigma)}H_g(G)-\varphi(d_W^2(F,{G}))=\mu+\sigma\sigma_\delta -{\delta }(\varepsilon_{min}+2\sigma\sigma_F ).
\end{align*}
\end{corollary}

%\begin{remark} When $\delta=0$, the Theorem \ref{th-hat} result reduce to the result of \cite{bpv24}'s Theorem 3.7.\end{remark}

\section{An illustrate example of CVaR}\label{sec:5}
%Various commonly employed distorted risk measures have been extensively examined under constraints on the first two moments. In particular, \cite{nu10} investigated the bounds of TVaR and \cite{l18} also analyzed the bounds of RVaR. The results presented in this study are similarly applicable to CVaR, offering corresponding bound analyses for it.

In this section, we apply our results to one widely used risk measure, called Conditional Value at Risk (CVaR).  We briefly introduce these as follows. The readers can refer to \cite{a02} and \cite{fs16} for more details.   

For any given $G\in\mathcal{M}^2$, 
 Value at Risk (VaR) is defined as
\begin{equation*}
\text{VaR}_\alpha(G):=G^{-1}(\alpha), ~~\alpha\in(0,1),
\end{equation*}
and its corresponding distortion function is $g(x)=\mathbf{1}_{(1-\alpha,1]}(x), ~~x\in[0,1].$
Conditional Value at Risk (CVaR) (also called Expected Shortfall (ES)) is denoted by
\begin{equation*}
	\text{CVaR}_{\alpha}(G):=\frac{1}{1-\alpha}\int_\alpha^1 \text{VaR}_u(G)\text{d}u =\int_0^1 G^{-1}(u)\text{d}{g}(u),
\end{equation*}
where the corresponding distortion function is $g(x)=\min\left\lbrace  \frac{x}{1-\alpha},1\right\rbrace, ~x\in[0,1],$ 
and the derivative of the distortion function is
$\gamma(x)=\frac{1}{1-\alpha}\mathbf{1}_{[0,1-\alpha]}(x)$.  
%The relationship between CVaR and RVaR, $\text{CVaR}_{\alpha}(X):=\text{RVaR}_{\alpha,1}(X)$, can be seen from the above definition.


The following proposition establishes the optimal quantiles and optimal values for CVaR. 
%\red{to be revised} %先按正常计算。到算例的时候，再告知参数的取值。


\begin{proposition}\label{6.1}
For $\alpha\in(0, 1)$, $\varepsilon\in(\varepsilon_{min},\varepsilon_{max})$ and $\delta\geq0$,  we have the optimal penalty coefficient as $\delta^*$, where $\delta^*$ satisfies
\begin{equation*}
\delta^*=-\frac{\rho\sqrt{\frac{\alpha}{1-\alpha}}}{2\sigma_F}+\frac{(\varepsilon_{min}+2\sigma\sigma_F-\varepsilon)\sqrt{\frac{\alpha(1-\rho^2)}{1-\alpha}}}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.
\end{equation*}
\begin{itemize}
    \item [(i)]When $\delta\ge\delta^*$, the value of CVaR with penalty under distribution uncertainty is
    \begin{align*}
    \mathop{\sup}_{G\in\mathcal{M}_{\varepsilon}(\mu,\sigma)}\text{CVaR}_{\alpha}(G)-\delta d^2_W(F,G)=\mu+\sigma\sigma_{CVaR_\delta} -{\delta }(\varepsilon_{min}+2\sigma\sigma_F ),
    \end{align*}
    and the optimal quantile function  is 
   \small{ $${G}^{-1}_{CVaR_\delta}(u)=\mu+ \left(\frac{\sigma(2\delta F^{-1}(u)-1-2\delta\mu_F)}{\sigma_{{CVaR_\delta}}}\right)\mathbf{1}_{u\in(0,\alpha]}+\left(\frac{\sigma(\frac{\alpha}{1-\alpha}+2\delta F^{-1}(u)-2\delta\mu_F)}{\sigma_{{CVaR_\delta}}}\right) \mathbf{1}_{u\in(\alpha,1)},$$}
    where $\sigma_{CVaR_\delta}=\sqrt{\frac{\alpha}{1-\alpha}+4\delta^2(\mu_F^2+\sigma_F^2) +4\delta \sigma_F\rho\sqrt{\frac{\alpha}{1-\alpha}}.}$
    \item [(ii)]When $\delta<\delta^*$, the value of CVaR with penalty under distribution uncertainty is
    \begin{align*}
    \mathop{\sup}_{G\in\mathcal{M}_{\varepsilon}(\mu,\sigma)}\text{CVaR}_{\alpha}(G)-\delta d^2_W(F,G)=\mu+\sigma\sigma_{CVaR_{\delta^*}} -{\delta }(\varepsilon_{min}+2\sigma\sigma_F ),
    \end{align*}
    and the optimal quantile function  is 
    \small{$${G}^{-1}_{CVaR_{\delta^*}}(u)=\mu+ \left(\frac{\sigma(2\delta^* F^{-1}(u)-1-2\delta^*\mu_F)}{\sigma_{CVaR_{\delta^*}}}\right)\mathbf{1}_{u\in(0,\alpha]}+\left(\frac{\sigma(\frac{\alpha}{1-\alpha}+2{\delta}^* F^{-1}(u)-2{\delta}^*\mu_F)}{\sigma_{CVaR_{\delta}^*}}\right) \mathbf{1}_{u\in(\alpha,1)},$$}
    where $\sigma_{CVaR_{\delta^*}}=\sqrt{\frac{\alpha}{1-\alpha}+4{{\delta}^*}^2(\mu_F^2+\sigma_F^2) +4{\delta}^* \sigma_F\rho\sqrt{\frac{\alpha}{1-\alpha}}.}$
\end{itemize}


\end{proposition}

\noindent\textbf{Proof}.
When $\delta<\delta^*$, since the derivative function of distortion function for CVaR is $\gamma(u)=\frac{1}{1-\alpha}\mathbf{1}_{[0,1-\alpha]}(u)$, $u\in (0,1)$, which is non-decreasing,  applying Theorem \ref{t1}, then we have
\begin{align*}
\mathop{\sup}_{G\in\mathcal{M}(\mu,\sigma)}\text{CVaR}_{\alpha}(G)-\delta d^2_W(F,G)=\mu+\sigma\sigma_{CVaR} -{\delta }(\varepsilon_{min}+2\sigma\sigma_F ), 
\end{align*}
where 
$\sigma_{CVaR_\delta}^2:=var(\gamma(U)+2\delta F^{-1}(U))=\frac{\alpha}{1-\alpha}+4\delta^2(\mu_F^2+\sigma_F^2) +4\delta \sigma_F\rho\sqrt{\frac{\alpha}{1-\alpha}}.$
%&\int_0^1(\gamma(u)+2\delta F^{-1}(u))^2\text{d}u-\left(\int_0^1\gamma(u)+2\delta F^{-1}(u)\text{d}u\right)^2\\



Then the optimal quantile of CVaR is
\begin{align*}
		{G}^{-1}_{CVaR}=\mu+ [\frac{\sigma(2\delta F^{-1}(u)-1-2\delta\mu_F)}{\sigma_{CVaR}}]\mathbf{1}_{u\in(0,\alpha]}+[\frac{\sigma(\frac{\alpha}{1-\alpha}+2\delta F^{-1}(u)-2\delta\mu_F)}{\sigma_{CVaR}}] \mathbf{1}_{u\in(\alpha,1)}.
\end{align*}

When $\delta<\delta^*$, we apply Lemma \ref{l1}, and we obtain

\begin{equation*}
    \sigma_0^2=\int_0^1 (\gamma(u)-1)^2\text{d}u=\frac{\alpha}{1-\alpha},
\end{equation*}
then we have the optimal penalty coefficient as $\delta^*$ , where $\delta^*$ satisfies


\begin{equation*}
\delta^*=-\frac{\rho\sqrt{\frac{\alpha}{1-\alpha}}}{2\sigma_F}+\frac{(\varepsilon_{min}+2\sigma\sigma_F-\varepsilon)\sqrt{\frac{\alpha(1-\rho^2)}{1-\alpha}}}{2\sigma_F\sqrt{(\varepsilon_{min}+4\sigma\sigma_F-\varepsilon)(\varepsilon-\varepsilon_{min})}}.
\end{equation*}

\hfill$\Box$

%\begin{corollary} We illustrate the various cases of Proposition \ref{6.1} under Theorem \ref{tu-2}, considering the reference distribution $F$ as the standard normal distribution,  and let $\mu=\mu_F=0,\sigma= \sigma_F=1,\alpha=0.7$.

