		\end{claimproof}


		However, Claims \ref{claim condition 1} and \ref{claim condition 2} together contradict that $\mu$ is pair-efficient at $P_A$, which completes the proof of part \ref{item equivalence single-peaked} of Theorem \ref{theorem equivalence}.\bigskip


		\noindent \textbf{Proof of part \ref{item equivalence single-dipped}.} The ``only-if'' part follows from the respective definitions. We proceed to prove the ``if'' part. To do so, we show that for every $P_A \in \mathbb{SD}^n(\prec_H)$ and every $\mu \in \mathcal{M}$, $\mu$ is Pareto-efficient at $P_A$ if $\mu$ is pair-efficient at $P_A$. Assume for contradiction that this is not true; there exist a preference profile $P_A \in \mathbb{SD}^n(\prec_H)$ and an allocation $\mu \in \mathcal{M}$ such that $\mu$ is pair-efficient at $P_A$, but not Pareto-efficient. 

		Since $\mu$ is not Pareto-efficient at $P_A$, another allocation $\nu$ exists that Pareto-dominates $\mu$ at $P_A$. Let $\tilde{A} := \{a \in A \mid \nu(a) \mathrel{P_a} \mu(a)\}$ be the (non-empty) set of agents who prefer their assignments under $\nu$ to those under $\mu$. Since $\nu$ Pareto-dominates $\mu$ at $P_A$, by the construction of $\tilde{A}$, it follows that for every $a \in A \setminus \tilde{A}$, $\mu(a) = \nu(a)$, and consequently,
		\begin{equation}\label{equation same assignments sd}
			\{\mu(a) \mid a \in \tilde{A}\} = \{\nu(a) \mid a \in \tilde{A}\}.
		\end{equation}
		Label the agents in $\tilde{A}$ as $b_1, \ldots, b_m$ (i.e., $\tilde{A} = \{b_1, \ldots, b_m\}$) such that $\mu(b_1) \prec_H \cdots \prec_H \mu(b_m)$. In the rest of this proof, we will show that the agents $b_1$ and $b_m$ prefer each other's assignments under $\mu$ to their own, demonstrating pair-inefficiency of $\mu$ at $P_A$.


		\begin{claim}\label{claim condition sd 1}
			$\mu(b_m) \mathrel{P_{b_1}} \mu(b_1)$.
		\end{claim}


		\begin{claimproof}[Proof of Claim \ref{claim condition sd 1}.]
			Since $\mu(b_1) \neq \nu(b_1)$, the fact $\mu(b_1) \prec_H \cdots \prec_H \mu(b_m)$, together with \eqref{equation same assignments sd}, implies $\mu(b_1) \prec_H \nu(b_1) \preceq_H \mu(b_m)$. Furthermore, since $\nu(b_1) \mathrel{P_{b_1}} \mu(b_1)$ and $\mu(b_1) \prec_H \nu(b_1)$, by single-dippedness of $P_{b_1}$, we have $d(P_{b_1}) \prec_H \nu(b_1)$. Because of this, and since $\nu(b_1) \preceq_H \mu(b_m)$, by single-dippedness of $P_{b_1}$, we have $\mu(b_m) \mathrel{R_{b_1}} \nu(b_1)$. This, together with the fact $\nu(b_1) \mathrel{P_{b_1}} \mu(b_1)$, implies $\mu(b_m) \mathrel{P_{b_1}} \mu(b_1)$. This completes the proof of Claim \ref{claim condition sd 1}.
		\end{claimproof}


		\begin{claim}\label{claim condition sd 2}
			$\mu(b_1) \mathrel{P_{b_m}} \mu(b_m)$.
		\end{claim}


		\begin{claimproof}[Proof of Claim \ref{claim condition sd 2}.]
			Since $\mu(b_m) \neq \nu(b_m)$, the fact $\mu(b_1) \prec_H \cdots \prec_H \mu(b_m)$, together with \eqref{equation same assignments sd}, implies $\mu(b_1) \preceq_H \nu(b_m) \prec_H \mu(b_m)$. Furthermore, since $\nu(b_m) \mathrel{P_{b_m}} \mu(b_m)$ and $\nu(b_m) \prec_H \mu(b_m)$, by single-dippedness of $P_{b_m}$, we have $\nu(b_m) \prec_H d(P_{b_m})$. Because of this, and since $\mu(b_1) \preceq_H \nu(b_m)$, by single-dippedness of $P_{b_m}$, we have $\mu(b_1) \mathrel{R_{b_m}} \nu(b_m)$. This, together with the fact $\nu(b_m) \mathrel{P_{b_m}} \mu(b_m)$, implies $\mu(b_1) \mathrel{P_{b_m}} \mu(b_m)$. This completes the proof of Claim \ref{claim condition sd 2}.
		\end{claimproof}


		However, Claims \ref{claim condition sd 1} and \ref{claim condition sd 2} together contradict that $\mu$ is pair-efficient at $P_A$, which completes the proof of part \ref{item equivalence single-dipped} of Theorem \ref{theorem equivalence}.
		\hfill
		\qed




		\section{Proof of Proposition \ref{proposition maximal}}\label{appendix proof of proposition maximal}

		\setcounter{equation}{0}
		\setcounter{table}{0}
		\setcounter{theorem}{0}


		\noindent \textbf{Proof of part \ref{item proposition sp}.} Since $\mathcal{P}_A \supsetneq \mathbb{SP}^n(\prec_H)$, there exists an agent $a \in A$ such that $\mathcal{P}_a \supsetneq \mathbb{SP}(\prec_H)$. Consider a preference $P_a$ of agent $a$ such that $P_a \in \mathcal{P}_a \setminus \mathbb{SP}(\prec_H)$. Let $p(P_a) = h$. (Note that house $h$ does not necessarily have to be the initial endowment of agent $a$.) Since $P_a \in \mathcal{P}_a \setminus \mathbb{SP}(\prec_H)$, there exist distinct $h', \tilde{h} \in H \setminus \{h\}$ with $h \mathrel{P_a} \tilde{h} \mathrel{P_a} h'$ where
		\begin{equation*}
			h \prec_H h' \prec_H \tilde{h} \hspace{2 mm} \mbox{ or } \hspace{2 mm} \tilde{h} \prec_H h' \prec_H h.
		\end{equation*}

		We now construct a preference profile at which not every pair-efficient allocation is Pareto-efficient. Fix two distinct agents $a', \tilde{a} \in A \setminus \{a\}$ and a bijection $\beta : A \setminus \{a, a', \tilde{a}\} \to H \setminus \{h, h', \tilde{h}\}$. (Note that house $h'$ does not need to be the initial endowment of agent $a'$, nor does house $\tilde{h}$ have to be the initial endowment of agent $\tilde{a}$.) Consider the preference profile $P^*_A \in \mathcal{P}_A$ such that
		\begin{enumerate}[(a)]
			\item $P^*_a = P_a$,

			\item $P^*_{a'} \in \mathbb{SP}(\prec_H)$ with $h' \mathrel{P^*_{a'}} h \mathrel{P^*_{a'}} \tilde{h}$,

			\item $P^*_{\tilde{a}} \in \mathbb{SP}(\prec_H)$ with $\tilde{h} \mathrel{P^*_{\tilde{a}}} h' \mathrel{P^*_{\tilde{a}}} h$, and 

			\item for every $b \in A \setminus \{a, a', \tilde{a}\}$, $P^*_b \in \mathbb{SP}(\prec_H)$ with $p(P^*_b) = \beta(b)$.
		\end{enumerate}

		Consider the allocation $\mu = [(a, \tilde{h}), (a', h), (\tilde{a}, h'), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$. We complete the proof by demonstrating that $\mu$ is pair-efficient at $P^*_A$, but not Pareto-efficient. To provide clear intuition for this claim, we first present a table summarizing the preferences. In the table, the pair-efficient allocation $\mu$ is highlighted in \blue{blue}, while the efficiency-improving trade is highlighted in \red{red}.
		\begin{table}[H]
			\centering
			\begin{tabular}{ccccc}
				\hline
				$P^*_{a}$ & $P^*_{a'}$ & $P^*_{\tilde{a}}$ & $\ldots$ & $P^*_b$ \\ \hline
				\hline
				\red{$h$} & $\vdots$ & $\vdots$ & $\ldots$ & \blue{$\beta(b)$} \\
				$\vdots$ & \red{$h'$} & \red{$\tilde{h}$} & $ $ & $\vdots$ \\
				\blue{$\tilde{h}$} & $\vdots$ & $\vdots$ & $ $ & $ $ \\
				$\vdots$ & \blue{$h$} & \blue{$h'$} & $ $ & $ $ \\
				$h'$ & $\vdots$ & $\vdots$ & $ $ & $ $ \\
				$\vdots$ & $\tilde{h}$ & $h$ & $ $ & $ $ \\
				$ $ & $\vdots$ & $\vdots$ & $ $ & $ $ \\
				\hline
			\end{tabular}
		\end{table}

		Now, we formally explain why $\mu$ is pair-efficient at $P^*_A$, but not Pareto-efficient. Since every agent in $A \setminus \{a, a', \tilde{a}\}$ is assigned their most preferred house under $\mu$ at $P^*_A$, no agent in $A \setminus \{a, a', \tilde{a}\}$ will be part of a mutually beneficial pairwise exchange even if such a pairwise exchange exists. Furthermore, it is straightforward to verify that no pair of agents in $\{a, a', \tilde{a}\}$ can benefit from trading their assignments under $\mu$ at $P^*_A$. Combining these two observations, it follows that $\mu$ is pair-efficient at $P^*_A$. However, $\mu$ is not Pareto-efficient at $P^*_A$ because the allocation $\nu = [(a, h), (a', h'), (\tilde{a}, \tilde{h}), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$ Pareto-dominates $\mu$ at $P^*_A$. This completes the proof of part \ref{item proposition sp} of Proposition \ref{proposition maximal}.\bigskip


		\noindent \textbf{Proof of part \ref{item proposition sd}.} Since $\mathcal{P}_A \supsetneq \mathbb{SD}^n(\prec_H)$, there exists an agent $a \in A$ such that $\mathcal{P}_a \supsetneq \mathbb{SD}(\prec_H)$. Consider a preference $P_a$ of agent $a$ such that $P_a \in \mathcal{P}_a \setminus \mathbb{SD}(\prec_H)$. Let $d(P_a) = h$. (Note that house $h$ does not necessarily have to be the initial endowment of agent $a$.) Since $P_a \in \mathcal{P}_a \setminus \mathbb{SD}(\prec_H)$, there exist distinct $h', \tilde{h} \in H \setminus \{h\}$ with $h' \mathrel{P_a} \tilde{h} \mathrel{P_a} h$ where
		\begin{equation*}
			h \prec_H h' \prec_H \tilde{h} \hspace{2 mm} \mbox{ or } \hspace{2 mm} \tilde{h} \prec_H h' \prec_H h.
		\end{equation*}
		In the rest of this proof, we will construct a preference profile at which not every pair-efficient allocation is Pareto-efficient. We distinguish the following two cases.\medskip


		\noindent\textbf{\textsc{Case} 1}: Suppose $h \prec_H h' \prec_H \tilde{h}$.

		First, we construct the required preference profile. Fix two distinct agents $a', \tilde{a} \in A \setminus \{a\}$ and a bijection $\beta : A \setminus \{a, a', \tilde{a}\} \to H \setminus \{h, h', \tilde{h}\}$. (Note that house $h'$ does not need to be the initial endowment of agent $a'$, nor does house $\tilde{h}$ have to be the initial endowment of agent $\tilde{a}$.) Consider three preferences $P^1, P^2, P^3 \in \mathbb{SD}(\prec_H)$ such that
		\begin{enumerate}[(a)]
			\item $h_i \mathrel{P^1} h_j$ for all $h_i, h_j \in H$ with $h_i \prec_H h_j$,

			\item $h_j \mathrel{P^2} h_i$ for all $h_i, h_j \in H$ with $h_i \prec_H h_j$, and

			\item $d(P^3) = h'$, and $h_k \mathrel{P^3} h_i \mathrel{P^3} h_j$ for all $h_i, h_j, h_k \in H$ with $h_i \preceq_H h \prec_H h_j \prec_H \tilde{h} \preceq_H h_k$.
		\end{enumerate}
		Consider the preference profile $P^*_A \in \mathcal{P}_A$ such that
		\begin{equation*}
			\begin{aligned}
				& P^*_a = P_a, \hspace{2 mm} P^*_{a'} = P^3, \hspace{2 mm} P^*_{\tilde{a}} = P^1,\\
				& P^*_b = P^1 \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\} \mbox{ with } \beta(b) \prec_H \tilde{h}, \mbox{ and }\\
				& P^*_b = P^2 \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\} \mbox{ with } \tilde{h} \prec_H \beta(b).
			\end{aligned}
		\end{equation*}

		Consider the allocation $\mu = [(a, \tilde{h}), (a', h), (\tilde{a}, h'), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$. We complete the proof by demonstrating that $\mu$ is pair-efficient at $P^*_A$, but not Pareto-efficient. It follows from the construction of $P^*_A$ and $\mu$ that no agent in $A \setminus \{a, a', \tilde{a}\}$ will be part of a mutually beneficial pairwise exchange even if such a pairwise exchange exists. Furthermore, it is straightforward to verify that no pair of agents in $\{a, a', \tilde{a}\}$ can benefit from trading their assignments under $\mu$ at $P^*_A$. Combining these two observations, it follows that $\mu$ is pair-efficient at $P^*_A$. However, $\mu$ is not Pareto-efficient at $P^*_A$ because the allocation $\nu = [(a, h'), (a', \tilde{h}), (\tilde{a}, h), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$ Pareto-dominates $\mu$ at $P^*_A$.\medskip


		\noindent\textbf{\textsc{Case} 2}: Suppose $\tilde{h} \prec_H h' \prec_H h$.

		First, we construct the required preference profile. Fix two distinct agents $a', \tilde{a} \in A \setminus \{a\}$ and a bijection $\beta : A \setminus \{a, a', \tilde{a}\} \to H \setminus \{h, h', \tilde{h}\}$. (Note that house $h'$ does not need to be the initial endowment of agent $a'$, nor does house $\tilde{h}$ have to be the initial endowment of agent $\tilde{a}$.) Consider three preferences $P^1, P^2, P^3 \in \mathbb{SD}(\prec_H)$ such that
		\begin{enumerate}[(a)]
			\item $h_i \mathrel{P^1} h_j$ for all $h_i, h_j \in H$ with $h_i \prec_H h_j$,

			\item $h_j \mathrel{P^2} h_i$ for all $h_i, h_j \in H$ with $h_i \prec_H h_j$, and

			\item $d(P^3) = h'$, and $h_i \mathrel{P^3} h_k \mathrel{P^3} h_j$ for all $h_i, h_j, h_k \in H$ with $h_i \preceq_H \tilde{h} \prec_H h_j \prec_H h \preceq_H h_k$.
		\end{enumerate}
		Consider the preference profile $P^*_A \in \mathcal{P}_A$ such that
		\begin{equation*}
			\begin{aligned}
				& P^*_a = P_a, \hspace{2 mm} P^*_{a'} = P^3, \hspace{2 mm} P^*_{\tilde{a}} = P^2,\\
				& P^*_b = P^1 \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\} \mbox{ with } \beta(b) \prec_H \tilde{h}, \mbox{ and }\\
				& P^*_b = P^2 \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\} \mbox{ with } \tilde{h} \prec_H \beta(b).
			\end{aligned}
		\end{equation*}

		Consider the allocation $\mu = [(a, \tilde{h}), (a', h), (\tilde{a}, h'), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$. We complete the proof by demonstrating that $\mu$ is pair-efficient at $P^*_A$, but not Pareto-efficient. It follows from the construction of $P^*_A$ and $\mu$ that no agent in $A \setminus \{a, a', \tilde{a}\}$ will be part of a mutually beneficial pairwise exchange even if such a pairwise exchange exists. Furthermore, it is straightforward to verify that no pair of agents in $\{a, a', \tilde{a}\}$ can benefit from trading their assignments under $\mu$ at $P^*_A$. Combining these two observations, it follows that $\mu$ is pair-efficient at $P^*_A$. However, $\mu$ is not Pareto-efficient at $P^*_A$ because the allocation $\nu = [(a, h'), (a', \tilde{h}), (\tilde{a}, h), (b, \beta(b)) \mbox{ for all } b \in A \setminus \{a, a', \tilde{a}\}]$ Pareto-dominates $\mu$ at $P^*_A$.\medskip


		Since Cases 1 and 2 are exhaustive, this completes the proof of part \ref{item proposition sd} of Proposition \ref{proposition maximal}.
		\hfill
		\qed


