\section{Proof of Theorem~\ref{theorem:go_is_Lie} and Theorem~\ref{theorem:lie_go(n)}}

\subsection{Single bosonic mode : Theorem~\ref{theorem:go_is_Lie}}\label{subsection:proof_of_iso_go(1)}

$\mathfrak{go}(1)$ is defined as the vector space over the real field, $\mathbb{R}$, spanned by nine basis vectors
\[\begin{split}\label{eq:basis_of_go(1)}
&\ad_{\hat{N}},\;\ad_{\hat{X}},\;\ad_{\hat{Y}},\;\ad_{\hat{x}},\;\ad_{\hat{p}},\\
&L_{\x\x}^{+},\; L_{\x\p}^{+},\; L_{\p\p}^{+},\; L_{\x\p}^{-}.
\end{split}
\]
To show that $\mathfrak{go}(1)$ is Lie algebra, we need to prove the existence of a \emph{bilinear} operator, $[A,B]$, that is closed under $\mathfrak{go}(1)$, and satisfies the \emph{anticommutativity} and the \emph{Jacobi identity}. 
Since the commutation relation of the (super-)operators, $[A,B]=AB-BA$, satisfies the three conditions: bilinear, anticommutativity, and the Jacobi identity, proving closeness is enough to complete the proof.

To prove the closeness and commutation relation between $\mathfrak{go}(1)$, we first rewrite operators in Eq.~\eqref{eq:basis_of_go(1)} in terms of $\ad_{\x}$, $\ad_{\p}$, $\ad^+_{\x}$, and $\ad^+_{\p}$. $\ad_{\hat{O}}^+$ is anti-adjoint operator defined by 
\[
\ad_{\hat{O}}^+ \R = \{\R,\hat{O}\} = \R\hat{O}+\hat{O}\R.
\]
Any operator in Eq.~\eqref{eq:basis_of_go(1)} can be rewritten as a quadratic expression in $\ad_{\x}$, $\ad_{\p}$, $\ad^+_{\x}$, and $\ad^+_{\p}$ as
\[\label{eq:ad_basis_change}\begin{split}
&\ad_{\hat{N}} = \tfrac{1}{2}(\ad_{\x}\ad_{\x}^+ +\ad_{\p}\ad_{\p}^+),\quad \ad_{\hat{X}} = \tfrac{1}{2}(\ad_{\p}\ad_{\x}^+ +\ad_{\x}\ad_{\p}^+),\\
&\ad_{\hat{Y}} = \tfrac{1}{2}(\ad_{\x}\ad_{\x}^+ -\ad_{\p}\ad_{\p}^+),\quad L_{\x\p}^- = \tfrac{1}{2}(\ad_{\x}\ad_{\p}^+ -\ad_{\p}\ad_{\x}^+),\\
&L_{\x\x}^+ = \ad_{\x}\ad_{\x},\quad L_{\x\p}^+ = \ad_{\x}\ad_{\p},\quad L_{\p\p}^+ = \ad_{\p}\ad_{\p},
\end{split}
\]
The reason why we rewrite it this way is to use the simple commutation relation between $\ad_{\x}$, $\ad_{\p}$, $\ad^+_{\x}$, and $\ad^+_{\p}$. There are only two non-trivial commutation relations,
\[\begin{split}
    [\ad_{\x}, \ad_{\p}^+]& =- \ad_{\I}^+=-2,\\
    [\ad_{\p}, \ad_{\x}^+]& = \ad_{\I}^+=2,
\end{split}
\]
while the remaining commutation relations between $\ad_{\x}$, $\ad_{\p}$, $\ad^+_{\x}$, and $\ad^+_{\p}$ are zero. Using this, we can obtain all commutation relations between operators in Eq.~\eqref{eq:basis_of_go(1)}, for example, 
\[
[L_{\x\x}^+, L_{\p\p}^+]=[\ad_{\x}\ad_{\x},\ad_{\p}\ad_{\p}]=0,
\]
by using $[\ad_{\x},\ad_{\p}]=0$.

We classify the operators according to whether they have a zero commutation relation, and make a Lie algebra by spanning them.
\[\begin{split}
    \mathfrak{g}&\equiv\mathrm{Span}(\ad_{\hat{N}},\ad_{\hat{X}},\ad_{\hat{Y}},L_{\x\p}^-)\\
    \mathfrak{h}&\equiv\mathrm{Span}(\ad_{\x},\ad_{\p},L_{\x\x}^+,L_{\p\p}^+,L_{\x\p}^+).
\end{split}
\]
It is obvious $\mathfrak{go}(1)=\mathfrak{g}\times\mathfrak{h}$. Further, $[\mathfrak{h},\mathfrak{h}]=0$, meaning that every element of $\mathfrak{h}$ commutes with every other element of $\mathfrak{h}$, since the commutation relation between $\ad_{\x}$ and $\ad_{\p}$ is zero. What remains is to determine the commutation relations $[\mathfrak{g},\mathfrak{g}]$ and $[\mathfrak{g},\mathfrak{h}]$. Every element $g\in\mathfrak{g}$ can be represented by a corresponding two-by-two real matrix, $\Gamma$,
as 
\[
\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\Gamma
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix} \in \mathfrak{g}.
\]
The basis of $\mathfrak{g}$ is given by
\[\begin{split}\label{eq:gl_2_rep}
\ad_{\hat{N}} &= 
\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\begin{pmatrix}
0 & -1 \\
1 & 0 \\
\end{pmatrix}
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},\\
\ad_{\hat{X}} &=\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\begin{pmatrix}
-1 & 0 \\
0 & 1 \\
\end{pmatrix}
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},\;\\
\ad_{\hat{Y}} &= \begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\begin{pmatrix}
0 & 1 \\
1 & 0 \\
\end{pmatrix}
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},\\
L_{\x\p}^{-} &= \begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\begin{pmatrix}
1 & 0 \\
0 & 1 \\
\end{pmatrix}
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix}.
\end{split}
\]
With this, using $\tr([\Gamma_1,\Gamma_2])=0$, we can derive the communutation relation relation $[g_1,g_2]$ for any two elements $g_1,g_2\in \mathfrak{g}$ as
\[\begin{split}
[g_1,g_2] &= \left[\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\Gamma_1
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\Gamma_2
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix}\right] \\
&=\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
[\Gamma_1,\Gamma_2]
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix}\in \mathfrak{g}.
\end{split}
\]
Additionally, because $\Gamma_{\hat{N}},\Gamma_{\hat{X}},\Gamma_{\hat{Y}},\Gamma_{L_{\x\p}^-}$ for a basis of two-by-two real matrices, we can rewrite the commutator $[\Gamma_1,\Gamma_2]$ as a linear combination of these matrices. As a result, we can also rewrite $[g_1,g_2]$ as the linear combination of the basis vectors, $\ad_{\hat{N}},\ad_{\hat{X}},\ad_{\hat{Y}},L_{\x\p}^-$, thus, $[g_1,g_2]\in \mathfrak{g}$.

We can also notice that for any two elements, the commutation relation $[g_1,g_2]$ corresponds exactly to the commutation relation of $[\Gamma_1,\Gamma_2]$, meaning that the factors in the resulting linear combination is the same. Hence, these Lie algebras are isomorphic, $\mathfrak{g}\approx\mathfrak{gl}(2,\mathbb{R})$.

Moreover, $\mathfrak{g}$ is a subspace of $\mathfrak{go}(1)=\mathfrak{g}\times\mathfrak{h}$, and due to its closeness, $[\mathfrak{g},\mathfrak{g}]\subset\mathfrak{g}$, $\mathfrak{g}$ forms a Lie algebra. Thus, $\mathfrak{g}$ is a Lie subalgebra of $\mathfrak{go}(1)$.

Finally, we are going to illustrate the remaining commutation relations, $[\mathfrak{g},\mathfrak{h}]$. Each linear element $h_1\in \mathfrak{h}_1\equiv\mathrm{Span}(\ad_{\x},\ad_{\p})$, is represented a two dimensional vector, $\bold{v}$, as
\[\label{eq:ad_vector}
\begin{pmatrix}
    -\ad_{\p} & \ad_{\x} 
\end{pmatrix}\bold{v}=h_1\in \mathfrak{h},
\]
where, the basis is given by
\[
\ad_{\x}=\begin{pmatrix}
    -\ad_{\p} & \ad_{\x} 
\end{pmatrix}\begin{pmatrix}
    0\\
    1
\end{pmatrix},\;\ad_{\p}=\begin{pmatrix}
    -\ad_{\p} & \ad_{\x} 
\end{pmatrix}\begin{pmatrix}
    -1\\
    0
\end{pmatrix}.
\]
With this, we derive the commutation relation between $g\in\mathfrak{g}$ and $h_1\in\mathfrak{h}$,
\[\begin{split}\label{eq:[g,h1]}
[g,h_1] &= \left[\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\Gamma
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},\begin{pmatrix}
    -\ad_{\p} & \ad_{\x} 
\end{pmatrix}\bold{v}\right] \\
&=\begin{pmatrix}
    \ad_{\p} & -\ad_{\x} 
\end{pmatrix}(\Gamma\bold{v})\in \mathfrak{h},
\end{split}
\]
because $\Gamma\bold{v}$ is also a two-dimensional real vector.

The quadratic ordered operators, $L_{\x\x}^+$, $L_{\p\p}^+$, and $L_{\x\p}^+$, are represented by a real symmetric two-by-two matrix, $D$, as
\[
 \begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}D\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix}=h_2\in\mathfrak{h}_2,
\]
where the basis of $\mathfrak{h}_2 \equiv\mathrm{Span}(L_{\x\x}^+,L_{\p\p}^+,L_{\x\p}^+)$ is given by
\[\begin{split}
    L_{\x\x}^{+}  &= \begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}\begin{pmatrix}
0 & 0 \\
0 & 1 \\
\end{pmatrix}\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix},\\
 L_{\p\p}^{+}  &= \begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}\begin{pmatrix}
1 & 0 \\
0 & 0 \\
\end{pmatrix}\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix},\\
 L_{\x\p}^{+}  &= \begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}\begin{pmatrix}
0 & -1/2 \\
-1/2 & 0 \\
\end{pmatrix}\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix},
\end{split}
\]


which act on the matrix in Eq.~\eqref{eq:gl_2_rep}. The commutation relation between them with $g\in\mathfrak{g}$ at the matrix representation is given by 
\[\begin{split}\label{eq:[g,h2]}
[g,h_2] &= \left[\begin{pmatrix}
-\ad_{\p} &
\ad_{\x} 
\end{pmatrix} 
\Gamma
\begin{pmatrix}
\frac{\ad^+_{\x}}{2} \\ \frac{\ad_{\p}^+}{2} 
\end{pmatrix},
\begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}D\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix}\right] \\
&=\begin{pmatrix}
-\ad_{\p} & \ad_{\x} \\
\end{pmatrix}(\Gamma D+D\Gamma^\top)\begin{pmatrix}
-\ad_{\p} \\
\ad_{\x} \\
\end{pmatrix}\in \mathfrak{h},
\end{split}
\]
because $\Gamma D+D\Gamma^\top$ is a real symmetric two-by-two matrix.

Since $\mathfrak{h}=\mathfrak{h}_1\times\mathfrak{h}_2$, we considered all commutation relation between $g\in \mathfrak{g}$ and $h\in \mathfrak{h}$.
As a result, $[\mathfrak{g},\mathfrak{h}] \subset \mathfrak{h}$ means $\mathfrak{h}$ is \emph{ideal} on $\mathfrak{go}(1) = \mathfrak{g}\oplus \mathfrak{h}$.

To summarize the results, $\mathfrak{g}\approx\mathfrak{gl}(2,\mathbb{R})$ is a Lie subalgebra of $\mathfrak{go}(1)$ and $\mathfrak{h}\approx \mathbb{R}^5$ is ideal of $\mathfrak{go}(1)$. The results say that $\mathfrak{go}(1)$ is an extended Lie algebra, $\mathfrak{gl}(2,\mathbb{R})$ by $\mathbb{R}^5$, denoted $\mathfrak{gl}(2,\mathbb{R})\oplus_S\mathbb{R}^5$, where $\oplus_S$ denotes a semidirect sum.

\subsection{Multi bosonic mode: Theorem~\ref{theorem:lie_go(n)}}\label{subsection:proof_of_go(n)}
$\mathfrak{go}(n)$ is the vector space over the real number,$\mathbb{R}$, which has $9n$ basis as
\[\begin{split}\label{eq:single_basis_of_go(n)}
&\ad_{\hat{N_i}},\;\ad_{\hat{X_i}},\;\ad_{\hat{Y_i}},\;\ad_{\hat{x_i}},\;\ad_{\hat{p_i}},\\
&L_{\x_i\x_i}^{+},\; L_{\x_i\p_i}^{+},\; L_{\p_i\p_i}^{+},\; L_{\x_i\p_i}^{-},
\end{split}
\]
for $1\leq i\leq n$ acting on single mode, which we dealt with before. Meanwhile, there is another basis acting on bimode,
\[\begin{split}\label{eq:bi_basis_of_go(n)}
    &\ad_{\hat{N}_{ij+}},\;\ad_{\hat{N}_{ij-}},\;\ad_{\hat{X}_{ij}},\;\ad_{\hat{Y}_{ij}},\\
    &L_{\x_i\x_j}^+,\;L_{\p_i\x_j}^+,\;L_{\x_i\p_j}^+,\;L_{\x_i\x_j}^+,\\
    &L_{\x_i\x_j}^-,\;L_{\p_i\x_j}^-,\;L_{\x_i\p_j}^-,\;L_{\x_i\x_j}^-,\\
\end{split}
\]
for $1\leq i< j \leq n $

We mentioned that the commutation operator $[A, B]$ is a bilinear operator, satisfying the condition for a Lie algebra. To complete the proof, we have to show the closeness of $\mathfrak{go}(n)$ under commutation, and their structure of them.

Like the single mode case, $\mathfrak{go}(1)$, we represent the basis of $\mathfrak{go}(n)$ by using $\ad_{\x_i}$, $\ad_{\p_i}$, $\ad^+_{\x_i}$, and $\ad^+_{\p_i}$.
The single-mode operators at Eq.~\eqref{eq:single_basis_of_go(n)} are equivalent to Eq.~\eqref{eq:basis_of_go(1)}.
\[\begin{split}\label{eq:bimode_for_g}
    &\ad_{\hat{N}_{ij+}} = \tfrac{1}{4}(\ad_{\x_i}\ad_{\x_j}^+ + \ad_{\x_j}\ad_{\x_i}^+ + \ad_{\p_i}\ad^+_{\p_j}+\ad_{\p_j}\ad^+_{\p_i}),\\
    &\ad_{\hat{N}_{ij-}} = \tfrac{1}{4}(\ad_{\p_i}\ad_{\x_j}^+ + \ad_{\x_j}\ad_{\p_i}^+ - \ad_{\x_i}\ad^+_{\p_j} - \ad_{\p_j}\ad^+_{\x_i}),\\
    &\ad_{\hat{X}_{ij}} = \tfrac{1}{4}(\ad_{\x_i}\ad_{\p_j}^+ +\ad_{\p_j}\ad_{\x_i}^+ + \ad_{\x_j}\ad^+_{\p_i}+\ad_{\p_i}\ad^+_{\x_j}),\\
    &\ad_{\hat{Y}_{ij}} = \tfrac{1}{4}(\ad_{\x_i}\ad_{\x_j}^+ +\ad_{\x_j}\ad_{\x_i}^+ - \ad_{\p_i}\ad^+_{\p_j}-\ad_{\p_j}\ad^+_{\p_i}) ,\\
    &L_{\x_i\x_j}^- = \tfrac{1}{2}(\ad_{\x_i}\ad_{\x_j}^+ -\ad_{\x_j}\ad_{\x_i}^+) ,\\
    &L_{\x_i\p_j}^- = \tfrac{1}{2}(\ad_{\x_i}\ad_{\p_j}^+ -\ad_{\p_j}\ad_{\x_i}^+) ,\\    
    &L_{\p_i\x_j}^- = \tfrac{1}{2}(\ad_{\p_i}\ad_{\x_j}^+ -\ad_{\x_j}\ad_{\p_i}^+) ,\\    
    &L_{\p_i\p_j}^- = \tfrac{1}{2}(\ad_{\p_i}\ad_{\p_j}^+ -\ad_{\p_j}\ad_{\p_i}^+) ,\\
\end{split}
\]
and
\[\begin{split}\label{eq:bimode_for_h}
    &L_{\x_i\x_j}^+ =\ad_{\x_i}\ad_{\x_j},\;L_{\x_i\p_j}^+ =\ad_{\x_i}\ad_{\p_j},\;\\
    &L_{\p_i\x_j}^+ =\ad_{\p_i}\ad_{\x_j},\;L_{\p_i\p_j}^+ =\ad_{\p_i}\ad_{\p_j},\;\\
\end{split}
\]

Let us classify the operators
\begin{align}
    \mathfrak{g}&\equiv\mathrm{Span}(\ad_{\hat{N_i}}\!,\ad_{\hat{X_i}}\!,\ad_{\hat{Y_i}}\!,L_{\x_i\p_i}^-\!,\, \mathrm{Eq.~}\eqref{eq:bimode_for_g}),&1\leq i<j\leq n, \label{eq:definition_of_g_in_appen}\\
    \mathfrak{h}_1&\equiv\mathrm{Span}(\ad_{\x_i},\ad_{\p_i}),&1\leq i\leq n,\label{eq:definition_of_h1_in_appen}\\
    \mathfrak{h}_2&\equiv\mathrm{Span}(L_{\x_i\x_i}^+,L_{\p_i\p_i}^+,L_{\x_i\p_i}^+,\, \mathrm{Eq.~}\eqref{eq:bimode_for_h}),&1\leq i<j\leq n.\label{eq:definition_of_h2_in_appen}
\end{align}
We define $\mathfrak{h}\equiv\mathfrak{h}_1\times\mathfrak{h}_2$.
We can write $\mathfrak{go}(n)=\mathfrak{g}\times\mathfrak{h}$ and $[\mathfrak{h},\mathfrak{h}]=0$. 

Let's represent $\mathfrak{g}$ and $\mathfrak{h}$ by finite dimensional matrices. Because we have many adjoint and anti-adjoint operators of $\x_i$ and $\p_i$, it is convenient to use vectorization. 
We define the vector 
\[\begin{split}
    \vec{\ad}=\begin{pmatrix}
    -\ad_{\p_1}\\
    \vdots\\
    -\ad_{\p_n}\\
    \ad_{\x_1}\\
    \vdots\\
    \ad_{\x_n}
\end{pmatrix},\quad
\vec{\ad^+}=\begin{pmatrix}
    \ad_{\x_1}^+\\
    \vdots\\
    \ad_{\x_n}^+\\
    \ad_{\p_1}^+\\
    \vdots\\
    \ad_{\p_n}^+
\end{pmatrix},\quad
\end{split}
\]
For single mode, elements of $\mathfrak{go}(1)$ have one to one relation with a two-by-two real matrix, $\Gamma$. For multi mode, the elements of $\mathfrak{go}(n)$, have one to one relation with a $2n$ by $2n$ real matrix, $\Gamma$, as
\[\frac{1}{2} \vec{\ad}^\top
\Gamma\vec{\ad^+} \in \mathfrak{g}.
\]
The commutation relation $[g_1,g_2]$ for elements of $g_1,g_2\in \mathfrak{g}$ as

\[\begin{split}
[g_1,g_2] &= \left[\frac{1}{2} \vec{\ad}^\top
\Gamma_1\vec{\ad^+} ,
\frac{1}{2} \vec{\ad}^\top
\Gamma_2\vec{\ad^+} 
\right] = \tfrac{1}{2} \vec{\ad}^\top[\Gamma_1,\Gamma_2]\vec{\ad^+}\end{split}
\]

The linear ordered operators, $\ad_{\x_i}$, and $\ad_{\p_i}$ are represented by real vector, $\bold{v}$, as
\[
\vec{\ad}^\top\bold{v}=h_1\in\mathfrak{h}_1,
\]
 The commutation relation between them with $g\in\mathfrak{g}$ at the matrix representation is given by 
\[\begin{split}\label{eq:[g,h2]_multi_mode}
[g,h_1] &= \left[
\tfrac{1}{2}\vec{\ad}^\top\Gamma\vec{\ad^+},
\vec{\ad}^\top\bold{v}
\right] =\vec{\ad}^\top
\Gamma \bold{v}\in \mathfrak{h}_1.
\end{split}
\]


The quadratic ordered operator, $L_{\x_i\x_j}^+$, $L_{\p_i\p_j}^+$, and $L_{\x_i\p_j}^+$, are represented by two-by-two symmetric real matrix, $D$, as
\[
\vec{\ad}^\top
D
\vec{\ad}=h_2\in\mathfrak{h}_2,
\]
 The commutation relation between them with $g\in\mathfrak{g}$ at the matrix representation is given by 
\[\begin{split}\label{eq:[g,h2]_multi_mode}
[g,h_2] &= \left[
\tfrac{1}{2}\vec{\ad}^\top\Gamma\vec{\ad^+},
\vec{\ad}^\top
D
\vec{\ad}
\right] =\vec{\ad}^\top
(\Gamma D+D\Gamma^\top)
\vec{\ad}\in \mathfrak{h}_2.
\end{split}
\]


As a result, we know that $[\mathfrak{g},\mathfrak{h}] \subset \mathfrak{h}$, which means $\mathfrak{h}$ is \emph{ideal} on $\mathfrak{go}(1) = \mathfrak{g}\oplus \mathfrak{h}$. The dimension of $\mathfrak{h}$ is $2n^2+3n$.

To summarize the results, $\mathfrak{g}\approx\mathfrak{gl}(2n,\mathbb{R})$ is a Lie subalgebra of $\mathfrak{go}(n)$ and $\mathfrak{h}\approx \mathbb{R}^{2n^2+3n}$ is ideal of $\mathfrak{go}(1)$. The results say that $\mathfrak{go}(1)$ is an extended Lie algebra, $\mathfrak{gl}(2n,\mathbb{R})$ by $\mathbb{R}^{2n^2+3n}$.

\section{Proof of Theorem~\ref{theorem:cptp}}\label{subsection:proof_cptp}

To satisfy the CPTP condition, a Lindblad operator needs to be positive. The positivity of the Lindblad operator indicates that the Lindblad operator has to be express in the following form,
\[\label{eq:general_Lindblad}
\mathcal{L}=\sum_k \hat{A}_k\bullet \hat{A}_k^\dagger-\tfrac{1}{2}\{\hat{A}_k^\dagger \hat{A}_k,\bullet \},
\]
where $A_j$ can be non-Hermitian operators. Let us represent Eq.~\eqref{eq:general_Lindblad} by Hermite operator $\hat{O}_j$ as
\[\label{eq:general_Lindblad_by_hermitian}
\mathcal{L}=\sum_{j,k} \gamma_{jk}\left(\hat{O}_k\bullet \hat{O}_j-\tfrac{1}{2}\{\hat{O}_j \hat{O}_k,\bullet \}\right).
\]
We can define the matrix $\gamma$ composed of $\gamma_{jk}$'s. $\mathcal{L}$ has to be Hermitian, so $\gamma_{kj}$ is complex conjugate of $\gamma_{jk}$, $\gamma_{jk}=\gamma_{kj}^*$. The condition provides the fact that $\gamma$ is hermitian, $\gamma = \gamma^\dagger$.
To make Eq.~\eqref{eq:general_Lindblad_by_hermitian} equivalent to Eq.~\eqref{eq:general_Lindblad}, $\gamma$ has to be a semi-definite positive matrix, $\gamma\geq0$.

At $\mathfrak{go}(1)$, there are four elements related to the Lindblad operator, $L_{xx}^+$, $L_{xp}^+$, $L_{pp}^+$, and $L_{xp}^-$. The linear combination of them is written as
\[\begin{split}\label{eq:lind_by_go}
    \go &= \gamma_{\x\x}^+L_{\x\x}^+ +\gamma_{\x\p}^+L_{\x\p}^+ +\gamma_{\p\p}^+L_{\p\p}^+ +\gamma_{\x\p}^-L_{\x\p}^- \\
    &= 2\gamma_{\x\x}^+\left(\x\bullet\x -\tfrac{1}{2}\{\x^2,\bullet\}\right) +2\gamma_{\p\p}^+\left(\p\bullet\p -\tfrac{1}{2}\{\p^2,\bullet\}\right) \\
    &+(\gamma_{\x\p}^+ +i\gamma_{\x\p}^- )\left(\x\bullet\p -\tfrac{1}{2}\{\p\x,\bullet\}\right) \\
    &+(\gamma_{\x\p}^+ -i\gamma_{\x\p}^- )\left(\p\bullet\x -\tfrac{1}{2}\{\x\p,\bullet\}\right).
\end{split}
\]
To make $\go$ satisfy CPTP condition, $\gamma$ given by,
\[\gamma =
\begin{pmatrix}
    2\gamma_{\x\x}^+ & \gamma_{\x\p}^+ +i\gamma_{\x\p^{-}}\\
    \gamma_{\x\p}^+ -i\gamma_{\x\p^{-}} & 2\gamma_{\p\p}^+
\end{pmatrix},
\]
has to be semi-definite positive. Since $\gamma$ is a two-by-two matrix, it is easy to determine whether $\gamma$ is semi-definite positive or not. $\gamma$ is semi-definite positive, if and only if, $\mathrm{det}(\gamma)\geq 0$, and $\tr(\gamma)\geq$. Hence, $\go$ satisfy the CPTP condition, if and only if, 
\[
\mathrm{det}(\gamma)=4\gamma_{\x\x}^+\gamma_{\p\p}^+-(\gamma_{\x\p}^{+})^2-(\gamma_{\x\p}^{-})^2\geq0,
\]
and 
\[
\tr(\gamma)=\gamma_{\x\x}^++\gamma_{\p\p}^+ \geq 0
\]


\section{Proof of Theorem~\ref{theorem:existence_of_GGO}}\label{section:proof_existence}

We will prove this statement for a multi-mode bosonic system with an arbitrary number of modes, $n$. The result for a single bosonic mode then follows as a special case as $n=1$.

Williamson decomposition allows any Gaussian state to be represented as a Gaussian unitary acting on a tensor product of thermal states, as
\[
\R = \U_G \bigotimes_{i=1}^n \R_{\mathrm{th}}^{(i)}(\beta_i)\U_G^\dagger,
\]
where $\R_{\mathrm{th}}^{(i)}(\beta_i)$ denotes the thermal state of the $i$th mode at inverse temperature $\beta_i$~\cite{Williamson1936, Weedbrook2012}. The thermal state at $\beta$ is 
\[
\R_{\mathrm{th}}(\beta)=(1-e^{-\beta})\sum_{m\geq 0}\pro{m}{m}.
\]
$\mathfrak{go}(n)$ contains all the generators that produce Gaussian unitaries through conjugation. Therefore, there exists an element $\go_{U}$ that satisfies
\[
\R = \exp(\go_{U_G})\bigotimes_{i=1}^n \R_i(\beta_i).
\]
Since unitary transformations are CPTP, $\exp(\go_{U_G})\in \mathrm{GO}^+(n)$ is the CPTP map. Moreover, since the inverse of a unitary operator is also unitary, and thus a CPTP map, it follows that $\exp(-\go_{U_G})\in\mathrm{GO}^+(n)$ is also a CPTP map; Gaussian unitary operators can freely modify the symplectic structure. To prove the proposition, it suffices to show that $\beta_i$ can be adjusted using CPTP elements of $\mathfrak{go}(n)$.

To demonstrate that CPTP elements of $\mathfrak{go}(n)$ can control the temperature, we propose two specific elements, composed of $L_{\x\x}^+$, $L_{\p\p}^+$, and $L_{\x\p}^-$,
\begin{eqnarray}
\go_{\beta_i \downarrow}  &=&\tfrac{1}{4} L_{\x_i\x_i}^+ + \tfrac{1}{4}L_{\p_i\p_i}^+ + \tfrac{1}{2} L_{\x_i\p_i}^-=\an^\dagger_i \bullet \an_i - \tfrac{1}{2}\{\an_i\an_i^\dagger,\bullet\}\\
\go_{\beta_i \uparrow} &=&\tfrac{1}{4} L_{\x_i\x_i}^+ + \tfrac{1}{4}L_{\p_i\p_i}^+ - \tfrac{1}{2} L_{\x_i\p_i}^-=\an_i\bullet\an_i^\dagger -\tfrac{1}{2}\{\an_i^\dagger \an_i,\bullet\}.
\end{eqnarray}
Theorem~\ref{theorem:cptp} guarantees that $go_{\beta_i \downarrow} $ and $\go_{\beta_i \uparrow}$ satisfy the CPTP condition.

From the relation between $\beta_i$ and mean photon number, $\mean{\hat{N_i}}=\tr(\N_i \R_{\mathrm{th}}^{(i)}(\beta_i) )$,
\[\label{eq:relation_beta_N}
\beta_i=\ln(\frac{\mean{\hat{N_i}}+1}{\mean{\hat{N_i}}}),
\]
we can characterize the thermal state by $\mean{\N_i}$. By examining how $\go_{\beta_i \downarrow}$ and $\go_{\beta_i \uparrow}$ transform $\mean{\N_i}$, we can see how it affects $\beta$

Let us first consider the case of $\go_{\beta_i \downarrow}$.
By the adjoint Lindblad equation, we obtain the time derivative of $\hat{N}_i$ by $\go_{\beta_i \downarrow}$ and $\go_{\beta_i\uparrow}$. The adjoint Lindblad equation corresponding to $\go_{\beta_i \downarrow}$ is given by
\[
\frac{d}{dt}\mean{\hat{N}_i}=\mean{\frac{d}{dt}\hat{N}_i}=\mean{\an_i\hat{N}_i\an_i^\dagger -\{\tfrac{1}{2}{\an_i\an_i^\dagger,\hat{N}_i}\}}=\mean{\hat{N}_i}+1,
\]
which follows the 
\[\label{eq:N(t)_down}
\mean{\hat{N}_i}(t)=e^t\left(\mean{\hat{N}_i}(0)+1\right)-1.
\]

Eq.~\eqref{eq:relation_beta_N} and Eq.~\eqref{eq:N(t)_down} yields,
\[
\exp(\go_{\beta_i\downarrow}t)\R_{\mathrm{th}}^{(i)}(\beta_i) = \R_{\mathrm{th}}^{(i)}(\beta_i(t)),
\]
where $\beta_i(t)$ is given by
\[\label{eq:beta_t}
\beta_i(t)=\ln(\frac{e^t\left(\mean{\hat{N}_i}+1\right)}{e^t\left(\mean{\hat{N}_i}+1\right) -1}) \leq \beta_i,
\]
and $\mean{\hat{N}_i} = \frac{1}{e^{\beta_i}-1}$. $\beta_i(t)$ is monotonically decreasing to zero by $t$.

Likewise, we can obtain the adjoint Lindblad equation for $\go_{\beta\uparrow}$, as
\[
\frac{d}{dt}\mean{\hat{N}_i}=\mean{\frac{d}{dt}\hat{N}_i}=\mean{\an_i^\dagger\hat{N}_i\an_i -\{\tfrac{1}{2}{\an_i^\dagger\an_i,\hat{N}_i}\}}=-\mean{\hat{N}_i},
\]
which follows the 
\[
\mean{\hat{N}_i}(t)=e^{-t}\mean{\hat{N}_i}(0),
\]
and we have the relation
\[
\exp(\go_{\beta_i\uparrow}t)\R_{\mathrm{th}}^{(i)}(\beta_i) = \R_{\mathrm{th}}^{(i)}(\beta_i(t)),
\]
where $\beta_i(t)$ is given by
\[\label{eq:beta_t}
\beta_i(t)=\ln(\frac{e^{-t}\mean{\hat{N}_i} +1}{e^{-t}\mean{\hat{N}_i}}),
\]
and $\mean{\hat{N}_i} = \frac{1}{e^{\beta_i}-1}$. $\beta(t)$ is monotonically increasing to infinity by $t$. 

Therefore, we can control $\beta_i$ to take any value in $(0,\infty)$ using $\exp(go_{\beta_i\downarrow}t)$ and $\exp(go_{\beta_i\uparrow}t)$.

Now we are ready to construct the CPTP element $\mathcal{E}_{\R\rightarrow\R'}\in \overline{\mathrm{GO}^+(n)}$
Let's assume that there is two gaussian states, $\R$ and $\R'$, which can be written as
\[
\begin{split}
    \R &= \U_G \bigotimes_{i=1}^n \R_{\mathrm{th}}^{(i)}(\beta_i)\U_G^\dagger,\\
    \R' &= \U_G' \bigotimes_{i=1}^n \R_{\mathrm{th}}^{(i)}(\beta_i')(\U_G')^{\dagger},   
\end{split}
\]
As we discussed, there exist $\exp(-\go_{U_G})\in\mathrm{GO}(n)$ and $\exp(\go_{U'_G})$, can connect $\R$ and $\R'$ to thermal states as
\[
\begin{split}
    \bigotimes_{i=1}^n \R_{\mathrm{th}}^{(i)}(\beta_i)&=\exp(-\go_{U_G})\R,\\
    \R' &= \exp(\go_{U'_G}) \bigotimes_{i=1}^n \R_{\mathrm{th}}^{(i)}(\beta_i'),   
\end{split}
\]

Let's define the set of indices 
$i$ for which $\beta_i\geq\beta_i'$ or $\beta_i<\beta_i'$,
\begin{eqnarray}
    A_{\beta\downarrow}&=&\{1\leq i\leq n | \beta_i\geq\beta_i' \}\\
    A_{\beta\uparrow}&=&\{1\leq i\leq n | \beta_i<\beta_i',\beta_i'\neq \infty \}\\
    A_{\beta=\infty}&=&\{1\leq i\leq n |\beta_i'=\infty \}
    %A_{\beta=\infty}&=&\{1\leq i\leq n | \beta_i'=\infty \}.
\end{eqnarray}
We classified $i$'s not only based on the order between $\beta_i$ and $\beta_i'$, but also on whether $\beta_i'$ is infinity or not. This classification is necessary because when $\beta_i'$ is infinity, there is no element of $\mathrm{GO}^+(n)$ that can connect $\R$ to $\R'$. 
We typically do not consider the case of inverse temperature $\beta=0$, infinite temperature. This is because in that case, the density matrix, $\R$
becomes the identity operator, which is no longer trace-class in an infinite-dimensional Hilbert space. 

If $ A_{\beta=\infty} =\emptyset$, then there exist $t_i\in [0,\infty)$, such that a CPTP element $\mathcal{E}_{\R\rightarrow \R'}\in \mathrm{GO}^+(n)$  can be constructed as
\[
\R' = \mathcal{E}_{\R \rightarrow \R'}\R =\exp(\go_{U_G'}) \prod_{i\in A_{\beta\downarrow}}\exp(\go_{\beta_i\downarrow}t_i) 
\prod_{i\in A_{\beta\uparrow}}\exp(\go_{\beta_i\uparrow}t_i)
\exp(-\go_{U_G})\R
\]

If $ A_{\beta=\infty} \neq\emptyset$, we can instead construct a sequence of CPTP elements $\mathcal{E}_k\in\mathrm{GO}^+(n)$ for $k\in\mathbb{N}$, as
\[
\mathcal{E}_{k} =\exp(\go_{U'}) \prod_{i\in A_{\beta\downarrow}}\exp(\go_{\beta_i\downarrow}t_i) 
\prod_{i\in A_{\beta\uparrow}}\exp(\go_{\beta_i\uparrow}t_i)\prod_{i\in A_{\beta=\infty}}\exp(\go_{\beta_i\uparrow}k)
%\prod_{i\in A_{\beta=\infty}}\exp(\go_{\beta_i\uparrow}k)
\exp(-\go_{U}).
\]
Taking the limit $\lim_{k\rightarrow\infty}\mathcal{E}_k = \mathcal{E}_{\R\rightarrow\R'}\in\overline{\mathrm{GO}^+(n)}$ we obtain a CPTP map in the closure of $\mathrm{GO}^+(n)$ that connects the two Gaussian states,
\[
\R =\mathcal{E}_{\R\rightarrow\R'}\R'
\]
Since we have shown that a CPTP element in $\overline{\mathrm{GO^+(n)}}$ exists for all cases, the statement holds.

\section{Proof of Theorem~\ref{proposition:Gaussian_channel}}\label{section:proof_of_GO+}

We will prove this statement for a multi-mode bosonic system with an arbitrary number of modes, $n$. The result for a single bosonic mode then follows as a special case as $n=1$.

Moreover, for convenience, we will utilize the result of Theorem~\ref{theorem:general_sol_multi} in the proof. It is important to emphasize, however, that the proof of Theorem~\ref{theorem:general_sol_multi} does not depend on Theorem~\ref{proposition:Gaussian_channel}, and thus, the argument in this paper does not involve circular reasoning.

Assume a Gaussian state, $\R$, characterized by an arbitrary covariance matrix $\sigma$ and displacement vector $\bold{d}$, which are defined as
\begin{eqnarray}
    \bold{d}_i &=&\begin{cases} 
		\mean{\x_i} & \mathrm{if}\;i\leq n \\ 
        \mean{\p_{i-n}} & \mathrm{if}\;i>n 
     \end{cases},\\
      \sigma_{ij} &=& \begin{cases} 
		\tfrac{1}{2}\mean{\{\x_i,\x_j\}}-\mean{\x_i}\mean{\x_j} & \mathrm{if}\;i,j\leq n \\ 
       \tfrac{1}{2}\mean{\{\x_i,\p_{j-n}\}}-\mean{\x_i}\mean{\p_{j-n}} & \mathrm{if}\;i\leq n\;\mathrm{and}\;j>n \\
       \tfrac{1}{2}\mean{\{\p_{i-n},\x_{j}\}}-\mean{\p_{i-n}}\mean{\x_{j}}& \mathrm{if}\;i>n\;\mathrm{and}\;j\leq n \\
        \tfrac{1}{2}\mean{\{\p_{i-n},\p_{j-n}\}}-\mean{\p_{i-n}}\mean{\p_{j-n}} & \mathrm{if}\;t>n 
     \end{cases},\\
\end{eqnarray}
where $\mean{\hat{O}}=\tr(\R\hat{O})$.
By using the result of Theorem~\ref{theorem:general_sol_multi},
$\R$ is evolved to $\R'$ under $\mathcal{E}_G=(D\oplus \bold{v})\oplus_{\mathrm{S}}M\in \mathrm{GO}^+(n)$ satisfying CPTP codition.
While there are no constraints on $\bold{v}$ and $D$, the matrix $M$ must satisfy the condition $\mathrm{det}(M)> 0$. $\R'$ is also a Gaussian state with its covariance matrix and displacement vector, as
\begin{eqnarray}
\sigma\; &\overset{\mathcal{E}_G}{\longrightarrow}& \;\sigma' =M\sigma M^\top +2D \label{eq:sigam_tran}\\
\bold{d}\; &\overset{\mathcal{E}_G}{\longrightarrow}& \;\bold{d}'= M\bold{d} + \bold{v}\label{eq:d_tran}.
\end{eqnarray}
where, $\mathrm{det}(M)> 0$, since $M\in \mathrm{GL}^+(2n)$.

Moreover, there exists a sequence $\mathcal{E}_{G,k}\in \mathrm{GO}^+(n)$ such that $\lim_{k\rightarrow\infty}\mathcal{E}_{G,k}\cong (D\oplus \bold{v})\oplus_{\mathrm{S}}M$, where determinant of $M$ is zero. Consequently, $\overline{\mathrm{GO^+(n)}}$ includes elements, $\mathcal{E}_G$ that give rise to transformations, Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran},
where $\mathrm{det}(M)\geq0$.

We claim that the CPTP element of $\overline{\mathrm{GO^+}(1)}$ is an infinitesimally divisible Gaussian quantum channel. A Gaussian quantum channel is infinitesimally divisible if and only if:
(1) it transforms the covariance matrix and displacement vector according to Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran}, (2)  $\mathrm{det}(M)\geq 0$, and (3) it follows the CPTP condition~\cite{Teiko2009}. We have shown that any CPTP element (condition (3)) of $\overline{\mathrm{GO}^+(n)}$ transforms the covariance matrix and displacement vector as Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran} (condition (1)), and that $\mathrm{det}(M)\geq 0$ (condition (2)). Hence, the proposition is proven.

\section{Proof of Theorem~\ref{proposition:Gaussian_channel_2}}\label{section:proof_Gassian=GO}

We will prove this statement for a multi-mode bosonic system with an arbitrary number of modes, $n$. The result for a single bosonic mode then follows as a special case as $n=1$.

As discussed in Section~\ref{section:proof_of_GO+}, we use results of Theorem~\ref{theorem:general_sol_multi} in our proof, but we explicitly clarify that this does not result in circular reasoning. 

We begin by addressing the definition of $\mathrm{GO}(n)$ or a general $n$, which is not included in the main text. To define $\mathrm{GO}(n)=\mathrm{GO}^+(n)\cup\mathrm{GO}^{-}(n)$, we first need to define $\mathrm{GO}^-(n)$, whose definition slightly differs from the case of $n=1$. While $\mathrm{GO}^-(1)$ was defined via the transpose channel, its definition for $\mathrm{GO}^{-1}(n)$ involves the partial transpose channel. 
the partial transpose channel, $\mathcal{E}_{\top_1}$ is defined by
\[
\mathcal{E}_{\top_1}\R = \R^{\top_1},
\]
where $\R^{\top_1}$ denotes the partial transpose on the first mode. For $n=1$ the partial transpose is equivalent to the total transpose, which maintains consistency in the definition.

We are now ready to define $\mathrm{GO}^-(n)$, which is given as
\[
\mathrm{GO}^-(n)=\{\exp(\go)\mathcal{E}_{\top_1}|\go\in\mathfrak{go}(n)\}.
\]
The partial $\mathcal{E}_{\top_1}$ is represented by the matrix,
 \[
 M_{\top_1}=\begin{pmatrix}
     1 & 0 &0_{(2n-2)}\\
     0 & -1&0_{(2n-2)} \\
     0_{(2n-2)} & 0_{(2n-2)} & I_{(2n-2)(2n-2)}
 \end{pmatrix}
 \] 
 with $\mathrm{det}(M)=-1$. By using the multiplicative property of the Lie group, we can see that any element $\mathcal{E}_G\cong (D+\bold{v})\oplus_{\mathrm{S}}M\in \mathrm{GO}^-(n)$ is represented by a matrix $M$ with $\mathrm{det}(M)<0$. 

$\mathrm{GO}(n)$ is union of $\mathrm{GO}^+(n)$ and $\mathrm{GO}^-(n)$, such that $\mathcal{E}_G\cong (D+\bold{v})\oplus_{\mathrm{S}}M \in \mathrm{GO}(n)$ corresponding to $M$ with $\mathrm{det}(M)\neq 0$.
For a state $\R$ characterized by $\sigma$ and $\bold{d}$, $\mathcal{E}_G\cong (D+\bold{v})\oplus_{\mathrm{S}}M\in \mathrm{GO}(n)$ induces the transformation, Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran}. Unlike $\mathrm{GO}^+(n)$, $\mathrm{GO}(n)$ includes elements with $\mathrm{det}(M)<0$

Moreover, there exists a sequence $\mathcal{E}_{G,k}\in \mathrm{GO}(n)$ such that $\lim_{k\rightarrow\infty}\mathcal{E}_{G,k}\cong (D\oplus \bold{v})\oplus_{\mathrm{S}}M$, where determinant of $M$ is zero. Consequently, $\overline{\mathrm{GO(n)}}$ includes elements, $\mathcal{E}_G$ that give rise to transformations, Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran} with any real matrix $M$.

We claim that the CPTP element of $\overline{\mathrm{GO}(n)}$ is a Gaussian quantum channel. A quantum channel is a Gaussian quantum channel if and only if:
(1) it transforms the covariance matrix and displacement vector according to Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran}, and (2) it follows the CPTP condition~\cite{Weedbrook2012}. We have shown that any CPTP element (condition (2)) of $\overline{\mathrm{GO}(1)}$ transforms the covariance matrix and displacement vector as Eq.~\eqref{eq:sigam_tran} and Eq.~\eqref{eq:d_tran} (condition (1)). Hence, the proposition is proven.





\section{Proof of Theorem~\ref{theorem:general_sol_single_mode} and Theorem~\ref{theorem:general_sol_multi}}\label{section:evolution_GO}

We will prove Theorem~\ref{theorem:general_sol_multi}, and the proof of Theorem~\ref{theorem:general_sol_single_mode} follows as a special case with, $n=1$

\subsection{Evolution of Wigner functions under $\mathcal{E}_G$}

First, we consider elements of $\mathrm{GO}^+(n)$, which is $\exp(\go)$, where $\go\in\mathfrak{go}(n)$.
We can decompose $\exp(\go)$ as
\[
\exp(\go) = \exp(h_2)\exp(h_1)\exp(g),
\]
where $g\in\mathfrak{g}$, $h_1\in\mathfrak{h}_1$, and $h_2\in\mathfrak{h}_2$,  The definition of $\mathfrak{h}_1$, $\mathfrak{h}_2$, and $\mathfrak{g}$ is equal to Eq.~\eqref{eq:definition_of_g_in_appen}, Eq.~\eqref{eq:definition_of_h1_in_appen}, and Eq.~\eqref{eq:definition_of_h2_in_appen}.

In section~\ref{subsection:proof_of_go(n)}, we express $g$, $h_1$ and $h_2$ using $\vec{\ad}$ and $\vec{\ad^+}$. As all observables, $\hat{O}$, can be represented through the Wigner function, $W_{\hat{O}}(\vec{x},\vec{p})$, the adjoint and anti-adjoint operators, $\ad$
and $\ad^+$, can likewise be represented as local operators acting on the Wigner function. As operators acting on the Wigner function, $\vec{\ad}$ and $\vec{\ad^+}$ are represented as follows:
\[
\vec{\ad}=-\begin{pmatrix}
    \partial_{x_1}\\
    \vdots\\
    \partial_{x_n}\\
    \partial_{p_1}\\
    \vdots\\
    \partial_{p_n}
\end{pmatrix} =-\begin{pmatrix}
    \vec{\partial_x}\\
    \vec{\partial_p}
\end{pmatrix} \quad \vec{\ad^+}=2\begin{pmatrix}
    {x_1}\\
    \vdots\\
    {x_n}\\
    {p_1}\\
    \vdots\\
    {p_n}
\end{pmatrix}=2\begin{pmatrix}
    \vec{x}\\
    \vec{p}
\end{pmatrix}
\]
Accordingly, $g$, $h_1$ and $h_2$ can be represented as operators acting on the Wigner function as,
\begin{eqnarray}
    g&=&-\begin{pmatrix}
         \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix}\Gamma \begin{pmatrix}
       \vec{x}\\
        \vec{p}
    \end{pmatrix},\\
    h_1&=&-\begin{pmatrix}
        \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix} {\bold{v}},\\
    h_2&=&\begin{pmatrix}
        \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix} D \begin{pmatrix}
        \vec{\partial_x}\\
        \vec{\partial_p}
    \end{pmatrix}.
\end{eqnarray}
As a result, $\exp(\go)$ is given by
\[
\exp(\go) = \exp(\begin{pmatrix}
        \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix} D \begin{pmatrix}
        \vec{\partial_x}\\
        \vec{\partial_p}
    \end{pmatrix})\exp(-\begin{pmatrix}
        \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix} {\bold{v}}) \exp(-\begin{pmatrix}
        \vec{\partial_x}^\top &\vec{\partial_p}^\top
    \end{pmatrix}\Gamma \begin{pmatrix}
        \vec{x}\\
        \vec{p}
    \end{pmatrix}),
\]
 is equivalent to the fact that $\exp(\go)$ can be represented in terms of $M=\exp(\Gamma)$, $D$, and $\bold{v}$. Since $M$ is exponential of $\Gamma$,
$\mathrm{det}(M)>0$.
We can derive a closed-form expression for the action of any wingner function $W(\vec{x},\vec{p})$,
\[\label{eq:exp(go)_action}
    W(\vec{x},\vec{p})\overset{\exp(\go)}{\longrightarrow} \frac{1}{\mathrm{det}(M)}\int_{-\infty}^\infty \int_{-\infty}^\infty  d\vec{y} d\vec{q} W\left(M^{-1} 
    \left(\icol{
    \vec{y}\\
    \vec{q}}-\bold{v}\right)
    \right)
    \frac{1}{4\pi\sqrt{\mathrm{det}(D)}}\exp({-\irow{\vec{x}^\top-\vec{y}^\top&\vec{p}^\top-\vec{q}^\top}\tfrac{D^{-1}}{4}\icol{\vec{x}-\vec{y}\\\vec{p}-\vec{q}}}).
\]
In other words, we have obtained a general formula describing how elements in $\mathrm{GO}^+(n)$ transform the Wigner function.


To complete the proof, we also need to consider the elements of $\mathrm{GO}^-(n)$. Any element of $\mathrm{GO}^-(n)$ is expressed by $\exp(\go)\mathcal{E}_{\top_1}$, where $\mathcal{E}_{\top_1}$ is partial transpose channel acting on the first mode. $\mathcal{E}_{\top_1}$ also can be considered as an operator acting on a Wigner function, $W(\vec{x},\vec{p})$,
\[\label{eq:M_top_action}
    W(\vec{x},\vec{p})\overset{\mathcal{E}_{\top_1}}{\longrightarrow} W\left(M_{\top_1}\icol{
    \vec{y}\\
    \vec{q})}\right),
\]
where
 \[
 M_{\top_1}=\begin{pmatrix}
     1 & 0 &0_{(2n-2)}\\
     0 & -1&0_{(2n-2)} \\
     0_{(2n-2)} & 0_{(2n-2)} & I_{(2n-2)(2n-2)}
 \end{pmatrix}.
 \] 
Combining Eq.~\eqref{eq:exp(go)_action} and Eq.~\eqref{eq:M_top_action}, we obtain the how $\exp(\go)\mathcal{E}_{\top_1}$ transforms a Wignerfunction,
\[\label{eq:exp(go)E_top_action}
    W(\vec{x},\vec{p})\overset{\exp(\go)\mathcal{E}_{\top_1}}{\longrightarrow} 
    \frac{1}{|\mathrm{det}(M)|}\int_{-\infty}^\infty \int_{-\infty}^\infty  d\vec{y} d\vec{q} W\left(M^{-1}
    \left(\icol{
    \vec{y}\\
    \vec{q}}-\bold{v}
    \right)\right)
    \frac{1}{4\pi\sqrt{\mathrm{det}(D)}}\exp({-\irow{\vec{x}^\top-\vec{y}^\top&\vec{p}^\top-\vec{q}^\top}\tfrac{D^{-1}}{4}\icol{\vec{x}-\vec{y}\\\vec{p}-\vec{q}}}).
\]
where $M=M_{\top_1}\exp(\Gamma)$. From the facts that $\mathrm{det}(M_{\top_1})=-1$ and $\mathrm{det}(\exp(\Gamma))>0$,  it follows that $\mathrm{det(M)}<0$.

Lastly, we consider the elements of $\overline{\mathrm{GO}(n)}$, i.e., the limits of elements in $\mathrm{GO}(n)$.

We require strong convergence for the limit of any sequence $\mathcal{E}_{G,k}\in \mathrm{GO}(n)$. Strong convergence indicates that $\lim_{k\rightarrow\infty} \mathcal{E}_{G,k} = \mathcal{E}_{G,\infty}$, when 
\[
\lim_{k\rightarrow\infty} \mathcal{E}_{G,k} \R  = \mathcal{E}_{G,\infty} \R,
\]
for all $\R$. Each $\mathcal{E}_{G,k}\cong (D_k\oplus \bold{v}_k)\oplus_{\mathrm{S}}M_k$ consists of a linear coordinate transformation followed by convolution with a Gaussian function. Such operators converge strongly only if the sequences, $M_k$, $\bold{v}_k$, and $D_k$ converge uniformly~\cite{friedlander1999introduction}. 
The sequence $M_k$ can converge to $M_0$ with $\mathrm{det}(M_0)=0$, such that $\overline{\mathrm{GO}(n)}$ include the element $\mathcal{E}_G = (D\oplus \bold{v})\oplus_{\mathrm{S}}M$ where $\mathrm{det}(M)=0$. In the case where $\mathrm{det}(M)=0$, special care must be taken in analyzing the transformation induced by $\mathcal{E}_G$, since the inverse of $M$ is not defined when $\mathrm{det}(M)=0$. To illustrate, we consider the simplest case $\mathcal{E}_{G,0}$ in which $M = 0_{2n\times2n}$, $D = 0_{2n\times2n}$, and $\bold{v} =  0_{2n}$.
\[\label{eq:E_0_action}
    W(\vec{x},\vec{p})\overset{\mathcal{E}_{G,0}}{\longrightarrow} \delta(\vec{x},\vec{p}),
\]
where $\delta(\vec{x},\vec{p})$ is Dirac-delta function.

\subsection{Evolution of $\mathcal{E}_G$}
We will discuss how the elements of $\mathrm{GO}^+(n)$ evolve under $\go'$.
$\mathcal{E}_G\in\mathrm{GO}^+(n)$ can be expressed as $\exp(\go)$ and, as discussed in the previous subsection, can be decomposed into $\exp(h_2)\exp(h_1)\exp(g)$. Each of these can be expressed in terms of $D$, $\bold{v}$, and $M=\exp(\Gamma)$, respectively.
To describe the evolution of $\mathcal{E}_G$, it is sufficient to describe the evolution of $D$, $\bold{v}$, and $M$.

Let us consider a time evolution,
\[\label{eq:dynamics_of_EG}
\frac{d}{dt}\mathcal{E}_G = \go' \mathcal{E}_G,
\]
where we note that $\go$, which serves as the exponent of $\mathcal{E}_G$, and $\go'$ which dictates its evolution.
To distinguish them, we express $\go'$ as
\[
\go'=\frac{1}{2}
\vec{\ad}^\top \Gamma_M \vec{\ad^+}+\vec{\ad}^\top\Gamma_D \vec{\ad}+\vec{\ad}^\top
\Gamma_{\bold{v}}.
\]
Eq.~\eqref{eq:dynamics_of_EG} can be rewritten as
\[\label{eq:dynamics_of_EG_decom}
\begin{split}
    &\frac{d}{dt}\exp(\vec{\ad}^\top D \vec{\ad})\exp(\vec{\ad}^\top
\bold{v})\exp(\frac{1}{2}
\vec{\ad}^\top \Gamma \vec{\ad^+}) \\
&\quad= \left(\frac{1}{2}
\vec{\ad}^\top \Gamma_M \vec{\ad^+}+\vec{\ad}^\top\Gamma_D \vec{\ad}+\vec{\ad}^\top
\Gamma_{\bold{v}}\right) \exp(\vec{\ad}^\top D \vec{\ad})\exp(\vec{\ad}^\top
\bold{v})\exp(\frac{1}{2}
\vec{\ad}^\top \Gamma \vec{\ad^+}).
\end{split}
\]
Applying the commutation relations, the expression can be modified as.
\[\label{eq:dynamics_of_EG_decom}
\begin{split}
    &\frac{d}{dt}\exp(\vec{\ad}^\top D \vec{\ad})\exp(\vec{\ad}^\top
\bold{v})\exp(\frac{1}{2}
\vec{\ad}^\top \Gamma \vec{\ad^+}) \\
    &\quad=\left(\vec{\ad}^\top\frac{dD}{dt}\vec{\ad}\right)
    \exp(\vec{\ad}^\top D \vec{\ad})
    \exp(\vec{\ad}^\top
\bold{v})
\exp(\frac{1}{2} 
\vec{\ad}^\top \Gamma \vec{\ad^+}) \\
&\quad+\exp(\vec{\ad}^\top D \vec{\ad})
\left(\vec{\ad}^\top\frac{d\bold{v}}{dt}\right)
\exp(\vec{\ad}^\top\bold{v})
\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+})\\
&\quad+\exp(\vec{\ad}^\top D \vec{\ad})
\exp(\vec{\ad}^\top\bold{v})
\left(\frac{d}{dt}\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+})\right)\\
&\quad=\left(\vec{\ad}^\top (\Gamma_D+\Gamma_M D +D\Gamma_M^\top ) \vec{\ad}\right)
    \exp(\vec{\ad}^\top D \vec{\ad})
    \exp(\vec{\ad}^\top
\bold{v})
\exp(\frac{1}{2} 
\vec{\ad}^\top \Gamma \vec{\ad^+}) \\
&\quad+\exp(\vec{\ad}^\top D \vec{\ad})
\left(\vec{\ad}^\top(\Gamma_{\bold{v}}+\Gamma_M\bold{v})\right)
\exp(\vec{\ad}^\top\bold{v})
\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+})\\
&\quad+\exp(\vec{\ad}^\top D \vec{\ad})
\exp(\vec{\ad}^\top\bold{v})
\left(\frac{1}{2}\vec{\ad}^\top\Gamma_M\vec{\ad^+}\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+})\right).
\end{split}
\]
Comparing the individual terms, we derive three distinct equations,
\begin{eqnarray}
\frac{d}{dt}D &=& \Gamma_D +\Gamma_M D +D\Gamma_M^\top,\\
\frac{d}{dt}\bold{v} &=& \Gamma_{\bold{v}} +\Gamma_M \bold{v},\\
\frac{d}{dt}\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+}) &=& \frac{1}{2}\vec{\ad}^\top\Gamma_M\vec{\ad^+}\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+}).\label{eq:dynamics_of_M_before}\\
\end{eqnarray}
Using the isomorphism, $\exp(\frac{1}{2} \vec{\ad}^\top \Gamma \vec{\ad^+})$ can be expressed as $M=\exp(\Gamma)$, and Eq.~\eqref{eq:dynamics_of_M_before} is equivalent to,
\[
\frac{d}{dt}M =\Gamma_M M.
\]
Therefore, we have obtained the time evolution of $M$, $D$, and $\bold{v}$.

\section{Proof of theorem~\ref{theorem:superconformal_algebra}}\label{section_proof_superconformal}
$\mathcal{N}=1$ superconformal algebra in three dimensions is isomorphic to $\mathfrak{osp}(1|4)$~\cite{Eberhardt_2021}. Based on this, we will prove the isomorphism between $\mathcal{N}=1$ superconformal algebra in three dimensions and $\mathfrak{ego}(1)$ by establishing the isomorphism between $\mathfrak{ego}(1)$ and $\mathfrak{osp}(1|4)$. 
$\mathfrak{osp}(1|4)$ is composed of ten bosonic generators, $\mathcal{X}_{ij}$ and four fermionic generators, $\mathcal{Y}_{i}$~\cite{Blank1981}, where $i=-2,-1,1,2$. Commutation relations between $\mathcal{X}_{ij}$, and $\mathcal{Y}_{i}$ is given by
\begin{align}
    [\mathcal{X}_{ij},\mathcal{X}_{kl}]&=g_{ik}\mathcal{X}_{jl}+g_{jk}\mathcal{X}_{il}+g_{il}\mathcal{X}_{jk}+g_{jl}\mathcal{X}_{ik},\label{eq:boson_boson_osp}\\
    [\mathcal{X}_{ij},\mathcal{Y}_k]&=g_{ik}\mathcal{Y}_j+g_{jk}\mathcal{Y}_i,\label{eq:boson_fermion_osp}\\
    \{\mathcal{Y}_{i},\mathcal{Y}_j\}&=2\mathcal{X}_{ij}\label{eq:anti_commute_osp},
\end{align}
where $g_{ij}$ is symplectic structure constant as
\[
g_{ij}=\mathrm{sign}(i)\delta_{0,i+j}.
\]

We associate the linear operators, $\ad_{\x}$,  $\ad_{\p}$, $\ad_{\x}^+$, and $\ad_{\p}^+$ with $\mathcal{Y}_i$ as
\[
\mathcal{Y}_2 = -\ad_{\x},\quad\mathcal{Y}_1 = \ad_{\p},\quad\mathcal{Y}_{-1} = \tfrac{1}{2}\ad_{\x}^+,\quad\mathcal{Y}_{-2} = \tfrac{1}{2}\ad_{\p}^+\quad.
\]
Eq.~\eqref{eq:anti_commute_osp} provides the representation of $\mathcal{X}_{ij}$ as the quadratic operators in $\mathfrak{ego}(1)$, explicitly,
\[\begin{split}
\mathcal{X}_{22}&=\tfrac{1}{2}\{\mathcal{Y}_{2},\mathcal{Y}_{2}\}=\ad_{\x}\ad_{\x}=L_{\x\x}^+, \quad
\mathcal{X}_{21}=\tfrac{1}{2}\{\mathcal{Y}_{2},\mathcal{Y}_{1}\}=-\ad_{\x}\ad_{\p}=-L_{\x\p}^+,\\
\mathcal{X}_{11}&=\tfrac{1}{2}\{\mathcal{Y}_{1},\mathcal{Y}_{1}\}=\ad_{\p}\ad_{\p}=L_{\p\p}^+,\quad \mathcal{X}_{-2-2}=\tfrac{1}{2}\{\mathcal{Y}_{-2},\mathcal{Y}_{-2}\}=\tfrac{1}{4}(\ad_{\p}^+)^2,\\
\mathcal{X}_{-2-1}&=\tfrac{1}{2}\{\mathcal{Y}_{-2},\mathcal{Y}_{-1}\}=\tfrac{1}{4}\ad_{\x}^+\ad_{\p}^+,\quad \mathcal{X}_{-1-1}=\tfrac{1}{2}\{\mathcal{Y}_{-1},\mathcal{Y}_{-1}\}=\tfrac{1}{4}(\ad_{\x}^+)^2,\\
\mathcal{X}_{2-1}&=\tfrac{1}{2}\{\mathcal{Y}_{2},\mathcal{Y}_{-1}\}=-\tfrac{1}{4}(\ad_{\x}\ad_{\x}^+ +\ad_{\x}^+\ad_{\x})=-\tfrac{1}{2}\ad_{\hat{N}}-\tfrac{1}{2}\ad_{\hat{Y}}, \\
\mathcal{X}_{2-2}&=\tfrac{1}{2}\{\mathcal{Y}_{2},\mathcal{Y}_{-2}\}=-\tfrac{1}{4}(\ad_{\x}\ad_{\p}^+ +\ad_{\p}^+\ad_{\x})=-\tfrac{1}{2}(L_{\x\p}^- +\tfrac{1}{2})-\tfrac{1}{2}\ad_{\hat{X}},\\
\mathcal{X}_{1-2}&=\tfrac{1}{2}\{\mathcal{Y}_{1},\mathcal{Y}_{-2}\}=\tfrac{1}{4}(\ad_{\p}\ad_{\p}^+ +\ad_{\p}^+\ad_{\p})=\tfrac{1}{2}\ad_{\hat{N}}-\tfrac{1}{2}\ad_{\hat{Y}}, \\
\mathcal{X}_{1-1}&=\tfrac{1}{2}\{\mathcal{Y}_{1},\mathcal{Y}_{-1}\}=\tfrac{1}{4}(\ad_{\p}\ad_{\x}^+ +\ad_{\x}^+\ad_{\p})=-\tfrac{1}{2}(L_{\x\p}^- +\tfrac{1}{2})+\tfrac{1}{2}\ad_{\hat{X}}.
\end{split}
\]
We associated the quadratic operators with $\mathcal{X}_{ij}$, conserving the anti-commutation relation, Eq.~\eqref{eq:anti_commute_osp}, such that, the conservation of commutation relations, Eq.~\eqref{eq:boson_boson_osp} and Eq.~\eqref{eq:boson_fermion_osp}, is sufficient to prove the isomorphism.

In the general $\mathfrak{osp}(1|4)$, the commutation relations among the $\mathcal{Y}_i$ are not defined. However, in our representation, $\mathfrak{ego}(1)$, they satisfy the following commutation relations,
\[
[-\ad_{\x},\tfrac{1}{2}\ad_{\p}^+]=1,\quad[\ad_{\p},\tfrac{1}{2}\ad_{\x}^+]=1,
\]
while the other commutation relations yield zero. Equivalently, this can be written as
\[\label{eq:commute_fermion_osp}
[\mathcal{Y}_i,\mathcal{Y}_j]=g_{ij}.
\]

Accordingly, we have identified the commutation relations, Eq.~\eqref{eq:commute_fermion_osp}, and anti-commutation relations, Eq.~\eqref{eq:anti_commute_osp}, of $\mathcal{Y}_i$ corresponding to elements of  $\mathfrak{ego}(1)$. Moreover, Eq.~\eqref{eq:commute_fermion_osp} and Eq.~\eqref{eq:anti_commute_osp}, guarantee the conservation of the other commutation relations, Eq.~\eqref{eq:boson_boson_osp}, and Eq.~\eqref{eq:boson_fermion_osp}. 

Let us obtain the commutation relation between $\mathcal{X}_{ij}$, using $\mathcal{X}_{ij}=\tfrac{1}{2}(\mathcal{Y}_i\mathcal{Y}_j+\mathcal{Y_j}\mathcal{Y_i})$, and Eq.~\eqref{eq:commute_fermion_osp}, as
\[\begin{split}   
[\mathcal{X}_{ij},\mathcal{X}_{kl}]&=\tfrac{1}{4}[\mathcal{Y}_i\mathcal{Y}_j+\mathcal{Y}_j\mathcal{Y}_i,\mathcal{Y}_k\mathcal{Y}_l+\mathcal{Y}_l\mathcal{Y}_k]\\
&=\tfrac{1}{2}g_{ik}(\mathcal{Y}_j\mathcal{Y}_l + \mathcal{Y}_l\mathcal{Y}_j) 
+\tfrac{1}{2}g_{jk}(\mathcal{Y}_i\mathcal{Y}_l + \mathcal{Y}_l\mathcal{Y}_i)
+\tfrac{1}{2}g_{il}(\mathcal{Y}_j\mathcal{Y}_k + \mathcal{Y}_k\mathcal{Y}_j)
+\tfrac{1}{2}g_{jl}(\mathcal{Y}_i\mathcal{Y}_k + \mathcal{Y}_k\mathcal{Y}_i)\\
&=g_{ik}\mathcal{X}_{jl}+g_{jk}\mathcal{X}_{il}+g_{il}\mathcal{X}_{jk}+g_{jl}\mathcal{X}_{ik},
\end{split}
\]
which corresponding to Eq.~\eqref{eq:boson_boson_osp}. 

Likewise, Let us obtain the commutation relation between $\mathcal{X}_{ij}$ and $\mathcal{Y}_k$,
\[\begin{split}
[\mathcal{X}_{ij},\mathcal{Y}_{k}]= \tfrac{1}{2}[\mathcal{Y}_i\mathcal{Y}_j+\mathcal{Y}_j\mathcal{Y}_i,\mathcal{Y}_k]=g_{ik}\mathcal{Y}_j + g_{jk}\mathcal{Y}_i
\end{split}
\]
which corresponding to Eq.~\eqref{eq:boson_fermion_osp}. Consequently, we have recovered Eq.~\eqref{eq:boson_boson_osp}, and Eq.~\eqref{eq:boson_fermion_osp} by using the commutation and anti-commutation relations of $\mathcal{Y}_i$.

Establishing a one-to-one correspondence between the elements of $\mathfrak{ego}(1)$ and $\mathfrak{osp}(1|4)$, and demonstrating the preservation of all (anti-)commutation relations, we have proven that the two Lie superalgebras are isomorphic.
\section{Proof of theorem~\ref{theorem:iff_condtion_Gaussian_ego}}\label{section:proof_nogo_ego}

We will use proof by contradiction. For contradiction, let us assume that there exists a linear operator $\mathcal{S}$ which conserves the Gaussianity, which does not belong into $\mathfrak{ego}(1)\times\mathrm{Span}(\mathcal{I})$, $\mathcal{S}\notin \mathfrak{ego}(1)\times\mathrm{Span}(\mathcal{I})$. We will show that $\mathcal{S}$ must belong to $\mathfrak{ego}(1)\times\mathrm{Span}(\mathcal{I})$, otherwise there is a Gaussian observable $\hat{O}$ losing its Gaussianity, which is a contradiction.

Since $\mathcal{S}$ is a linear operator, we can express $\mathcal{S}$ as
\[
\mathcal{S} = \sum_j  \hat{A}_j\bullet \hat{B}_j.
\]
Any operator, $A_k$ and $B_k$ can be decomposed by $\an$ and $\an^\dagger$ as
\[\begin{split}
    \hat{A}_j = \sum_{k,l} A_{j,kl}  \an^{\dagger k}\an^{l},\\
    \hat{B}_j = \sum_{k,l} B_{j,kl}  \an^{\dagger k}\an^{l},
\end{split}
\]
for non-negative integer, $k$ and $l$. This is because monomials $\an^{\dagger k}\an^{l}$ form an operator basis in a single-mode bosonic space~\cite{Cahill1969}.

Likewise, we can write the $\mathcal{S}$ using a series expansion as
\[\label{eq:properordered_LG}
\mathcal{S}=\sum_{j,k,l,m} \gamma_{jklm} \an^{\dagger j}\an^{ k}\bullet \an^{ l}\an^{\dagger m}.
\]
with complex coefficients $\gamma_{jklm}$, where $j,k,l$ and $m$ are non-negative integers.
$\an$ and $\an^\dagger$ is a linear combination of $\x$ and $\p$, $\mathcal{S}$ can be rewritten by
\[\label{eq:properordered_LG_xp}
\mathcal{S}=\sum_{j,k,l,m} \gamma_{jklm}' \x^j\p^{ k}\bullet \p^{ l}\x^{m}.
\]
$\x$ acting on $\hat{O}$ from the left side is equivalent to $\tfrac{1}{2}(\ad_{\x}^+ -i \ad_{\x})$, i.e., $\x\hat{O}=\tfrac{1}{2}(\ad_{\x}^+(\hat{O}) -i \ad_{\x}(\hat{O}))$, $\x$ acting from the right is equivalent to $\tfrac{1}{2}(\ad_{\x}^+ +i \ad_{\x})$. The action of $\p$ on the left and right sides is expressed similarly. Hence, Eq.~\eqref{eq:properordered_LG_xp} is rewritten as
\[\begin{split}\label{eq:properordered_LG_ad}
    \mathcal{S}&=\sum_{j,k,l,m} \frac{\gamma_{jklm}'}{2^{j+k+l+m}}  
    (\ad_{\hat{x}}^+ +i \ad_{\hat{x}})^m
    (\ad_{\hat{p}}^+ +i \ad_{\hat{p}})^l
    (\ad_{\hat{x}}^+ -i \ad_{\hat{x}})^j
    (\ad_{\hat{p}}^+ -i \ad_{\hat{p}})^k\\
    &=\sum_{j,k,l,m} \alpha_{jklm} (\ad_{\x}^+)^j(\ad_{\p}^+)^k(\ad_{\x})^l(\ad_{\p})^m.
\end{split}
\]
Since it appears in $\frac{d\hat{O}}{dt}=\mathcal{S}\hat{O}$, to preserve Hermitianity of $\hat{O}(t)=\exp(\mathcal{S}t)\hat{O}$, we require $\mathcal{S}\hat{O}$ to be a Hermitian operator. Additionally, note that for every combination of powers, $(\ad_{\x}^+)^j(\ad_{\p}^+)^k(\ad_{\x})^l(\ad_{\p})^m\hat{O}$ is a Hermitian operator. This follows from combining a) for any Hermitian operator $\hat{H}$, also $\ad_{\hat{H}}\hat{O}$, and $\ad^+_{\hat{H}}\hat{O}$ are Hermitian, thus also b) $(\ad_{\hat{H}_1}\ad_{\hat{H}_2}\hat{O} )^\dagger=\ad_{\hat{H}_1}\ad_{\hat{H}_2}\hat{O}$, and we can use induction to prove the statement for every combination of powers. This implies that all $\alpha_{jklm}$ are real. Thus, we have shown that $\mathcal{S}$ must necessarily have the form of Eq.~\eqref{eq:properordered_LG_ad} with all $\alpha_{jklm}$ real.

Next, we consider the property of a Gaussian-conserving operator. We consider Gaussian observables which have a Gaussian function as the Wigner function as,
\[
W(x,p) = A\exp({-\irow{x-x_0&p-p_0}\Lambda\icol{x-x_0\\p-p_0}}).
\]
If a Gaussian observable, $\hat{O}$, is evolved to another Gaussian observable by $\mathcal{S}$, the Wigner function must preserve its form. It follows that we can express the evolution via the chain rule as
\[\label{eq:L_GR}
\mathcal{S}\hat{O}(t) = \frac{d}{dt}\hat{O}(t) =\left(\lambda_A\frac{\partial}{\partial A}+\lambda_\Lambda\frac{\partial}{\partial \Lambda}+\lambda_{x_0}\frac{\partial}{\partial x_0} + \lambda_{p_0}\frac{\partial}{\partial p_0}\ \right)W(x,p),
\]
where $\lambda_A =\frac{\partial A}{\partial t}$, $\lambda_\Lambda=\frac{\partial \Lambda}{\partial t}$, $\lambda_{x_0}=\frac{\partial x_0}{\partial t}$, and $\lambda_{p_0}=\frac{\partial {p_0}}{\partial t}$.
Executing the derivatives we find that Eq.~\eqref{eq:L_GR} can be rewritten as
\[\label{eq:L_GR_2}
L_G \R =(\lambda_{x^2}x^2+\lambda_{p^2}p^2+\lambda_{xp}xp+\lambda_{x}x+\lambda_{p}p+\lambda_{0} )W(x,p),
\]
where $\lambda$'s are real coefficients. This means that for a Gaussian state, for an operator $L_G$ to preserve its Gaussianity, the Wigner function being acted upon by $L_G$ must transform as being multiplied by at most quadratic powers in $x$ and $p$. 
%Eq.~\eqref{eq:L_GR_2} indicates that $L_G\R$ has Wigner function as a product of $\R$ with up to quadratic order of $x$ and $p$. Moreover, since we require that $L_G$ conserve the Gaussianity for any Gaussian state, $L_G\R$ has to be express as Eq.~\eqref{eq:L_GR_2} for any Gaussian state.

Now we check how the $L_G$, which must have a form of~\eqref{eq:properordered_LG_ad} with all $\alpha_{jklm}$ real, transforms the Wigner function, and compare it to the requirement given by Eq.~\eqref{eq:L_GR_2}.

%We need to check that $L_G$ at Eq.~\eqref{eq:properordered_LG_ad} generate a Wigner function of $L_G\R$ with a Gaussian state as Eq.~\eqref{eq:L_GR_2}. 

The adjoint operators acting on the density matrix are transformed into the operators acting on the Wigner function as~\cite{Breuer2002}
\[\begin{split}
\ad_{\x} \rightarrow- \frac{\partial}{\partial p},\quad
\ad_{\p} \rightarrow \frac{\partial}{\partial x},\quad
\ad_{\x}^{+}  \rightarrow 2x,\quad
\ad_{\p}^{+}  \rightarrow 2p,
\end{split}
\]
which provides
\[
    \mathcal{S}=\sum_{j,k,l,m} \alpha_{jklm} (2x)^j(2p)^k\left(-\frac{\partial}{\partial p}\right)^l\left(\frac{\partial}{\partial x}\right)^m.
\]
Consider a simple Gaussian observable, $\hat{O}$, with the Wigner function
\[
W(x,p)=\exp(-\Lambda_{xx}x^2 -\Lambda_{pp}p^2 ),
\]
where $\Lambda_{xx}>0$ and $\Lambda_{pp}>0$
Applying $\mathcal{S}$ (recall Eq.~\eqref{eq:properordered_LG_ad}) to this Wigner function gives,
\[\begin{split}\label{eq:L_GR_poly}
    \mathcal{S}\hat{O} &=\!\! \sum_{j,k,l,m} \!\alpha_{jklm} (2x)^j(2p)^k (\sqrt{\Lambda_{pp}})^l (-\sqrt{\Lambda_{xx}})^m H_l(\sqrt{\Lambda_{pp}}p)H_m(\sqrt{\Lambda_{xx}}x) \exp(-\Lambda_{xx}x^2 -\Lambda_{pp}p^2 ),
\end{split}
\]
where $H_n(x)$ are Hermite polynomials. Using the following equation,
\[
x^j = \frac{i!}{2^j}\sum_{i\geq 0}^{\floor{j}}\frac{1}{i!(j-2i)!}H_i(x),
\]
which holds for any non-negative integers, $i$ and $j$,
we decompose Eq.~\eqref{eq:L_GR_poly} as
\[\label{eq:LGonR}
\begin{split}
    \mathcal{S}\hat{O} &=\!\! \sum_{j,k,l,m\geq 0} \!\alpha'_{jklm} (2x)^j(2p)^k (\sqrt{\Lambda_{pp}})^l (-\sqrt{\Lambda_{xx}})^m 
    \left(\frac{l!}{2^l}\sum_{i}^{\floor{\tfrac{l}{2}}}\frac{1}{i!(l-2i)!}H_i(\sqrt{\Lambda_{pp}}p) \right)
    \left(\frac{m!}{2^m}\sum_{i}^{\floor{\tfrac{m}{2}}}\frac{1}{j!(m-2i)!}H_j(\sqrt{\Lambda_{xx}}x) \right)\\
    &\times\exp(-\Lambda_{xx}x^2 -\Lambda_{pp}p^2 )\\
    &= \sum_{j,k,l,m\geq 0} \!\alpha'_{jklm} (2x)^j(2p)^k (\Lambda_{pp}p)^l (-\Lambda_{xx}x)^m \exp(-\tfrac{1}{4D_{xx}}x^2 -\tfrac{1}{4D_{pp}}p^2 ),
\end{split}
\]
where $\alpha'_{knlm}$'s are linear combination of $\alpha_{knlm}$. We compare Eq.~\eqref{eq:LGonR} with Eq.~\eqref{eq:L_GR_2}. Since in our example we required $\Lambda_{xx}>0$ and $\Lambda_{pp}>0$, to satisfy the Gaussianity preserving condition, we have  $\alpha'_{klmn}=0$ for any $k+l+m+n>2$. 

Considering linear relation between $\alpha_{knlm}$ and $\alpha_{knlm}'$, we can notice that $\alpha_{knlm}$ also have to be zero whenever $k+n+l+m>2$. This means that $L_G$ has to be expressed by
\[\begin{split}\label{eq:properordered_LG_ad_2}
    \mathcal{S}
    &=\sum_{j\geq 0,k\geq 0,l\geq 0,m\geq 0,j+k+l+m\leq 2} \alpha_{jklm} (\ad_{\x}^+)^j(\ad_{\p}^+)^k(\ad_{\x})^l(\ad_{\p})^m
\end{split}
\]

As a result, $\mathcal{S}$ is composed of adjoint and anti-adjoint operators of $\x$ and $\p$, up to quadratic order.

$\mathfrak{ego}(1) \times \mathrm{Span}(\mathcal{I})$ contains all linear superoperators formed from adjoint and anti-adjoint operators of $\x$ and $\p$ up to quadratic order. Hence, $\mathcal{S}$ must belong to $\mathfrak{ego}(1) \times \mathrm{Span}(\mathcal{I})$, which contradicts the assumption.
