        \boxed{\texttt{\_:\_}} \ar[d]\ar[dr] & & \boxed{\texttt{P}}\ar[d] & &  \boxed{\texttt{\_:\_}} \ar[d]\ar[dr] & & \boxed{\texttt{P}}\ar[d]\\
