\author{Denis Vinokurov}
\date{}
\title{Maximizing higher eigenvalues in dimensions three and above}
\maketitle
\begin{abstract}
  We study the problem of maximizing the $k$-th eigenvalue functional
  over the class of absolutely continuous measures on
  a closed Riemannian manifold of dimension $m\geq 3$.

  For dimensions $3 \leq m \leq 6$, we generalize the work of Karpukhin and
  Stern on the first eigenvalue, showing that the maximizing
  measures are realized by smooth
  harmonic maps into finite-dimensional spheres.

  For $m \geq 7$, the maximizing measures are again induced by
  harmonic maps, which may now exhibit singularities. We prove that $m-7$
  is the optimal upper bound for the Hausdorff dimension of the singular set.
  More precisely, for any $m \geq 7$, there exist maximizing harmonic maps on the
  $m$-dimensional sphere whose singular sets have any prescribed integer
  dimension up to $m - 7$.
\end{abstract}
%%
%% LaTeX can automatically make a table of contents.  This is done by
%% uncommenting the following:
%%
\tableofcontents

\section{Introduction and main results}

\subsection{Eigenvalue optimization in high dimensions}
Let $(M,g)$ be a closed Riemannian manifold with $m = \dim M$, and let
$\Delta_g = \delta_g d \colon C^\infty(M) \to C^\infty(M)$ be the associated
Laplace-Beltrami operator, where $\delta_g$ is the formal adjoint of $d$.
The spectrum of $\Delta_g$ forms the following
nondecreasing sequence:
\begin{equation}
  0 = \lambda_0(g) < \lambda_1(g) \leq \lambda_2(g) \leq
  \cdots\nearrow \infty,
\end{equation}
where the eigenvalues are repeated according to their multiplicities. The following variational characterization
of $\lambda_k(g)$ is well known:
\begin{equation}\label{eq:eigen-var-char-metric}
  \lambda_k(g) = \inf_{F_{k+1}} \sup_{\phi \in F_{k+1}} \frac{\int \abs{d\phi}^2_g dv_g}{\int \phi^2 dv_g},
\end{equation}
where $F_{k+1} \subset C^\infty(M)$ ranges over $(k+1)$-dimensional subspaces.

If $\mathcal{M}(M)$ denotes the space of all nonnegative Radon measures on $M$
and $\mu \in \mathcal{M}(M)$ one defines $\lambda_k(\mu) \in [0,\infty]$
in parallel with the eigenvalues~\eqref{eq:eigen-var-char-metric} by:
\begin{equation}\label{meas-eigenval}
  \lambda_k(\mu) = \lambda_k(\mu, g) := \inf_{F_{k+1}} \sup_{\phi \in F_{k+1}} \frac{\int \abs{d\phi}^2_g dv_g}{\int \phi^2 d\mu},
\end{equation}
where $F_{k+1}$ is the same as in~\eqref{eq:eigen-var-char-metric}.
If $\mu$ is regular enough, e.g., the map $H^1(M) \to L^2(M, \mu) $ is compact,
the variational eigenvalues~\eqref{meas-eigenval} are the true eigenvalues
of the problem
\begin{equation}\label{eq:meas-eigenfunc}
  \Delta_g \phi = \lambda_k \phi \mu.
\end{equation}
Let us consider the following optimization problem:
\begin{equation}\label{measure-opt}
  \mathcal{V}_k(g) = \sup_{\substack{\mu \in C^\infty\\ \mu > 0}} \overline{\lambda}_k(\mu),
  \quad \text{where } \overline{\lambda}_k(\mu) := \lambda_k(\mu)\mu(M).
\end{equation}

The eigenvalues of measures~\eqref{meas-eigenval} were first introduced and
studied in~\cite*{Kokarev:2014:measure-eigenval} in the context of Riemannian surfaces.
Notice that in dimension $m = 2$, the Dirichlet energy density $\abs{d\phi}^2_g dv_g$ is
conformally invariant. Hence, $\mathcal{V}_k(g) = \mathcal{V}_k(\tilde{g})$
for all $\tilde{g} \in [g]$, and
the optimization problem~\eqref{measure-opt} coincide with the eigenvalue
optimization in the conformal class:
\begin{equation}
  \mathcal{V}_k(g) = \Lambda_k([g]) := \sup_{\tilde{g} \in [g]} \lambda_k(\tilde{g}) \Area (\tilde{g})
\end{equation}
Thus, $\mathcal{V}_k(g)$ can be viewed as another
generalization of the eigenvalue optimization problem on surfaces
as opposed to the optimization within a conformal class in higher dimensions.

For existence and regularity results on maximizers of $\Lambda_k([g])$ on surfaces,
see~\cite{Karpukhin-Nadirashvili-Penskoi-Polterovich:2022:existence,
Petrides:2018:exist-of-max-eigenval-on-surfaces}. See  also \cite{Kim:2022:second-sphere-eigenval,
Karpukhin-Metras-Polterovich:2024:dirac-eigenval-opt,
Perez-Ayala:2021:conf-laplace-sire-xu-norm,
Perez-Ayala:2022:extr-metrics-paneitz-operator,
Gursky-Perez-Ayala:2022:2d-eigenval-conform-laplacian}
for some related eigenvalue optimization results.

The motivation for the above optimization problem arises from its
connection to harmonic maps into spheres. Namely, critical measures
$\mu$ of the functional $\overline{\lambda}_k$
are generated by such maps. More precisely, one can construct
a map $u\colon (M, g) \to \Sph^n$
consisting of the $k$-th eigenfunctions of~\eqref{eq:meas-eigenfunc}. Then it follows that
$\mu = \abs{du}^2_g dv_g$, $\lambda_k(|du|^2_g dv_g) = 1$, and
and the map $u$ solves the equation
\begin{equation}\label{extr-measures}
  \Delta_g u = \abs{du}^2_g u
\end{equation}
coordinate-wisely
(see, e.g., \cite*[Proposition~4.13]{Karpukhin-Stern:2024:harm-map-in-higher-dim}).
Recall that a map $u\colon (M, g) \to (N,h)$ is called
harmonic if it is a critical point of the energy functional
\begin{equation}
  E[u] = \int \abs{du}^2_{g,h} dv_g.
\end{equation}
In the case $(N,h) = \Sph^n$,  the associated Euler–Lagrange equation is
precisely~\eqref{extr-measures}.

Another interesting observation is that
the suprema~\eqref{measure-opt} admit an equivalent formulation
in terms of an optimization problem involving the negative eigenvalues
of Schrödinger operators. Let $V \in C^\infty(M)$ be a positive
function, and consider the Schrödinger operator $\Delta_g - V$.
We define the \emph{(spectral) index} of V, denoted
\begin{equation}
  \ind V := \ind (\Delta_g - V),
\end{equation}
as the maximal dimension of subspaces on which $\Delta_g - V$
is negative definite, which is the same as the number of
negative eigenvalues (counted with multiplicities) of the operator.

Using the correspondence $V = \lambda_k(\mu) \mu$, where $\mu \in C^\infty$,
one immediately sees that $\ind V \leq k$, and hence
\begin{equation}
  \mathcal{V}_k(g) = \sup \set*{\int V dv_g}{V \in C^\infty,\ V > 0,\ \ind V \leq k},
\end{equation}
see also~\cite[Section~2]{Karpukhin-Nadirashvili-Penskoi-Polterovich:2022:existence}.
The positivity condition $V > 0$ can be relaxed to $V \geq 0$, since the inequality
$\ind V \leq k$ is preserved under weak$^*$  limits of measures. In fact, it
was shown in~\cite{Grigoryan-Nadirashvili-Sire:2016:eigenval-schrodinger} that one may
dispense with the condition $V \geq 0$ entirely and take the supremum over
all smooth potentials. This observation was later used in~\cite{Karpukhin-Nadirashvili-Penskoi-Polterovich:2022:existence}
to prove the existence
and regularity of maximizers for $\mathcal{V}_k(g)$ in dimension $m=2$.

In~\cite{Grigoryan-Netrusov-Yau:2004:eignval-of-ellipt-oper}
Grigor’yan, Netrusov and Yau established upper bounds for a broad class of
eigenvalue optimization problems on metric measure spaces.
In particular, they proved (see~\cite[Remark~5.10]{Grigoryan-Netrusov-Yau:2004:eignval-of-ellipt-oper})
that:
\begin{equation}
  \mathcal{V}_k(g) \leq Ck^\frac{2}{m} \Vol(g)^{1-\frac{2}{m}} < \infty.
\end{equation}

Karpukhin and
Stern~\cite*{Karpukhin-Stern:2024:harm-map-in-higher-dim} recently proved
that that for dimensions
$3 \leq m \leq 5$, maximizers
for $\mathcal{V}_1(g)$ exist and are realized by smooth,
sphere-valued harmonic maps. In this paper, we extend their result by
proving the existence of maximizers for all
$k$ and in all dimensions. Furthermore, we show that the maximizers are
smooth when
$3 \leq m \leq 6$ (see Corollary~\ref{cor:smooth-maximizers} below).
\begin{theorem}\label{thm:main}
  Let $(M,g)$ be a closed Riemannian manifold of dimension $m \geq 3$.
  Then there exists a locally stable harmonic map $u \in H^1(M,\Sph^\infty)$ that is
  smooth outside of a closed set $\Sigma$ of Hausdorff dimension at most $m-7$,
  $u \in C^\infty(M\setminus\Sigma, \Sph^\infty)$, such that
  \begin{equation}
    \lambda_k(\abs{du}^2_g dv_g) = 1
    \quad\text{and}\quad
    \mathcal{V}_k(g) = \int \abs{du}^2_g dv_g.
  \end{equation}
\end{theorem}
Throughout the paper, we write $\Sph^\infty = \Sph(\ell^2)$ for
the unit sphere in the Hilbert space of square-summable sequences. See Section~\ref{sec:harm-maps}
for all necessary definitions concerning harmonic maps.
\begin{remark}
  As shown in Proposition~\ref{prop:no-atoms}, the maximizing sequence exhibits
  no concentration of energy — i.e., no bubbling — unlike in the case of eigenvalue maximization
  in dimension $m = 2$.
\end{remark}
As a consequence of Theorem~\ref{thm:main}, we obtain a generalization
of~\cite*[Theorem~1.5]{Karpukhin-Stern:2024:harm-map-in-higher-dim},
which establishes existence of smooth maximizers for
all $k > 0$ and in one additional dimension:
\begin{corollary}\label{cor:smooth-maximizers}
  If $3 \leq m \leq 6$,
  the supremum $\mathcal{V}_k(g)$ is achieved on a smooth harmonic map
  $u\colon M \to \Sph^n$ into a finite-dimensional sphere.
\end{corollary}
\begin{proof}
  Any weakly harmonic map of finite (spectral) index is locally stable as a map
  into $\Sph^\infty$ (see Definition~\ref{def:stable-map} and
  the proof of Proposition~\ref{prop:con-bilin-form}). Therefore,
  by Theorem~\ref{thm:reg-harm-map}, any maximizing weakly harmonic map
  $u\colon M \to \Sph^\infty$ is smooth, which implies that
  there is only a finite number of the linearly independent coordinate functions
  since the Schrödinger operator $\Delta - \abs{du}^2$ has a compact resolvent.
\end{proof}
Thus, at least in dimensions $3 \leq m \leq 6$, every closed manifold admits
infinitely many smooth harmonic maps into spheres, each of which
maximizes some eigenvalue functional $\overline{\lambda}_k$.

\begin{remark}
  An analogue of  Theorem~\ref{thm:main},
  holds in the context of Steklov eigenvalue optimization – i.e.,
  when $\partial M \neq \varnothing$ and $\overline{\lambda}_k$ is maximized
  over measures supported on the boundary, $\supp \mu \subset \partial M$.
  See Theorem~\ref{thm:main-steklov} for the precise statement.

  The main remaining question in this setting concerns the regularity
  of maximizers.
\end{remark}


\subsection{Maximizing harmonic maps on spheres}
Let $(\Sph^m, g_{\Sph^m})$ denote the $m$-dimensional unit sphere with the
standard round metric, where $m\geq 3$. In \cite*[Theorem~1.6]{Karpukhin-Stern:2024:harm-map-in-higher-dim},
Karpukhin and Stern computed the supremum of the first eigenvalue over measures
on $\Sph^m$:
\begin{equation}\label{eq:V_1-sphere}
  \mathcal{V}_1(g_{\Sph^m}) = m \sigma_m
\end{equation}
where $\sigma_m = \operatorname{Vol} (g_{\Sph^m})$ is the volume of the round sphere. The standard volume measure
$dv_{g_{\Sph^m}}$, which corresponds to the harmonic map
$\id \colon \Sph^m \to \Sph^m$, is the unique maximizer for $\mathcal{V}_1(g_{\Sph^m})$.
The value of $\mathcal{V}_1(g_{\Sph^2}) = \Lambda_1([g_{\Sph^2}])$ was first computed by Hersch~\cite*{Hersch:1970:sphere-inequality}.

From~\eqref{eq:V_1-sphere}, we see that the maximizing harmonic map – the identity map $\id_{\Sph^m}$ –
is smooth even if
$m \geq 7$. However, this is no longer the case for higher eigenvalues and
singularities do occur.
\begin{definition}
  Let $0\leq k\leq m-3$. We refer to the map $\SHM{k} \colon \Sph^m \to \Sph^{m-1-k}$
  defined by
  \begin{equation}
    \SHM{k}\colon (x,y) \mapsto \frac{x}{\abs{x}},
    \quad\text{where } (x,y) \in \Sph^{m}\subset \R^{m-k}\times\R^{k+1},
  \end{equation}
  as a \emph{generalized equator map}. It is a smooth map away from
  $\brc{0}\times\Sph^k$. Note that for $k = 0$,
  this is simply the radial projection onto the equator.
\end{definition}

Set $n := m - 1 - k$, so $n \geq 2$. In the coordinates $\Sph^{n} \times (0,1)\times \Sph^{k} \to \Sph^m$,
\begin{equation}\label{sec:calc-on-sphere}
  (\theta, t, \omega) \mapsto \brr{\theta\sqrt{1-t}, \omega\sqrt{t}},
\end{equation}
$\SHM{k}$ is given by
\begin{equation}
  \SHM{k}\colon (\theta, t, \omega) \mapsto \theta.
\end{equation}

In these coordinates, $g_{\Sph^m} = (1-t) g_{\theta} + \frac{1}{4}\frac{dt^2}{1-t^2} + t g_{\omega}$, so
\begin{equation}
  \Delta_{g_{\Sph^m}} \SHM{k} = \frac{\Delta_{\theta} (\id_{\theta})}{1-t}
  = \frac{\abs{d(\id_{\theta})}^2_{\theta}}{1-t}
  = \abs{d \SHM{k}}^2\SHM{k}
\end{equation}
since the identity
$\id_{\theta} \colon \Sph^{n}\to \Sph^{n}$ is harmonic,
with $\abs{d(\id_{\theta})}^2_{\theta} = n$.
The energy of $\SHM{k}$ equals
\begin{equation}\label{eq:equator-energy}
  \begin{split}
    E[\SHM{k}] &= \int \abs{d\SHM{k}}^2 dv_{g_{\Sph^m}} = n
    \tfrac{\sigma_{n}\sigma_{k}}{2}\int_{0}^1 (1-t)^{\frac{n-1}{2}-1}t^{\frac{k-1}{2}}dt
    \\ &= n \tfrac{\sigma_{n}\sigma_{k}}{2} B(\tfrac{n-1}{2}, \tfrac{k+1}{2})
    = n \tfrac{n+k}{n-1} \brs{\tfrac{\sigma_{n}\sigma_{k}}{2} B(\tfrac{n+1}{2}, \tfrac{k+1}{2})}
    \\ &=  \tfrac{n(m-1)}{n-1}  \sigma_{m},
  \end{split}
\end{equation}
where $B(x,y)$ is the beta function.
Thus, $\SHM{k} \in H^1(\Sph^m,\Sph^{n})$ is a weakly harmonic map, whose
singularity set is precisely $\brc{0}\times\Sph^k$.

\begin{theorem}\label{thm:2d-eigen-sphere-upper-bound}
  Let $m \geq 3$ and $0\leq k\leq m-3$. For any
  (nonnegative) continuous measure $\mu \in \mathcal{M}_c(\Sph^m)$,
  one has
  \begin{equation}
    \overline{\lambda}_{k+2}(\mu) \leq E[\SHM{k}].
  \end{equation}
\end{theorem}
\begin{remark}
    The case of equality implies $\lambda_{k+2}(\mu)\mu = \abs{d\SHM{k}}^2_{g_{\Sph^m}} dv_{g_{\Sph^m}}$.
  Therefore, the upper bound is not optimal when $k > m - 7$.

  The reason that $\SHM{k}$ fails to be a maximizer for $k \geq m - 6$
  is because $\ind \SHM{k} := \ind (\Delta - \abs{d\SHM{k}}^2) = \infty$ in this case.  To see this, let
  us assume for simplicity that $3\leq m \leq 6$ and $k=0$.
  Then the essential spectrum of the Laplacian $\Delta$ on
  $L^2(\Sph^m, \abs{d\SHM{0}}^2dv_{g_{\Sph^m}})$
  begins no later
  than at $\frac{(m-2)^2}{4(m-1)} < 1$ for $m\leq 6$. This can be seen by analyzing the blow-up of
  $\SHM{0}$ near a pole so that
  $\epsilon^{m-2} (M_\epsilon)_*(\abs{d\SHM{0}}^2 dv_{g_{\Sph^m}})
  \to \frac{m-1}{\abs{x}^2}dv_{g_{\R^m}}$ on $\R^m$, where $M_\epsilon(x) = x/\epsilon$.
  Then, applying
  \cite[Lemma~1.3]{Schoen-Uhlenbeck:1984:min-harm-maps}, one obtains the lower bound
  $\frac{(m-2)^2}{4(m-1)}$, which is realized by pulling back suitable
  compactly supported radial test functions from $\R^m$.
  Thus, the (spectral) index of $\SHM{0}$ is infinite.
\end{remark}
\begin{theorem}\label{thm:2d-eigen-sphere-index}
  Let $\SHM{k}\colon\Sph^{m}\to\Sph^{m-1-k}$ be a generalized equator map and $0\leq k \leq m - 7$.
  Then $\ind \SHM{k} = k+2$, so the map $\SHM{k}$ is the unique maximizer
  realizing $\mathcal{V}_{k+2}(g_{\Sph^m})$.
\end{theorem}
Thus, $\SHM{k}$ is indeed a maximizer for $\mathcal{V}_{k+2}(g_{\Sph^m})$
when $0\leq k \leq m - 7$, and one cannot always expect the
smoothness of maximizers in Theorem~\ref{thm:main}.

In Corollary~\ref{cor:sph-dim-restric}, we establish a new necessary condition
for maximizing measures, which can in fact be shown to hold for critical
measures as well. As a consequence, the identity map
$\id \colon \Sph^m \to \Sph^m$
cannot realize $\mathcal{V}_2(g_{\Sph^m})$
since it is impossible to map $\Sph^m \to \Sph^{m-1}$ using only linear functions.

On the other hand for $3\leq m \leq 6$, we know that there exists a smooth harmonic
map $u \colon \Sph^m \to \Sph^n$ realizing $\mathcal{V}_2(g_{\Sph^m})$. Its spectral index must be
$\ind u \leq 2$.
Since the identity map maximizes $\overline{\lambda}_1$ but not
$\overline{\lambda}_2$, any maximizer of $\overline{\lambda}_2$ must have spectral
index exactly $\ind u = 2$. Unfortunately, we do not know any natural
example of a harmonic maps with
$\ind u = 2$. This leads to the following question:
\begin{question}
  Which smooth harmonic maps $u \colon \Sph^m \to \Sph^n$, with
  (spectral) index $\ind u = 2$,
  realize $\mathcal{V}_2(g_{\Sph^m})$
  for $3\leq m \leq 6$?
\end{question}

It is also natural to compare $\mathcal{V}_{k}(g_{\Sph^m})$ with the conformal class suprema
$\Lambda_k([g_{\Sph^m}])$, where
\begin{equation}\label{conf-class-opt}
    \Lambda_k([g]) = \sup_{\tilde{g} \in [g]} \overline{\lambda}_k(\tilde{g}),
  \quad \text{with } \overline{\lambda}_k(\tilde{g}) := \lambda_k(\tilde{g}) \Vol(\tilde{g})^{\frac{2}{m}}.
\end{equation}
El Soufi and Ilias \cite*{ElSoufi-Ilias:1986:hersch} computed
$\Lambda_1([g_{\Sph^m}])\sigma_m^{1-2/m} = m \sigma_m = \mathcal{V}_1(g_{\Sph^m})$,
thereby generalizing the classical result of Hersch for $m = 2$.
Thanks to~\cite*{Kim:2022:second-sphere-eigenval}, the supremum of the second eigenvalue in the conformal class
$[g_{\Sph^m}]$ is also known: $\Lambda_2([g_{\Sph^m}]) = m (2\sigma_m)^{\frac{2}{m}}$.
This yields the inequalities
\begin{equation}
  \mathcal{V}_{1}(g_{\Sph^m}) < \mathcal{V}_{2}(g_{\Sph^m}) < \Lambda_2([g_{\Sph^m}])\sigma_m^{1-\frac{2}{m}}.
\end{equation}

\subsection{Ideas of the proof of existence}

Recall that the existence of maximizers
on surfaces can be established by constructing a
maximizing sequence of probability measures $\mu_\epsilon$, converging
weakly$^*$ to some limiting measure $\mu$, i.e.
$\lambda_\epsilon := \lambda_k(\mu_\epsilon) \to \mathcal{V}_k$, together with
eigenmaps
$\Phi_\epsilon \in H^1(M,\R^{n_\epsilon})$ satisfying
$\Delta \Phi = \lambda_\epsilon \Phi_\epsilon \mu_\epsilon$ and
$\abs{\Phi_\epsilon}^2 \to 1$.
In dimension $m = 2$, it is possible to uniformly bound $n_\epsilon \leq n$
(the multiplicity is bounded by the genus). Then any weak limit
$\Phi$ of $\brc{\Phi_\epsilon}$ satisfies
$\abs{\Phi}^2 = 1$ by the compactness of
the embedding $H^1(M,\R^n) \hookrightarrow  L^2(M,\R^n)$.
One can further show that
$\Phi$ is a harmonic map and and that the continuous part of $\mu$ is equal to
$\abs{d\Phi}^2dv_g$. Thus, modulo some bubble analysis near the atoms of $\mu$,
the proof is complete.

Now, in dimensions $m \geq 3$, however, there is no known uniform bound on $n_\epsilon$.
A natural idea is to embed $\R^{n_\epsilon} \subset \R^\infty = \ell^2$
and attempt to carry out the same strategy. However, the embedding
$H^1(M,\R^\infty) \hookrightarrow  L^2(M,\R^\infty)$ is no longer
compact, so one cannot expect the equation $\abs{\Phi}^2 = 1$ to hold in the limit,
which is essential for the proof.

Instead of working directly in $H^1(M,\R^\infty)$, one may consider a different
functional space in which the limiting object $\Phi$
shares the property $\abs{\Phi}^2 = 1$. An idea for a such space
comes by viewing eigenvalues as
Lipschitz functionals on the space of compact
operators on a suitable Hilbert space,
$\lambda_k \colon \mathcal{K}[H] \to \C$. The first variation of $\lambda_k$
then lies in the dual $\mathcal{K}[H]^* \approx \mathcal{N}[H]$, which is known
to be the space of nuclear (a.k.a. trace-class) operators. This motivates working with
operators (or tensors) $\mathfrak{t}_\epsilon = \sum \phi^i_\epsilon \otimes \phi^i_\epsilon \in \mathcal{N}[H^1(M)]$ rather than with the vector-valued map
$\Phi = (\phi^1_\epsilon,\cdots,\phi^{n_\epsilon}_\epsilon)$. Fortunately, the weak$^*$ topology of $\mathcal{N}[H^1(M)]$
is strong enough to ensure $\sum \abs{\phi^i}^2 = 1$ for any weak$^*$ limit
$\mathfrak{t} = \sum \phi^i \otimes \phi^i$ of $\brc{\mathfrak{t}_\epsilon}$.
Then Lemma~\ref{lem:tensor-decomp} allows us to adapt the remainder
of the proof as in the two-dimensional case
(cf.~\cite{vinokurov:2025:sym-eigen-val}).


\subsection{Discussion}
\subsubsection{Harmonic maps into infinite dimensional targets}
Theorem~\ref{thm:main} admits harmonic maps $u\colon M \to \Sph^\infty$
whose images do not lie in any finite-dimensional subsphere.
Nevertheless, it remains unclear whether the supremum of the functional
$\mu \mapsto \overline{\lambda}_k(\mu)$ is ever realized by such maps.
One obstruction to constructing an example of this kind is that the
corresponding harmonic map would have to satisfy
the inequality
\begin{equation}
  \ind (\Delta - \abs{du}^2) \leq k < \infty,
\end{equation}
which implies that zero, being an eigenvalue of infinite multiplicity, is the bottom of
the essential spectrum of the
operator $\Delta - \abs{du}^2$, considered as an unbounded operator
on $L^2(M)$. Note that the finiteness of the index has two important consequences:
it implies local stability~\eqref{ineq:stable-map} (see the proof of Proposition~\ref{prop:con-bilin-form}),
and it also ensures stationarity of the map (see Lemma~\ref{lem:stable-energy-min}).
Furthermore, the local
stability condition, combined with a
partition of unity argument, implies
\begin{equation}
  \int \phi^2 \abs{du}^2 \leq \int \abs{d\phi}^2 + C \int \phi^2
\end{equation}
for all $\phi \in C^\infty$. This inequality shows that the operator
$(\Delta - \abs{du}^2)|_{C^\infty_0(M\setminus\Sigma)}$ is symmetric and
bounded from below (with respect to $L^2(M))$,
and thus essentially self-adjoint. Of course, to achieve infinite multiplicity, the map
must necessarily have singularities.
This motivates the following question:
\begin{question}
  Is every (weakly) harmonic map $u\colon M \to \Sph^\infty$
  of finite (spectral) index contained in a finite-dimensional subsphere $\Sph^n \subset \Sph^\infty$?
\end{question}
A positive answer to this question would, in turn, imply a positive answer to the following more specific problem:
\begin{question}
  In the setting of Theorem~\ref{thm:main}, does every maximizing harmonic map
$u\colon M \to \Sph^\infty$ actually take values in a finite-dimensional subsphere $\Sph^n \subset \Sph^\infty$?
\end{question}

% \vspace{0.5em}
\subsubsection{Other eigenvalue optimizations}
Traditionally,
the geometric optimization problem consists of identifying the suprema
$\Lambda_k([g])$~\eqref{conf-class-opt}. As we shall see in a moment
both $\mathcal{V}_k(g)$ and $\Lambda_k([g])$ are the borderline cases
of the following eigenvalue maximization problems parametrized
by $q \in [\frac{m}{m-2}, \infty]$.

Let us define
\begin{equation}
 \lambda_k(\mu, \sigma, g) := \inf_{F_{k+1}} \sup_{\phi \in F_{k+1}}
 \frac{\int \abs{d\phi}^2_g \sigma dv_g}{\int \phi^2 d\mu},
\end{equation}
and then
\begin{equation}\label{general-eigenval}
  \mathcal{V}_{k,q}(g) := \sup_{\substack{\mu, \sigma \in C^\infty\\ \mu, \sigma > 0}}
  \lambda_k(\mu, \sigma, g) \frac{\mu(M)}{\norm{\sigma}_{L^q}}.
\end{equation}
When $q < \frac{m}{m-2}$, the supremum $\mathcal{V}_{k,q}(g)$ becomes infinite.
This can be seen by choosing $\mu_\epsilon = \sigma_\epsilon =
\chi_{B_\epsilon(p)}$ to be the characteristic functions of a geodesic
ball. The infimum also becomes arbitrarily small, e.g., by fixing $\sigma = 1$
and letting $\mu_\epsilon \to \sum_{i=1}^{k} \delta_{p_i}$.

For $q = \infty$, note that $\frac{1}{\norm{\sigma}_{L^\infty}} \lambda_k(\mu, \sigma, g)
  \leq \lambda_k(\mu, g)$
since $\frac{\sigma}{\norm{\sigma}_{L^\infty}}\leq 1$. Hence, taking
$\sigma = 1$, we obtain the identity $\mathcal{V}_{k}(g) = \mathcal{V}_{k,\infty}(g)$.
Assuming $\Vol(g) = 1$, the Hölder inequality yields
\begin{equation}
  \mathcal{V}_{k}(g) = \mathcal{V}_{k,\infty}(g)
  \leq \mathcal{V}_{k,q}(g) \leq \mathcal{V}_{k,\frac{m}{m-2}}(g)
  \leq C([g])k^\frac{2}{m},
\end{equation}
where the final bound follows from
\cite[Theorem~2.1]{Colbois-ElSoufi-Savo:2015:-laplace-with-density}
(cf. also \cite[Theorem~5.3]{Grigoryan-Netrusov-Yau:2004:eignval-of-ellipt-oper}
with $\int_{B(x,r)} \sigma \leq C\norm{\sigma}_{L^{\frac{m}{m-2}}} r^2$).

In analogy with Section~\ref{subsec:clarke-subdif} (see also
\cite[Section~5]{Petrides-Tewodrose:2024:eigenvalue-via-clarke}),
the subdifferential
calculus shows that critical pairs $(\sigma, \mu)$ correspond
to $p$-harmonic maps $u \colon M \to \Sph^n$, where $p = \frac{2q}{q-1}$,
satisfying
\begin{equation}\label{p-crit-meas}
  \sigma = \abs{du}^{p-2}_g,\ \mu = \abs{du}^p_g dv_g,\
  \text{ and }\ \delta_g(\abs{du}_g^{p-2} du) = \abs{du}^p_g u.
\end{equation}

To recover $\Lambda_k([g])$, one may set $q = \frac{m}{m-2}$ and
$\mu = \sigma^{\frac{m}{m-2}} dv_g$ in~\eqref{general-eigenval}, which gives
\begin{equation}
  \Lambda_k([g]) \leq \mathcal{V}_{k,\frac{m}{m-2}}(g).
\end{equation}
However, as the critical point characterization~\eqref{p-crit-meas} suggests,
both $\Lambda_k([g])$ and $\mathcal{V}_{k,\frac{m}{m-2}}(g)$
share the same set of critical measures – those generated by $m$-harmonic
maps into spheres. Therefore, if $\mathcal{V}_{k,\frac{m}{m-2}}(g)$
is achieved by such a map, one should expect
$\mathcal{V}_{k,\frac{m}{m-2}}(g) = \Lambda_k([g])$.
This leads to the following natural questions:
\begin{question}
  For $q \in [\frac{m}{m-2}, \infty)$ and $p = \frac{2q}{q-1}$,
  does there exist a $p$-harmonic map that realizes $\mathcal{V}_{k,q}(g)$?
\end{question}
A more specific case of particular interest – formally implied by the previous question:
\begin{question}\label{quest-m-2-equal}
  Does the equality $\mathcal{V}_{k,\frac{m}{m-2}}(g) = \Lambda_k([g])$ hold?
\end{question}

In this generalized setting, the quadratic form
$\phi \mapsto \int \abs{d\phi}^2 \sigma dv_g$ and
$\phi \mapsto \int \phi^2 d\mu$ are naturally defined on
$H^{1,p}(M)$. While one can still construct maximizing sequences
of “almost $p$-harmonic” tensors $\mathfrak{t}_\epsilon = \sum \phi^i_\epsilon \otimes \phi^i_\epsilon$,
the analysis must be carried out in the stronger norm $\norm{\mathfrak{t}_\epsilon}_p :=
\int [\mathfrak{t}_\epsilon]^\frac{p}{2} + \int \mathfrak{D}[\mathfrak{t}_\epsilon]^\frac{p}{2}$,
which dominates the nuclear norm $\norm{\mathfrak{t}_\epsilon}_{\mathcal{N}[H^1]}$, see~\eqref{eq:nucler-top-H1}.
The presence of a nontrivial density $\sigma$, which can be zero at some points,
further complicates establishing strong
convergence $\mathfrak{t}_\epsilon \to \mathfrak{t}$ in the norm $\norm{\cdot}_p$.


