  \centering
  \includegraphics[,width=\textwidth]{fig1_wvfm.pdf}
  \caption{(a) Normalized waveform from a EJ276D PS detector, (b) neutron (red dashed line), and $\gamma$ (blue solid line) waveforms.}
  \label{Waves}
